std::string import_log_timestamp() {
    char stamp[16];
    amo_log_hms_copy(stamp, sizeof(stamp));
    return stamp;
}





void append_import_log_locked(UiState& ui, const std::string& message) {


    if (message.empty()) return;
    char clean_buf[1024];
    const size_t clean_n = amo_line_clean_copy(message.data(), message.size(), clean_buf, sizeof(clean_buf));
    std::string clean(clean_buf, std::min(clean_n, sizeof(clean_buf) - 1u));


    const std::string row = import_log_timestamp() + " · " + clean;


    if (!ui.import_progress_log.empty()) {
        std::string tail = ui.import_progress_log.back();
        const size_t sep = tail.find(" · ");

        if (sep != std::string::npos) tail = tail.substr(sep + 3);

        if (tail == clean) {

            ui.import_progress_detail = clean;

            return;
        }
    }


    ui.import_progress_log.push_back(row);


    while (ui.import_progress_log.size() > 36) ui.import_progress_log.pop_front();
    ui.import_progress_detail = clean;
}




void append_import_log(UiState& ui, const std::string& message) {


    std::lock_guard<std::mutex> lock(ui.mu);
    append_import_log_locked(ui, message);
}




void reset_import_log_locked(UiState& ui, const std::string& first_message) {


    ui.import_progress_log.clear();


    ui.import_progress_detail.clear();
    append_import_log_locked(ui, first_message);
}


