ImGuiViewport* main_viewport_safe() {

    ImGuiViewport* vp = ImGui::GetMainViewport();

    return vp ? vp : nullptr;
}



ImVec2 main_viewport_pos() {

    if (ImGuiViewport* vp = main_viewport_safe()) return vp->WorkPos;

    return ImVec2(0, 0);
}




ImVec2 main_viewport_size() {

    if (ImGuiViewport* vp = main_viewport_safe()) return vp->WorkSize;

    return ImGui::GetIO().DisplaySize;
}

#ifdef _WIN32


bool main_native_window_is_maximized() {



    if (g_tlalpowa_main_window) {

        const int maximized = glfwGetWindowAttrib(g_tlalpowa_main_window, GLFW_MAXIMIZED);

        if (maximized == GLFW_TRUE) return true;
        HWND hwnd = glfwGetWin32Window(g_tlalpowa_main_window);

        if (hwnd && IsZoomed(hwnd)) return true;
    }

    if (ImGuiViewport* vp = ImGui::GetMainViewport()) {
        HWND hwnd = nullptr;

        if (vp->PlatformHandleRaw) hwnd = reinterpret_cast<HWND>(vp->PlatformHandleRaw);

        if (!hwnd && vp->PlatformHandle) {

            GLFWwindow* glfw_window = reinterpret_cast<GLFWwindow*>(vp->PlatformHandle);

            if (glfw_window) hwnd = glfwGetWin32Window(glfw_window);
        }

        if (hwnd && IsZoomed(hwnd)) return true;
    }

    return false;
}
#endif




float golden_w(float ratio) {


    const ImVec2 ds = main_viewport_size();

    return std::max(1.0f, ds.x * ratio);
}



float golden_h(float ratio) {

    const ImVec2 ds = main_viewport_size();

    return std::max(1.0f, ds.y * ratio);
}



float top_bar_height() {
    /*
     * Invariante visual: la barra superior mide exactamente lo mismo que la
     * plantilla canónica de controles.  No agregar guardas locales aquí: si la
     * barra crece, botones y pestañas dejan de cerrar al mismo alto.
     */
    return std::max(34.0f, golden_h(kTlalpowaControlHeightRatio));
}



float bottom_bar_height() {
    const float h = golden_h(kBottomBarHeightRatio);



    return std::clamp(h, golden_h(kGoldenN7), golden_h(kGoldenN5));
}


float golden_tab_chrome_height() {
    
    return std::max(1.0f, golden_h(kTlalpowaControlHeightRatio));
}

float golden_tab_frame_pad_x() {
    
    return std::max(1.0f, golden_tab_chrome_height() * kGoldenN1);
}

float golden_tab_frame_pad_y() {
    const float h = golden_tab_chrome_height();
    const float text_h = std::max(1.0f, ImGui::GetTextLineHeight());
    
    return std::max(0.0f, (h - text_h) * 0.5f);
}

float golden_control_rounding() {
    /*
     * Radio único de botones, pestañas, cajas de texto, combos y checks.
     * Subir o bajar la redondez se hace sólo aquí: cualquier radio local
     * reabre divergencias visuales y rompe la plantilla compartida.
     */
    return std::max(1.0f, golden_tab_chrome_height() * kGoldenN2);
}

float golden_tab_rounding() {
    return golden_control_rounding();
}

float golden_visible_tab_rounding() {
    return golden_control_rounding();
}

float golden_ui_font_px_from_height(float reference_h) {
    
    const float h = std::isfinite(reference_h) && reference_h > 0.0f ? reference_h : 900.0f;
    return h * kTlalpowaFontHeightRatio;
}

float golden_checkbox_side() {
    
    return std::max(1.0f, golden_tab_chrome_height() * kGoldenN1);
}

float golden_checkbox_rounding() {
    return golden_control_rounding();
}


float ui_x_gap(float ratio = kGoldenN12) {

    return golden_w(ratio);
}




float ui_x_min(float ratio, float min_px) {

    return std::max(min_px, golden_w(ratio));
}



float ui_y_min(float ratio, float min_px) {

    return std::max(min_px, golden_h(ratio));
}




struct WorkAreaRect {
    ImVec2 pos = ImVec2(0.0f, 0.0f);
    ImVec2 size = ImVec2(0.0f, 0.0f);
};



WorkAreaRect primary_work_area_rect() {
    WorkAreaRect r;

    if (ImGuiViewport* vp = main_viewport_safe()) {
        r.pos = vp->WorkPos;
        r.size = vp->WorkSize;
    } else {
        r.pos = ImVec2(0.0f, 0.0f);

        r.size = ImGui::GetIO().DisplaySize;
    }
#ifdef _WIN32



    if (main_native_window_is_maximized()) {
        RECT work{};

        bool have_work = false;
        HWND hwnd = nullptr;

        if (g_tlalpowa_main_window) hwnd = glfwGetWin32Window(g_tlalpowa_main_window);

        if (!hwnd) {

            if (ImGuiViewport* vp = ImGui::GetMainViewport()) {

                if (vp->PlatformHandleRaw) hwnd = reinterpret_cast<HWND>(vp->PlatformHandleRaw);

                if (!hwnd && vp->PlatformHandle) {

                    GLFWwindow* glfw_window = reinterpret_cast<GLFWwindow*>(vp->PlatformHandle);

                    if (glfw_window) hwnd = glfwGetWin32Window(glfw_window);
                }
            }
        }
        HMONITOR mon = hwnd ? MonitorFromWindow(hwnd, MONITOR_DEFAULTTONEAREST) : nullptr;
        MONITORINFO mi{};
        mi.cbSize = sizeof(mi);

        if (mon && GetMonitorInfoW(mon, &mi)) {
            work = mi.rcWork;
            have_work = true;

        } else if (SystemParametersInfoW(SPI_GETWORKAREA, 0, &work, 0)) {
            have_work = true;
        }

        if (have_work) {
            r.pos = ImVec2(static_cast<float>(work.left), static_cast<float>(work.top));

            r.size = ImVec2(static_cast<float>(std::max<LONG>(1, work.right - work.left)),

                            static_cast<float>(std::max<LONG>(1, work.bottom - work.top)));
        }
    }
#endif

    return r;
}

