void set_next_main_window_rect(float x, float y, float w, float h) {

    if (ImGuiViewport* vp = main_viewport_safe()) ImGui::SetNextWindowViewport(vp->ID);
    const ImVec2 ds = main_viewport_size();
    const float sx = std::isfinite(x) ? std::clamp(x, 0.0f, std::max(0.0f, ds.x)) : 0.0f;
    const float sy = std::isfinite(y) ? std::clamp(y, 0.0f, std::max(0.0f, ds.y)) : 0.0f;
    const float sw = std::isfinite(w) ? std::clamp(w, 1.0f, std::max(1.0f, ds.x - sx)) : 1.0f;
    const float sh = std::isfinite(h) ? std::clamp(h, 1.0f, std::max(1.0f, ds.y - sy)) : 1.0f;

    ImGui::SetNextWindowPos(main_pos(sx, sy), ImGuiCond_Always);

    ImGui::SetNextWindowSize(ImVec2(sw, sh), ImGuiCond_Always);
}



