std::optional<std::array<int, 5>> parse_numeric_date_time_components(std::string text) {
    int parts[5] = {0, 0, 0, -1, -1};
    if (!ozmvm_parse_numeric_date_time_components(text.data(), text.size(), parts)) return std::nullopt;
    return std::array<int, 5>{parts[0], parts[1], parts[2], parts[3], parts[4]};
}




std::optional<int> parse_epi_year_token(const std::string& raw) {


    const std::string s = normalize_key(raw);
    const int year = ozmvm_first_epi_year_1900_2099(s.data(), s.size());
    if (year < 1900 || year > 2100) return std::nullopt;

    return year;
}



std::optional<int> parse_epi_week_token_contextual(const std::string& raw) {


    std::string s = normalize_key(raw);
    const int week = ozmvm_epi_week_contextual(s.data(), s.size());
    return week > 0 ? std::optional<int>(week) : std::nullopt;
}




std::optional<std::pair<int, int>> parse_epi_year_week(const std::string& s) {


    const auto year = parse_epi_year_token(s);

    if (!year) return std::nullopt;


    const auto week = parse_epi_week_token_contextual(s);

    if (!week) return std::nullopt;

    return std::make_pair(*year, *week);
}




int64_t timeline_hour_for_epi_week_label(const std::string& label) {


    if (auto yw = parse_epi_year_week(label)) {

        return timeline_hour_from_civil(yw->first, 1, 1, 0) + static_cast<int64_t>(std::max(0, yw->second - 1)) * 7 * 24;
    }

    return 0;
}




int nearest_week_index_for_timeline(const std::vector<std::string>& weeks, int64_t hour) {

    if (weeks.empty()) return 0;
    int best = 0;
    int64_t best_delta = std::numeric_limits<int64_t>::max();

    for (int i = 0; i < static_cast<int>(weeks.size()); ++i) {

        const int64_t wh = timeline_hour_for_epi_week_label(weeks[i]);

        const int64_t delta = std::llabs(wh - hour);

        if (delta < best_delta) { best_delta = delta; best = i; }
    }

    return best;
}



void refresh_timeline_input(UiState& ui) {

    const std::string label = format_timeline_compact_edit(ui.timeline_hour, ui.timeline_minute);
#ifdef _WIN32

    strncpy_s(ui.timeline_input, label.c_str(), _TRUNCATE);
#else

    std::snprintf(ui.timeline_input, sizeof(ui.timeline_input), "%s", label.c_str());
#endif

    ui.timeline_input_dirty = false;
}



void tlalpowa_ensure_timeline_initialized_for_replay(UiState& ui) {
    ui.timeline_max_hour = std::max<int64_t>(ui.timeline_max_hour, current_local_timeline_hour());
    if (!ui.timeline_initialized) {
        ui.timeline_hour = clamp_timeline_navigation_hour(ui.timeline_max_hour);
        ui.timeline_minute = current_local_timeline_minute();
        ui.timeline_initialized = true;
        refresh_timeline_input(ui);
        return;
    }
    ui.timeline_hour = clamp_timeline_navigation_hour(ui.timeline_hour);
    ui.timeline_minute = std::clamp(ui.timeline_minute, 0, 59);
}


void tlalpowa_apply_total_timeline_minutes_direct(UiState& ui, int64_t total_minutes) {
    const int64_t min_total = timeline_min_navigation_hour() * 60LL;
    const int64_t max_total = timeline_max_navigation_hour() * 60LL + 59LL;
    total_minutes = std::clamp<int64_t>(total_minutes, min_total, max_total);
    ui.timeline_hour = clamp_timeline_navigation_hour(floor_div_i64(total_minutes, 60LL));
    ui.timeline_minute = static_cast<int>(positive_mod_i64(total_minutes, 60LL));
    refresh_timeline_input(ui);
}


void tlalpowa_shift_timeline_minutes_direct(UiState& ui, int64_t delta_minutes) {
    tlalpowa_apply_total_timeline_minutes_direct(
        ui,
        clamp_timeline_navigation_hour(ui.timeline_hour) * 60LL +
            static_cast<int64_t>(std::clamp(ui.timeline_minute, 0, 59)) + delta_minutes);
}


void tlalpowa_advance_playback_once_direct(UiState& ui) {
    tlalpowa_ensure_timeline_initialized_for_replay(ui);
    switch (std::clamp(ui.play_step_unit, 0, 4)) {
    case 0:
        tlalpowa_shift_timeline_minutes_direct(ui, 1LL);
        return;
    case 1:
        tlalpowa_shift_timeline_minutes_direct(ui, 60LL);
        return;
    case 2:
        tlalpowa_shift_timeline_minutes_direct(ui, 24LL * 60LL);
        return;
    case 3:
        tlalpowa_shift_timeline_minutes_direct(ui, 7LL * 24LL * 60LL);
        return;
    case 4: {
        int year = 0;
        unsigned month = 1, day = 1;
        const int64_t safe_hour = clamp_timeline_navigation_hour(ui.timeline_hour);
        civil_from_days(timeline_epoch_days() + floor_div_i64(safe_hour, 24), year, month, day);
        const unsigned hour_of_day = static_cast<unsigned>(positive_mod_i64(safe_hour, 24));
        int64_t total_months = static_cast<int64_t>(year) * 12LL + static_cast<int64_t>(month - 1u) + 1LL;
        const int64_t min_months = static_cast<int64_t>(kTimelineMinCivilYear) * 12LL;
        const int64_t max_months = static_cast<int64_t>(kTimelineMaxCivilYear) * 12LL + 11LL;
        total_months = std::clamp<int64_t>(total_months, min_months, max_months);
        const int new_year = static_cast<int>(total_months / 12LL);
        const unsigned new_month = static_cast<unsigned>(total_months % 12LL) + 1u;
        const unsigned new_day = std::min<unsigned>(day, timeline_navigation_days_in_month(new_year, new_month));
        const int64_t new_hour = timeline_hour_from_civil(new_year, new_month, new_day, hour_of_day);
        tlalpowa_apply_total_timeline_minutes_direct(ui, new_hour * 60LL + static_cast<int64_t>(std::clamp(ui.timeline_minute, 0, 59)));
        return;
    }
    default:
        return;
    }
}


void tlalpowa_process_global_space_and_playback(UiState& ui, GLFWwindow* window, float dt, bool keyboard_text_capture) {
    static bool previous_space_down = false;
    const bool space_down = window && glfwGetKey(window, GLFW_KEY_SPACE) == GLFW_PRESS;
    if (space_down && !previous_space_down && !keyboard_text_capture && !main_ui_blocked_by_tool_window(ui)) {
        tlalpowa_ensure_timeline_initialized_for_replay(ui);
        ui.playing = !ui.playing;
        ui.play_accum = 0.0f;
    }
    previous_space_down = space_down;

    if (!ui.playing) return;
    tlalpowa_ensure_timeline_initialized_for_replay(ui);
    ui.play_rate = std::clamp(ui.play_rate, 0.125f, 64.0f);
    const float safe_dt = std::clamp(dt, 0.0f, 0.20f);
    ui.play_accum += safe_dt * ui.play_rate;

    int consumed = 0;
    constexpr int kMaxPlaybackStepsPerFrame = 24;
    while (ui.play_accum >= 1.0f && consumed < kMaxPlaybackStepsPerFrame) {
        ui.play_accum -= 1.0f;
        tlalpowa_advance_playback_once_direct(ui);
        ++consumed;
    }
    if (consumed >= kMaxPlaybackStepsPerFrame) {
        // El reloj visual jamás debe convertir una pausa del SO en cientos de
        // saltos acumulados: se descarta deuda temporal antes de trabar la UI.
        ui.play_accum = 0.0f;
    }
}



void sync_week_from_timeline(UiState& ui, const std::vector<std::string>& weeks) {
    if (weeks.empty()) return;
    const int max_week = std::max(0, static_cast<int>(weeks.size()) - 1);
    const int64_t target_hour = ui.timeline_hour;
    int exact = -1;
    int nearest = 0;
    int64_t nearest_delta = std::numeric_limits<int64_t>::max();

    for (int i = 0; i <= max_week; ++i) {
        const int64_t start = timeline_hour_for_epi_week_label(weeks[static_cast<size_t>(i)]);
        if (start == 0) continue;
        const int64_t end = start + 7ll * 24ll;
        if (target_hour >= start && target_hour < end) {
            exact = i;
            break;
        }
        const int64_t delta = std::min(std::llabs(target_hour - start), std::llabs(target_hour - end));
        if (delta < nearest_delta) { nearest_delta = delta; nearest = i; }
    }

    // La navegación histórica sólo mueve epidemiología si ya hay una capa activa:
    // nunca enciende casillas ni lee IXIPTLAH por sí sola. Cuando la fecha cae en
    // una semana cargada, la representación queda exactamente en esa semana; fuera
    // de cobertura se usa el borde más cercano, evitando prolongaciones infinitas.
    const int resolved = (exact >= 0) ? exact : std::clamp(nearest, 0, max_week);
    ui.selected_week = resolved;
    ui.week_start = resolved;
    ui.week_end = resolved;
}


void force_epidemiology_exact_week_locked(UiState& ui) {
    // Invariante estricta post-crashfix: epidemiología jamás usa ventanas semanales
    // amplias para mapa, pastelillos ni gráficas. La barra histórica puede moverse
    // libremente para capas históricas/atmosféricas, pero no persigue ni gobierna
    // semanas epidemiológicas. Todo cierre de carga deja week_start == week_end ==
    // selected_week para impedir que la primera semana se prolongue hacia atrás o
    // la última hacia adelante por intervalos heredados.
    const int max_week = std::max(0, static_cast<int>(ui.weeks.size()) - 1);
    ui.selected_week = std::clamp(ui.selected_week, 0, max_week);
    ui.week_start = ui.selected_week;
    ui.week_end = ui.selected_week;
}





std::string get_json_string(const std::string& s, const char* key) {


    size_t begin = 0;
    size_t end = 0;
    int has_escape = 0;


    if (!ozmvm_json_string_span(s.data(), s.size(), key, &begin, &end, &has_escape)) return {};

    if (!has_escape) return s.substr(begin, end - begin);
    std::string out;

    out.reserve(end - begin);

    for (size_t p = begin; p < end; ++p) {
        const char c = s[p];

        if (c == '\\' && p + 1 < end) {
            const char n = s[++p];

            if (n == 'n') out.push_back('\n');

            else if (n == 'r') out.push_back('\r');

            else if (n == 't') out.push_back('\t');

            else if (n == 'u' && p + 4 < s.size()) {


                p += 4;

                out.push_back('?');
            } else {

                out.push_back(n);
            }
        } else {

            out.push_back(c);
        }
    }

    return out;
}




std::string get_json_string(const std::string& s, const std::string& key) {


    return get_json_string(s, key.c_str());
}




bool system_light_theme() {
#ifdef _WIN32

    DWORD value = 1;
    DWORD size = sizeof(value);
    const LSTATUS ok = RegGetValueW(HKEY_CURRENT_USER,

        L"Software\\Microsoft\\Windows\\CurrentVersion\\Themes\\Personalize",
        L"AppsUseLightTheme", RRF_RT_REG_DWORD, nullptr, &value, &size);

    return ok == ERROR_SUCCESS ? value != 0 : false;
#else

    return false;
#endif
}




ImVec4 system_accent_color() {
#ifdef _WIN32
    DWORD value = 0;
    DWORD size = sizeof(value);
    LSTATUS ok = RegGetValueW(HKEY_CURRENT_USER,
        L"Software\\Microsoft\\Windows\\DWM",
        L"ColorizationColor", RRF_RT_REG_DWORD, nullptr, &value, &size);

    if (ok == ERROR_SUCCESS) {
        const int r = static_cast<int>((value >> 16) & 0xff);

        const int g = static_cast<int>((value >> 8) & 0xff);
        const int b = static_cast<int>(value & 0xff);

        if (r + g + b > 0) return ImVec4(r / 255.0f, g / 255.0f, b / 255.0f, 1.0f);
    }
    ok = RegGetValueW(HKEY_CURRENT_USER,
        L"Software\\Microsoft\\Windows\\DWM",
        L"AccentColor", RRF_RT_REG_DWORD, nullptr, &value, &size);

    if (ok == ERROR_SUCCESS) {
        const int r = static_cast<int>(value & 0xff);
        const int g = static_cast<int>((value >> 8) & 0xff);
        const int b = static_cast<int>((value >> 16) & 0xff);

        if (r + g + b > 0) return ImVec4(r / 255.0f, g / 255.0f, b / 255.0f, 1.0f);
    }

    return ImVec4(0.10f, 0.48f, 0.86f, 1.0f);
#else

    return ImVec4(0.10f, 0.48f, 0.86f, 1.0f);
#endif
}


ImU32 u32(const ImVec4& c, float alpha = 1.0f) {

    return ImGui::ColorConvertFloat4ToU32(ImVec4(c.x, c.y, c.z, c.w * alpha));
}


struct GoldenChromeResult {
    bool clicked = false;
    bool hovered = false;
    bool active = false;
};

float golden_chrome_horizontal_padding(float h) {

    return std::max(1.0f, std::max(1.0f, h) * kGoldenN3);
}

float golden_chrome_label_font_px(float  ) {
    
    return std::max(1.0f, ImGui::GetFontSize());
}

ImVec2 golden_chrome_label_size(const char* label, float h) {
    const char* visible = label ? label : "";
    ImFont* font = ImGui::GetFont();
    const float font_px = golden_chrome_label_font_px(h);
    if (!font) return ImGui::CalcTextSize(visible);
    return font->CalcTextSizeA(font_px, std::numeric_limits<float>::max(), 0.0f, visible);
}

float golden_chrome_text_top_gap(float h, float text_h) {

    const float surplus = std::max(0.0f, std::max(1.0f, h) - std::max(0.0f, text_h));
    if (surplus <= 0.0f) return 0.0f;
    return surplus * 0.5f;
}

float golden_chrome_text_bottom_gap(float h, float text_h) {
    const float surplus = std::max(0.0f, std::max(1.0f, h) - std::max(0.0f, text_h));
    if (surplus <= 0.0f) return 0.0f;
    return surplus * 0.5f;
}

float golden_chrome_auto_width(const char* label, float h, bool square = false) {
    const float safe_h = std::max(1.0f, h);
    if (square) return safe_h;
    const ImVec2 text = golden_chrome_label_size(label, safe_h);
    return std::max(safe_h * (kGoldenN0 + kGoldenN1), text.x + golden_chrome_horizontal_padding(safe_h) * 2.0f);
}

ImU32 golden_chrome_fill(bool light, const ImVec4& accent, bool selected, bool hovered, bool held, bool primary) {
    if (primary) {
        return held ? u32(accent, 1.0f) : (hovered ? u32(accent, 0.84f) : u32(accent, 0.94f));
    }
    if (selected) {
        return light ? IM_COL32(255, 255, 255, 255) : IM_COL32(20, 28, 37, 255);
    }
    if (hovered || held) {
        return light ? IM_COL32(236, 244, 251, 244) : IM_COL32(39, 51, 65, 242);
    }
    return light ? IM_COL32(226, 236, 246, 205) : IM_COL32(28, 38, 50, 218);
}

ImU32 golden_chrome_text_color(bool light, bool selected, bool primary) {
    if (primary) return IM_COL32(255, 255, 255, 255);
    if (selected) return light ? IM_COL32(27, 36, 47, 255) : IM_COL32(238, 244, 250, 255);
    return light ? IM_COL32(76, 91, 108, 242) : IM_COL32(191, 204, 217, 242);
}

GoldenChromeResult draw_golden_control_hitbox(const char* id, const ImVec2& a, float w, float h, bool square, float& out_w, float& out_h) {
    const float safe_h = std::max(1.0f, h);
    const float safe_w = std::max(1.0f, square ? safe_h : w);
    out_w = safe_w;
    out_h = safe_h;
    ImGui::SetCursorScreenPos(a);
    ImGui::PushID(id ? id : "##golden-control");
    ImGui::PushStyleVar(ImGuiStyleVar_FramePadding, ImVec2(0.0f, 0.0f));
    ImGui::PushStyleVar(ImGuiStyleVar_ItemSpacing, ImVec2(0.0f, 0.0f));
    const bool clicked = ImGui::InvisibleButton("##golden-control-hitbox", ImVec2(safe_w, safe_h));
    const bool hovered = ImGui::IsItemHovered();
    const bool held = ImGui::IsItemActive();
    ImGui::PopStyleVar(2);
    ImGui::PopID();
    return GoldenChromeResult{clicked, hovered, held};
}

void draw_golden_control_label(ImDrawList* dl, const char* label, const ImVec2& a, float w, float h,
                               ImU32 text_col) {
    if (!dl) return;
    const char* visible = label ? label : "";
    ImFont* font = ImGui::GetFont();
    const float font_px = golden_chrome_label_font_px(h);
    const ImVec2 text = golden_chrome_label_size(visible, h);
    const float pad_x = golden_chrome_horizontal_padding(h);
    const float text_x = std::clamp(a.x + (w - text.x) * 0.5f, a.x + pad_x, std::max(a.x + pad_x, a.x + w - pad_x - text.x));
    const float top_gap = golden_chrome_text_top_gap(h, text.y);
    const float bottom_gap = golden_chrome_text_bottom_gap(h, text.y);
    (void)bottom_gap;
    const float text_y = a.y + top_gap;
    if (font) dl->AddText(font, font_px, ImVec2(text_x, text_y), text_col, visible);
    else dl->AddText(ImVec2(text_x, text_y), text_col, visible);
}

GoldenChromeResult draw_golden_button_template(const char* id, const char* label, const ImVec2& a,
                                               float w, float h, const ImVec4& accent, bool light,
                                               bool selected = false, bool primary = false, bool square = false) {

    float safe_w = 1.0f;
    float safe_h = 1.0f;
    GoldenChromeResult r = draw_golden_control_hitbox(id ? id : label, a, w, h, square, safe_w, safe_h);
    ImDrawList* dl = ImGui::GetWindowDrawList();
    const ImVec2 b(a.x + safe_w, a.y + safe_h);
    const ImU32 fill = golden_chrome_fill(light, accent, selected, r.hovered, r.active, primary);
    
    const float rounding = golden_tab_rounding();
    const float shadow_offset = std::max(1.0f, safe_h * kGoldenN10);
    const ImU32 shadow = light ? IM_COL32(120, 140, 160, primary ? 34 : 24) : IM_COL32(0, 0, 0, primary ? 74 : 58);
    dl->AddRectFilled(ImVec2(a.x, a.y + shadow_offset), ImVec2(b.x, b.y + shadow_offset), shadow, rounding, ImDrawFlags_RoundCornersAll);
    dl->AddRectFilled(a, b, fill, rounding, ImDrawFlags_RoundCornersAll);
    if (r.hovered || r.active) {
        const ImU32 wash = primary ? IM_COL32(255, 255, 255, 22) : u32(accent, light ? 0.08f : 0.13f);
        dl->AddRectFilled(a, b, wash, rounding, ImDrawFlags_RoundCornersAll);
    }
    draw_golden_control_label(dl, label, a, safe_w, safe_h, golden_chrome_text_color(light, selected, primary));
    return r;
}

GoldenChromeResult draw_golden_tab_template(const char* id, const char* label, const ImVec2& a,
                                            float w, float h, const ImVec4& accent, bool light,
                                            bool selected = false) {

    float safe_w = 1.0f;
    float safe_h = 1.0f;
    GoldenChromeResult r = draw_golden_control_hitbox(id ? id : label, a, w, h, false, safe_w, safe_h);
    ImDrawList* dl = ImGui::GetWindowDrawList();
    const ImVec2 b(a.x + safe_w, a.y + safe_h);
    const ImU32 fill = golden_chrome_fill(light, accent, selected, r.hovered, r.active, false);
    const float rounding = std::max(1.0f, golden_visible_tab_rounding());
    if (selected) {
        const ImU32 shadow = light ? IM_COL32(120, 140, 160, 18) : IM_COL32(0, 0, 0, 46);
        dl->AddRectFilled(ImVec2(a.x, a.y + std::max(1.0f, safe_h * kGoldenN12)), b, shadow, rounding, ImDrawFlags_RoundCornersTop);
    }
    dl->AddRectFilled(a, b, fill, rounding, ImDrawFlags_RoundCornersTop);
    if (selected) {
        dl->AddRectFilled(ImVec2(a.x, b.y - std::max(1.0f, safe_h * kGoldenN10)), b, fill, 0.0f);
    } else if (r.hovered || r.active) {
        dl->AddRectFilled(a, b, u32(accent, light ? 0.055f : 0.10f), rounding, ImDrawFlags_RoundCornersTop);
    }
    draw_golden_control_label(dl, label, a, safe_w, safe_h, golden_chrome_text_color(light, selected, false));
    return r;
}





