void draw_golden_tab_strip(const char* id, int& active_index, const char* const* labels, int count, const ImVec4& accent, bool light) {
    
    if (!labels || count <= 0) return;
    active_index = std::clamp(active_index, 0, count - 1);
    ImGui::PushID(id);
    const float h = golden_tab_chrome_height();
    ImVec2 a = ImGui::GetCursorScreenPos();
    const float x0 = a.x;
    const ImVec2 mouse = ImGui::GetIO().MousePos;
    const bool manual_release = ImGui::IsMouseReleased(ImGuiMouseButton_Left) &&
                                ImGui::IsWindowHovered(ImGuiHoveredFlags_AllowWhenBlockedByActiveItem);
    for (int i = 0; i < count; ++i) {
        const char* label = labels[i] ? labels[i] : "";
        const float w = golden_chrome_auto_width(label, h, false);
        const GoldenChromeResult r = draw_golden_tab_template(label, label, a, w, h, accent, light, active_index == i);
        const bool manual_hit = manual_release &&
                                mouse.x >= a.x && mouse.x <= a.x + w &&
                                mouse.y >= a.y && mouse.y <= a.y + h;
        if (r.clicked || manual_hit) active_index = i;
        a.x += w;
    }
    ImGui::SetCursorScreenPos(ImVec2(x0, a.y + h));
    ImGui::PopID();
}





