PreviewTexture load_preview_texture(const fs::path& path) {

    static std::string loaded_path;

    static fs::file_time_type loaded_time{};
    static std::uintmax_t loaded_size = 0;

    static PreviewTexture texture;

    const std::string p = path_utf8(path);
    std::error_code ec;

    if (p.empty() || !fs::exists(path, ec) || ec) return {};

    const auto current_time = fs::last_write_time(path, ec);

    if (ec) return {};


    const auto current_size = fs::file_size(path, ec);

    if (ec || current_size == 0) return {};

    if (loaded_path == p && loaded_time == current_time && loaded_size == current_size && texture.id != 0) return texture;

    if (texture.id != 0) {


        glDeleteTextures(1, &texture.id);

        texture = {};
    }


    std::ifstream in(path, std::ios::binary);

    if (!in) return {};

    std::vector<unsigned char> bytes((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());

    if (bytes.empty() || bytes.size() > static_cast<size_t>(std::numeric_limits<int>::max())) return {};
    int w = 0, h = 0, channels = 0;

    unsigned char* pixels = stbi_load_from_memory(bytes.data(), static_cast<int>(bytes.size()), &w, &h, &channels, 4);

    if (!pixels || w <= 0 || h <= 0) {

        if (pixels) stbi_image_free(pixels);

        loaded_path.clear();

        return {};
    }
    unsigned int id = 0;

    glGenTextures(1, &id);

    glBindTexture(GL_TEXTURE_2D, id);

    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);

    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);

    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);

    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);

    glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, w, h, 0, GL_RGBA, GL_UNSIGNED_BYTE, pixels);

    stbi_image_free(pixels);

    texture = {id, w, h};

    loaded_path = p;

    loaded_time = current_time;
    loaded_size = current_size;

    return texture;
}




