void tlalpowa_ensure_default_csv_source_roots() {

    /* Contrato local: las fuentes atmosféricas oficiales se resuelven respecto
       del directorio base de TLALPOWA, jamás contra rutas absolutas heredadas.
       REDMET es el directorio físico local para la red meteorológica horaria;
       RAMA conserva contaminantes horarios y RUOA_PEMBU conserva registros
       minutales PEMBU/RUOA. */
    ensure_dir(tlalpowa_default_csv_source_root(0));
    ensure_dir(tlalpowa_default_csv_source_root(1));
    ensure_dir(tlalpowa_default_csv_source_root(3));
}



fs::path tlalpowa_resolve_project_relative_path(const fs::path& raw) {

    if (raw.empty()) return raw;
    if (raw.is_absolute()) return raw;
    return (project_root() / raw).lexically_normal();
}



std::string tlalpowa_persist_local_path_utf8(const fs::path& raw) {

    if (raw.empty()) return std::string();
    if (raw.is_relative()) return path_utf8(raw.lexically_normal());

    std::error_code ec_root;
    std::error_code ec_path;
    const fs::path root = fs::absolute(project_root(), ec_root).lexically_normal();
    const fs::path path = fs::absolute(raw, ec_path).lexically_normal();
    if (!ec_root && !ec_path && !root.empty() && !path.empty()) {
        auto ri = root.begin();
        auto pi = path.begin();
        bool inside = true;
        for (; ri != root.end(); ++ri, ++pi) {
            if (pi == path.end() || *pi != *ri) { inside = false; break; }
        }
        if (inside) {
            const fs::path rel = path.lexically_relative(root);
            if (!rel.empty()) return path_utf8(rel);
        }
    }
    return path_utf8(raw);
}



bool tlalpowa_csv_path_is_old_atmospheric_auto_root(const fs::path& p) {

    const std::string key = normalize_key(path_utf8(p));
    return key.find("rama meteorologicos") != std::string::npos ||
           key.find("rama_meteorologicos") != std::string::npos ||
           key.find("rama contaminantes") != std::string::npos ||
           key.find("rama_contaminantes") != std::string::npos ||
           key.find("atmosfericos redma") != std::string::npos ||
           key.find("atmosfericos ruoa_unam") != std::string::npos ||
           key.find("atmosfericos ruoa unam") != std::string::npos ||
           key.find("datos atmosfericos") != std::string::npos;
}



fs::path tlalpowa_normalize_saved_csv_root(int source, const fs::path& saved_raw, bool manual_saved) {

    const fs::path def = tlalpowa_default_csv_source_root(source);
    fs::path saved = tlalpowa_resolve_project_relative_path(saved_raw);
    if (saved.empty()) return def;

    std::error_code ec;
    const bool exists = fs::exists(saved, ec) && !ec;

    if (!manual_saved) return def;
    if (tlalpowa_csv_path_is_old_atmospheric_auto_root(saved)) return def;
    if (!exists && source >= 0 && source <= 3) return def;
    return saved;
}




