std::string tile_layer_name(TileLayer layer) {

    if (layer == TileLayer::Satellite) return "world_imagery_current_satellite_only_v20260604";

    if (layer == TileLayer::Relief) return "relief_shaded_legacy";

    if (layer == TileLayer::TerrainDem) return "terrain_dem_terrarium_real_m";

    return "osm_standard_attributed";
}





std::string tile_url(TileLayer layer, int z, int x, int y) {


    std::ostringstream url;

    if (layer == TileLayer::Satellite) {


        // Fuente satelital estricta para todos los LOD: no hay retroceso silencioso a OSM.
        // La separación de caché en tile_layer_name fuerza refresco de teselas cuando cambia
        // la política visual, evitando mezclar raster viejo con el modo satelital actual.
        url << "https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/"
            << z << "/" << y << "/" << x;

    } else if (layer == TileLayer::Relief) {




        url << "https://elevation-tiles-prod.s3.amazonaws.com/terrarium/"
            << z << "/" << x << "/" << y << ".png";

    } else if (layer == TileLayer::TerrainDem) {



        url << "https://elevation-tiles-prod.s3.amazonaws.com/terrarium/"

            << z << "/" << x << "/" << y << ".png";
    } else {


        url << "https://tile.openstreetmap.org/" << z << "/" << x << "/" << y << ".png";
    }


    return url.str();
}




fs::path tile_cache_path(TileLayer layer, int z, int x, int y) {

    return map_tile_cache_root() / tile_layer_name(layer) / std::to_string(z) / std::to_string(x) / (std::to_string(y) + ".tile");
}




void prune_map_tile_cache_if_needed() {



    const fs::path root = map_tile_cache_root();
    std::error_code ec;

    if (!fs::exists(root, ec)) return;

    struct Entry {

        fs::path path;
        std::uintmax_t size = 0;

        fs::file_time_type t{};
    };

    std::vector<Entry> files;
    std::uintmax_t total = 0;

    for (fs::recursive_directory_iterator it(root, fs::directory_options::skip_permission_denied, ec), end; it != end && !ec; it.increment(ec)) {

        if (!it->is_regular_file(ec)) continue;


        const std::uintmax_t sz = it->file_size(ec);

        if (ec) { ec.clear(); continue; }
        total += sz;

        files.push_back({it->path(), sz, it->last_write_time(ec)});

        if (ec) ec.clear();
    }

    if (total <= kMapTileCacheSoftLimitBytes) return;

    std::sort(files.begin(), files.end(), [](const Entry& a, const Entry& b) { return a.t < b.t; });

    const std::uintmax_t target = static_cast<std::uintmax_t>(static_cast<double>(kMapTileCacheSoftLimitBytes) * 0.72);

    for (const auto& e : files) {

        if (total <= target) break;

        fs::remove(e.path, ec);

        if (!ec && total >= e.size) total -= e.size;

        ec.clear();
    }
}





std::string wininet_status_text(DWORD status) {


    if (status == 200) return "HTTP 200";


    if (status == 206) return "HTTP 206";


    if (status == 304) return "HTTP 304";


    if (status == 416) return "HTTP 416";


    return "HTTP " + std::to_string(static_cast<unsigned long>(status));
}



