bool tlalpowa_profile_is_mauri(const UiState& ui) {
    const std::string key = normalize_key(tlalpowa_profile_name_from_buffer(ui.user_display_name));
    return key == "mauri" || key == "mauricio" || key == "mauricio isbl" || key == "mauricioisbl";
}

void tlalpowa_apply_github_preference_defaults(UiState& ui) {
    // Politica de distribucion: las instalaciones descargadas reciben el nucleo
    // publicado automaticamente. El perfil del autor queda excluido para evitar
    // que su carpeta de desarrollo se reemplace con su propia publicacion.
    if (!ui.github_auto_update_preference_seen) {
        ui.github_auto_update_enabled = !tlalpowa_profile_is_mauri(ui);
    }
    if (!ui.github_import_data_preference_seen) {
        // El autor local no recibe sobrescritura de Datos por omision; todo otro perfil
        // parte en modo espejo completo para sostener instalaciones reproducibles.
        ui.github_import_data_enabled = !tlalpowa_profile_is_mauri(ui);
    }
}





void save_user_location_state(const UiState& ui) {
    static std::mutex state_file_mutex;
    const std::lock_guard<std::mutex> state_file_lock(state_file_mutex);
    nlohmann::json j;
    bool current_state_valid = false;
    try {

        const fs::path state = app_state_path();

        std::error_code ec;

        if (fs::exists(state, ec) && !ec) {


            const auto parsed = nlohmann::json::parse(read_text_file(state), nullptr, false);


            if (!parsed.is_discarded() && parsed.is_object()) {
                j = parsed;
                current_state_valid = true;
            }
        }
    } catch (...) {}


    if (!j.is_object()) j = nlohmann::json::object();

    const int persisted_language = std::clamp(ui.user_language, 0, 2);
    const int persisted_theme = std::clamp(ui.user_theme_mode, -1, 1);
    const int persisted_gender = std::clamp(ui.user_gender, 0, 3);
    j["perfil_nombre"] = tlalpowa_profile_name_from_buffer(ui.user_display_name);
    j["perfil_idioma"] = persisted_language;
    j["perfil_idioma_clave"] = tlalpowa_language_code(persisted_language);
    j["perfil_genero"] = persisted_gender;
    j["perfil_genero_clave"] = tlalpowa_gender_code(persisted_gender);
    
    j["perfil_tema"] = persisted_theme;
    j["perfil_tema_clave"] = tlalpowa_theme_code(persisted_theme);
    j["tonalli_visible"] = true;
    j["mapa_neblina_manual"] = ui.map_fog_manual;
    j["github_actualizacion_automatica"] = ui.github_auto_update_enabled;
    j["github_actualizacion_automatica_preferencia_guardada"] = ui.github_auto_update_preference_seen;
    j["github_importar_datos"] = ui.github_import_data_enabled;
    j["github_importar_datos_preferencia_guardada"] = ui.github_import_data_preference_seen;
    if (!ui.github_latest_commit_sha.empty()) j["github_ultimo_commit_aplicado"] = ui.github_latest_commit_sha;


    if (!ui.local_pdf_dir.empty()) {


        j["ultima_carpeta_pdf"] = path_utf8(ui.local_pdf_dir);
        j["ultima_fuente_pdf"] = ui.import_pdf_source;
        j["ultima_carpeta_pdf_es_manual"] = ui.pdf_dir_custom;
    }


    if (!ui.local_csv_dir.empty()) {


        j["ultima_carpeta_csv"] = tlalpowa_persist_local_path_utf8(ui.local_csv_dir);
        j["ultima_carpeta_csv_es_manual"] = ui.csv_dir_custom;


        j["ultima_fuente_csv"] = ui.import_csv_source;

        j["atmosfera_anio_inicio"] = ui.atmosphere_year_start;

        j["atmosfera_anio_fin"] = ui.atmosphere_year_end;
    }

    if (!ui.local_satellite_dir.empty()) {

        j["ultima_carpeta_satelital"] = path_utf8(ui.local_satellite_dir);

        j["ultima_fuente_satelital"] = ui.import_satellite_source;
        j["ultima_carpeta_satelital_es_manual"] = ui.satellite_dir_custom;

        j["satelital_anio_inicio"] = ui.satellite_year_start;

        j["satelital_anio_fin"] = ui.satellite_year_end;
    }


    if (!ui.local_external_dir.empty()) {


        j["ultima_carpeta_fuente_datos"] = path_utf8(ui.local_external_dir);
        j["ultima_fuente_datos"] = ui.external_source;
        j["ultima_carpeta_fuente_datos_es_manual"] = ui.external_dir_custom;

        j["fuente_datos_desde_web"] = ui.external_from_web;


        j["fuente_datos_anio_inicio"] = ui.external_year_start;


        j["fuente_datos_anio_fin"] = ui.external_year_end;
    }


    try {
        const fs::path state = app_state_path();
        const fs::path backup = fs::path(state.wstring() + L".bak");
        std::error_code ec;
        if (current_state_valid && fs::exists(state, ec) && !ec) {
            fs::copy_file(state, backup, fs::copy_options::overwrite_existing, ec);
        }
        (void)write_text_file_atomic(state, j.dump(2) + "\n");
    } catch (...) {}
}



void load_user_location_state(UiState& ui) {
    try {

        fs::path state = app_state_path();
        std::error_code ec;

        if (!fs::exists(state, ec) || ec) {
            ec.clear();
            const fs::path backup = fs::path(state.wstring() + L".bak");
            if (!fs::exists(backup, ec) || ec) return;
            state = backup;
        }


        auto j = nlohmann::json::parse(read_text_file(state), nullptr, false);

        if (j.is_discarded() || !j.is_object()) {
            const fs::path backup = fs::path(app_state_path().wstring() + L".bak");
            ec.clear();
            if (state != backup && fs::exists(backup, ec) && !ec) {
                j = nlohmann::json::parse(read_text_file(backup), nullptr, false);
            }
        }
        if (j.is_discarded() || !j.is_object()) return;

        if (j.contains("perfil_nombre") && j["perfil_nombre"].is_string()) {
            tlalpowa_copy_profile_name(ui.user_display_name, j["perfil_nombre"].get<std::string>());
        }
        if (j.contains("perfil_idioma") && j["perfil_idioma"].is_number_integer()) {
            ui.user_language = std::clamp(j["perfil_idioma"].get<int>(), 0, 2);
        }
        if (j.contains("perfil_tema") && j["perfil_tema"].is_number_integer()) {
            ui.user_theme_mode = std::clamp(j["perfil_tema"].get<int>(), -1, 1);
        } else if (j.contains("perfil_tema_clave") && j["perfil_tema_clave"].is_string()) {
            const std::string theme_key = normalize_key(j["perfil_tema_clave"].get<std::string>());
            if (theme_key == "sistema" || theme_key == "system" || theme_key == "igual que el sistema") ui.user_theme_mode = -1;
            else if (theme_key == "oscuro" || theme_key == "dark") ui.user_theme_mode = 1;
            else if (theme_key == "claro" || theme_key == "light") ui.user_theme_mode = 0;
        }
        if (j.contains("perfil_genero") && j["perfil_genero"].is_number_integer()) {
            ui.user_gender = std::clamp(j["perfil_genero"].get<int>(), 0, 3);
        } else if (j.contains("perfil_genero_clave") && j["perfil_genero_clave"].is_string()) {
            const std::string gender_key = normalize_key(j["perfil_genero_clave"].get<std::string>());
            if (gender_key == "mujer" || gender_key == "woman" || gender_key == "female") ui.user_gender = 0;
            else if (gender_key == "hombre" || gender_key == "man" || gender_key == "male") ui.user_gender = 3;
            else if (gender_key == "no_binario" || gender_key == "no binario" || gender_key == "non_binary" || gender_key == "non binary") ui.user_gender = 2;
            else ui.user_gender = 1;
        }
        // Tonalli no materializa datos ni dispara streaming: puede nacer visible sin violar
        // el arranque frío de capas científicas. La lectura calendárica es local y constante.
        ui.timeline_show_tonalli = j.value("tonalli_visible", true);
        ui.map_fog_manual = std::clamp(j.value("mapa_neblina_manual", ui.map_fog_manual), -1.0f, 0.72f);
        if (j.contains("github_actualizacion_automatica")) {
            ui.github_auto_update_enabled = j.value("github_actualizacion_automatica", ui.github_auto_update_enabled);
            ui.github_auto_update_preference_seen =
                j.value("github_actualizacion_automatica_preferencia_guardada", true);
        }
        if (j.contains("github_importar_datos")) {
            ui.github_import_data_enabled = j.value("github_importar_datos", ui.github_import_data_enabled);
            ui.github_import_data_preference_seen = j.value("github_importar_datos_preferencia_guardada", true);
        } else {
            ui.github_import_data_preference_seen = false;
        }
        if (j.contains("github_ultimo_commit_aplicado") && j["github_ultimo_commit_aplicado"].is_string()) {
            ui.github_latest_commit_sha = j["github_ultimo_commit_aplicado"].get<std::string>();
        }


        if (j.contains("ultima_fuente_pdf") && j["ultima_fuente_pdf"].is_number_integer()) {
            ui.import_pdf_source = std::clamp(j["ultima_fuente_pdf"].get<int>(), 0, 5);
        }


        if (j.contains("ultima_carpeta_pdf") && j["ultima_carpeta_pdf"].is_string()) {


            fs::path saved = clean_user_path(fs::path(widen_utf8(j["ultima_carpeta_pdf"].get<std::string>())));

            if (!saved.empty()) {

                ui.local_pdf_dir = saved;
                ui.last_saved_pdf_dir = saved;
                ui.pdf_dir_custom = j.value("ultima_carpeta_pdf_es_manual", true);
            }
        }


        if (j.contains("ultima_fuente_csv") && j["ultima_fuente_csv"].is_number_integer()) {


            ui.import_csv_source = std::clamp(j["ultima_fuente_csv"].get<int>(), 0, 5);
        }

        if (j.contains("atmosfera_anio_inicio") && j["atmosfera_anio_inicio"].is_number_integer()) {

            ui.atmosphere_year_start = std::clamp(j["atmosfera_anio_inicio"].get<int>(), 1986, 2300);
        }

        if (j.contains("atmosfera_anio_fin") && j["atmosfera_anio_fin"].is_number_integer()) {

            ui.atmosphere_year_end = std::clamp(j["atmosfera_anio_fin"].get<int>(), 1986, 2300);
        }

        if (ui.atmosphere_year_end < ui.atmosphere_year_start) ui.atmosphere_year_end = ui.atmosphere_year_start;


        if (j.contains("ultima_carpeta_csv") && j["ultima_carpeta_csv"].is_string()) {


            fs::path saved = clean_user_path(fs::path(widen_utf8(j["ultima_carpeta_csv"].get<std::string>())));
            const bool manual_saved = j.value("ultima_carpeta_csv_es_manual", false);
            saved = tlalpowa_normalize_saved_csv_root(ui.import_csv_source, saved, manual_saved);

            if (!saved.empty()) {


                ui.local_csv_dir = saved;


                ui.last_saved_csv_dir = saved;


                ui.csv_dir_custom = manual_saved && !tlalpowa_csv_path_is_old_atmospheric_auto_root(saved);
            }
        }

        if (j.contains("ultima_fuente_satelital") && j["ultima_fuente_satelital"].is_number_integer()) {

            ui.import_satellite_source = std::clamp(j["ultima_fuente_satelital"].get<int>(), 0, 4);
        }

        if (j.contains("satelital_anio_inicio") && j["satelital_anio_inicio"].is_number_integer()) {

            ui.satellite_year_start = std::clamp(j["satelital_anio_inicio"].get<int>(), 2004, 2300);
        }

        if (j.contains("satelital_anio_fin") && j["satelital_anio_fin"].is_number_integer()) {

            ui.satellite_year_end = std::clamp(j["satelital_anio_fin"].get<int>(), 2004, 2300);
        }


        if (ui.satellite_year_end < ui.satellite_year_start) ui.satellite_year_end = ui.satellite_year_start;

        if (j.contains("ultima_carpeta_satelital") && j["ultima_carpeta_satelital"].is_string()) {

            fs::path saved = clean_user_path(fs::path(widen_utf8(j["ultima_carpeta_satelital"].get<std::string>())));

            if (!saved.empty()) {
                ui.local_satellite_dir = saved;

                ui.last_saved_satellite_dir = saved;
                ui.satellite_dir_custom = j.value("ultima_carpeta_satelital_es_manual", true);
            }
        }

        if (j.contains("ultima_fuente_datos") && j["ultima_fuente_datos"].is_number_integer()) {

            ui.external_source = std::clamp(j["ultima_fuente_datos"].get<int>(), 0, 128);
        }
        ui.external_from_web = j.value("fuente_datos_desde_web", ui.external_from_web);

        if (j.contains("fuente_datos_anio_inicio") && j["fuente_datos_anio_inicio"].is_number_integer()) {


            ui.external_year_start = std::clamp(j["fuente_datos_anio_inicio"].get<int>(), 1800, 2300);
        }

        if (j.contains("fuente_datos_anio_fin") && j["fuente_datos_anio_fin"].is_number_integer()) {


            ui.external_year_end = std::clamp(j["fuente_datos_anio_fin"].get<int>(), 1800, 2300);
        }


        if (ui.external_year_end < ui.external_year_start) ui.external_year_end = ui.external_year_start;

        if (j.contains("ultima_carpeta_fuente_datos") && j["ultima_carpeta_fuente_datos"].is_string()) {

            fs::path saved = clean_user_path(fs::path(widen_utf8(j["ultima_carpeta_fuente_datos"].get<std::string>())));

            if (!saved.empty()) {

                ui.local_external_dir = saved;
                ui.last_saved_external_dir = saved;
                ui.external_dir_custom = j.value("ultima_carpeta_fuente_datos_es_manual", true);
            }
        }
    } catch (...) {}
}




bool download_url_to_file(const std::string& url, const fs::path& destination,
                          std::uintmax_t minimum_bytes = 256,
                          int max_attempts = 3,
                          bool allow_resume = true) {
#ifdef _WIN32

    ensure_dir(destination.parent_path());


    const fs::path partial = fs::path(destination.wstring() + L".download");


    const std::wstring wurl = widen_utf8(url);
    const std::wstring ua = L"Tlalpowa/2026 descargas-paralelas-atomicas-cacheadas";
    std::error_code ec;


    configure_wininet_parallelism_once();


    const DWORD buffer_bytes = download_buffer_size_bytes();


    const DWORD connect_timeout_ms = static_cast<DWORD>(download_env_int_local("TLALPOWA_DOWNLOAD_CONNECT_TIMEOUT_MS", 650, 250, 30000));


    const DWORD read_timeout_ms = static_cast<DWORD>(download_env_int_local("TLALPOWA_DOWNLOAD_READ_TIMEOUT_MS", 1200, 450, 120000));


    const int default_attempts = download_env_flag_enabled_local("TLALPOWA_DOWNLOAD_AGGRESSIVE_FAST_MODE", true) ? 1 : max_attempts;


    const int effective_max_attempts = download_env_int_local("TLALPOWA_DOWNLOAD_MAX_ATTEMPTS", default_attempts, 1, 8);




    const std::string bulk_url_norm = normalize_key(url);


    const bool official_bulk_download =


        bulk_url_norm.find("datosabiertos.aire.cdmx.gob.mx") != std::string::npos ||


        bulk_url_norm.find("aire.cdmx.gob.mx") != std::string::npos ||


        bulk_url_norm.find("sersalud.cdmx.gob.mx") != std::string::npos ||


        bulk_url_norm.find("ddsisem.edomex.gob.mx") != std::string::npos ||


        bulk_url_norm.find("datos.cdmx.gob.mx") != std::string::npos ||


        bulk_url_norm.find("archivo.datos.cdmx.gob.mx") != std::string::npos;


    if (official_bulk_download || download_env_flag_enabled_local("TLALPOWA_USE_CURL_FOR_ALL", false)) {


        bool curl_started = false;


        if (download_url_to_file_curl(url, destination, minimum_bytes, allow_resume, &curl_started)) return true;


        if (curl_started && download_env_flag_enabled_local("TLALPOWA_CURL_NO_WININET_FALLBACK", true)) return false;
    }



    for (int attempt = 1; attempt <= std::max(1, effective_max_attempts); ++attempt) {
        HINTERNET hInternet = InternetOpenW(ua.c_str(), INTERNET_OPEN_TYPE_PRECONFIG, nullptr, nullptr, 0);

        if (!hInternet) {


            std::this_thread::sleep_for(std::chrono::milliseconds(160 * attempt + download_retry_jitter_ms(attempt)));
            continue;
        }


        configure_wininet_timeouts(hInternet, connect_timeout_ms, read_timeout_ms);

        std::uintmax_t resume_from = 0;


        if (allow_resume && fs::exists(partial, ec) && !ec) resume_from = file_size_or_zero(partial);

        ec.clear();

        std::wstring headers = L"Accept: application/pdf, application/zip, text/html, */*\r\nCache-Control: no-cache\r\nPragma: no-cache\r\n";

        if (resume_from > 0) headers += L"Range: bytes=" + std::to_wstring(resume_from) + L"-\r\n";



        HINTERNET hFile = InternetOpenUrlW(hInternet, wurl.c_str(),
                                           headers.c_str(),
                                           static_cast<DWORD>(headers.size()),

                                           INTERNET_FLAG_KEEP_CONNECTION | INTERNET_FLAG_NO_UI | INTERNET_FLAG_RELOAD | INTERNET_FLAG_NO_CACHE_WRITE | INTERNET_FLAG_EXISTING_CONNECT, 0);

        if (!hFile) {
            InternetCloseHandle(hInternet);


            std::this_thread::sleep_for(std::chrono::milliseconds(240 * attempt + download_retry_jitter_ms(attempt)));
            continue;
        }


        configure_wininet_timeouts(hFile, connect_timeout_ms, read_timeout_ms);

        DWORD status = 0;
        DWORD status_len = sizeof(status);


        if (!HttpQueryInfoW(hFile, HTTP_QUERY_STATUS_CODE | HTTP_QUERY_FLAG_NUMBER, &status, &status_len, nullptr)) status = 200;

        if (resume_from > 0 && status == 200) {


            InternetCloseHandle(hFile);
            InternetCloseHandle(hInternet);
            fs::remove(partial, ec);

            ec.clear();


            std::this_thread::sleep_for(std::chrono::milliseconds(180));
            --attempt;

            continue;
        }

        if (status == 416 && resume_from >= minimum_bytes) {



            InternetCloseHandle(hFile);
            InternetCloseHandle(hInternet);


            if (atomic_promote_file(partial, destination)) return true;


            std::this_thread::sleep_for(std::chrono::milliseconds(180 + download_retry_jitter_ms(attempt)));
            continue;
        }

        if (!(status == 200 || status == 206)) {

            InternetCloseHandle(hFile);
            InternetCloseHandle(hInternet);
            const bool deterministic_miss = (status == 400 || status == 401 || status == 403 || status == 404 || status == 410);


            if (deterministic_miss && download_env_flag_enabled_local("TLALPOWA_HTTP_FAST_FAIL", true)) {

                return false;
            }


            std::this_thread::sleep_for(std::chrono::milliseconds(180 * attempt + download_retry_jitter_ms(attempt)));

            continue;
        }


        const std::uintmax_t body_len = query_content_length(hFile);
        const std::uintmax_t expected_total = body_len > 0 ? (status == 206 ? resume_from + body_len : body_len) : 0;


        std::ofstream out(partial, std::ios::binary | (status == 206 ? std::ios::app : std::ios::trunc));

        if (!out) {

            InternetCloseHandle(hFile);
            InternetCloseHandle(hInternet);


            std::this_thread::sleep_for(std::chrono::milliseconds(260 * attempt + download_retry_jitter_ms(attempt)));
            continue;
        }


        std::vector<char> buffer(static_cast<size_t>(std::max<DWORD>(65536, buffer_bytes)));

        DWORD read = 0;
        bool ok = true;

        while (InternetReadFile(hFile, buffer.data(), static_cast<DWORD>(buffer.size()), &read)) {

            if (read == 0) break;

            out.write(buffer.data(), read);

            if (!out) { ok = false; break; }
        }

        out.close();

        InternetCloseHandle(hFile);
        InternetCloseHandle(hInternet);



        const std::uintmax_t got = file_size_or_zero(partial);
        const bool enough = got >= minimum_bytes;
        const bool complete_by_size = expected_total == 0 || got >= expected_total;

        if (ok && enough && complete_by_size) {


            if (atomic_promote_file(partial, destination)) return true;
        }


        std::this_thread::sleep_for(std::chrono::milliseconds(360 * attempt + download_retry_jitter_ms(attempt)));
    }


    return false;
#else


    (void)url;
    (void)destination;
    (void)minimum_bytes;

    (void)max_attempts;
    (void)allow_resume;

    return false;
#endif

}




bool strong_zip_validation(const fs::path& p, std::uintmax_t min_bytes);
std::vector<std::pair<std::string, std::wstring>> zip_extract_commands_for_windows(const fs::path& zip_path, const fs::path& staging);

fs::path tlalpowa_github_update_root() {
    return build_runtime_root() / "github_update";
}

fs::path tlalpowa_github_update_state_path() {
    return tlalpowa_github_update_root() / "github_update_state.json";
}

std::string tlalpowa_github_repo_api_commit_url(const char* branch) {
    return std::string("https://api.github.com/repos/mauricioisbl/Tlalpowa/commits/") + branch;
}

std::string tlalpowa_github_repo_zip_url(const std::string& sha_or_branch) {
    const std::string ref = sha_or_branch.empty() ? std::string("main") : sha_or_branch;
    return "https://github.com/mauricioisbl/Tlalpowa/archive/" + ref + ".zip";
}

std::string tlalpowa_parse_github_commit_sha(const fs::path& json_path) {
    try {
        const auto j = nlohmann::json::parse(read_text_file(json_path), nullptr, false);
        if (!j.is_discarded() && j.is_object()) {
            if (j.contains("sha") && j["sha"].is_string()) {
                std::string sha = j["sha"].get<std::string>();
                if (sha.size() >= 7 && sha.size() <= 64) return sha;
            }
            auto commit_it = j.find("commit");
            if (commit_it != j.end() && commit_it->is_object()) {
                auto tree_it = commit_it->find("tree");
                if (tree_it != commit_it->end() && tree_it->is_object()) {
                    auto sha_it = tree_it->find("sha");
                    if (sha_it != tree_it->end() && sha_it->is_string()) return sha_it->get<std::string>();
                }
            }
        }
    } catch (...) {}
    return {};
}

std::string tlalpowa_read_last_applied_github_sha() {
    try {
        const fs::path applied_txt = tlalpowa_github_update_root() / "ultimo_commit_aplicado.txt";
        std::error_code ec;
        if (fs::exists(applied_txt, ec) && !ec) {
            std::string s = trim(read_text_file(applied_txt));
            if (s.size() >= 7 && s.size() <= 64) return s;
        }
        const fs::path state = tlalpowa_github_update_state_path();
        if (!fs::exists(state, ec) || ec) return {};
        const auto j = nlohmann::json::parse(read_text_file(state), nullptr, false);
        if (!j.is_discarded() && j.is_object() && j.contains("ultimo_commit_aplicado") && j["ultimo_commit_aplicado"].is_string()) {
            return j["ultimo_commit_aplicado"].get<std::string>();
        }
    } catch (...) {}
    return {};
}

void tlalpowa_write_last_applied_github_sha(const std::string& sha, bool import_data) {
    nlohmann::json j = nlohmann::json::object();
    j["ultimo_commit_preparado"] = sha;
    j["importar_datos"] = import_data;
    j["utc"] = now_utc_iso();
    (void)write_text_file_atomic(tlalpowa_github_update_state_path(), j.dump(2) + "\n");
}

std::string tlalpowa_fetch_latest_github_sha() {
    const fs::path tmp = tlalpowa_github_update_root() / "commit.json";
    std::error_code ec;
    fs::remove(tmp, ec);
    if (download_url_to_file(tlalpowa_github_repo_api_commit_url("main"), tmp, 32, 2, false)) {
        std::string sha = tlalpowa_parse_github_commit_sha(tmp);
        if (!sha.empty()) return sha;
    }
    fs::remove(tmp, ec);
    if (download_url_to_file(tlalpowa_github_repo_api_commit_url("master"), tmp, 32, 2, false)) {
        return tlalpowa_parse_github_commit_sha(tmp);
    }
    return {};
}

bool tlalpowa_find_repo_root_after_extract(const fs::path& staging, fs::path& out_root) {
    std::error_code ec;
    if (!fs::exists(staging, ec) || ec) return false;
    auto looks_repo = [](const fs::path& d) {
        std::error_code ec2;
        return fs::exists(d / "Fuente", ec2) && fs::exists(d / "CMakeLists.txt", ec2);
    };
    if (looks_repo(staging)) { out_root = staging; return true; }
    for (const auto& e : fs::directory_iterator(staging, ec)) {
        if (ec) break;
        if (!e.is_directory(ec)) continue;
        if (looks_repo(e.path())) { out_root = e.path(); return true; }
    }
    for (const auto& e : fs::recursive_directory_iterator(staging, fs::directory_options::skip_permission_denied, ec)) {
        if (ec) break;
        if (!e.is_directory(ec)) continue;
        if (looks_repo(e.path())) { out_root = e.path(); return true; }
    }
    return false;
}

bool tlalpowa_extract_github_zip(const fs::path& zip_path, const fs::path& staging) {
#ifdef _WIN32
    std::error_code ec;
    fs::remove_all(staging, ec);
    ensure_dir(staging);
    const auto commands = zip_extract_commands_for_windows(zip_path, staging);
    for (const auto& [name, cmd] : commands) {
        (void)name;
        const int rc = run_process_timeout_no_console(cmd, 180000);
        if (rc == 0) {
            fs::path repo_root;
            if (tlalpowa_find_repo_root_after_extract(staging, repo_root)) return true;
        }
    }
    return false;
#else
    (void)zip_path;
    (void)staging;
    return false;
#endif
}

bool tlalpowa_spawn_detached_script(const fs::path& script) {
#ifdef _WIN32
    std::wstring cmd = L"cmd.exe /D /C start \"\" /MIN " + quote_windows_arg(script.wstring());
    STARTUPINFOW si{};
    PROCESS_INFORMATION pi{};
    si.cb = sizeof(si);
    si.dwFlags = STARTF_USESHOWWINDOW;
    si.wShowWindow = SW_HIDE;
    std::vector<wchar_t> mutable_cmd(cmd.begin(), cmd.end());
    mutable_cmd.push_back(L'\0');
    BOOL ok = CreateProcessW(nullptr, mutable_cmd.data(), nullptr, nullptr, FALSE, CREATE_NO_WINDOW, nullptr, nullptr, &si, &pi);
    if (!ok) return false;
    CloseHandle(pi.hThread);
    CloseHandle(pi.hProcess);
    return true;
#else
    (void)script;
    return false;
#endif
}

std::string tlalpowa_cmd_escape_percent(std::string s) {
    std::string out;
    out.reserve(s.size() + 8);
    for (char c : s) {
        if (c == '%') out += "%%";
        else out.push_back(c);
    }
    return out;
}

bool tlalpowa_write_apply_github_update_script(const fs::path& repo_root,
                                               const fs::path& base_root,
                                               const std::string& sha,
                                               bool import_data,
                                               fs::path& script_path) {
#ifdef _WIN32
    const fs::path upd = tlalpowa_github_update_root();
    ensure_dir(upd);
    script_path = upd / "Aplicar_Actualizacion_Tlalpowa.cmd";
    const std::string src = tlalpowa_cmd_escape_percent(path_utf8(repo_root));
    const std::string dst = tlalpowa_cmd_escape_percent(path_utf8(base_root));
    const std::string sha_safe = safe_filename(sha).substr(0, 64);
    std::ostringstream cmd;
    cmd << "@echo off\r\n";
    cmd << "setlocal EnableExtensions DisableDelayedExpansion\r\n";
    cmd << "chcp 65001 >nul\r\n";
    cmd << "set \"SRC=" << src << "\"\r\n";
    cmd << "set \"DST=" << dst << "\"\r\n";
    cmd << "set \"SHA=" << sha_safe << "\"\r\n";
    cmd << "set \"UPD=%DST%\\Build\\runtime\\github_update\"\r\n";
    cmd << "if not exist \"%UPD%\" mkdir \"%UPD%\" >nul 2>nul\r\n";
    cmd << "set \"LOG=%UPD%\\aplicar_%SHA%.log\"\r\n";
    cmd << "set \"STAGED_FLAG=%UPD%\\actualizacion_%SHA%.preparada\"\r\n";
    cmd << "set \"APPLIED_FLAG=%UPD%\\actualizacion_%SHA%.aplicada\"\r\n";
    cmd << "echo [Tlalpowa] Aplicador GitHub %DATE% %TIME%>%LOG%\r\n";
    cmd << "echo [Tlalpowa] SRC=%SRC%>>%LOG%\r\n";
    cmd << "echo [Tlalpowa] DST=%DST%>>%LOG%\r\n";
    cmd << "echo preparado>%STAGED_FLAG%\r\n";
    cmd << "if not exist \"%SRC%\\tlalpowa_actualizacion_manifest.json\" (echo [error] Falta manifiesto incremental>>%LOG% & exit /b 12)\r\n";
    cmd << "if exist \"%SRC%\\Tlalpowa.exe\" (echo [ok] Delta trae Tlalpowa.exe>>%LOG%) else (echo [ok] Tlalpowa.exe no cambio>>%LOG%)\r\n";
    cmd << "if not exist \"%DST%\" mkdir \"%DST%\" >nul 2>nul\r\n";
    cmd << "set /a WAIT=0\r\n";
    cmd << ":esperar_tlalpowa\r\n";
    cmd << "tasklist /FI \"IMAGENAME eq Tlalpowa.exe\" 2>nul | find /I \"Tlalpowa.exe\" >nul\r\n";
    cmd << "if not errorlevel 1 (set /a WAIT+=1 & if %WAIT% GEQ 900 (echo [error] Tlalpowa.exe no libero despues de 15 min>>%LOG% & exit /b 40) & timeout /t 1 /nobreak >nul & goto esperar_tlalpowa)\r\n";
    cmd << "set \"BACKUP=%UPD%\\backup_%SHA%\"\r\n";
    cmd << "if exist \"%BACKUP%\" rmdir /S /Q \"%BACKUP%\" >>%LOG% 2>&1\r\n";
    cmd << "mkdir \"%BACKUP%\" >>%LOG% 2>&1\r\n";
    cmd << "for %%F in (Tlalpowa.exe CMakeLists.txt Compilar_Tlalpowa.cmd Procesar_Iconos_Tlalpowa.cmd Publicar_Tlalpowa.cmd Instalar_Dependencias_Globales_Tlalpowa.cmd) do if exist \"%DST%\\%%F\" copy /Y \"%DST%\\%%F\" \"%BACKUP%\\%%F\" >>%LOG% 2>&1\r\n";
    cmd << "if exist \"%DST%\\Fuente\" robocopy \"%DST%\\Fuente\" \"%BACKUP%\\Fuente\" /MIR /R:1 /W:1 /NFL /NDL /NP /NJH /NJS >>%LOG% 2>&1\r\n";
    cmd << "if exist \"%SRC%\\tlalpowa_actualizacion_eliminados.txt\" for /F \"usebackq delims=\" %%R in (\"%SRC%\\tlalpowa_actualizacion_eliminados.txt\") do if exist \"%DST%\\%%R\" (for %%P in (\"%BACKUP%\\%%R\") do if not exist \"%%~dpP\" mkdir \"%%~dpP\" >nul 2>nul & copy /Y \"%DST%\\%%R\" \"%BACKUP%\\%%R\" >>%LOG% 2>&1)\r\n";
    cmd << "echo [Tlalpowa] Copiando solo archivos modificados del nucleo...>>%LOG%\r\n";
    cmd << "robocopy \"%SRC%\" \"%DST%\" /E /R:5 /W:1 /COPY:DAT /DCOPY:DAT /XJ /XD .git Build .vs .idea .vscode __pycache__ Datos /XF *.user *.suo github_update_state.json ultimo_commit_aplicado.txt tlalpowa_actualizacion_eliminados.txt >>%LOG% 2>&1\r\n";
    cmd << "set \"RC=%ERRORLEVEL%\"\r\n";
    cmd << "if %RC% GEQ 8 (echo [error] Robocopy nucleo RC=%RC%>>%LOG% & call :rollback & exit /b %RC%)\r\n";
    cmd << "for %%F in (\"%DST%\\*.ico\" \"%DST%\\*.png\") do if exist %%~fF (echo [Tlalpowa] Eliminando raster prohibido de base: %%~nxF>>%LOG% & del /F /Q %%~fF >>%LOG% 2>&1)\r\n";
    if (import_data) {
        cmd << "if not exist \"%SRC%\\Datos\" goto datos_snapshot_ausente\r\n";
        cmd << "echo [Tlalpowa] Copiando solo archivos modificados de Datos...>>%LOG%\r\n";
        cmd << "robocopy \"%SRC%\\Datos\" \"%DST%\\Datos\" /E /R:5 /W:1 /COPY:DAT /DCOPY:DAT /XJ /NFL /NDL /NP /NJH /NJS >>%LOG% 2>&1\r\n";
        cmd << "set \"RC=%ERRORLEVEL%\"\r\n";
        cmd << "if %RC% GEQ 8 (echo [error] Robocopy Datos RC=%RC%>>%LOG% & call :rollback & exit /b %RC%)\r\n";
        cmd << "goto datos_sincronizados\r\n";
        cmd << ":datos_snapshot_ausente\r\n";
        cmd << "echo [aviso] Snapshot sin Datos; no se toca Datos local>>%LOG%\r\n";
        cmd << ":datos_sincronizados\r\n";
    } else {
        cmd << "echo [Tlalpowa] Datos locales preservados por preferencia del usuario.>>%LOG%\r\n";
    }
    cmd << "if exist \"%SRC%\\tlalpowa_actualizacion_eliminados.txt\" for /F \"usebackq delims=\" %%R in (\"%SRC%\\tlalpowa_actualizacion_eliminados.txt\") do if exist \"%DST%\\%%R\" (echo [Tlalpowa] Eliminando archivo retirado: %%R>>%LOG% & del /F /Q \"%DST%\\%%R\" >>%LOG% 2>&1)\r\n";
    cmd << "if exist \"%SRC%\\Tlalpowa.exe\" if not exist \"%DST%\\Tlalpowa.exe\" (echo [error] El exe nuevo no quedo en destino>>%LOG% & call :rollback & exit /b 41)\r\n";
    cmd << "if exist \"%DST%\\Tlalpowa.exe\" (assoc .ixiptlah=Tlalpowa.Ixiptlah >>%LOG% 2>&1 & ftype Tlalpowa.Ixiptlah=\"%DST%\\Tlalpowa.exe\" \"%%1\" >>%LOG% 2>&1)\r\n";
    cmd << "echo %SHA%>\"%UPD%\\ultimo_commit_aplicado.txt\"\r\n";
    cmd << "echo {\"ultimo_commit_aplicado\":\"%SHA%\",\"importar_datos\":" << (import_data ? "true" : "false") << ",\"aplicado\":true}>\"%UPD%\\github_update_state.json\"\r\n";
    cmd << "echo aplicada>%APPLIED_FLAG%\r\n";
    cmd << "echo [Tlalpowa] Actualizacion aplicada correctamente.>>%LOG%\r\n";
    cmd << "exit /b 0\r\n";
    cmd << ":rollback\r\n";
    cmd << "echo [Tlalpowa] Intentando rollback defensivo...>>%LOG%\r\n";
    cmd << "if exist \"%BACKUP%\" robocopy \"%BACKUP%\" \"%DST%\" /E /R:1 /W:1 /NFL /NDL /NP /NJH /NJS >>%LOG% 2>&1\r\n";
    cmd << "exit /b 0\r\n";
    return write_text_file_atomic(script_path, cmd.str());
#else
    (void)repo_root; (void)base_root; (void)sha; (void)import_data; (void)script_path;
    return false;
#endif
}

struct TlalpowaUpdateManifestEntry {
    std::string path;
    std::string sha256;
    std::uintmax_t size = 0;
    bool data = false;
};

bool tlalpowa_safe_update_relative_path(const std::string& value) {
    if (value.empty() || value.front() == '/' || value.front() == '\\') return false;
    const fs::path p = fs::path(widen_utf8(value)).lexically_normal();
    if (p.is_absolute()) return false;
    for (const auto& part : p) {
        if (part == L"..") return false;
    }
    return true;
}

std::vector<TlalpowaUpdateManifestEntry> tlalpowa_read_update_manifest(const fs::path& path) {
    std::vector<TlalpowaUpdateManifestEntry> out;
    try {
        const auto j = nlohmann::json::parse(read_text_file(path), nullptr, false);
        if (j.is_discarded() || !j.is_object() || j.value("schema", 0) != 1) return out;
        auto files = j.find("files");
        if (files == j.end() || !files->is_array()) return out;
        for (const auto& item : *files) {
            if (!item.is_object()) continue;
            TlalpowaUpdateManifestEntry entry;
            entry.path = item.value("path", std::string{});
            entry.sha256 = lowercase_ascii(item.value("sha256", std::string{}));
            entry.size = item.value("size", static_cast<std::uintmax_t>(0));
            entry.data = item.value("data", false);
            if (!tlalpowa_safe_update_relative_path(entry.path) || entry.sha256.size() != 64) {
                out.clear();
                return out;
            }
            out.push_back(std::move(entry));
        }
    } catch (...) {
        out.clear();
    }
    return out;
}

std::string tlalpowa_sha256_file(const fs::path& path) {
#ifdef _WIN32
    std::ifstream in(path, std::ios::binary);
    if (!in) return {};
    BCRYPT_ALG_HANDLE algorithm = nullptr;
    BCRYPT_HASH_HANDLE hash = nullptr;
    DWORD object_size = 0;
    DWORD hash_size = 0;
    DWORD result_size = 0;
    std::vector<unsigned char> object;
    std::vector<unsigned char> digest;
    auto cleanup = [&]() {
        if (hash) BCryptDestroyHash(hash);
        if (algorithm) BCryptCloseAlgorithmProvider(algorithm, 0);
    };
    if (BCryptOpenAlgorithmProvider(&algorithm, BCRYPT_SHA256_ALGORITHM, nullptr, 0) < 0 ||
        BCryptGetProperty(algorithm, BCRYPT_OBJECT_LENGTH, reinterpret_cast<PUCHAR>(&object_size),
                          sizeof(object_size), &result_size, 0) < 0 ||
        BCryptGetProperty(algorithm, BCRYPT_HASH_LENGTH, reinterpret_cast<PUCHAR>(&hash_size),
                          sizeof(hash_size), &result_size, 0) < 0) {
        cleanup();
        return {};
    }
    object.resize(object_size);
    digest.resize(hash_size);
    if (BCryptCreateHash(algorithm, &hash, object.data(), object_size, nullptr, 0, 0) < 0) {
        cleanup();
        return {};
    }
    std::array<unsigned char, 1024 * 1024> buffer{};
    while (in) {
        in.read(reinterpret_cast<char*>(buffer.data()), static_cast<std::streamsize>(buffer.size()));
        const std::streamsize got = in.gcount();
        if (got > 0 && BCryptHashData(hash, buffer.data(), static_cast<ULONG>(got), 0) < 0) {
            cleanup();
            return {};
        }
    }
    if (in.bad() || BCryptFinishHash(hash, digest.data(), hash_size, 0) < 0) {
        cleanup();
        return {};
    }
    cleanup();
    static constexpr char hex[] = "0123456789abcdef";
    std::string result;
    result.reserve(digest.size() * 2);
    for (unsigned char byte : digest) {
        result.push_back(hex[byte >> 4]);
        result.push_back(hex[byte & 0x0f]);
    }
    return result;
#else
    (void)path;
    return {};
#endif
}

std::string tlalpowa_github_raw_path_url(const std::string& ref, const std::string& relative_path) {
    std::ostringstream out;
    out << "https://raw.githubusercontent.com/mauricioisbl/Tlalpowa/" << ref << "/";
    static constexpr char hex[] = "0123456789ABCDEF";
    for (unsigned char c : relative_path) {
        if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
            (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.' || c == '/') {
            out << static_cast<char>(c);
        } else {
            out << '%' << hex[c >> 4] << hex[c & 0x0f];
        }
    }
    return out.str();
}

bool tlalpowa_prepare_and_schedule_github_update(const std::string& sha,
                                                 bool import_data,
                                                 std::string& status) {
#ifdef _WIN32
    const fs::path upd = tlalpowa_github_update_root();
    ensure_dir(upd);
    const std::string ref = sha.empty() ? std::string("main") : sha;
    const fs::path remote_manifest = upd / ("manifest_" + safe_filename(ref).substr(0, 16) + ".json");
    std::error_code ec;
    fs::remove(remote_manifest, ec);
    if (!download_url_to_file(tlalpowa_github_raw_path_url(ref, "tlalpowa_actualizacion_manifest.json"),
                              remote_manifest, 32, 3, false)) {
        status = "No pude descargar el manifiesto incremental de GitHub";
        return false;
    }
    const auto remote_entries = tlalpowa_read_update_manifest(remote_manifest);
    if (remote_entries.empty()) {
        status = "El manifiesto incremental de GitHub no es valido";
        return false;
    }

    const fs::path base = research_root();
    const fs::path local_manifest = base / "tlalpowa_actualizacion_manifest.json";
    const auto old_entries = tlalpowa_read_update_manifest(local_manifest);
    std::unordered_map<std::string, TlalpowaUpdateManifestEntry> remote_by_path;
    for (const auto& entry : remote_entries) remote_by_path[entry.path] = entry;

    const fs::path staging = upd / ("delta_" + safe_filename(ref).substr(0, 16));
    fs::remove_all(staging, ec);
    ensure_dir(staging);
    std::size_t changed_count = 0;
    std::uintmax_t download_bytes = 0;
    for (const auto& entry : remote_entries) {
        if (entry.data && !import_data) continue;
        const fs::path local = base / fs::path(widen_utf8(entry.path));
        bool current = false;
        ec.clear();
        if (fs::exists(local, ec) && !ec && fs::is_regular_file(local, ec) && !ec &&
            file_size_or_zero(local) == entry.size) {
            current = tlalpowa_sha256_file(local) == entry.sha256;
        }
        if (current) continue;
        const fs::path target = staging / fs::path(widen_utf8(entry.path));
        ensure_dir(target.parent_path());
        if (!download_url_to_file(tlalpowa_github_raw_path_url(ref, entry.path), target, 0, 3, false) ||
            file_size_or_zero(target) != entry.size ||
            tlalpowa_sha256_file(target) != entry.sha256) {
            status = "Fallo la descarga o verificacion de: " + entry.path;
            return false;
        }
        ++changed_count;
        download_bytes += entry.size;
    }

    std::ostringstream deleted;
    for (const auto& old : old_entries) {
        if (old.data && !import_data) continue;
        if (remote_by_path.find(old.path) == remote_by_path.end()) deleted << old.path << "\n";
    }
    (void)write_text_file_atomic(staging / "tlalpowa_actualizacion_eliminados.txt", deleted.str());
    if (!copy_file_atomic(remote_manifest, staging / "tlalpowa_actualizacion_manifest.json")) {
        status = "No pude preparar el manifiesto incremental local";
        return false;
    }

    fs::path script;
    if (!tlalpowa_write_apply_github_update_script(staging, base, ref, import_data, script)) {
        status = "No pude preparar el aplicador atomico de GitHub";
        return false;
    }
    tlalpowa_write_last_applied_github_sha(ref, import_data);
    if (!tlalpowa_spawn_detached_script(script)) {
        status = "Actualizacion descargada, pero no pude lanzar el aplicador";
        return false;
    }
    status = "Actualizacion incremental preparada: " + std::to_string(changed_count) +
             " archivo(s), " + std::to_string(download_bytes) +
             " bytes descargados; se aplicara al cerrar Tlalpowa";
    return true;
#else
    (void)sha; (void)import_data;
    status = "Actualizacion GitHub disponible solo en Windows por ahora";
    return false;
#endif
}

void tlalpowa_start_github_update_check(UiState& ui, bool manual) {
    {
        std::lock_guard<std::mutex> lock(ui.mu);
        if (ui.github_update_checking) return;
        if (ui.github_update_thread.joinable()) ui.github_update_thread.join();
        ui.github_update_checking = true;
        ui.github_update_status = manual ? "Comprobando GitHub..." : "Comprobando GitHub en segundo plano...";
    }
    const bool import_data = ui.github_import_data_enabled;
    ui.github_update_thread = std::thread([&ui, import_data]() {
#ifdef _WIN32
        SetThreadPriority(GetCurrentThread(), THREAD_MODE_BACKGROUND_BEGIN);
#endif
        std::string final_status;
        std::string latest_sha;
        try {
            latest_sha = tlalpowa_fetch_latest_github_sha();
            if (latest_sha.empty()) {
                final_status = "No pude leer el ultimo commit de GitHub";
            } else {
                const std::string last_sha = tlalpowa_read_last_applied_github_sha();
                if (!last_sha.empty() && last_sha == latest_sha) {
                    final_status = "GitHub sin cambios: " + latest_sha.substr(0, std::min<std::size_t>(12, latest_sha.size()));
                } else {
                    (void)tlalpowa_prepare_and_schedule_github_update(latest_sha, import_data, final_status);
                }
            }
        } catch (const std::exception& e) {
            final_status = std::string("GitHub fallo: ") + e.what();
        } catch (...) {
            final_status = "GitHub fallo por excepcion desconocida";
        }
#ifdef _WIN32
        SetThreadPriority(GetCurrentThread(), THREAD_MODE_BACKGROUND_END);
#endif
        {
            std::lock_guard<std::mutex> lock(ui.mu);
            ui.github_latest_commit_sha = latest_sha;
            ui.github_update_status = final_status;
            ui.github_update_checking = false;
            if (!latest_sha.empty()) save_user_location_state(ui);
        }
    });
}




struct ScopedDownloadFileLock {

    fs::path lock_path;
    bool acquired = false;
#ifdef _WIN32
    HANDLE handle = INVALID_HANDLE_VALUE;
#endif



    explicit ScopedDownloadFileLock(const fs::path& target) {

        lock_path = fs::path(target.wstring() + L".lock");

        ensure_dir(lock_path.parent_path());
#ifdef _WIN32

        const auto try_open = [&]() -> HANDLE {

            return CreateFileW(lock_path.wstring().c_str(), GENERIC_WRITE, 0, nullptr, CREATE_NEW,

                               FILE_ATTRIBUTE_TEMPORARY | FILE_ATTRIBUTE_HIDDEN, nullptr);
        };
        handle = try_open();

        if (handle == INVALID_HANDLE_VALUE) {


            std::error_code ec;

            if (fs::exists(lock_path, ec)) {

                const auto age = fs::file_time_type::clock::now() - fs::last_write_time(lock_path, ec);

                if (!ec && age > std::chrono::minutes(2)) {

                    fs::remove(lock_path, ec);
                    handle = try_open();
                }
            }
        }

        if (handle != INVALID_HANDLE_VALUE) {

            const std::string body = "pid=" + std::to_string(GetCurrentProcessId()) + "\nstarted=" + now_utc_iso() + "\n";
            DWORD written = 0;

            WriteFile(handle, body.data(), static_cast<DWORD>(body.size()), &written, nullptr);
            acquired = true;
        }
#else
        acquired = true;
#endif
    }


    ~ScopedDownloadFileLock() {
#ifdef _WIN32

        if (handle != INVALID_HANDLE_VALUE) CloseHandle(handle);
#endif

        if (acquired) {
            std::error_code ec;

            fs::remove(lock_path, ec);
        }
    }
};




int run_command_no_console(const std::wstring& cmdline, const fs::path& working_dir) {

#ifdef _WIN32
    STARTUPINFOW si{};
    PROCESS_INFORMATION pi{};
    si.cb = sizeof(si);
    si.dwFlags = STARTF_USESHOWWINDOW;
    si.wShowWindow = SW_HIDE;

    std::vector<wchar_t> mutable_cmd(cmdline.begin(), cmdline.end());

    mutable_cmd.push_back(L'\0');
    const DWORD flags = CREATE_NO_WINDOW;


    BOOL ok = CreateProcessW(nullptr, mutable_cmd.data(), nullptr, nullptr, FALSE, flags, nullptr,
                             working_dir.empty() ? nullptr : working_dir.wstring().c_str(), &si, &pi);

    if (!ok) return static_cast<int>(GetLastError());

    WaitForSingleObject(pi.hProcess, INFINITE);
    DWORD code = 0;
    GetExitCodeProcess(pi.hProcess, &code);


    CloseHandle(pi.hThread);
    CloseHandle(pi.hProcess);

    return static_cast<int>(code);
#else
    (void)cmdline;
    (void)working_dir;

    return -1;
#endif
}




void trim_current_process_working_set_soft() {
#ifdef _WIN32

    SetProcessWorkingSetSize(GetCurrentProcess(), static_cast<SIZE_T>(-1), static_cast<SIZE_T>(-1));
#endif
}

void configure_process_memory_budget() {
#ifdef _WIN32
    constexpr SIZE_T kMinWorkingSet = 32ull * 1024ull * 1024ull;
    constexpr SIZE_T kMaxWorkingSet = 448ull * 1024ull * 1024ull;
    constexpr DWORD kHardMaxEnable = 0x00000004u;
    constexpr DWORD kHardMinDisable = 0x00000002u;
    SetProcessWorkingSetSizeEx(GetCurrentProcess(), kMinWorkingSet, kMaxWorkingSet,
                               kHardMaxEnable | kHardMinDisable);
#endif
}


int g_tile_requests_remaining = 0;

int g_tile_texture_loads_remaining = 0;
int g_terrain_requests_remaining = 0;
int g_terrain_loads_remaining = 0;


std::atomic_bool g_osm_boundary_tiles_visible{false};
std::atomic_bool g_map_tile_cache_pinned{false};




void prune_resident_map_textures_locked(std::map<std::string, MapTileTexture>& cache) {



    if (g_map_tile_cache_pinned.load(std::memory_order_relaxed)) return;
    if (cache.size() <= kMaxResidentMapTextures) return;

    std::vector<std::string> keys;

    keys.reserve(cache.size());

    for (const auto& [k, v] : cache) keys.push_back(k);

    std::sort(keys.begin(), keys.end(), [&](const std::string& a, const std::string& b) {

        return cache[a].last_used_frame < cache[b].last_used_frame;
    });

    for (const auto& k : keys) {

        if (cache.size() <= kMaxResidentMapTextures) break;
        auto it = cache.find(k);

        if (it == cache.end()) continue;

        MapTileTexture& t = it->second;

        if (g_map_frame_counter > t.last_used_frame + 4) {

            if (t.id != 0) { glDeleteTextures(1, &t.id); t.id = 0; }
            t.width = 0;
            t.height = 0;

            if (g_map_frame_counter > t.last_used_frame + 240) cache.erase(it);
        }
    }
}




std::mutex& resident_map_tile_mutex() {


    static std::mutex tile_mu;

    return tile_mu;
}



std::map<std::string, MapTileTexture>& resident_map_tile_cache() {

    static std::map<std::string, MapTileTexture> cache;


    return cache;
}




std::atomic<int>& resident_map_active_downloads() {


    static std::atomic<int> active_downloads{0};


    return active_downloads;
}



PreviewTexture load_texture_from_file(const fs::path& path) {

    if (!fs::exists(path)) return {};


    std::ifstream in(path, std::ios::binary);

    if (!in) return {};

    std::vector<unsigned char> bytes((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());

    if (bytes.empty() || bytes.size() > static_cast<size_t>(std::numeric_limits<int>::max())) return {};
    int w = 0, h = 0, channels = 0;

    unsigned char* pixels = stbi_load_from_memory(bytes.data(), static_cast<int>(bytes.size()), &w, &h, &channels, 4);

    if (!pixels || w <= 0 || h <= 0) {

        if (pixels) stbi_image_free(pixels);

        return {};
    }
    unsigned int id = 0;

    glGenTextures(1, &id);

    glBindTexture(GL_TEXTURE_2D, id);

    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);

    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);

    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);

    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);

    glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, w, h, 0, GL_RGBA, GL_UNSIGNED_BYTE, pixels);

    stbi_image_free(pixels);

    return {id, w, h};
}




MapTileTexture& map_tile_texture(TileLayer layer, int z, int x, int y) {


    auto& tile_mu = resident_map_tile_mutex();

    auto& cache = resident_map_tile_cache();


    auto& active_downloads = resident_map_active_downloads();
    const int n = 1 << z;
    const int wrapped_x = ((x % n) + n) % n;

    const std::string key = tile_layer_name(layer) + ":" + std::to_string(z) + ":" + std::to_string(wrapped_x) + ":" + std::to_string(y);


    std::lock_guard<std::mutex> lock(tile_mu);

    auto& tile = cache[key];

    tile.last_used_frame = g_map_frame_counter;

    if ((g_map_frame_counter & 63ull) == 0ull) prune_resident_map_textures_locked(cache);

    if (tile.id == 0) {

        const fs::path path = tile_cache_path(layer, z, wrapped_x, y);

        if (fs::exists(path)) {

            if (g_tile_texture_loads_remaining > 0) {
                std::size_t resident_count = 0u;
                for (const auto& [_, resident] : cache) {
                    if (resident.id != 0) ++resident_count;
                }
                const std::size_t resident_limit = g_map_tile_cache_pinned.load(std::memory_order_relaxed)
                    ? kMaxResidentMapTextures * 2u
                    : kMaxResidentMapTextures;
                if (resident_count >= resident_limit) return tile;

                --g_tile_texture_loads_remaining;

                const PreviewTexture tex = load_texture_from_file(path);

                tile.id = tex.id;

                tile.width = tex.width;

                tile.height = tex.height;

                if (tile.id != 0) {

                    tile.requested = false;

                    if (layer == TileLayer::OpenStreetMap) g_osm_boundary_tiles_visible = true;
                } else {


                    std::error_code rm_ec;

                    fs::remove(path, rm_ec);

                    tile.requested = false;
                }
            }


        } else if (!tile.requested && active_downloads.load() < kMaxConcurrentTileDownloads && g_tile_requests_remaining > 0) {

            --g_tile_requests_remaining;

            tile.requested = true;


            const std::string url = tile_url(layer, z, wrapped_x, y);


            active_downloads.fetch_add(1);


            auto* active_downloads_ptr = &active_downloads;


            std::thread([url, path, active_downloads_ptr]() {


                download_url_to_file(url, path);


                active_downloads_ptr->fetch_sub(1);
            }).detach();
        }
    }

    return tile;
}




struct TerrainTileData {
    bool requested = false;
    bool loaded = false;
    int sample_n = 11;

    std::vector<float> elevation_m;
    float min_elevation_m = 0.0f;
    float max_elevation_m = 0.0f;
    std::uint64_t last_used_frame = 0;
};



void prune_resident_terrain_locked(std::map<std::string, TerrainTileData>& cache) {

    if (cache.size() <= kMaxResidentTerrainTiles) return;

    std::vector<std::string> keys;

    keys.reserve(cache.size());

    for (const auto& [k, v] : cache) keys.push_back(k);

    std::sort(keys.begin(), keys.end(), [&](const std::string& a, const std::string& b) {

        return cache[a].last_used_frame < cache[b].last_used_frame;

    });

    for (const auto& k : keys) {

        if (cache.size() <= kMaxResidentTerrainTiles) break;
        auto it = cache.find(k);

        if (it == cache.end()) continue;

        TerrainTileData& t = it->second;

        if (g_map_frame_counter > t.last_used_frame + 6) {

            t.elevation_m.clear();
            t.elevation_m.shrink_to_fit();
            t.loaded = false;

            if (g_map_frame_counter > t.last_used_frame + 240) cache.erase(it);
        }
    }
}




std::mutex& resident_terrain_mutex() {


    static std::mutex dem_mu;

    return dem_mu;
}



std::map<std::string, TerrainTileData>& resident_terrain_cache() {

    static std::map<std::string, TerrainTileData> cache;

    return cache;
}




std::atomic<int>& resident_terrain_active_downloads() {


    static std::atomic<int> active_downloads{0};


    return active_downloads;
}



void release_map_runtime_memory_for_data_view() {
    {


        std::lock_guard<std::mutex> lock(resident_map_tile_mutex());

        auto& cache = resident_map_tile_cache();

        for (auto& [_, tile] : cache) {

            if (tile.id != 0) {

                glDeleteTextures(1, &tile.id);

                tile.id = 0;
            }

            tile.width = 0;

            tile.height = 0;
        }

        cache.clear();
    }
    {


        std::lock_guard<std::mutex> lock(resident_terrain_mutex());
        auto& cache = resident_terrain_cache();


        for (auto& [_, tile] : cache) {

            tile.elevation_m.clear();

            tile.elevation_m.shrink_to_fit();

            tile.loaded = false;
        }

        cache.clear();
    }

    trim_current_process_working_set_soft();
}




float decode_terrarium_elevation(unsigned char r, unsigned char g, unsigned char b) {

    return static_cast<float>(static_cast<int>(r) * 256 + static_cast<int>(g)) + static_cast<float>(b) / 256.0f - 32768.0f;
}



bool load_terrain_tile_samples(const fs::path& path, TerrainTileData& out) {


    std::ifstream in(path, std::ios::binary);

    if (!in) return false;

    std::vector<unsigned char> bytes((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());

    if (bytes.empty() || bytes.size() > static_cast<size_t>(std::numeric_limits<int>::max())) return false;
    int w = 0, h = 0, channels = 0;

    unsigned char* pixels = stbi_load_from_memory(bytes.data(), static_cast<int>(bytes.size()), &w, &h, &channels, 3);

    if (!pixels || w <= 0 || h <= 0) {

        if (pixels) stbi_image_free(pixels);

        return false;
    }
    const int n = std::max(9, out.sample_n);

    std::vector<float> samples(static_cast<size_t>(n * n), 0.0f);

    float mn = std::numeric_limits<float>::max();
    float mx = -std::numeric_limits<float>::max();

    for (int sy = 0; sy < n; ++sy) {
        const float fy = static_cast<float>(sy) / static_cast<float>(n - 1);
        const int py = std::clamp(static_cast<int>(std::lround(fy * static_cast<float>(h - 1))), 0, h - 1);

        for (int sx = 0; sx < n; ++sx) {
            const float fx = static_cast<float>(sx) / static_cast<float>(n - 1);
            const int px = std::clamp(static_cast<int>(std::lround(fx * static_cast<float>(w - 1))), 0, w - 1);
            const int idx = (py * w + px) * 3;

            const float elev = decode_terrarium_elevation(pixels[idx], pixels[idx + 1], pixels[idx + 2]);
            samples[static_cast<size_t>(sy * n + sx)] = elev;
            mn = std::min(mn, elev);
            mx = std::max(mx, elev);
        }
    }

    stbi_image_free(pixels);
    out.sample_n = n;

    out.elevation_m = std::move(samples);
    out.min_elevation_m = mn == std::numeric_limits<float>::max() ? 0.0f : mn;
    out.max_elevation_m = mx == -std::numeric_limits<float>::max() ? 0.0f : mx;
    out.loaded = true;

    return true;
}




TerrainTileData& terrain_tile_data(int z, int x, int y) {

    auto& dem_mu = resident_terrain_mutex();
    auto& cache = resident_terrain_cache();


    auto& active_downloads = resident_terrain_active_downloads();
    const int n = 1 << z;
    const int wrapped_x = ((x % n) + n) % n;
    const std::string key = std::to_string(z) + ":" + std::to_string(wrapped_x) + ":" + std::to_string(y);


    std::lock_guard<std::mutex> lock(dem_mu);

    auto& tile = cache[key];

    tile.last_used_frame = g_map_frame_counter;

    if ((g_map_frame_counter & 63ull) == 1ull) prune_resident_terrain_locked(cache);

    if (!tile.loaded) {

        const fs::path path = tile_cache_path(TileLayer::TerrainDem, z, wrapped_x, y);

        if (fs::exists(path)) {

            if (g_terrain_loads_remaining > 0) {

                --g_terrain_loads_remaining;

                load_terrain_tile_samples(path, tile);
            }


        } else if (!tile.requested && active_downloads.load() < kMaxConcurrentTileDownloads && g_terrain_requests_remaining > 0) {
            --g_terrain_requests_remaining;

            tile.requested = true;


            const std::string url = tile_url(TileLayer::TerrainDem, z, wrapped_x, y);


            active_downloads.fetch_add(1);


            auto* active_downloads_ptr = &active_downloads;


            std::thread([url, path, active_downloads_ptr]() {


                download_url_to_file(url, path);


                active_downloads_ptr->fetch_sub(1);
            }).detach();
        }
    }

    return tile;
}




