struct GeoBounds {

    double lon_min = 0.0;

    double lon_max = 0.0;

    double lat_min = 0.0;

    double lat_max = 0.0;
    bool valid = false;
};




GeoBounds bounds_for_features(const std::vector<MapFeature>& features) {
    GeoBounds b;

    for (const auto& f : features) {

        for (const auto& ring : f.rings) {

            for (const auto& p : ring) {

                if (!b.valid) {

                    b.lon_min = b.lon_max = p.x;

                    b.lat_min = b.lat_max = p.y;
                    b.valid = true;
                } else {

                    b.lon_min = std::min(b.lon_min, p.x);

                    b.lon_max = std::max(b.lon_max, p.x);

                    b.lat_min = std::min(b.lat_min, p.y);

                    b.lat_max = std::max(b.lat_max, p.y);
                }
            }
        }
    }

    return b;
}





float map_pitch_horizon_y_at_x(const MapViewport& view, float x) {
    (void)x;
    const float pitch = std::clamp(view.pitch, 0.0f, kMapMaxPitch);
    const float cy = view.origin.y + view.size.y * 0.5f;
    const float far_scale = std::clamp(std::cos(pitch * 0.68f), 0.36f, 1.0f);
    return cy - view.size.y * 0.5f * far_scale;
}

