ImVec2 apply_map_pitch_to_screen(const ImVec2& p, const MapViewport& view) {
    const float pitch = std::clamp(view.pitch, 0.0f, kMapMaxPitch);
    if (pitch <= 0.0001f || view.size.y <= 1.0f) return p;
    const float cx = view.origin.x + view.size.x * 0.5f;
    const float cy = view.origin.y + view.size.y * 0.5f;
    const float dy = p.y - cy;
    const float far_scale = std::clamp(std::cos(pitch * 0.68f), 0.36f, 1.0f);
    const float near_scale = 1.0f + pitch * 0.035f;
    const float y_scale = dy < 0.0f ? far_scale : near_scale;
    const float depth = std::clamp(-dy / std::max(1.0f, view.size.y * 0.5f), -1.0f, 1.0f);
    const float x_scale = 1.0f - std::max(0.0f, depth) * pitch * 0.018f;
    return ImVec2(cx + (p.x - cx) * x_scale, cy + dy * y_scale);
}

ImVec2 remove_map_pitch_from_screen(const ImVec2& p, const MapViewport& view) {
    const float pitch = std::clamp(view.pitch, 0.0f, kMapMaxPitch);
    if (pitch <= 0.0001f || view.size.y <= 1.0f) return p;
    const float cx = view.origin.x + view.size.x * 0.5f;
    const float cy = view.origin.y + view.size.y * 0.5f;
    const float projected_dy = p.y - cy;
    const float far_scale = std::clamp(std::cos(pitch * 0.68f), 0.36f, 1.0f);
    const float near_scale = 1.0f + pitch * 0.035f;
    const float flat_dy = projected_dy / (projected_dy < 0.0f ? far_scale : near_scale);
    const float depth = std::clamp(-flat_dy / std::max(1.0f, view.size.y * 0.5f), -1.0f, 1.0f);
    const float x_scale = 1.0f - std::max(0.0f, depth) * pitch * 0.018f;
    return ImVec2(cx + (p.x - cx) / std::max(0.25f, x_scale), cy + flat_dy);
}

struct LocalEnuMeters {
    double east = 0.0;
    double north = 0.0;
    double up = 0.0;
};

Point2 map_pitch_center_lonlat(const MapViewport& view) {
    const double inv_scale = 1.0 / std::max(1.0e-9, static_cast<double>(view.scale));
    return world_px_to_lonlat(view.center_x - static_cast<double>(view.pan.x) * inv_scale,
                              view.center_y - static_cast<double>(view.pan.y) * inv_scale,
                              view.z);
}

LocalEnuMeters local_enu_from_lonlat_wgs84(const Point2& p, const Point2& center, double height_m) {
    constexpr double pi = 3.14159265358979323846;
    constexpr double a = 6378137.0;
    constexpr double inv_f = 298.257223563;
    constexpr double f = 1.0 / inv_f;
    constexpr double e2 = f * (2.0 - f);

    auto ecef = [&](double lon_deg, double lat_deg, double h) {
        const double lon = lon_deg * pi / 180.0;
        const double lat = lat_deg * pi / 180.0;
        const double slat = std::sin(lat);
        const double clat = std::cos(lat);
        const double slon = std::sin(lon);
        const double clon = std::cos(lon);
        const double n = a / std::sqrt(1.0 - e2 * slat * slat);
        return std::array<double, 3>{(n + h) * clat * clon,
                                     (n + h) * clat * slon,
                                     (n * (1.0 - e2) + h) * slat};
    };

    const auto c = ecef(center.x, center.y, 0.0);
    const auto q = ecef(p.x, p.y, height_m);
    const double dx = q[0] - c[0];
    const double dy = q[1] - c[1];
    const double dz = q[2] - c[2];
    const double lon0 = center.x * pi / 180.0;
    const double lat0 = center.y * pi / 180.0;
    const double slon0 = std::sin(lon0);
    const double clon0 = std::cos(lon0);
    const double slat0 = std::sin(lat0);
    const double clat0 = std::cos(lat0);

    LocalEnuMeters out;
    out.east = -slon0 * dx + clon0 * dy;
    out.north = -slat0 * clon0 * dx - slat0 * slon0 * dy + clat0 * dz;
    out.up = clat0 * clon0 * dx + clat0 * slon0 * dy + slat0 * dz;
    return out;
}

ImVec2 project_lonlat_metric_3d(const Point2& p, const MapViewport& view, double height_m = 0.0) {
    const float pitch = std::clamp(view.pitch, 0.0f, kMapMaxPitch);
    const double x = lon_to_world_px(p.x, view.z);
    const double y = lat_to_world_px(p.y, view.z);
    const ImVec2 flat(
        view.origin.x + view.size.x * 0.5f + view.pan.x + static_cast<float>((x - view.center_x) * view.scale),
        view.origin.y + view.size.y * 0.5f + view.pan.y + static_cast<float>((y - view.center_y) * view.scale));
    if (pitch <= 0.0001f || view.size.x <= 1.0f || view.size.y <= 1.0f) return flat;
    ImVec2 projected = apply_map_pitch_to_screen(flat, view);
    const double mpp = std::max(1.0e-6, meters_per_screen_pixel(view));
    projected.y -= static_cast<float>((height_m / mpp) * std::sin(static_cast<double>(pitch) * 0.68));
    return projected;
}

ImVec2 project_world_px_metric_3d(double wx, double wy, const MapViewport& view, double height_m = 0.0) {
    return project_lonlat_metric_3d(world_px_to_lonlat(wx, wy, view.z), view, height_m);
}

ImVec2 project_lonlat(const Point2& p, const MapViewport& view) {

    return project_lonlat_metric_3d(p, view, 0.0);
}





