bool point_in_geo_ring(const Point2& p, const std::vector<Point2>& ring) {

    if (ring.size() < 3) return false;
    bool inside = false;



    for (size_t i = 0, j = ring.size() - 1; i < ring.size(); j = i++) {
        const double xi = ring[i].x;
        const double yi = ring[i].y;
        const double xj = ring[j].x;
        const double yj = ring[j].y;
        const bool crosses = ((yi > p.y) != (yj > p.y));

        if (!crosses) continue;
        const double denom = (yj - yi);
        const double x_intersect = xi + (p.y - yi) * (xj - xi) / ((std::abs(denom) < 1e-12) ? (denom < 0.0 ? -1e-12 : 1e-12) : denom);

        if (p.x < x_intersect) inside = !inside;
    }

    return inside;
}



bool point_in_geo_features(const Point2& p, const std::vector<MapFeature>& features) {



    if (!std::isfinite(p.x) || !std::isfinite(p.y) || features.empty()) return false;

    for (const auto& feature : features) {

        for (const auto& ring : feature.rings) {

            if (point_in_geo_ring(p, ring)) return true;
        }
    }

    return false;
}




