MapViewport remap_viewport_zoom(const MapViewport& source, int target_z) {

    if (target_z == source.z) return source;
    const double factor = std::ldexp(1.0, source.z - target_z);

    MapViewport out = source;
    out.z = target_z;

    out.center_x = source.center_x / factor;
    out.center_y = source.center_y / factor;


    out.scale = static_cast<float>(static_cast<double>(source.scale) * factor);

    return out;
}



