struct SolarIlluminationState {
    double elevation_deg = 90.0;
    double azimuth_deg = 180.0;
};

double runtime_local_standard_meridian_deg() {
    std::time_t now = std::time(nullptr);
    if (now == static_cast<std::time_t>(-1)) return -90.0;
    std::tm local_tm{};
    std::tm utc_tm{};
#ifdef _WIN32
    if (localtime_s(&local_tm, &now) != 0 || gmtime_s(&utc_tm, &now) != 0) return -90.0;
#else
    if (!localtime_r(&now, &local_tm) || !gmtime_r(&now, &utc_tm)) return -90.0;
#endif
    const std::time_t local_as_epoch = std::mktime(&local_tm);
    const std::time_t utc_as_epoch = std::mktime(&utc_tm);
    if (local_as_epoch == static_cast<std::time_t>(-1) || utc_as_epoch == static_cast<std::time_t>(-1)) return -90.0;
    const double offset_hours = std::round(std::difftime(local_as_epoch, utc_as_epoch) / 3600.0);
    return std::clamp(offset_hours * 15.0, -180.0, 180.0);
}

SolarIlluminationState solar_illumination_for_timeline(const Point2& lonlat, int64_t timeline_hour, int timeline_minute) {
    constexpr double pi = 3.14159265358979323846;
    const int64_t days = floor_div_i64(timeline_hour, 24);
    const unsigned hour = static_cast<unsigned>(positive_mod_i64(timeline_hour, 24));
    int year = kTimelineStartYear;
    unsigned month = 1, day = 1;
    civil_from_days(timeline_epoch_days() + days, year, month, day);
    const int doy = static_cast<int>(days_from_civil(year, month, day) - days_from_civil(year, 1u, 1u) + 1);
    const double local_minutes = static_cast<double>(hour) * 60.0 + static_cast<double>(std::clamp(timeline_minute, 0, 59));
    const double gamma = 2.0 * pi / 365.0 * (static_cast<double>(std::clamp(doy, 1, 366)) - 1.0 + (local_minutes / 60.0 - 12.0) / 24.0);
    const double eqtime = 229.18 * (0.000075 + 0.001868 * std::cos(gamma) - 0.032077 * std::sin(gamma)
                                  - 0.014615 * std::cos(2.0 * gamma) - 0.040849 * std::sin(2.0 * gamma));
    const double decl = 0.006918 - 0.399912 * std::cos(gamma) + 0.070257 * std::sin(gamma)
                      - 0.006758 * std::cos(2.0 * gamma) + 0.000907 * std::sin(2.0 * gamma)
                      - 0.002697 * std::cos(3.0 * gamma) + 0.001480 * std::sin(3.0 * gamma);
    const double standard_meridian = runtime_local_standard_meridian_deg();
    double true_solar_minutes = local_minutes + eqtime + 4.0 * (lonlat.x - standard_meridian);
    true_solar_minutes = std::fmod(true_solar_minutes, 1440.0);
    if (true_solar_minutes < 0.0) true_solar_minutes += 1440.0;
    const double hour_angle = (true_solar_minutes / 4.0 - 180.0) * pi / 180.0;
    const double lat = std::clamp(lonlat.y, -89.0, 89.0) * pi / 180.0;
    const double cos_zenith = std::clamp(std::sin(lat) * std::sin(decl) + std::cos(lat) * std::cos(decl) * std::cos(hour_angle), -1.0, 1.0);
    const double zenith = std::acos(cos_zenith);
    const double elevation = 90.0 - zenith * 180.0 / pi;
    double azimuth = (std::atan2(std::sin(hour_angle), std::cos(hour_angle) * std::sin(lat) - std::tan(decl) * std::cos(lat)) + pi) * 180.0 / pi;
    azimuth = std::fmod(azimuth + 360.0, 360.0);
    return SolarIlluminationState{elevation, azimuth};
}

void draw_solar_daylight_overlay(ImDrawList* dl, const MapViewport& view, int64_t timeline_hour, int timeline_minute) {
    if (!dl || view.size.x <= 1.0f || view.size.y <= 1.0f) return;
    const Point2 center = view_center_lonlat(view);
    const SolarIlluminationState sun = solar_illumination_for_timeline(center, timeline_hour, timeline_minute);

    const float elev = static_cast<float>(std::clamp(sun.elevation_deg, -60.0, 90.0));
    const float night = std::clamp((6.0f - elev) / 34.0f, 0.0f, 1.0f);
    const float civil_twilight = std::clamp((10.0f - std::fabs(elev + 2.0f)) / 15.0f, 0.0f, 1.0f);
    const float golden = std::clamp((14.0f - std::fabs(elev - 4.0f)) / 18.0f, 0.0f, 1.0f);
    if (night <= 0.015f && civil_twilight <= 0.015f && golden <= 0.015f) return;

    const float left = view.origin.x;
    const float top = view.origin.y;
    const float right = view.origin.x + view.size.x;
    const float bottom = view.origin.y + view.size.y;
    const double az = sun.azimuth_deg * 3.14159265358979323846 / 180.0;
    const float sx = static_cast<float>(std::sin(az));
    const float sy = static_cast<float>(-std::cos(az));

    dl->PushClipRect(view.origin, ImVec2(right, bottom), true);

    // Noche visual, no apagón uniforme: se conserva detalle satelital y se introduce
    // anisotropía en dirección solar para que el mapa lea como superficie iluminada.
    const int base_cool_alpha = std::clamp(static_cast<int>(std::round(10.0f + night * 62.0f + civil_twilight * 18.0f)), 0, 96);
    if (base_cool_alpha > 1) {
        auto cool_corner = [&](float xnorm, float ynorm) -> ImU32 {
            const float dot = std::clamp(xnorm * sx + ynorm * sy, -1.0f, 1.0f);
            const float shadow = (1.0f - dot) * 0.5f;
            const int a = std::clamp(static_cast<int>(std::round(static_cast<float>(base_cool_alpha) + shadow * night * 42.0f)), 0, 126);
            return IM_COL32(6, 10, 17, a);
        };
        dl->AddRectFilledMultiColor(ImVec2(left, top), ImVec2(right, bottom),
                                    cool_corner(-1.0f, -1.0f), cool_corner(1.0f, -1.0f),
                                    cool_corner(1.0f, 1.0f), cool_corner(-1.0f, 1.0f));
    }

    const int blue_veil_alpha = std::clamp(static_cast<int>(std::round(night * 30.0f + civil_twilight * 12.0f)), 0, 44);
    if (blue_veil_alpha > 1) {
        dl->AddRectFilled(ImVec2(left, top), ImVec2(right, bottom), IM_COL32(18, 28, 40, blue_veil_alpha), 0.0f);
    }

    const int warm_alpha = std::clamp(static_cast<int>(std::round((golden + civil_twilight * 0.55f) * (1.0f - night * 0.42f) * 34.0f)), 0, 40);
    if (warm_alpha > 1) {
        auto warm_corner = [&](float xnorm, float ynorm) -> ImU32 {
            const float dot = std::clamp(xnorm * sx + ynorm * sy, -1.0f, 1.0f);
            const float lit = (dot + 1.0f) * 0.5f;
            const int a = std::clamp(static_cast<int>(std::round(lit * static_cast<float>(warm_alpha))), 0, 44);
            return IM_COL32(255, 213, 164, a);
        };
        dl->AddRectFilledMultiColor(ImVec2(left, top), ImVec2(right, bottom),
                                    warm_corner(-1.0f, -1.0f), warm_corner(1.0f, -1.0f),
                                    warm_corner(1.0f, 1.0f), warm_corner(-1.0f, 1.0f));
    }

    dl->PopClipRect();
}




