std::vector<ImVec2> project_ring_lod_metric(const std::vector<Point2>& ring, const MapViewport& view, int stride) {
    std::vector<ImVec2> pts;
    if (ring.size() < 3) return pts;
    if (stride < 1) stride = 1;
    const size_t reserve_n = stride <= 1 ? ring.size() : (ring.size() / static_cast<size_t>(stride) + 3u);
    pts.reserve(std::min<size_t>(ring.size(), reserve_n));
    for (size_t i = 0; i < ring.size(); i += static_cast<size_t>(stride)) pts.push_back(project_lonlat(ring[i], view));
    if (pts.size() < 3 && ring.size() >= 3) {
        pts.clear();
        pts.push_back(project_lonlat(ring.front(), view));
        pts.push_back(project_lonlat(ring[ring.size() / 2u], view));
        pts.push_back(project_lonlat(ring.back(), view));
    } else if (ring.size() > 3 && stride > 1) {
        const ImVec2 last = project_lonlat(ring.back(), view);
        if (std::hypot(last.x - pts.back().x, last.y - pts.back().y) > 0.5f) pts.push_back(last);
    }
    return pts;
}


double map_scale_denominator(const MapViewport& view) {

    const double m_per_px = meters_per_screen_pixel(view);

    return std::max(1.0, m_per_px * 96.0 / 0.0254);
}







int desired_tile_zoom_for_view(const UiState& ui, const MapViewport& view, const std::vector<MapFeature>& zmvm_features, const std::vector<MapFeature>& buffer_features) {



    const Point2 center = view_center_lonlat(view);
    const bool center_inside_zmvm = point_in_geo_features(center, zmvm_features);
    const bool center_inside_buffer = center_inside_zmvm || point_in_geo_features(center, buffer_features);
    const bool moving = ui.map_interaction_cooldown > 0.0f;
    return tlal_lod_desired_z(map_scale_denominator(view), center_inside_buffer ? 1 : 0, moving ? 1 : 0, ui.map_idle_seconds,
                              kMapOverviewTileZoom, kMapScale300kTileZoom, kMapScale90kTileZoom,
                              kMapScale30kTileZoom, kMapScale15kIdleTileZoom);
}




