fs::path first_existing_path(std::initializer_list<fs::path> paths) {

    for (const auto& p : paths) {

        std::error_code ec;

        if (!p.empty() && fs::exists(p, ec) && !ec) return p;
    }

    return paths.size() > 0 ? *paths.begin() : fs::path{};
}




