bool path_contains_importable_pdfs_relaxed(const fs::path& candidate) {



    if (candidate.empty()) return false;
    try {

        const fs::path resolved = resolve_existing_path_relaxed(candidate);
        std::error_code ec;

        if (!fs::exists(resolved, ec) || ec) return false;


        return !list_pdfs_recursive(resolved).empty();

    } catch (...) {

        return false;
    }
}




fs::path first_pdf_bearing_path_or_existing(std::initializer_list<fs::path> paths) {

    std::vector<fs::path> existing;

    existing.reserve(paths.size());

    for (const auto& raw : paths) {

        if (raw.empty()) continue;

        const fs::path p = resolve_existing_path_relaxed(raw);
        std::error_code ec;

        if (fs::exists(p, ec) && !ec) existing.push_back(p);


        if (path_contains_importable_pdfs_relaxed(p)) return p;
    }

    if (!existing.empty()) return existing.front();

    return paths.size() > 0 ? resolve_existing_path_relaxed(*paths.begin()) : fs::path{};
}




