constexpr std::uint8_t kAtmosNetworkRedmet = 1u << 0;
constexpr std::uint8_t kAtmosNetworkRama = 1u << 1;
constexpr std::uint8_t kAtmosNetworkRuoa = 1u << 2;
constexpr std::uint8_t kAtmosNetworkPembuRuoa = 1u << 3;
constexpr std::uint8_t kAtmosNetworkAll = kAtmosNetworkRedmet | kAtmosNetworkRama | kAtmosNetworkRuoa | kAtmosNetworkPembuRuoa;

std::uint8_t atmosphere_network_mask_from_text(const std::string& raw) {
    const std::string k = normalize_key(raw);
    if (k.empty()) return 0u;

    /*
       Contrato de red, no de variable: PEMBU/RUOA y RUOA dominan frente a
       palabras genéricas como "meteorológico" o "contaminante" presentes en
       rutas, dominios o descripciones. Sin esta frontera, una estación PEMBU
       podía entrar al filtro REDMET sólo porque medía temperatura, y una RAMA
       podía parecer disponible dentro de meteorología.
    */
    if (k.find("pembu") != std::string::npos) return kAtmosNetworkPembuRuoa;
    if (k.find("ruoa") != std::string::npos) return kAtmosNetworkRuoa;

    std::uint8_t mask = 0u;
    if (k.find("rama") != std::string::npos || k.find("simat") != std::string::npos ||
        k.find("contaminante") != std::string::npos || k.find("calidad aire") != std::string::npos) mask |= kAtmosNetworkRama;
    if (k.find("redmet") != std::string::npos || k.find("redma") != std::string::npos ||
        k.find("meteorologic") != std::string::npos || k.find("meteorolog") != std::string::npos ||
        k.find("radiacion") != std::string::npos) mask |= kAtmosNetworkRedmet;
    return mask;
}

std::uint8_t atmosphere_network_mask_from_metadata_text(const std::string& source_id,
                                                        const std::string& source_file,
                                                        const std::string& source_path,
                                                        const std::string& domain) {
    std::uint8_t mask = 0u;
    mask |= atmosphere_network_mask_from_text(source_id);
    mask |= atmosphere_network_mask_from_text(source_file);
    mask |= atmosphere_network_mask_from_text(source_path);
    mask |= atmosphere_network_mask_from_text(domain);
    return mask;
}

bool atmosphere_network_mask_enabled(std::uint8_t active_mask, std::uint8_t sample_mask) {
    active_mask &= kAtmosNetworkAll;
    sample_mask &= kAtmosNetworkAll;
    if (active_mask == 0u) return false;
    if (sample_mask == 0u) return true;
    return (active_mask & sample_mask) != 0u;
}

std::string atmosphere_network_mask_signature(std::uint8_t mask) {
    return std::string("red:") + std::to_string(static_cast<unsigned>(mask & kAtmosNetworkAll));
}

std::string atmospheric_parameter_key(const std::string& pollutant);

std::uint8_t atmosphere_requested_network_mask_from_ui_flags(bool redmet,
                                                            bool rama,
                                                            bool ruoa,
                                                            bool pembu_ruoa) {
    return static_cast<std::uint8_t>((redmet ? kAtmosNetworkRedmet : 0u) |
                                    (rama ? kAtmosNetworkRama : 0u) |
                                    (ruoa ? kAtmosNetworkRuoa : 0u) |
                                    (pembu_ruoa ? kAtmosNetworkPembuRuoa : 0u));
}

std::uint8_t atmosphere_allowed_network_mask_for_selection(const std::set<std::string>& selected_pollutants) {
    bool has_meteorological = false;
    bool has_contaminant = false;
    bool has_unclassified = false;

    for (const std::string& raw : selected_pollutants) {
        const std::string k = atmospheric_parameter_key(raw);
        if (k.empty()) continue;
        const bool is_meteorological = ozmvm_atm_key_is_meteorological(k.data(), k.size()) != 0;
        const bool is_contaminant = ozmvm_atm_key_is_contaminant(k.data(), k.size()) != 0;
        has_meteorological = has_meteorological || is_meteorological;
        has_contaminant = has_contaminant || is_contaminant;
        has_unclassified = has_unclassified || (!is_meteorological && !is_contaminant);
    }

    if (!has_meteorological && !has_contaminant && !has_unclassified) return kAtmosNetworkAll;
    if (has_unclassified) return kAtmosNetworkAll;

    std::uint8_t allowed = 0u;
    if (has_meteorological) allowed |= static_cast<std::uint8_t>(kAtmosNetworkRedmet | kAtmosNetworkPembuRuoa | kAtmosNetworkRuoa);
    if (has_contaminant) allowed |= static_cast<std::uint8_t>(kAtmosNetworkRama | kAtmosNetworkPembuRuoa | kAtmosNetworkRuoa);
    return static_cast<std::uint8_t>(allowed & kAtmosNetworkAll);
}

std::uint8_t atmosphere_active_network_mask_for_selection(const std::set<std::string>& selected_pollutants,
                                                          std::uint8_t requested_mask) {
    requested_mask = static_cast<std::uint8_t>(requested_mask & kAtmosNetworkAll);
    if (requested_mask == 0u) return 0u;
    return static_cast<std::uint8_t>(requested_mask & atmosphere_allowed_network_mask_for_selection(selected_pollutants));
}

