std::vector<fs::path> dependency_roots_for_app() {

    std::vector<fs::path> roots;

    auto add_root = [&](const fs::path& root) {

        if (root.empty()) return;


        const fs::path normalized = root.lexically_normal();


        const std::string key = path_utf8(normalized);

        for (const auto& existing : roots) {

            if (path_utf8(existing.lexically_normal()) == key) return;
        }


        roots.push_back(normalized);
    };


    add_root(executable_dir() / "Dependencias");
    const std::string deps_root = getenv_utf8_or_empty("TLALPOWA_DEPS_ROOT");

    if (!deps_root.empty()) {

        const std::string cleaned = trim(deps_root);

        if (!cleaned.empty()) add_root(fs::path(widen_utf8(cleaned)));
    }
#ifdef _WIN32

    add_root(fs::path(L"C:/ProgramData/Tlalpowa/Dependencias"));



    add_root(fs::path(L"C:/ProgramData/Observatorio-ZMVM/Dependencias"));
#endif

    return roots;
}



fs::path sidecar_dependency_report() {

    std::vector<fs::path> candidates;

    for (const auto& deps_root : dependency_roots_for_app()) {


        candidates.push_back(deps_root / "dependencies.local.json");
    }

    for (const auto& p : candidates) {
        std::error_code ec;

        if (fs::exists(p, ec) && !ec) return p;
    }

    return candidates.empty() ? fs::path{} : candidates.front();
}



fs::path bundled_tool(const wchar_t* exe_name) {

    std::vector<fs::path> candidates;

    for (const auto& deps_root : dependency_roots_for_app()) {

        candidates.push_back(deps_root / "poppler" / "Library" / "bin" / exe_name);

        candidates.push_back(deps_root / "poppler" / "bin" / exe_name);

        candidates.push_back(deps_root / "bin" / exe_name);
    }

    for (const auto& p : candidates) {
        std::error_code ec;

        if (fs::exists(p, ec) && !ec) return p;
    }

    return first_existing_path({

        fs::path(L"C:/ProgramData/Tlalpowa/Dependencias") / "poppler" / "Library" / "bin" / exe_name,

        fs::path(L"C:/ProgramData/Observatorio-ZMVM/Dependencias") / "poppler" / "Library" / "bin" / exe_name
    });
}




std::optional<fs::path> pick_windows_folder(const wchar_t* title) {
#ifdef _WIN32


    HRESULT init = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED | COINIT_DISABLE_OLE1DDE);
    const bool should_uninit = SUCCEEDED(init);

    IFileDialog* dialog = nullptr;

    HRESULT hr = CoCreateInstance(CLSID_FileOpenDialog, nullptr, CLSCTX_INPROC_SERVER, IID_PPV_ARGS(&dialog));

    if (FAILED(hr) || !dialog) {

        if (should_uninit) CoUninitialize();

        return std::nullopt;
    }
    DWORD options = 0;
    dialog->GetOptions(&options);

    dialog->SetOptions(options | FOS_PICKFOLDERS | FOS_FORCEFILESYSTEM | FOS_PATHMUSTEXIST);
    dialog->SetTitle(title);


    std::optional<fs::path> result;

    if (SUCCEEDED(dialog->Show(nullptr))) {
        IShellItem* item = nullptr;

        if (SUCCEEDED(dialog->GetResult(&item)) && item) {
            PWSTR raw = nullptr;

            if (SUCCEEDED(item->GetDisplayName(SIGDN_FILESYSPATH, &raw)) && raw) {

                result = fs::path(raw);
                CoTaskMemFree(raw);
            }
            item->Release();
        }
    }
    dialog->Release();

    if (should_uninit) CoUninitialize();

    return result;
#else
    (void)title;

    return std::nullopt;
#endif
}

std::optional<fs::path> pick_windows_file(const wchar_t* title,
                                          const wchar_t* filter_name,
                                          const wchar_t* extension) {
#ifdef _WIN32
    HRESULT init = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED | COINIT_DISABLE_OLE1DDE);
    const bool should_uninit = SUCCEEDED(init);
    IFileOpenDialog* dialog = nullptr;
    HRESULT hr = CoCreateInstance(CLSID_FileOpenDialog, nullptr, CLSCTX_INPROC_SERVER, IID_PPV_ARGS(&dialog));
    if (FAILED(hr) || !dialog) {
        if (should_uninit) CoUninitialize();
        return std::nullopt;
    }
    DWORD options = 0;
    dialog->GetOptions(&options);
    dialog->SetOptions(options | FOS_FORCEFILESYSTEM | FOS_FILEMUSTEXIST | FOS_PATHMUSTEXIST);
    dialog->SetTitle(title);
    COMDLG_FILTERSPEC filter{filter_name, extension};
    dialog->SetFileTypes(1, &filter);
    std::optional<fs::path> result;
    if (SUCCEEDED(dialog->Show(nullptr))) {
        IShellItem* item = nullptr;
        if (SUCCEEDED(dialog->GetResult(&item)) && item) {
            PWSTR raw = nullptr;
            if (SUCCEEDED(item->GetDisplayName(SIGDN_FILESYSPATH, &raw)) && raw) {
                result = fs::path(raw);
                CoTaskMemFree(raw);
            }
            item->Release();
        }
    }
    dialog->Release();
    if (should_uninit) CoUninitialize();
    return result;
#else
    (void)title;
    (void)filter_name;
    (void)extension;
    return std::nullopt;
#endif
}



float side_panel_width(const UiState& ui) {
    const ImVec2 ds = main_viewport_size();
    const float ratio = std::isfinite(ui.side_panel_ratio)
        ? std::clamp(ui.side_panel_ratio, kSidePanelMinRatio, kSidePanelMaxRatio)

        : kSidePanelDefaultRatio;
    const float default_w = golden_w(kSidePanelDefaultRatio);
    const float max_w = golden_w(kSidePanelMaxRatio);



    return std::clamp(ds.x * ratio, default_w, std::max(default_w, max_w));
}




int64_t get_json_int(const std::string& s, const std::string& key) {


    return ozmvm_json_i64(s.data(), s.size(), key.c_str());
}




double get_json_double_field(const std::string& s, const std::string& key) {
    const std::string needle = "\"" + key + "\"";
    size_t p = s.find(needle);

    if (p == std::string::npos) return 0.0;
    p = s.find(':', p + needle.size());

    if (p == std::string::npos) return 0.0;
    ++p;

    while (p < s.size() && std::isspace(static_cast<unsigned char>(s[p]))) ++p;
    char* end = nullptr;

    const double v = std::strtod(s.c_str() + p, &end);

    return end == s.c_str() + p ? 0.0 : v;
}




std::string jurisdiction_id_from_name(const std::string& name) {

    static const std::map<std::string, std::string> aliases = {
        {"azcapotzalco", "azcapotzalco"},
        {"coyoacan", "coyoacan"},
        {"cuajimalpa de morelos", "cuajimalpa"},
        {"gustavo a madero", "gustavo_a_madero"},
        {"iztacalco", "iztacalco"},
        {"iztapalapa", "iztapalapa"},
        {"magdalena contreras", "magdalena_contreras"},
        {"la magdalena contreras", "magdalena_contreras"},
        {"milpa alta", "milpa_alta"},
        {"alvaro obregon", "alvaro_obregon"},
        {"tlahuac", "tlahuac"},
        {"tlalpan", "tlalpan"},

        {"xochimilco", "xochimilco"},
        {"benito juarez", "benito_juarez"},
        {"cuauhtemoc", "cuauhtemoc"},
        {"miguel hidalgo", "miguel_hidalgo"},

        {"venustiano carranza", "venustiano_carranza"}
    };


    const std::string key = normalize_key(name);
    auto it = aliases.find(key);

    if (it != aliases.end()) return it->second;

    return safe_filename(key);
}

