std::vector<fs::path> mobility_gtfs_zip_candidates() {



    std::vector<fs::path> c;

    const fs::path d = datos_externos_root();

    c.push_back(mobility_gtfs_zip_path());

    c.push_back(d / "gtfs.zip");

    c.push_back(d / "GTFS.zip");

    c.push_back(d / "GTFS CDMX.zip");

    c.push_back(d / "movilidad_gtfs.zip");


    c.push_back(d / "Descargas web" / "gtfs.zip");


    c.push_back(d / "Descargas web" / "GTFS.zip");

    c.push_back(d / "Transporte y Movilidad" / "gtfs.zip");

    c.push_back(d / "Transporte y Movilidad" / "GTFS.zip");
    std::error_code ec;

    if (fs::exists(d, ec) && !ec) {

        for (fs::recursive_directory_iterator it(d, fs::directory_options::skip_permission_denied, ec), end; it != end && !ec; it.increment(ec)) {

            if (!it->is_regular_file(ec)) { ec.clear(); continue; }

            const fs::path p = it->path();


            const std::string fn = normalize_key(path_utf8(p.filename()));


            const std::string ext = normalize_key(path_utf8(p.extension()));

            if (ext == ".zip" && fn.find("gtfs") != std::string::npos) c.push_back(p);
        }
    }

    return c;
}



fs::path best_mobility_gtfs_zip_path() {
    std::error_code ec;

    fs::path best;

    fs::file_time_type best_time{};
    std::uintmax_t best_size = 0;

    for (const auto& p : mobility_gtfs_zip_candidates()) {

        if (!fs::exists(p, ec) || ec || !fs::is_regular_file(p, ec) || ec) { ec.clear(); continue; }


        const std::uintmax_t sz = fs::file_size(p, ec); if (ec || sz < 1024) { ec.clear(); continue; }

        const auto tm = fs::last_write_time(p, ec); if (ec) { ec.clear(); continue; }

        if (best.empty() || tm > best_time || (tm == best_time && sz > best_size)) {

            best = p; best_time = tm; best_size = sz;
        }
    }

    return best;
}



