bool is_probably_zip(const fs::path& p);


bool is_probably_pdf(const fs::path& p);



std::string read_file_window(const fs::path& p, std::uintmax_t offset, std::size_t n) {


    std::ifstream in(p, std::ios::binary);

    if (!in || n == 0) return {};
    in.seekg(static_cast<std::streamoff>(offset), std::ios::beg);

    if (!in) return {};
    std::string data(n, '\0');

    in.read(data.data(), static_cast<std::streamsize>(data.size()));

    data.resize(static_cast<std::size_t>(std::max<std::streamsize>(0, in.gcount())));

    return data;
}


std::string read_file_head(const fs::path& p, std::size_t n = 8192) {

    return read_file_window(p, 0, n);
}


std::string read_file_tail(const fs::path& p, std::size_t n = 65536) {


    const std::uintmax_t sz = file_size_or_zero(p);

    if (sz == 0) return {};
    const std::uintmax_t offset = sz > n ? sz - n : 0;

    return read_file_window(p, offset, static_cast<std::size_t>(std::min<std::uintmax_t>(n, sz)));
}



bool contains_ci(std::string haystack, std::string needle) {


    haystack = normalize_key(haystack);


    needle = normalize_key(needle);

    return !needle.empty() && haystack.find(needle) != std::string::npos;
}



bool env_flag_enabled_app(const char* name) {
    const std::string raw = getenv_utf8_or_empty(name);

    if (raw.empty()) return true;


    const std::string v = normalize_key(raw);

    return v == "1" || v == "true" || v == "on" || v == "yes" || v == "si";
}



int env_int_clamped_app(const char* name, int fallback, int lo, int hi) {
    const std::string raw = getenv_utf8_or_empty(name);

    if (raw.empty()) return std::clamp(fallback, lo, hi);
    try { return std::clamp(std::stoi(raw), lo, hi); } catch (...) { return std::clamp(fallback, lo, hi); }
}



int official_download_worker_count(int planned, int fallback = 20) {


    const unsigned hw_raw = std::thread::hardware_concurrency();
    const int hw = hw_raw == 0 ? fallback : static_cast<int>(hw_raw);


    const int auto_workers = std::clamp(std::max(fallback, hw * 12), 24, 160);


    const int configured = env_int_clamped_app("TLALPOWA_DOWNLOAD_WORKERS", auto_workers, 1, 256);

    return std::max(1, std::min(std::max(1, planned), configured));
}




int official_download_worker_count_for(const char* env_name, int planned, int fallback) {


    int base = official_download_worker_count(planned, fallback);
    const std::string raw = env_name ? getenv_utf8_or_empty(env_name) : std::string{};

    if (!raw.empty()) base = env_int_clamped_app(env_name, base, 1, 256);

    else if (fallback > 0) base = std::min(base, fallback);

    return std::max(1, std::min(std::max(1, planned), base));
}


template <typename T>


size_t wait_ready_future_index(std::vector<std::future<T>>& futures, const std::atomic_bool* cancel_flag = nullptr, int poll_ms = 18) {


    if (futures.empty()) return 0;

    for (;;) {


        for (size_t i = 0; i < futures.size(); ++i) {


            if (futures[i].wait_for(std::chrono::milliseconds(0)) == std::future_status::ready) return i;
        }


        if (cancel_flag && cancel_flag->load()) return 0;


        std::this_thread::sleep_for(std::chrono::milliseconds(std::clamp(poll_ms, 1, 100)));
    }
}




bool preview_raster_enabled_by_env_app() {
    const std::string raw = getenv_utf8_or_empty("TLALPOWA_PREVIEW_RASTER_MODE");

    if (raw.empty()) return false;


    const std::string v = normalize_key(raw);

    if (v == "0" || v == "false" || v == "off" || v == "no" || v == "vector" || v == "bbox" || v == "direct") return false;

    return v == "1" || v == "true" || v == "on" || v == "yes" || v == "si" ||
           v == "jpg" || v == "jpeg" || v == "png" || v == "auto" || v == "live" ||
           v == "live20" || v == "prefetch20" || v == "bulk";
}



bool looks_like_html_or_gateway_error(const fs::path& p) {

    const std::string head = read_file_head(p, 8192);

    if (head.empty()) return false;



    return contains_ci(head, "<!doctype html") || contains_ci(head, "<html") ||

           contains_ci(head, "bad gateway") || contains_ci(head, "gateway timeout") ||
           contains_ci(head, "service unavailable") || contains_ci(head, "not found") ||
           contains_ci(head, "access denied") || contains_ci(head, "forbidden") ||
           contains_ci(head, "error 404") || contains_ci(head, "error 500");
}




bool pdf_has_eof_marker(const fs::path& p) {



    return read_file_tail(p, 65536).find("%%EOF") != std::string::npos;
}



bool zip_has_end_of_central_directory(const fs::path& p) {



    const std::string tail = read_file_tail(p, 70000);

    return tail.find(std::string("PK\x05\x06", 4)) != std::string::npos;
}



bool is_probably_html_index(const fs::path& p) {

    const std::string head = read_file_head(p, 32768);

    if (head.size() < 256) return false;


    if (looks_like_html_or_gateway_error(p) && !(contains_ci(head, "bolet") || contains_ci(head, "epidemi"))) return false;


    return contains_ci(head, "<html") || contains_ci(head, "bolet") || contains_ci(head, "epidemi");
}





bool strong_pdf_validation(const fs::path& p, std::uintmax_t min_bytes) {


    if (file_size_or_zero(p) < min_bytes) return false;

    if (looks_like_html_or_gateway_error(p)) return false;


    return is_probably_pdf(p) && pdf_has_eof_marker(p);
}




bool strong_zip_validation(const fs::path& p, std::uintmax_t min_bytes) {


    if (file_size_or_zero(p) < min_bytes) return false;

    if (looks_like_html_or_gateway_error(p)) return false;

    return is_probably_zip(p) && zip_has_end_of_central_directory(p);
}



bool enough_free_space_for_download(const fs::path& dir, std::uintmax_t requested_floor_bytes = 256ull * 1024ull * 1024ull) {
#ifdef _WIN32
    ULARGE_INTEGER free_to_caller{}, total{}, total_free{};
    const std::wstring root = dir.empty() ? research_root().wstring() : dir.wstring();

    if (GetDiskFreeSpaceExW(root.c_str(), &free_to_caller, &total, &total_free)) {

        return free_to_caller.QuadPart >= requested_floor_bytes;
    }
#endif
    (void)dir;
    (void)requested_floor_bytes;

    return true;
}



std::uintmax_t directory_size_limited(const fs::path& root, std::uintmax_t stop_after) {
    std::uintmax_t total = 0;

    std::error_code ec;

    if (!fs::exists(root, ec)) return 0;

    for (fs::recursive_directory_iterator it(root, fs::directory_options::skip_permission_denied, ec), end; it != end && !ec; it.increment(ec)) {

        if (!it->is_regular_file(ec)) { ec.clear(); continue; }


        const std::uintmax_t sz = it->file_size(ec);

        if (!ec) total += sz;

        ec.clear();

        if (total >= stop_after) return total;
    }

    return total;
}



void prune_quarantine_if_needed() {


    const fs::path qdir = epidemiology_quarantine_dir();
    const std::uintmax_t limit = 160ull * 1024ull * 1024ull;

    if (directory_size_limited(qdir, limit + 1) <= limit) return;

    std::vector<fs::path> files;
    std::error_code ec;

    for (fs::recursive_directory_iterator it(qdir, fs::directory_options::skip_permission_denied, ec), end; it != end && !ec; it.increment(ec)) {

        if (it->is_regular_file(ec)) files.push_back(it->path());

        ec.clear();
    }

    std::sort(files.begin(), files.end(), [](const fs::path& a, const fs::path& b) {
        std::error_code ea, eb;

        return fs::last_write_time(a, ea) < fs::last_write_time(b, eb);
    });

    for (const auto& f : files) {

        if (directory_size_limited(qdir, limit + 1) <= limit) break;
        fs::remove(f, ec);

        ec.clear();
    }
}




void quarantine_file(const fs::path& p, const std::string& reason, nlohmann::json* audit = nullptr) {
    std::error_code ec;

    if (!fs::exists(p, ec) || ec) return;


    ensure_dir(epidemiology_quarantine_dir());
    const std::string stamp = now_utc_iso();
    std::string clean_stamp = stamp;

    for (char& c : clean_stamp) if (c == ':' || c == '-' || c == 'T' || c == 'Z') c = '_';


    const fs::path dst = epidemiology_quarantine_dir() / (clean_stamp + "__" + safe_filename(reason) + "__" + safe_filename(path_utf8(p.filename())));
    fs::rename(p, dst, ec);

    if (ec) {

        ec.clear();


        fs::copy_file(p, dst, fs::copy_options::overwrite_existing, ec);
        fs::remove(p, ec);
    }

    if (audit) {
        (*audit)["quarantined"] = true;
        (*audit)["quarantine_reason"] = reason;

        (*audit)["quarantine_file"] = path_utf8(dst.filename());
    }
    prune_quarantine_if_needed();
}




