bool file_has_magic(const fs::path& p, const std::string& expected, std::size_t search_window = 0) {


    std::ifstream in(p, std::ios::binary);

    if (!in) return false;
    const std::size_t n = std::max<std::size_t>(expected.size(), search_window > 0 ? search_window : expected.size());
    std::string head(n, '\0');

    in.read(head.data(), static_cast<std::streamsize>(head.size()));

    head.resize(static_cast<std::size_t>(std::max<std::streamsize>(0, in.gcount())));

    if (search_window > 0) return head.find(expected) != std::string::npos;

    return head.rfind(expected, 0) == 0;
}



bool is_probably_zip(const fs::path& p) {


    return file_has_magic(p, "PK\x03\x04") || file_has_magic(p, "PK\x05\x06") || file_has_magic(p, "PK\x07\x08");
}




bool is_probably_pdf(const fs::path& p) {




    return file_has_magic(p, "%PDF-", 1024);
}



std::string html_entity_decode_basic(std::string s) {

    const std::vector<std::pair<std::string, std::string>> repl = {
        {"&amp;", "&"}, {"&quot;", "\""}, {"&#39;", "'"}, {"&lt;", "<"}, {"&gt;", ">"}
    };

    for (const auto& [a, b] : repl) {
        size_t pos = 0;

        while ((pos = s.find(a, pos)) != std::string::npos) {
            s.replace(pos, a.size(), b);
            pos += b.size();
        }
    }

    return s;
}



int hex_digit_value(char c) {

    if (c >= '0' && c <= '9') return c - '0';

    if (c >= 'a' && c <= 'f') return 10 + (c - 'a');

    if (c >= 'A' && c <= 'F') return 10 + (c - 'A');

    return -1;
}




std::string url_percent_decode(std::string s) {
    std::string out;

    out.reserve(s.size());

    for (size_t i = 0; i < s.size(); ++i) {

        if (s[i] == '%' && i + 2 < s.size()) {
            const int hi = hex_digit_value(s[i + 1]);
            const int lo = hex_digit_value(s[i + 2]);

            if (hi >= 0 && lo >= 0) {

                out.push_back(static_cast<char>((hi << 4) | lo));
                i += 2;
                continue;
            }
        }

        out.push_back(s[i] == '+' ? ' ' : s[i]);
    }

    return out;
}




std::string url_percent_encode_unsafe(std::string s) {
    static constexpr char hex[] = "0123456789ABCDEF";
    std::string out;

    out.reserve(s.size() + 16);

    for (size_t i = 0; i < s.size(); ++i) {
        const unsigned char c = static_cast<unsigned char>(s[i]);

        if (c == '%' && i + 2 < s.size() && hex_digit_value(s[i + 1]) >= 0 && hex_digit_value(s[i + 2]) >= 0) {

            out.push_back('%');

            out.push_back(static_cast<char>(std::toupper(static_cast<unsigned char>(s[i + 1]))));


            out.push_back(static_cast<char>(std::toupper(static_cast<unsigned char>(s[i + 2]))));
            i += 2;
            continue;
        }
        const bool unsafe = c <= 0x20 || c >= 0x7f || c == '"' || c == '<' || c == '>' ||
                            c == '\\' || c == '^' || c == '`' || c == '{' || c == '}' || c == '|';

        if (!unsafe) {

            out.push_back(static_cast<char>(c));
            continue;
        }

        out.push_back('%');

        out.push_back(hex[(c >> 4) & 0x0f]);

        out.push_back(hex[c & 0x0f]);
    }

    return out;
}




std::string absolute_url(const std::string& base, std::string href) {
    href = html_entity_decode_basic(href);


    if (href.rfind("http://", 0) == 0 || href.rfind("https://", 0) == 0) return url_percent_encode_unsafe(href);


    if (href.rfind("//", 0) == 0) return url_percent_encode_unsafe("https:" + href);
    const auto scheme_pos = base.find("://");


    if (scheme_pos == std::string::npos) return href;

    const auto path_start = base.find('/', scheme_pos + 3);

    const std::string origin = path_start == std::string::npos ? base : base.substr(0, path_start);


    if (!href.empty() && href[0] == '/') return url_percent_encode_unsafe(origin + href);

    const std::string dir = path_start == std::string::npos ? origin + "/" : base.substr(0, base.find_last_of('/') + 1);


    return url_percent_encode_unsafe(dir + href);
}




std::vector<std::string> scrape_links_by_extension(const std::string& html, const std::string& base_url, const std::string& ext) {

    std::vector<std::string> out;

    std::set<std::string> seen;

    size_t pos = 0;
    size_t href_begin = 0;
    size_t href_end = 0;
    size_t next = 0;

    while (ozmvm_html_next_href(html.data(), html.size(), pos, &href_begin, &href_end, &next)) {
        pos = next;
        std::string href(html.data() + href_begin, href_end - href_begin);

        std::string low = normalize_key(href);

        if (low.find(ext) == std::string::npos) continue;


        std::string url = absolute_url(base_url, href);


        if (seen.insert(url).second) out.push_back(url);
    }

    return out;
}




std::string filename_from_url(const std::string& url, const std::string& fallback) {


    std::string u = url;
    const size_t q = u.find('?');

    if (q != std::string::npos) u = u.substr(0, q);
    const size_t slash = u.find_last_of('/');

    std::string f = slash == std::string::npos ? u : u.substr(slash + 1);
    f = html_entity_decode_basic(f);

    if (f.empty() || f.find('.') == std::string::npos) f = fallback;

    return safe_filename(f);
}




bool download_validated_url_to_file(const std::string& url, const fs::path& final_path,
                                    const std::string& kind, std::uintmax_t min_bytes,


                                    int attempts, nlohmann::json* audit = nullptr) {

    ensure_dir(final_path.parent_path());


    if (!enough_free_space_for_download(final_path.parent_path())) {

        if (audit) {


            (*audit)["url"] = url;
            (*audit)["kind"] = kind;

            (*audit)["target"] = path_utf8(final_path.filename());


            (*audit)["blocked_before_download"] = "espacio libre insuficiente para una descarga segura";
        }

        return false;
    }


    const fs::path candidate = fs::path(final_path.wstring() + L".candidate");

    std::error_code ec;


    const std::string force_raw = getenv_utf8_or_empty("TLALPOWA_FORCE_REDOWNLOAD");


    const bool force_redownload = !force_raw.empty() && env_flag_enabled_app("TLALPOWA_FORCE_REDOWNLOAD");


    const auto final_valid_for_kind = [&]() -> bool {


        const std::uintmax_t sz = file_size_or_zero(final_path);


        if (kind == "pdf") return strong_pdf_validation(final_path, min_bytes);

        if (kind == "zip") return strong_zip_validation(final_path, min_bytes);

        if (kind == "html") return is_probably_html_index(final_path) && sz >= min_bytes;

        return sz >= min_bytes && !looks_like_html_or_gateway_error(final_path);
    };



    if (final_valid_for_kind() && !force_redownload && kind != "html") {

        if (audit) {


            (*audit)["url"] = url;
            (*audit)["kind"] = kind;

            (*audit)["target"] = path_utf8(final_path.filename());

            (*audit)["skipped_existing_valid_file"] = true;


            (*audit)["previous_final_size_bytes"] = file_size_or_zero(final_path);
            (*audit)["previous_valid"] = true;


            (*audit)["final_size_bytes"] = file_size_or_zero(final_path);
        }

        return true;
    }



    ScopedDownloadFileLock transfer_lock(final_path);

    if (!transfer_lock.acquired) {



        for (int i = 0; i < 50; ++i) {


            if (final_valid_for_kind() && !force_redownload) {

                if (audit) {


                    (*audit)["url"] = url;
                    (*audit)["kind"] = kind;

                    (*audit)["target"] = path_utf8(final_path.filename());

                    (*audit)["waited_for_parallel_writer"] = true;


                    (*audit)["final_size_bytes"] = file_size_or_zero(final_path);

                    (*audit)["previous_valid"] = true;
                }

                return true;
            }


            std::this_thread::sleep_for(std::chrono::milliseconds(80));
        }

        if (audit) {


            (*audit)["url"] = url;
            (*audit)["kind"] = kind;

            (*audit)["target"] = path_utf8(final_path.filename());

            (*audit)["blocked_by_parallel_writer"] = true;


            (*audit)["final_size_bytes"] = file_size_or_zero(final_path);
        }

        return false;
    }


    fs::remove(candidate, ec);




    fs::remove(fs::path(candidate.wstring() + L".download"), ec);



    const std::uintmax_t previous_size = file_size_or_zero(final_path);
    const bool previous_valid = final_valid_for_kind();


    if (previous_valid && !force_redownload && kind != "html") {

        if (audit) {


            (*audit)["url"] = url;
            (*audit)["kind"] = kind;

            (*audit)["target"] = path_utf8(final_path.filename());

            (*audit)["skipped_existing_valid_file_after_lock"] = true;
            (*audit)["previous_final_size_bytes"] = previous_size;
            (*audit)["previous_valid"] = true;
            (*audit)["final_size_bytes"] = previous_size;
        }

        return true;
    }



    const bool fetched = download_url_to_file(url, candidate, min_bytes, attempts, true);
    bool valid = false;
    std::string validation_reason = "no_descargado";

    if (fetched) {

        if (kind == "zip") {

            valid = strong_zip_validation(candidate, min_bytes);
            validation_reason = valid ? "zip_valido_con_eocd" : "zip_invalido_o_truncado";


        } else if (kind == "pdf") {


            valid = strong_pdf_validation(candidate, min_bytes);
            validation_reason = valid ? "pdf_valido_con_eof" : "pdf_invalido_truncado_o_html";

        } else if (kind == "html") {


            valid = is_probably_html_index(candidate) && file_size_or_zero(candidate) >= min_bytes;
            validation_reason = valid ? "html_indice_valido" : "html_indice_invalido";
        } else {


            valid = file_size_or_zero(candidate) >= min_bytes && !looks_like_html_or_gateway_error(candidate);
            validation_reason = valid ? "generico_valido" : "generico_invalido";
        }
    }


    if (audit) {


        (*audit)["url"] = url;

        (*audit)["kind"] = kind;

        (*audit)["target"] = path_utf8(final_path.filename());
        (*audit)["fetched"] = fetched;
        (*audit)["validation_reason"] = validation_reason;
        (*audit)["valid_signature"] = valid;


        (*audit)["candidate_size_bytes"] = file_size_or_zero(candidate);
        (*audit)["previous_final_size_bytes"] = previous_size;
        (*audit)["previous_valid"] = previous_valid;
    }


    if (fetched && valid) {


        const bool promoted = atomic_promote_file(candidate, final_path);

        if (audit) {

            (*audit)["promoted_atomically"] = promoted;


            (*audit)["final_size_bytes"] = file_size_or_zero(final_path);
            (*audit)["final_valid_after_promote"] =

                (kind == "zip" ? strong_zip_validation(final_path, min_bytes) :


                 kind == "pdf" ? strong_pdf_validation(final_path, min_bytes) :


                 kind == "html" ? is_probably_html_index(final_path) : file_size_or_zero(final_path) >= min_bytes);
        }

        return promoted;
    }



    if (fs::exists(candidate, ec) && !ec) quarantine_file(candidate, validation_reason, audit);

    if (audit) {

        (*audit)["preserved_previous_valid_file"] = previous_valid;


        (*audit)["final_size_bytes"] = file_size_or_zero(final_path);
    }

    return false;
}



std::vector<fs::path> list_files_recursive(const fs::path& root, const std::string& ext_norm) {

    std::vector<fs::path> out;
    std::error_code ec;

    if (!fs::exists(root, ec)) return out;

    for (fs::recursive_directory_iterator it(root, fs::directory_options::skip_permission_denied, ec), end; it != end; it.increment(ec)) {

        if (ec) { ec.clear(); continue; }

        std::error_code item_ec;

        if (!it->is_regular_file(item_ec) || item_ec) { ec.clear(); continue; }


        std::string name = normalize_key(path_utf8(it->path().extension()));


        if (name == normalize_key(ext_norm)) out.push_back(it->path());
    }

    std::sort(out.begin(), out.end(), [](const fs::path& a, const fs::path& b) { return path_utf8(a) < path_utf8(b); });

    return out;
}



std::vector<fs::path> list_regular_files_recursive(const fs::path& root) {

    std::vector<fs::path> out;
    std::error_code ec;

    if (!fs::exists(root, ec)) return out;


    for (fs::recursive_directory_iterator it(root, fs::directory_options::skip_permission_denied, ec), end; it != end; it.increment(ec)) {

        if (ec) { ec.clear(); continue; }
        std::error_code item_ec;

        if (it->is_regular_file(item_ec) && !item_ec) out.push_back(it->path());
    }

    std::sort(out.begin(), out.end(), [](const fs::path& a, const fs::path& b) { return path_utf8(a) < path_utf8(b); });

    return out;
}



bool path_extension_is_relaxed(const fs::path& p, const std::string& ext_norm) {


    return normalize_key(path_utf8(p.extension())) == normalize_key(ext_norm);
}



std::string path_relative_utf8_relaxed(const fs::path& child, const fs::path& base) {
    std::error_code ec;

    fs::path rel = fs::relative(child, base, ec);

    if (ec || rel.empty()) rel = child.filename();

    return path_utf8(rel);
}



fs::path unique_available_path(const fs::path& wanted) {
    std::error_code ec;

    if (!fs::exists(wanted, ec)) return wanted;

    const std::string stem = path_utf8(wanted.stem());

    const std::string ext = path_utf8(wanted.extension());

    for (int i = 2; i < 10000; ++i) {

        fs::path candidate = wanted.parent_path() / (stem + "__" + std::to_string(i) + ext);

        ec.clear();

        if (!fs::exists(candidate, ec)) return candidate;
    }

    return wanted.parent_path() / (stem + "__" + simple_hash_hex(path_utf8(wanted) + now_utc_iso()) + ext);
}


std::string truncate_filename_preserving_extension(std::string name, std::size_t max_component_bytes = 150) {



    name = trim(name);

    if (name.empty()) name = "archivo";

    if (name.size() <= max_component_bytes) return name;

    fs::path np(name);

    std::string stem = path_utf8(np.stem());

    std::string ext = path_utf8(np.extension());

    if (ext.size() > 24) ext = ext.substr(0, 24);
    const std::string h = simple_hash_hex(name).substr(0, 12);
    const std::string suffix = "__" + h + ext;

    if (suffix.size() >= max_component_bytes) return h + ext;
    const std::size_t keep = max_component_bytes - suffix.size();

    if (stem.size() > keep) stem.resize(keep);

    while (!stem.empty() && (stem.back() == '_' || stem.back() == '-' || stem.back() == ' ' || stem.back() == '.')) stem.pop_back();

    if (stem.empty()) stem = "archivo";

    return stem + suffix;
}



