std::string pdf_file_fingerprint_relaxed(const fs::path& p) {




    const std::uintmax_t sz = file_size_or_zero(p);

    std::string head = read_file_head(p, 65536);

    std::string tail = read_file_tail(p, 65536);

    return std::to_string(sz) + ":" + simple_hash_hex(head) + ":" + simple_hash_hex(tail);
}




bool same_file_size_and_valid_pdf(const fs::path& a, const fs::path& b) {

    if (!fs::exists(a) || !fs::exists(b)) return false;


    if (!usable_extracted_pdf_validation(a) || !usable_extracted_pdf_validation(b)) return false;


    if (file_size_or_zero(a) != file_size_or_zero(b)) return false;


    return pdf_file_fingerprint_relaxed(a) == pdf_file_fingerprint_relaxed(b);
}


