std::vector<fs::path> list_pdf_payload_candidates_recursive(const fs::path& root) {



    std::vector<fs::path> out;

    for (const auto& f : list_regular_files_recursive(root)) {


        if (path_extension_is_relaxed(f, ".pdf") || usable_extracted_pdf_validation(f)) out.push_back(f);
    }

    std::sort(out.begin(), out.end(), [](const fs::path& a, const fs::path& b) { return path_utf8(a) < path_utf8(b); });

    out.erase(std::unique(out.begin(), out.end(), [](const fs::path& a, const fs::path& b) {


        return normalize_key(path_utf8(a.lexically_normal())) == normalize_key(path_utf8(b.lexically_normal()));

    }), out.end());

    return out;
}



std::vector<fs::path> list_zip_payload_candidates_recursive(const fs::path& root) {



    std::vector<fs::path> out;

    for (const auto& f : list_regular_files_recursive(root)) {

        if (path_extension_is_relaxed(f, ".zip") || is_probably_zip(f)) {

            if (strong_zip_validation(f, 128)) out.push_back(f);
        }
    }

    std::sort(out.begin(), out.end(), [](const fs::path& a, const fs::path& b) { return path_utf8(a) < path_utf8(b); });

    out.erase(std::unique(out.begin(), out.end(), [](const fs::path& a, const fs::path& b) {


        return normalize_key(path_utf8(a.lexically_normal())) == normalize_key(path_utf8(b.lexically_normal()));
    }), out.end());

    return out;
}


