    std::istringstream in(metro_seed);

    std::string row;

    while (std::getline(in, row)) {


        row = trim(row);

        if (row.empty()) continue;

        std::vector<std::string> c;
        std::string cur;

        std::istringstream ss(row);


        while (std::getline(ss, cur, '\t')) c.push_back(trim(cur));

        if (c.size() < 7) continue;
        try {
            const std::string key = c[0];
            colors[key] = c[1];

            years[key] = std::stoi(c[2]);
            labels[key] = c[3];


            names[key].push_back(c[4]);

            const double lat = std::stod(c[5]);

            const double lon = std::stod(c[6]);

            pts[key].push_back({lon, lat});
        } catch (...) {}
    }

    for (const auto& [key, pvec] : pts) {


        lines.push_back(make_mobility_line("Red Metro", "metro_l" + normalize_key(key), labels[key], colors[key], years[key], pvec, names[key]));
    }



