nlohmann::json mobility_line_to_json(const MobilityLine& line) {


    nlohmann::json j;
    j["type"] = "line";
    j["id"] = line.id;
    j["system"] = line.system;
    j["name"] = line.name;
    j["color"] = line.color_hex;

    j["source_precision"] = line.source_precision;

    j["valid_from"] = line.valid_from;
    j["valid_to"] = line.valid_to;


    j["points"] = nlohmann::json::array();

    for (const auto& p : line.points) j["points"].push_back({p.x, p.y});


    j["point_valid_from"] = nlohmann::json::array();

    for (size_t i = 0; i < line.points.size(); ++i) {
        int y = line.valid_from;

        if (i < line.point_valid_from.size()) y = line.point_valid_from[i];

        j["point_valid_from"].push_back(y);
    }


    j["stations"] = nlohmann::json::array();

    for (const auto& s : line.stations) {

        j["stations"].push_back({

            {"id", s.id}, {"name", s.name}, {"lon", s.lon}, {"lat", s.lat},
            {"valid_from", s.valid_from}, {"valid_to", s.valid_to}
        });
    }

    return j;
}




std::string gtfs_compiled_manifest_path_string() {


    return path_utf8(build_runtime_root() / "movilidad_gtfs_compilado_manifest.json");
}




std::vector<std::string> split_csv_gtfs(const std::string& s) {



    std::vector<std::string> out;
    std::string cur;
    bool quoted = false;

    for (size_t i = 0; i < s.size(); ++i) {
        const char ch = s[i];

        if (ch == '"') {

            if (quoted && i + 1 < s.size() && s[i + 1] == '"') { cur.push_back('"'); ++i; }
            else quoted = !quoted;

        } else if (ch == ',' && !quoted) {


            out.push_back(trim(cur));

            cur.clear();

        } else cur.push_back(ch);
    }


    out.push_back(trim(cur));

    return out;
}



std::map<std::string, size_t> gtfs_header_index(const std::vector<std::string>& header) {

    std::map<std::string, size_t> idx;


    for (size_t i = 0; i < header.size(); ++i) idx[normalize_key(header[i])] = i;

    return idx;
}



std::string gtfs_cell(const std::vector<std::string>& row, const std::map<std::string, size_t>& idx, const std::string& key) {


    auto it = idx.find(normalize_key(key));

    if (it == idx.end() || it->second >= row.size()) return {};

    return row[it->second];
}



int mobility_valid_from_guess(const std::string& system, const std::string& short_name, const std::string& long_name) {


    const std::string sys = normalize_key(system);


    std::string k = normalize_key(short_name);


    const std::string ln = normalize_key(long_name);

    if (sys == "metro") {

        if (k == "1" || ln.find("linea 1") != std::string::npos) return 1969;

        if (k == "2" || k == "3" || ln.find("linea 2") != std::string::npos || ln.find("linea 3") != std::string::npos) return 1970;

        if (k == "4" || k == "5") return 1981;

        if (k == "6") return 1983;

        if (k == "7") return 1984;

        if (k == "9") return 1987;

        if (k == "a" || ln.find("linea a") != std::string::npos) return 1991;

        if (k == "8") return 1994;

        if (k == "b" || ln.find("linea b") != std::string::npos) return 1999;


        if (k == "12") return 2012;
    }

    if (sys == "metrobus") {

        if (k == "1") return 2005;

        if (k == "2") return 2008;

        if (k == "3") return 2011;

        if (k == "4") return 2012;

        if (k == "5") return 2013;

        if (k == "6") return 2016;

        if (k == "7") return 2018;
    }

    if (sys == "trenes") {

        if (ln.find("suburbano") != std::string::npos || ln.find("cuautitlan") != std::string::npos || ln.find("buenavista") != std::string::npos) return 2008;

        if (ln.find("interurbano") != std::string::npos || ln.find("insurgente") != std::string::npos || ln.find("toluca") != std::string::npos) return 2023;

        return 2008;
    }

    return 1900;
}




std::string normalize_gtfs_color(std::string c, const std::string& system, const std::string& short_name) {

    c.erase(std::remove(c.begin(), c.end(), '#'), c.end());

    if (c.size() == 6) return "#" + c;


    const std::string sys = normalize_key(system);


    const std::string k = normalize_key(short_name);

    if (sys == "metro") {

        if (k == "1") return "#F05A9D"; if (k == "2") return "#005DAA"; if (k == "3") return "#B59A2A";

        if (k == "4") return "#6EC6A4"; if (k == "5") return "#FFD100"; if (k == "6") return "#DA291C";

        if (k == "7") return "#F58220"; if (k == "8") return "#009739"; if (k == "9") return "#6F2C1F";

        if (k == "a") return "#8E267B"; if (k == "b") return "#B1B3B3"; if (k == "12") return "#C9A227";
    }

    if (sys == "metrobus") return "#D21F26";

    if (sys == "trenes") return "#5B6770";

    if (sys == "pumabus") return "#C8102E";

    return "#4F8DFF";
}



bool extract_zip_to_directory(const fs::path& zip_path, const fs::path& out_dir) {
    std::error_code ec;
    fs::remove_all(out_dir, ec);
    ensure_dir(out_dir);
#ifdef _WIN32



    for (const auto& candidate : zip_extract_commands_for_windows(zip_path, out_dir)) {

        if (run_command_no_console(candidate.second, research_root()) == 0) return true;
    }

    return false;
#else

    (void)zip_path; (void)out_dir; return false;
#endif
}



fs::path find_gtfs_file(const fs::path& root, const std::string& filename) {
    std::error_code ec;

    for (fs::recursive_directory_iterator it(root, fs::directory_options::skip_permission_denied, ec), end; it != end && !ec; it.increment(ec)) {

        if (!it->is_regular_file(ec)) { ec.clear(); continue; }


        if (normalize_key(path_utf8(it->path().filename())) == normalize_key(filename)) return it->path();
    }

    return {};
}




bool compile_mobility_from_gtfs_zip(const fs::path& zip_path, nlohmann::json* audit = nullptr) {



    if (!fs::exists(zip_path) || !strong_zip_validation(zip_path, 1024)) return false;

    const fs::path extract_dir = build_runtime_root() / L"gtfs_extract_movilidad";

    if (!extract_zip_to_directory(zip_path, extract_dir)) return false;

    const fs::path agency_p = find_gtfs_file(extract_dir, "agency.txt");

    const fs::path routes_p = find_gtfs_file(extract_dir, "routes.txt");

    const fs::path trips_p = find_gtfs_file(extract_dir, "trips.txt");

    const fs::path shapes_p = find_gtfs_file(extract_dir, "shapes.txt");

    const fs::path stops_p = find_gtfs_file(extract_dir, "stops.txt");


    const fs::path stop_times_p = find_gtfs_file(extract_dir, "stop_times.txt");


    if (routes_p.empty() || trips_p.empty() || shapes_p.empty()) return false;


    std::map<std::string, std::string> agency_name;

    if (!agency_p.empty()) {


        std::ifstream in(agency_p, std::ios::binary); std::string row;

        if (std::getline(in, row)) {


            auto h = gtfs_header_index(split_csv_gtfs(row));

            while (std::getline(in, row)) {


                auto c = split_csv_gtfs(row);
                const std::string id = gtfs_cell(c, h, "agency_id");
                const std::string nm = gtfs_cell(c, h, "agency_name");

                if (!id.empty()) agency_name[id] = nm;
            }
        }
    }


    struct Rt { std::string id, agency, shortn, longn, route_type, system, color; };

    std::map<std::string, Rt> routes;
    {


        std::ifstream in(routes_p, std::ios::binary); std::string row;

        if (std::getline(in, row)) {


            auto h = gtfs_header_index(split_csv_gtfs(row));

            while (std::getline(in, row)) {


                auto c = split_csv_gtfs(row);
                Rt r;
                r.id = gtfs_cell(c, h, "route_id");
                r.agency = gtfs_cell(c, h, "agency_id");
                r.shortn = gtfs_cell(c, h, "route_short_name");

                r.longn = gtfs_cell(c, h, "route_long_name");

                r.route_type = gtfs_cell(c, h, "route_type");


                const std::string ag = normalize_key(agency_name[r.agency]);


                const std::string txt = normalize_key(r.shortn + " " + r.longn + " " + agency_name[r.agency] + " " + r.agency);


                const bool is_metrobus = (ag.find("metrobus") != std::string::npos || txt.find("metrobus") != std::string::npos || txt.find("metro bus") != std::string::npos);
                const bool is_pumabus = (txt.find("pumabus") != std::string::npos || txt.find("puma bus") != std::string::npos || txt.find("puma") != std::string::npos || txt.find("unam") != std::string::npos || ag.find("universidad nacional") != std::string::npos);
                const bool is_rtp = (txt.find("rtp") != std::string::npos || ag.find("red de transporte de pasajeros") != std::string::npos || txt.find("red de transporte de pasajeros") != std::string::npos);
                const bool is_ste = (txt.find("trolebus") != std::string::npos || txt.find("trole bus") != std::string::npos || txt.find("tren ligero") != std::string::npos || ag.find("servicio de transportes electricos") != std::string::npos || r.route_type == "0" || r.route_type == "11");
                const bool is_train = (!is_ste && (txt.find("tren suburbano") != std::string::npos || txt.find("ferrocarril suburbano") != std::string::npos || txt.find("suburbano") != std::string::npos || txt.find("tren interurbano") != std::string::npos || txt.find("interurbano") != std::string::npos || txt.find("el insurgente") != std::string::npos || txt.find("toluca") != std::string::npos || r.route_type == "2"));
                const bool is_cablebus = (txt.find("cablebus") != std::string::npos || txt.find("cable bus") != std::string::npos || r.route_type == "6");
                const bool is_concessioned = (txt.find("concesionado") != std::string::npos || txt.find("concesion") != std::string::npos || txt.find("corredor") != std::string::npos || txt.find("colectivo") != std::string::npos || txt.find("combi") != std::string::npos || txt.find("microbus") != std::string::npos);




                const std::string rid = normalize_key(r.id);
                const bool has_metro_token = (txt.find(" metro ") != std::string::npos || txt.rfind("metro ", 0) == 0 || ag == "metro" || rid.find("metro") != std::string::npos);


                const bool is_stc = (ag.find("sistema de transporte colectivo") != std::string::npos || ag == "stc" || ag == "metro" || ag == "metro cdmx" || ag == "metro de la ciudad de mexico" || ag == "sistema de transporte colectivo metro" || txt.find(" sistema de transporte colectivo ") != std::string::npos || txt.find(" stc ") != std::string::npos || (!is_metrobus && !is_pumabus && !is_rtp && !is_ste && !is_train && !is_cablebus && has_metro_token && (r.shortn == "1" || r.shortn == "2" || r.shortn == "3" || r.shortn == "4" || r.shortn == "5" || r.shortn == "6" || r.shortn == "7" || r.shortn == "8" || r.shortn == "9" || normalize_key(r.shortn) == "a" || normalize_key(r.shortn) == "b" || r.shortn == "12")));


                if (is_metrobus) r.system = "Red Metrobús";

                else if (is_pumabus) r.system = "Pumabús";

                else if (is_rtp) r.system = "RTP";

                else if (is_ste) r.system = "Transporte Eléctrico";

                else if (is_train) r.system = "Redes Ferroviarias";

                else if (is_cablebus) r.system = "Otros Sistemas De Movilidad";

                else if (is_stc) r.system = "Red Metro";

                else if (is_concessioned || r.route_type == "3") r.system = "Rutas Concesionadas";
                else r.system = "Otros Sistemas De Movilidad";


                r.color = normalize_gtfs_color(gtfs_cell(c, h, "route_color"), r.system, r.shortn);

                if (!r.id.empty()) routes[r.id] = r;
            }
        }
    }


    std::map<std::string, std::map<std::string, int>> route_shape_counts;

    std::map<std::string, std::string> trip_route, trip_shape;
    {


        std::ifstream in(trips_p, std::ios::binary); std::string row;

        if (std::getline(in, row)) {


            auto h = gtfs_header_index(split_csv_gtfs(row));

            while (std::getline(in, row)) {


                auto c = split_csv_gtfs(row);
                const std::string route_id = gtfs_cell(c, h, "route_id");
                const std::string trip_id = gtfs_cell(c, h, "trip_id");
                const std::string shape_id = gtfs_cell(c, h, "shape_id");

                if (route_id.empty() || trip_id.empty() || shape_id.empty()) continue;

                if (!routes.count(route_id)) continue;
                trip_route[trip_id] = route_id;
                trip_shape[trip_id] = shape_id;
                route_shape_counts[route_id][shape_id]++;
            }
        }
    }


    std::map<std::string, std::vector<std::string>> route_shapes;

    std::set<std::string> wanted_shapes;

    for (const auto& [rid, counts] : route_shape_counts) {

        std::vector<std::pair<int, std::string>> ordered;

        for (const auto& [shape, n] : counts) ordered.push_back({-n, shape});

        std::sort(ordered.begin(), ordered.end());

        for (const auto& item : ordered) {

            route_shapes[rid].push_back(item.second);

            wanted_shapes.insert(item.second);
        }
    }


    std::map<std::string, std::vector<std::pair<int, Point2>>> shape_points;
    {


        std::ifstream in(shapes_p, std::ios::binary); std::string row;

        if (std::getline(in, row)) {


            auto h = gtfs_header_index(split_csv_gtfs(row));

            while (std::getline(in, row)) {


                auto c = split_csv_gtfs(row);
                const std::string sid = gtfs_cell(c, h, "shape_id");

                if (!wanted_shapes.count(sid)) continue;
                try {

                    const double lat = std::stod(gtfs_cell(c, h, "shape_pt_lat"));

                    const double lon = std::stod(gtfs_cell(c, h, "shape_pt_lon"));
                    const int seq = std::stoi(gtfs_cell(c, h, "shape_pt_sequence"));

                    if (lon > -103 && lon < -96 && lat > 17 && lat < 22) shape_points[sid].push_back({seq, {lon, lat}});
                } catch (...) {}
            }
        }
    }

    for (auto& [_, v] : shape_points) {
        std::sort(v.begin(), v.end(), [](const auto& a, const auto& b){ return a.first < b.first; });



        v.erase(std::unique(v.begin(), v.end(), [](const auto& a, const auto& b){

            return std::abs(a.second.x - b.second.x) < 1e-10 && std::abs(a.second.y - b.second.y) < 1e-10;
        }), v.end());
    }


    std::map<std::string, MobilityStation> stops;

    if (!stops_p.empty()) {


        std::ifstream in(stops_p, std::ios::binary); std::string row;

        if (std::getline(in, row)) {


            auto h = gtfs_header_index(split_csv_gtfs(row));

            while (std::getline(in, row)) {


                auto c = split_csv_gtfs(row);
                try {
                    MobilityStation st;
                    st.id = gtfs_cell(c, h, "stop_id");
                    st.name = gtfs_cell(c, h, "stop_name");

                    st.lat = std::stod(gtfs_cell(c, h, "stop_lat"));

                    st.lon = std::stod(gtfs_cell(c, h, "stop_lon"));

                    if (!st.id.empty() && st.lon > -103 && st.lon < -96 && st.lat > 17 && st.lat < 22) stops[st.id] = st;
                } catch (...) {}
            }
        }
    }

    const auto route_shape_key = [](const std::string& rid, const std::string& sid) { return rid + "\n" + sid; };

    std::map<std::string, std::string> selected_trip_to_route_shape;

    std::set<std::string> selected_route_shapes;

    for (const auto& [trip, rid] : trip_route) {
        auto it = trip_shape.find(trip);


        if (it == trip_shape.end()) continue;
        const std::string key = route_shape_key(rid, it->second);

        if (selected_route_shapes.insert(key).second) selected_trip_to_route_shape[trip] = key;
    }


    std::map<std::string, std::vector<std::pair<int, MobilityStation>>> route_shape_stops;


    if (!stop_times_p.empty()) {


        std::ifstream in(stop_times_p, std::ios::binary); std::string row;

        if (std::getline(in, row)) {


            auto h = gtfs_header_index(split_csv_gtfs(row));

            while (std::getline(in, row)) {


                auto c = split_csv_gtfs(row);
                const std::string trip = gtfs_cell(c, h, "trip_id");
                auto rt = selected_trip_to_route_shape.find(trip);

                if (rt == selected_trip_to_route_shape.end()) continue;
                const std::string stop_id = gtfs_cell(c, h, "stop_id");

                auto st = stops.find(stop_id);

                if (st == stops.end()) continue;
                const std::string rid = trip_route[trip];
                int seq = 0;
                try { seq = std::stoi(gtfs_cell(c, h, "stop_sequence")); } catch (...) {}
                MobilityStation ms = st->second;
                ms.line_id = rid;
                ms.system = routes[rid].system;

                ms.valid_from = mobility_valid_from_guess(ms.system, routes[rid].shortn, routes[rid].longn);

                route_shape_stops[rt->second].push_back({seq, ms});
            }
        }
    }

    for (auto& [_, v] : route_shape_stops) {
        std::sort(v.begin(), v.end(), [](const auto& a, const auto& b){ return a.first < b.first; });

        v.erase(std::unique(v.begin(), v.end(), [](const auto& a, const auto& b){ return a.second.id == b.second.id; }), v.end());
    }


    std::vector<MobilityLine> lines;

    for (const auto& [rid, shapes] : route_shapes) {
        auto rr = routes.find(rid);

        if (rr == routes.end()) continue;
        const Rt& r = rr->second;
        int shape_ix = 0;

        for (const auto& sid : shapes) {
            auto sp = shape_points.find(sid);

            if (sp == shape_points.end() || sp->second.size() < 2) continue;
            MobilityLine ml;

            ml.id = "gtfs_" + safe_filename(rid) + "_shape_" + safe_filename(sid);
            ml.system = r.system;

            ml.name = !r.shortn.empty() ? (std::string("Línea ") + r.shortn) : (!r.longn.empty() ? r.longn : rid);

            if (shapes.size() > 1) ml.name += " · trazo " + std::to_string(++shape_ix);
            ml.color_hex = r.color;
            ml.source_precision = "gtfs";

            ml.valid_from = mobility_valid_from_guess(r.system, r.shortn, r.longn);

            ml.valid_to = 9999;

            ml.points.reserve(sp->second.size());

            ml.point_valid_from.reserve(sp->second.size());

            for (const auto& item : sp->second) { ml.points.push_back(item.second); ml.point_valid_from.push_back(ml.valid_from); }
            auto rs = route_shape_stops.find(route_shape_key(rid, sid));

            if (rs != route_shape_stops.end()) for (const auto& item : rs->second) ml.stations.push_back(item.second);
            refresh_mobility_bounds(ml);

            lines.push_back(std::move(ml));
        }
    }

    if (lines.empty()) return false;

    ensure_dir(mobility_consolidated_path().parent_path());
    std::ostringstream out;


    for (const auto& ml : lines) out << mobility_line_to_json(ml).dump() << "\n";


    if (!write_text_file_atomic(mobility_consolidated_path(), out.str())) return false;


    nlohmann::json cm;
    cm["dataset"] = "movilidad_integrada_desde_gtfs";

    cm["compiler_version"] = "2026-05-transport-lod-v36-minimal-hidpi-timeline";
    cm["compiled_at_utc"] = now_utc_iso();

    cm["source_zip"] = path_utf8(zip_path.filename());


    cm["source_size_bytes"] = file_size_or_zero(zip_path);
    cm["line_count"] = lines.size();
    cm["shape_count"] = wanted_shapes.size();


    cm["precision"] = "shapes.txt GTFS oficial: todos los shape_id usados por ruta, vertices ordenados por shape_pt_sequence; stops.txt/stop_times.txt para estaciones por shape.";


    write_text_file_atomic(build_runtime_root() / "movilidad_gtfs_compilado_manifest.json", cm.dump(2) + "\n");

    if (audit) (*audit)["gtfs_compiled"] = cm;
    std::error_code ec; fs::remove_all(extract_dir, ec);

    return true;
}



bool copy_embedded_mobility_base_if_available(const fs::path& out) {

    const fs::path embedded = mobility_embedded_base_path();
    std::error_code ec;

    if (!fs::exists(embedded, ec) || ec || !fs::is_regular_file(embedded, ec)) return false;
    try {



        std::ifstream in(embedded, std::ios::binary);

        if (!in) return false;

        std::string row;
        int valid_lines = 0;

        while (std::getline(in, row)) {


            row = trim(row);

            if (row.empty()) continue;


            auto j = nlohmann::json::parse(row, nullptr, false);

            if (j.is_discarded() || !j.is_object() || j.value("type", "") != "line") return false;
            auto pts = j.find("points");

            if (pts == j.end() || !pts->is_array() || pts->size() < 2) return false;
            ++valid_lines;
        }

        if (valid_lines < 8) return false;

        ensure_dir(out.parent_path());


        return copy_file_atomic(embedded, out);
    } catch (...) { return false; }
}




void ensure_seed_mobility_dataset() {

    const fs::path out = mobility_consolidated_path();
    std::error_code ec;


    const fs::path gtfs_compiled_manifest = build_runtime_root() / "movilidad_gtfs_compilado_manifest.json";

    const fs::path local_gtfs_zip = best_mobility_gtfs_zip_path();

    if (fs::exists(out, ec) && !ec) {

        if (fs::exists(gtfs_compiled_manifest, ec) && !ec) {
            try {


                auto cm = nlohmann::json::parse(read_text_file(gtfs_compiled_manifest), nullptr, false);

                if (!cm.is_discarded() && cm.value("compiler_version", "") == "2026-05-transport-lod-v36-minimal-hidpi-timeline") return;
            } catch (...) {}


        }



        try { (void)read_text_file(out); } catch (...) {}


        nlohmann::json m;


        try { if (fs::exists(mobility_manifest_path())) m = nlohmann::json::parse(read_text_file(mobility_manifest_path()), nullptr, false); } catch (...) {}

        if (!m.is_discarded() && m.value("version", "") == "2026-05-base-integrada-v36-minimal-hidpi-timeline") return;


    }

    ensure_dir(out.parent_path());


    std::ofstream f(out, std::ios::binary);

    if (!f) return;

    for (const auto& line : seed_mobility_lines()) {


        f << mobility_line_to_json(line).dump() << "\n";
    }


    nlohmann::json manifest;
    manifest["dataset"] = "movilidad_integrada_base";

    manifest["version"] = "2026-05-base-integrada-v36-minimal-hidpi-timeline";


    manifest["storage_policy"] = "Datos plano: Epidemiologia como salida tabular; cache_mapa vive fuera de Datos";

    manifest["embedded_base"] = path_utf8(mobility_embedded_base_path().filename());


    manifest["official_sources"] = nlohmann::json::array({


        "https://datos.cdmx.gob.mx/dataset/gtfs",


        "https://datos.cdmx.gob.mx/dataset/afluencia-diaria-del-metro-cdmx",


        "https://datos.cdmx.gob.mx/dataset/afluencia-diaria-de-metrobus-cdmx"
    });


    std::ofstream m(mobility_manifest_path(), std::ios::binary);

    if (m) m << manifest.dump(2) << "\n";
}



void apply_metro_historical_overrides(std::vector<MobilityLine>& lines);


std::string mobility_system_group(const std::string& system);
bool mobility_line_is_tren_ligero(const MobilityLine& line);



void compact_mobility_line_for_runtime(MobilityLine& ml) {

    if (ml.points.size() < 3) return;
    const std::string group = mobility_system_group(ml.system);
    const bool tren_ligero = mobility_line_is_tren_ligero(ml);
    double tol = (ml.points.size() > 2400) ? 0.000040 : ((ml.points.size() > 900) ? 0.000026 : 0.000014);



    if (group == "metro" || tren_ligero) tol *= 1.18;

    else if (group == "trenes") tol *= 2.55;

    else if (group == "metrobus" || group == "electrico" || group == "pumabus") tol *= 0.095;

    else if (group == "rtp" || group == "concesionado" || group == "otros") tol *= 0.055;
    const double tol2 = tol * tol;

    std::vector<Point2> pts;

    std::vector<int> yrs;

    pts.reserve(ml.points.size());

    yrs.reserve(ml.points.size());

    auto year_at = [&](size_t i) -> int { return (i < ml.point_valid_from.size()) ? ml.point_valid_from[i] : ml.valid_from; };

    pts.push_back(ml.points.front());

    yrs.push_back(year_at(0));
    Point2 last = ml.points.front();

    int last_year = yrs.front();

    for (size_t i = 1; i + 1 < ml.points.size(); ++i) {
        const Point2& p = ml.points[i];

        const int y = year_at(i);
        const double dx = p.x - last.x;
        const double dy = p.y - last.y;

        if ((dx * dx + dy * dy) < tol2 && y == last_year) continue;

        pts.push_back(p);

        yrs.push_back(y);
        last = p;

        last_year = y;
    }

    pts.push_back(ml.points.back());

    yrs.push_back(year_at(ml.points.size() - 1));

    if (pts.size() >= 2 && pts.size() < ml.points.size()) {
        ml.points.swap(pts);
        ml.point_valid_from.swap(yrs);
        refresh_mobility_bounds(ml);
    }
}





std::vector<MobilityLine> load_mobility_lines_from_jsonl(const fs::path& path) {

    std::vector<MobilityLine> out;


    std::ifstream in(path, std::ios::binary);

    if (!in) return out;

    std::string line;

    while (std::getline(in, line)) {


        if (trim(line).empty()) continue;


        auto j = nlohmann::json::parse(line, nullptr, false);

        if (j.is_discarded() || !j.is_object() || j.value("type", "") != "line") continue;
        MobilityLine ml;
        ml.id = j.value("id", "");
        ml.system = j.value("system", "");
        ml.name = j.value("name", "");
        ml.color_hex = j.value("color", "#ffffff");
        ml.source_precision = j.value("source_precision", std::string("seed"));
        ml.valid_from = j.value("valid_from", 1900);
        ml.valid_to = j.value("valid_to", 9999);
        const auto points = j.find("points");

        if (points != j.end() && points->is_array()) {

            for (const auto& p : *points) {

                if (p.is_array() && p.size() >= 2 && p[0].is_number() && p[1].is_number()) ml.points.push_back({p[0].get<double>(), p[1].get<double>()});
            }
        }
        ml.point_valid_from.assign(ml.points.size(), ml.valid_from);

        const auto py = j.find("point_valid_from");

        if (py != j.end() && py->is_array()) {
            const size_t n = std::min(ml.points.size(), py->size());

            for (size_t i = 0; i < n; ++i) if ((*py)[i].is_number_integer()) ml.point_valid_from[i] = (*py)[i].get<int>();
        }
        const auto stations = j.find("stations");

        if (stations != j.end() && stations->is_array()) {

            for (const auto& stj : *stations) {

                if (!stj.is_object()) continue;
                MobilityStation st;
                st.id = stj.value("id", "");
                st.line_id = ml.id;
                st.system = ml.system;
                st.name = stj.value("name", "");

                st.lon = stj.value("lon", 0.0);

                st.lat = stj.value("lat", 0.0);
                st.valid_from = stj.value("valid_from", ml.valid_from);

                st.valid_to = stj.value("valid_to", ml.valid_to);

                if (!st.name.empty()) ml.stations.push_back(std::move(st));
            }
        }

        if (!ml.id.empty() && ml.points.size() >= 2) {
            refresh_mobility_bounds(ml);

            compact_mobility_line_for_runtime(ml);

            out.push_back(std::move(ml));


            if ((out.size() & 31u) == 0u) std::this_thread::yield();
        }
    }

    return out;
}



std::vector<MobilityLine> load_embedded_mobility_lines_from_compiled_resource() {


    const unsigned char* data = obs_embedded_mobility_jsonl_data();


    const std::size_t size = obs_embedded_mobility_jsonl_size();

    if (!data || size == 0) return {};



    std::string_view text(reinterpret_cast<const char*>(data), size);

    std::vector<MobilityLine> out;

    out.reserve(64);
    size_t pos = 0;

    while (pos < text.size()) {
        size_t nl = text.find('\n', pos);

        if (nl == std::string_view::npos) nl = text.size();
        std::string_view sv = text.substr(pos, nl - pos);
        pos = nl + 1;


        while (!sv.empty() && (sv.back() == '\r' || sv.back() == '\n' || sv.back() == ' ' || sv.back() == '\t')) sv.remove_suffix(1);

        while (!sv.empty() && (sv.front() == ' ' || sv.front() == '\t')) sv.remove_prefix(1);

        if (sv.empty()) continue;


        auto j = nlohmann::json::parse(sv.begin(), sv.end(), nullptr, false);

        if (j.is_discarded() || !j.is_object() || j.value("type", "") != "line") continue;
        MobilityLine ml;
        ml.id = j.value("id", "");
        ml.system = j.value("system", "");

        ml.name = j.value("name", "");
        ml.color_hex = j.value("color", "#ffffff");

        ml.source_precision = j.value("source_precision", std::string("compiled_runtime"));
        ml.valid_from = j.value("valid_from", 1900);
        ml.valid_to = j.value("valid_to", 9999);
        const auto points = j.find("points");

        if (points != j.end() && points->is_array()) {

            ml.points.reserve(points->size());

            for (const auto& p : *points) if (p.is_array() && p.size() >= 2 && p[0].is_number() && p[1].is_number()) ml.points.push_back({p[0].get<double>(), p[1].get<double>()});
        }
        ml.point_valid_from.assign(ml.points.size(), ml.valid_from);
        const auto py = j.find("point_valid_from");

        if (py != j.end() && py->is_array()) {
            const size_t n = std::min(ml.points.size(), py->size());

            for (size_t i = 0; i < n; ++i) if ((*py)[i].is_number_integer()) ml.point_valid_from[i] = (*py)[i].get<int>();
        }
        const auto stations = j.find("stations");

        if (stations != j.end() && stations->is_array()) {

            ml.stations.reserve(stations->size());

            for (const auto& stj : *stations) {

                if (!stj.is_object()) continue;
                MobilityStation st;
                st.id = stj.value("id", "");
                st.line_id = ml.id;
                st.system = ml.system;
                st.name = stj.value("name", "");

                st.lon = stj.value("lon", 0.0);

                st.lat = stj.value("lat", 0.0);
                st.valid_from = stj.value("valid_from", ml.valid_from);
                st.valid_to = stj.value("valid_to", ml.valid_to);

                if (!st.name.empty()) ml.stations.push_back(std::move(st));
            }
        }

        if (!ml.id.empty() && ml.points.size() >= 2) {

            refresh_mobility_bounds(ml);

            compact_mobility_line_for_runtime(ml);

            out.push_back(std::move(ml));
        }
    }

    return out;
}




void load_mobility_integrated(UiState& ui) {
    try {
        std::error_code ec;

        const fs::path runtime_lite = mobility_runtime_lite_path();

        const fs::path consolidated = mobility_consolidated_path();



        std::vector<MobilityLine> lines;


        if (fs::exists(runtime_lite, ec) && !ec && file_size_or_zero(runtime_lite) >= 1024) {


            lines = load_mobility_lines_from_jsonl(runtime_lite);
        }

        if (lines.empty()) {

            lines = load_embedded_mobility_lines_from_compiled_resource();
        }

        if (lines.empty()) {


            lines = load_mobility_lines_from_jsonl(mobility_embedded_base_path());
        }

        if (lines.empty()) {


            if (!fs::exists(consolidated, ec) || ec || file_size_or_zero(consolidated) < 1024) ensure_seed_mobility_dataset();


            lines = load_mobility_lines_from_jsonl(consolidated);
        }

        if (lines.empty()) lines = seed_mobility_lines();
        apply_metro_historical_overrides(lines);


        bool has_metro_after_compile = false;

        std::set<std::string> existing_ids;

        for (const auto& ml : lines) {

            existing_ids.insert(ml.id);


            if (normalize_key(ml.system) == "metro") has_metro_after_compile = true;
        }

        if (!has_metro_after_compile) {


            auto base_lines = load_mobility_lines_from_jsonl(mobility_embedded_base_path());

            if (base_lines.empty()) base_lines = seed_mobility_lines();
            apply_metro_historical_overrides(base_lines);

            for (auto& bl : base_lines) {


                if (normalize_key(bl.system) != "metro") continue;

                if (existing_ids.insert(bl.id).second) {
                    bl.source_precision = "base_integrada_fallback_metro";

                    lines.push_back(std::move(bl));
                }
            }
        }


        auto shared_lines = std::make_shared<const std::vector<MobilityLine>>(std::move(lines));
        bool has_gtfs_precision = false;
        bool has_embedded_precision = false;

        for (const auto& ml : *shared_lines) {

            if (ml.source_precision == "gtfs") has_gtfs_precision = true;

            if (ml.source_precision == "base_integrada" || ml.source_precision == "base_integrada_fallback_metro") has_embedded_precision = true;
        }


        std::lock_guard<std::mutex> lock(ui.mu);

        ui.mobility_lines.clear();
        ui.mobility_lines.shrink_to_fit();
        ui.mobility_lines_ptr = shared_lines;
        ui.mobility_loaded = true;
        ui.mobility_loading = false;
        ui.mobility_status = has_gtfs_precision

            ? ("Movilidad integrada oficial/local: " + std::to_string(shared_lines->size()) + " trazos runtime/GTFS reclasificados; Metro/STC visible; sistemas separados")
            : (has_embedded_precision
                ? ("Movilidad integrada empacada: " + std::to_string(shared_lines->size()) + " trazos base; ampliar con GTFS solo actualiza precision")
                : ("Movilidad integrada base incluida: " + std::to_string(shared_lines->size()) + " trazos; no desaparece al acercar"));
        ui.mobility_revision.fetch_add(1, std::memory_order_relaxed);

    } catch (const std::exception& e) {


        std::lock_guard<std::mutex> lock(ui.mu);
        ui.mobility_loading = false;

        ui.mobility_status = std::string("No pude cargar movilidad integrada: ") + e.what();
    }
}





std::string ckan_best_resource_url(const nlohmann::json& package, const std::string& wanted_format, const std::string& preferred_name) {
    const auto result = package.find("result");

    if (result == package.end() || !result->is_object()) return {};
    const auto resources = result->find("resources");

    if (resources == result->end() || !resources->is_array()) return {};
    std::string fallback;


    const std::string fmt_wanted = normalize_key(wanted_format);


    const std::string pref = normalize_key(preferred_name);

    for (const auto& r : *resources) {

        if (!r.is_object()) continue;


        const std::string url = r.value("url", "");


        if (url.empty()) continue;


        const std::string fmt = normalize_key(r.value("format", ""));
        const std::string rname = r.value("name", std::string{});

        const std::string rdesc = r.value("description", std::string{});


        const std::string name = normalize_key(rname + " " + rdesc);


        const std::string url_norm = normalize_key(url);


        if (!fmt_wanted.empty() && fmt.find(fmt_wanted) == std::string::npos && url_norm.find(fmt_wanted) == std::string::npos) continue;


        if (fallback.empty()) fallback = url;


        if (!pref.empty() && name.find(pref) != std::string::npos) return url;
    }

    return fallback;
}




fs::path atmosphere_manifest_path() {


    return build_runtime_root() / "atmosfera_descargas_manifest.json";
}



bool usable_csv_download(const fs::path& p, std::uintmax_t min_bytes);



bool download_ckan_csv_package_to_file(const std::string& package_id,

                                       const fs::path& target_file,
                                       const std::string& preferred_name,
                                       const std::string& human_name,



                                       nlohmann::json& audit) {
    audit = {
        {"package_id", package_id},
        {"name", human_name},

        {"target_file", path_utf8(target_file.filename())},
        {"started_at_utc", now_utc_iso()}
    };

    ensure_dir(target_file.parent_path());


    const fs::path meta_tmp = build_runtime_root() / ("ckan_" + package_id + ".json.tmp");


    const std::string api = "https://datos.cdmx.gob.mx/api/3/action/package_show?id=" + package_id;


    const bool meta_ok = download_url_to_file(api, meta_tmp, 32, 3, true);


    std::string resource_url;

    if (meta_ok) {


        auto pkg = nlohmann::json::parse(read_text_file(meta_tmp), nullptr, false);


        if (!pkg.is_discarded()) resource_url = ckan_best_resource_url(pkg, "csv", preferred_name);
    }
    std::error_code ec;

    fs::remove(meta_tmp, ec);


    fs::remove(fs::path(meta_tmp.wstring() + L".download"), ec);


    audit["metadata_ok"] = meta_ok;


    audit["resource_url"] = resource_url;


    audit["previous_size_bytes"] = file_size_or_zero(target_file);
    bool ok = false;


    if (!resource_url.empty()) ok = download_validated_url_to_file(resource_url, target_file, "csv", 256, 4, &audit);


    const bool preserved_previous = !ok && usable_csv_download(target_file, 256);
    audit["ok"] = ok;

    audit["preserved_previous_valid_file"] = preserved_previous;


    audit["final_size_bytes"] = file_size_or_zero(target_file);
    audit["completed_at_utc"] = now_utc_iso();

    return ok || preserved_previous;
}




std::string simat_annual_atmosphere_url(int source, int year) {
    const std::string prefix = source == 1 ? "contaminantes_" : "meteorologia_";


    return "http://datosabiertos.aire.cdmx.gob.mx:8080/opendata/anuales_horarios/" +


           prefix + std::to_string(year) + ".csv";
}




std::vector<std::string> simat_annual_atmosphere_urls(int source, int year) {


    std::vector<std::string> urls;

    if (source == 1) {


        urls.push_back("https://aire.cdmx.gob.mx/descargas/Opendata/anuales_horarios/contaminantes_" +


                       std::to_string(year) + ".csv");
    } else {


        urls.push_back("https://aire.cdmx.gob.mx/descargas/Opendata/anuales_horarios/meteorolog%C3%ADa_" +


                       std::to_string(year) + ".csv");
    }




    urls.push_back(simat_annual_atmosphere_url(source, year));

    if (source == 0) {


        urls.push_back("http://datosabiertos.aire.cdmx.gob.mx:8080/opendata/anuales_horarios/meteorolog%C3%ADa_" +


                       std::to_string(year) + ".csv");
    }

    std::vector<std::string> unique;

    std::set<std::string> seen;


    for (const auto& url : urls) {


        if (seen.insert(url).second) unique.push_back(url);
    }

    return unique;
}



fs::path simat_annual_atmosphere_target(int source, int year) {


    const fs::path root = source == 1 ? rama_contaminants_csv_root() : rama_meteorological_csv_root();
    const std::string prefix = source == 1 ? "simat_contaminantes_" : "simat_meteorologicos_";


    return root / (prefix + std::to_string(year) + ".csv");
}



bool usable_csv_download(const fs::path& p, std::uintmax_t min_bytes = 4096) {


    return fs::exists(p) && file_size_or_zero(p) >= min_bytes && !looks_like_html_or_gateway_error(p);
}



