bool download_simat_catalogs_for_source(int source, nlohmann::json& audit) {


    const fs::path root = selected_csv_source_root(source);
    ensure_dir(root);
    audit = {
        {"source", source == 1 ? "RAMA contaminantes horarios" : "REDMET meteorologia horaria"},
        {"provider", "SIMAT aire.cdmx.gob.mx catalogos Opendata"},

        {"target_root", path_utf8(root)},
        {"started_at_utc", now_utc_iso()},


        {"catalogs", nlohmann::json::array()}
    };
    int ok_count = 0;


    for (const auto& [filename, url] : simat_catalog_sources()) {


        nlohmann::json one;

        const fs::path target = root / filename;


        const bool ok = usable_csv_download(target, 64) ||


                        download_validated_url_to_file(url, target, "csv", 64, 3, &one);


        one["url"] = url;

        one["target_file"] = filename;
        one["ok"] = ok;


        one["final_size_bytes"] = file_size_or_zero(target);

        if (ok) ++ok_count;

        audit["catalogs"].push_back(one);
    }
    audit["ok"] = ok_count >= 2;
    audit["completed_at_utc"] = now_utc_iso();

    return audit.value("ok", false);
}




bool download_simat_annual_atmosphere_csv(int source, int year, nlohmann::json& audit) {

    const fs::path target = simat_annual_atmosphere_target(source, year);


    const std::vector<std::string> urls = simat_annual_atmosphere_urls(source, year);

    audit = {
        {"source", source == 1 ? "RAMA contaminantes horarios" : "REDMET meteorologia horaria"},
        {"provider", "SIMAT aire.cdmx.gob.mx Opendata; datosabiertos.aire.cdmx.gob.mx solo respaldo heredado"},

        {"year", year},


        {"url", urls.empty() ? std::string{} : urls.front()},


        {"candidate_urls", urls},

        {"target_file", path_utf8(target.filename())},
        {"started_at_utc", now_utc_iso()}
    };

    ensure_dir(target.parent_path());


    if (usable_csv_download(target)) {
        audit["ok"] = true;


        audit["skipped_existing_valid_csv"] = true;


        audit["final_size_bytes"] = file_size_or_zero(target);
        audit["completed_at_utc"] = now_utc_iso();

        return true;
    }

    bool ok = false;


    audit["attempts"] = nlohmann::json::array();


    for (const std::string& url : urls) {


        nlohmann::json transfer_audit;


        ok = download_validated_url_to_file(url, target, "csv", 4096, 4, &transfer_audit);


        transfer_audit["candidate_url"] = url;

        audit["attempts"].push_back(transfer_audit);


        if (ok || usable_csv_download(target)) {
            ok = true;


            audit["accepted_url"] = url;
            break;
        }
    }

    if (!ok) {


        bool all_missing = !urls.empty();


        audit["http_statuses"] = nlohmann::json::array();


        for (const std::string& url : urls) {


            const int status = http_status_code_fast(url);


            audit["http_statuses"].push_back({{"url", url}, {"status", status}});


            if (!http_status_is_official_miss(status)) all_missing = false;
        }

        const int current_year = approximate_current_epi_year();


        audit["official_not_published"] = all_missing && year > current_year;

        audit["official_missing_past_year"] = all_missing && year <= current_year;
    }


    audit["ok"] = ok || usable_csv_download(target);


    audit["final_size_bytes"] = file_size_or_zero(target);
    audit["completed_at_utc"] = now_utc_iso();

    return audit.value("ok", false);
}




bool download_atmosphere_source_for_import(UiState& ui, int source, int year_start, int year_end) {


    nlohmann::json manifest;
    manifest["dataset"] = "rama_redma_fuentes_oficiales";


    manifest["storage_policy"] = "CSV oficiales descargados en Descargas; Datos conserva solo bloques .ixiptlah";

    manifest["started_at_utc"] = now_utc_iso();


    manifest["sources"] = nlohmann::json::array();



    const auto set_status = [&](const std::string& message, float progress) {


        std::lock_guard<std::mutex> lock(ui.mu);
        ui.atmosphere_import_progress = progress;
        ui.atmosphere_import_status = message;

        ui.status = message;
        append_import_log_locked(ui, message);
    };

    bool ok = false;
    try {


        ScopedDownloadFileLock global_lock(official_data_download_global_lock_path());

        if (!global_lock.acquired) {

            set_status("Otra descarga oficial esta activa; se conserva la importacion local disponible.", 0.12f);

            return false;
        }

        year_start = std::clamp(year_start, source == 1 ? 1986 : 1986, 2300);

        year_end = std::clamp(year_end, 1986, 2300);

        if (year_end < year_start) year_end = year_start;

        manifest["year_start"] = year_start;

        manifest["year_end"] = year_end;


        manifest["raw_root"] = path_utf8(selected_csv_source_root(source));


        manifest["ixiptlah_root"] = path_utf8(atmosphere_output_root_for_source(source));



        nlohmann::json catalog_audit;


        const bool catalogs_ok = download_simat_catalogs_for_source(source, catalog_audit);
        catalog_audit["role"] = "catalogos_para_georreferenciar_unidades_y_parametros";

        manifest["sources"].push_back(catalog_audit);
        set_status(catalogs_ok ? "Catalogos SIMAT validados para estaciones, parametros y unidades." :
                                 "Catalogos SIMAT incompletos; se usaran respaldos internos cuando sea posible.",
                   0.09f);

        int attempted = 0;
        int ok_count = 0;

        int not_published_count = 0;
        int failed_count = 0;

        const int total = std::max(1, year_end - year_start + 1);


        const int workers = official_download_worker_count_for("TLALPOWA_DOWNLOAD_WORKERS_RAMA", total, 4);
        manifest["parallel_workers"] = workers;


        manifest["download_strategy"] = "cola anual acotada: anios recientes primero, pocos CSV grandes simultaneos, curl con tiempo largo para archivos oficiales, fast-fail solo de HTTP 404/410 confirmado, escrituras atomicas .candidate/.download y conservacion de CSV previos validos";


        manifest["env_workers"] = "TLALPOWA_DOWNLOAD_WORKERS_RAMA u TLALPOWA_DOWNLOAD_WORKERS";


        manifest["env_buffer_kib"] = "TLALPOWA_DOWNLOAD_BUFFER_KIB";


        struct AtmosphereYearResult {

            int year = 0;
            bool ok = false;

            bool not_published = false;


            nlohmann::json audit;
        };

        std::vector<int> years;

        years.reserve(static_cast<size_t>(total));

        for (int year = year_end; year >= year_start; --year) years.push_back(year);

        std::vector<int> failed_years;



        std::vector<std::future<AtmosphereYearResult>> futures;


        futures.reserve(static_cast<size_t>(workers));

        size_t next_year = 0;


        const auto download_one_year = [source](int year) -> AtmosphereYearResult {

            AtmosphereYearResult r;

            r.year = year;
            try {


                r.ok = download_simat_annual_atmosphere_csv(source, year, r.audit);
                r.not_published = r.audit.value("official_not_published", false);

            } catch (const std::exception& e) {
                r.ok = false;
                r.audit["exception"] = e.what();

                r.audit["year"] = year;

            } catch (...) {
                r.ok = false;
                r.audit["exception"] = "excepcion_desconocida";

                r.audit["year"] = year;
            }

            return r;
        };

        const auto launch_year = [&]() {

            const int year = years[next_year++];


            futures.emplace_back(std::async(std::launch::async, [download_one_year, year]() -> AtmosphereYearResult {


                return download_one_year(year);
            }));
        };

        const auto drain_one_year = [&]() {


            const size_t ready = wait_ready_future_index(futures, nullptr, 14);


            AtmosphereYearResult r = futures[ready].get();


            futures.erase(futures.begin() + static_cast<std::ptrdiff_t>(ready));
            ++attempted;

            if (r.ok) ++ok_count;


            else if (r.not_published) ++not_published_count;
            else {
                ++failed_count;

                failed_years.push_back(r.year);
            }
            r.audit["parallel_completed_order"] = attempted;
            r.audit["parallel_workers"] = workers;

            manifest["sources"].push_back(r.audit);

            const float progress = 0.08f + 0.10f * static_cast<float>(attempted) / static_cast<float>(total);
            set_status((source == 1 ? "RAMA concurrente " : "REDMET concurrente ") +
                       std::to_string(attempted) + "/" + std::to_string(total) +

                       " años; ultimo: " + std::to_string(r.year) +

                       (r.ok ? " valido" : (r.not_published ? " aun no publicado" : " fallo")), progress);
        };


        set_status((source == 1 ? "Descargando RAMA horaria oficial en paralelo" : "Descargando REDMET horaria oficial en paralelo") +
                   std::string(" con verificacion completa; trabajadores ") + std::to_string(workers), 0.08f);


        while (next_year < years.size() || !futures.empty()) {


            while (next_year < years.size() && futures.size() < static_cast<size_t>(workers)) launch_year();


            if (!futures.empty()) drain_one_year();
        }

        for (int retry_round = 1; retry_round <= 3 && !failed_years.empty(); ++retry_round) {

            std::vector<int> retry_years = failed_years;

            failed_years.clear();

            const int retry_workers = std::max(1, std::min(2, static_cast<int>(retry_years.size())));


            std::vector<std::future<AtmosphereYearResult>> retry_futures;


            retry_futures.reserve(static_cast<size_t>(retry_workers));
            size_t next_retry = 0;
            int retry_done = 0;

            const auto launch_retry = [&]() {

                const int year = retry_years[next_retry++];


                retry_futures.emplace_back(std::async(std::launch::async, [download_one_year, year]() -> AtmosphereYearResult {


                    return download_one_year(year);
                }));
            };
            set_status((source == 1 ? "Reintentando RAMA " : "Reintentando REDMET ") +

                       std::to_string(retry_round) + "/3; anios pendientes " + std::to_string(retry_years.size()),
                       0.18f);


            while (next_retry < retry_years.size() || !retry_futures.empty()) {


                while (next_retry < retry_years.size() && retry_futures.size() < static_cast<size_t>(retry_workers)) launch_retry();


                if (retry_futures.empty()) continue;


                const size_t ready = wait_ready_future_index(retry_futures, nullptr, 18);


                AtmosphereYearResult r = retry_futures[ready].get();


                retry_futures.erase(retry_futures.begin() + static_cast<std::ptrdiff_t>(ready));
                ++attempted;
                ++retry_done;

                if (r.ok) ++ok_count;


                else if (r.not_published) ++not_published_count;

                else failed_years.push_back(r.year);
                r.audit["retry_round"] = retry_round;
                r.audit["retry_completed_order"] = retry_done;
                r.audit["retry_workers"] = retry_workers;

                manifest["sources"].push_back(r.audit);
                set_status((source == 1 ? "Reintento RAMA " : "Reintento REDMET ") +
                           std::to_string(retry_round) + "/3 " + std::to_string(retry_done) + "/" +

                           std::to_string(retry_years.size()) + "; ultimo: " + std::to_string(r.year) +

                           (r.ok ? " valido" : (r.not_published ? " aun no publicado" : " sigue fallando")),
                           0.18f);
            }
        }

        failed_count = static_cast<int>(failed_years.size());
        /* La compilacion IXIPTLAH no debe quedar bloqueada por un anio remoto
           caido si ya existen CSV oficiales validos de RAMA/REDMET. El estado
           parcial queda auditado; la etapa de parser sólo procesa años presentes. */
        ok = ok_count > 0;

        manifest["annual_attempted"] = attempted;
        manifest["annual_ok"] = ok_count;
        manifest["annual_official_not_published"] = not_published_count;
        manifest["annual_failed"] = failed_count;

        manifest["annual_failed_years"] = failed_years;
        manifest["retry_policy"] = "hasta 3 rondas adicionales para anios publicados que fallen; reintentos con 1-2 trabajadores para no saturar al portal oficial";


        manifest["complete_for_ixiptlah_compilation"] = ok;
        manifest["partial_years_allowed_for_ixiptlah_compilation"] = true;


        if (!ok && ok_count == 0) {

            set_status(source == 1 ? "SIMAT horario no dejo ningun anio valido; probando resumen CKAN solo como respaldo descargado." :
                                     "SIMAT horario no dejo ningun anio valido; probando resumen CKAN solo como respaldo descargado.",

                       0.16f);


            nlohmann::json audit;
            bool fallback_ok = false;

            if (source == 0) {


                fallback_ok = download_ckan_csv_package_to_file("redma",


                                                                rama_meteorological_csv_root() / "redma_resumen_cdmx.csv",
                                                                "meteorologicas",
                                                                "REDMET resumen datos abiertos CDMX",
                                                                audit);
            } else {


                fallback_ok = download_ckan_csv_package_to_file("red-automatica-de-monitoreo-atmosferico",


                                                                rama_contaminants_csv_root() / "rama_contaminantes_resumen_cdmx.csv",
                                                                "monitoreo atmosferico",
                                                                "RAMA resumen datos abiertos CDMX",
                                                                audit);
            }
            audit["fallback"] = "ckan_daily_summary";

            audit["fallback_ok"] = fallback_ok;


            audit["used_for_ixiptlah_compilation"] = false;

            manifest["sources"].push_back(audit);
        }
        manifest["ok"] = ok;
        manifest["finished_at_utc"] = now_utc_iso();


        write_text_file_atomic(atmosphere_manifest_path(), manifest.dump(2) + "\n");

    } catch (const std::exception& e) {
        manifest["ok"] = false;
        manifest["error"] = e.what();
        manifest["failed_at_utc"] = now_utc_iso();


        try { write_text_file_atomic(atmosphere_manifest_path(), manifest.dump(2) + "\n"); } catch (...) {}
        set_status(std::string("No pude descargar RAMA/REDMET; se intentara con Descargas locales: ") + e.what(), 0.05f);

        return false;
    }


    set_status(ok ? "Fuente atmosferica oficial completa/validada; compilando .ixiptlah." :


                    "Descarga atmosferica sin CSV valido; usa carpeta Local o reintenta descarga oficial.",

               ok ? 0.18f : 0.06f);

    return ok;
}




bool download_ruoa_pembu_source_for_import(UiState& ui, int year_start, int year_end) {
    nlohmann::json manifest;
    manifest["dataset"] = "ruoa_unam_pembu_csv_mensual";
    manifest["storage_policy"] = "CSV mensuales oficiales en Descargas/Atmosfericos/RUOA_PEMBU; escritura atomica, validacion anti-HTML y compilacion IXIPTLAH solo tras descarga valida";
    manifest["started_at_utc"] = now_utc_iso();

    const fs::path root = selected_csv_source_root(4);
    ensure_dir(root);

    const auto set_status = [&](const std::string& message, float progress, bool log_line) {
        std::lock_guard<std::mutex> lock(ui.mu);
        ui.atmosphere_import_progress = progress;
        ui.atmosphere_import_status = message;
        ui.status = message;
        if (log_line) append_import_log_locked(ui, message);
    };
    const auto set_ruoa_login_state = [&](int state, const std::string& message) {
        std::lock_guard<std::mutex> lock(ui.mu);
        ui.ruoa_login_state = state;
        ui.ruoa_login_message = message;
    };

    try {
        ScopedDownloadFileLock global_lock(official_data_download_global_lock_path());
        if (!global_lock.acquired) {
            set_status("RUOA_UNAM: otra descarga oficial esta activa; se conserva la carpeta local disponible.", 0.08f, true);
            return false;
        }

        const int current_year = std::max(2026, approximate_current_epi_year());
        year_start = std::clamp(year_start, 1997, current_year);
        year_end = std::clamp(year_end, 1997, current_year);
        if (year_end < year_start) std::swap(year_start, year_end);

        ImportRuoa::RuoaCredentials cred;
        cred.usuario = trim(getenv_utf8_or_empty("TLALPOWA_RUOA_USERNAME"));
        cred.password = getenv_utf8_or_empty("TLALPOWA_RUOA_PASSWORD");
        cred.correo = trim(getenv_utf8_or_empty("TLALPOWA_RUOA_EMAIL"));
        if (cred.correo.empty() && cred.usuario.find('@') != std::string::npos) cred.correo = cred.usuario;
        if (cred.usuario.empty() || cred.password.empty()) {
            set_ruoa_login_state(-1, "Credenciales RUOA incompletas.");
            set_status("RUOA_UNAM: escribe correo y contrasena antes de abrir la descarga PEMBU.", 0.06f, true);
            manifest["ok"] = false;
            manifest["error"] = "credenciales_ruoa_vacias";
            manifest["failed_at_utc"] = now_utc_iso();
            write_text_file_atomic(atmosphere_manifest_path(), manifest.dump(2) + "\n");
            return false;
        }

        ImportRuoa::RuoaDownloadOptions opt;
        opt.destino_raiz = root;
        opt.anio_mas_antiguo = year_start;
        opt.anio_mas_reciente = year_end;
        opt.pausa_ms_entre_csv = std::max(1000, download_env_int_local("TLALPOWA_RUOA_DELAY_MS", 1000, 1000, 60000));
        opt.intentos_por_csv = download_env_int_local("TLALPOWA_RUOA_ATTEMPTS", 3, 1, 8);
        opt.csv_min_bytes = static_cast<std::uintmax_t>(download_env_int_local("TLALPOWA_RUOA_MIN_BYTES", 64, 16, 1048576));
        opt.conservar_csv_valido = true;
        opt.estrictamente_reciente_a_antiguo = true;
        opt.transversal_por_mes = true;
        opt.cancelar = &ui.cancel_requested;

        manifest["raw_root"] = path_utf8(root);
        manifest["year_newest"] = year_end;
        manifest["year_oldest"] = year_start;
        manifest["station_order"] = ImportRuoa::estaciones_pembu();
        manifest["download_strategy"] = "rondas transversales: anio reciente a antiguo, mes diciembre a enero, todas las estaciones de ese mes antes de pasar al mes previo; retardo minimo de 1 segundo por CSV";

        {
            std::lock_guard<std::mutex> lock(ui.mu);
            ui.ruoa_station_done.fill(0);
            ui.ruoa_station_total.fill((year_end - year_start + 1) * 12);
            ui.ruoa_station_downloaded.fill(0);
            ui.ruoa_station_skipped.fill(0);
            ui.ruoa_station_failed.fill(0);
            ui.ruoa_total = static_cast<int>(ImportRuoa::estaciones_pembu().size()) * (year_end - year_start + 1) * 12;
            ui.ruoa_done = 0;
            ui.ruoa_downloaded = 0;
            ui.ruoa_usable = 0;
            ui.ruoa_skipped = 0;
            ui.ruoa_failed = 0;
            ui.ruoa_current_label = "";
            ui.ruoa_current_phase = "espera";
        }

        set_status("RUOA_UNAM: iniciando rondas PEMBU por mes; reciente a antiguo sin invertir la barra visual.", 0.06f, true);

        nlohmann::json ruoa_audit;
        int last_logged_block = -1;
        set_ruoa_login_state(2, "Verificando sesión RUOA.");
        const bool ok = ImportRuoa::descargar_csvs_pembu(cred, opt, ruoa_audit,
            [&](const ImportRuoa::RuoaProgress& p) {
                const float frac = p.total > 0 ? std::clamp(static_cast<float>(p.completados) / static_cast<float>(p.total), 0.0f, 1.0f) : 0.0f;
                const float progress = 0.06f + 0.13f * frac;
                {
                    std::lock_guard<std::mutex> lock(ui.mu);
                    ui.ruoa_total = p.total;
                    ui.ruoa_done = p.completados;
                    ui.ruoa_downloaded = p.descargados;
                    ui.ruoa_usable = p.utilizables;
                    ui.ruoa_skipped = p.omitidos_validos;
                    ui.ruoa_failed = p.fallidos;
                    ui.ruoa_current_label = p.etiqueta.empty() ? p.estacion : p.etiqueta;
                    ui.ruoa_current_phase = p.fase;
                    for (size_t i = 0; i < p.estaciones.size() && i < ui.ruoa_station_done.size(); ++i) {
                        ui.ruoa_station_done[i] = p.estaciones[i].completados;
                        ui.ruoa_station_total[i] = p.estaciones[i].total;
                        ui.ruoa_station_downloaded[i] = p.estaciones[i].descargados;
                        ui.ruoa_station_skipped[i] = p.estaciones[i].omitidos_validos;
                        ui.ruoa_station_failed[i] = p.estaciones[i].fallidos;
                    }
                }
                const std::string msg = "RUOA_UNAM " + std::to_string(p.completados) + "/" + std::to_string(std::max(1, p.total)) +
                    " CSV · descargados " + std::to_string(p.descargados) +
                    " · existentes " + std::to_string(p.omitidos_validos) +
                    " · fallos " + std::to_string(p.fallidos) +
                    " · " + (p.etiqueta.empty() ? p.estacion : p.etiqueta) + " " + std::to_string(p.anio) + "-" + (p.mes < 10 ? "0" : "") + std::to_string(p.mes) +
                    " · " + p.fase;
                const int block = p.completados / 12;
                const bool log_line = (block != last_logged_block) || p.completados == p.total;
                if (log_line) last_logged_block = block;
                set_status(msg, progress, log_line);
            });

        const bool ruoa_login_ok = ruoa_audit.value("login_ok", false);
        const std::string ruoa_login_msg = ruoa_audit.value("login_message", std::string());
        set_ruoa_login_state(ruoa_login_ok ? 1 : -1,
                             ruoa_login_ok ? std::string("Sesión RUOA autenticada.")
                                           : (ruoa_login_msg.empty() ? std::string("RUOA rechazó el inicio de sesión.") : ruoa_login_msg));

        manifest["ruoa_audit"] = ruoa_audit;
        manifest["ok"] = ok;
        manifest["primary_ok"] = ruoa_audit.value("primary_ok", 0);
        manifest["downloaded"] = ruoa_audit.value("downloaded", 0);
        manifest["completed"] = ruoa_audit.value("completed", 0);
        manifest["skipped_existing_valid"] = ruoa_audit.value("skipped_existing_valid", 0);
        manifest["failed"] = ruoa_audit.value("failed", 0);
        manifest["cancelled"] = ruoa_audit.value("cancelled", false);
        manifest["finished_at_utc"] = now_utc_iso();
        write_text_file_atomic(atmosphere_manifest_path(), manifest.dump(2) + "\n");

        if (ui.cancel_requested.load() || ruoa_audit.value("cancelled", false)) {
            set_status("RUOA_UNAM: descarga detenida sin corromper CSV; no se compila IXIPTLAH parcial.", 0.06f, true);
            return false;
        }
        set_status(ok ? "RUOA_UNAM: CSV PEMBU utilizables; compilando IXIPTLAH atmosferico." :
                        "RUOA_UNAM: no quedo ningun CSV PEMBU utilizable; no se compilaran datos parciales.",
                   ok ? 0.19f : 0.06f, true);
        return ok;
    } catch (const std::exception& e) {
        manifest["ok"] = false;
        manifest["error"] = e.what();
        manifest["failed_at_utc"] = now_utc_iso();
        try { write_text_file_atomic(atmosphere_manifest_path(), manifest.dump(2) + "\n"); } catch (...) {}
        set_ruoa_login_state(-1, e.what());
        set_status(std::string("RUOA_UNAM: fallo del puente PEMBU: ") + e.what(), 0.06f, true);
        return false;
    } catch (...) {
        manifest["ok"] = false;
        manifest["error"] = "excepcion_desconocida";
        manifest["failed_at_utc"] = now_utc_iso();
        try { write_text_file_atomic(atmosphere_manifest_path(), manifest.dump(2) + "\n"); } catch (...) {}
        set_ruoa_login_state(-1, "Fallo desconocido del puente RUOA.");
        set_status("RUOA_UNAM: fallo desconocido del puente PEMBU.", 0.06f, true);
        return false;
    }
}



void download_mobility_sources_async(UiState& ui) {
    {


        std::lock_guard<std::mutex> lock(ui.mu);


        if (ui.mobility_downloading) {
            ui.mobility_status = "La descarga oficial ya está en curso; no se iniciará otra para evitar solapamiento.";

            return;
        }
    }


    if (ui.mobility_download_thread.joinable()) ui.mobility_download_thread.join();
    {


        std::lock_guard<std::mutex> lock(ui.mu);


        ui.mobility_downloading = true;


        ui.mobility_download_attempted = 0;


        ui.mobility_download_ok = 0;


        ui.mobility_download_total = 3;


        ui.mobility_download_progress = 0.0f;


        ui.mobility_download_phase = "Preparando descarga atómica";
        ui.mobility_status = "Preparando descarga oficial segura; no se reemplazará ningún archivo válido hasta completar.";
        reset_import_log_locked(ui, ui.mobility_status);
    }


    ui.mobility_download_thread = std::thread([&ui]() {


        nlohmann::json manifest;
        manifest["dataset"] = "movilidad_integrada_fuentes_oficiales";


        manifest["downloaded_at_utc"] = now_utc_iso();

        manifest["storage_policy"] = "pocos archivos dentro de Datos; sin mapa_parcelas ni cache cartografica en Datos";


        manifest["atomic_policy"] = "descarga en .download, reanudacion HTTP Range cuando sea posible, promocion atomica al archivo final";


        manifest["sources"] = nlohmann::json::array();
        int ok_count = 0;
        int attempted = 0;
        const int total = 3;


        const auto set_phase = [&](const std::string& phase, int current_attempted, int current_ok) {


            std::lock_guard<std::mutex> lock(ui.mu);


            ui.mobility_download_phase = phase;


            ui.mobility_download_attempted = current_attempted;


            ui.mobility_download_ok = current_ok;


            ui.mobility_download_total = total;


            ui.mobility_download_progress = total > 0 ? std::clamp(static_cast<float>(current_attempted) / static_cast<float>(total), 0.0f, 1.0f) : 0.0f;
            ui.mobility_status = phase + " (" + std::to_string(current_attempted) + "/" + std::to_string(total) + ")";
            append_import_log_locked(ui, ui.mobility_status);
        };

        try {
            ensure_dir(datos_root());


            ScopedDownloadFileLock global_lock(official_data_download_global_lock_path());

            if (!global_lock.acquired) {


                {
                std::lock_guard<std::mutex> lock(ui.mu);


                ui.mobility_downloading = false;
                ui.mobility_status = "Ya existe otra descarga oficial activa; se evitó solapamiento global.";


                ui.mobility_download_phase = "Descarga oficial bloqueada por candado global";

                return;
            }
            }


            ScopedDownloadFileLock batch_lock(mobility_manifest_path());

            if (!batch_lock.acquired) {


                std::lock_guard<std::mutex> lock(ui.mu);


                ui.mobility_downloading = false;
                ui.mobility_status = "Ya existe una descarga oficial activa o un bloqueo reciente; se evitó solapamiento.";


                ui.mobility_download_phase = "Descarga bloqueada por seguridad";

                return;
            }


            const auto fetch_package = [](MobilityPackageJob job) -> MobilityPackageResult {
                MobilityPackageResult r;
                r.job = job;
                try {


                const fs::path meta_tmp = build_runtime_root() / ("ckan_" + job.package_id + ".json.tmp");


                const std::string api = "https://datos.cdmx.gob.mx/api/3/action/package_show?id=" + job.package_id;


                const bool meta_ok = download_url_to_file(api, meta_tmp, 32, 3, true);


                std::string resource_url;

                if (meta_ok) {


                    auto pkg = nlohmann::json::parse(read_text_file(meta_tmp), nullptr, false);


                    if (!pkg.is_discarded()) resource_url = ckan_best_resource_url(pkg, job.fmt, job.preferred_name);
                }
                std::error_code ec;
                fs::remove(meta_tmp, ec);


                fs::remove(fs::path(meta_tmp.wstring() + L".download"), ec);

                r.audit["package_id"] = job.package_id;
                r.audit["name"] = job.human_name;
                r.audit["format"] = job.fmt;


                r.audit["local_file"] = path_utf8(job.target_file.filename());


                r.audit["previous_size_bytes"] = file_size_or_zero(job.target_file);

                r.audit["metadata_ok"] = meta_ok;


                r.audit["resource_url"] = resource_url;

                bool data_ok = false;


                nlohmann::json transfer_audit;


                if (!resource_url.empty()) {


                    data_ok = download_validated_url_to_file(resource_url, job.target_file, job.fmt, job.min_bytes, 4, &transfer_audit);
                }



                const std::uintmax_t final_size = file_size_or_zero(job.target_file);


                const bool previous_usable = job.fmt == "zip" ? strong_zip_validation(job.target_file, job.min_bytes) : usable_csv_download(job.target_file, job.min_bytes);
                const bool preserved_previous = !data_ok && previous_usable;

                r.ready = data_ok || preserved_previous;
                r.audit["ok"] = data_ok;
                r.audit["transfer_audit"] = transfer_audit;

                r.audit["preserved_previous_valid_file"] = preserved_previous;
                r.audit["final_size_bytes"] = final_size;


                r.audit["partial_file"] = path_utf8(fs::path(job.target_file.wstring() + L".download").filename());
                r.audit["completed_at_utc"] = now_utc_iso();

                } catch (const std::exception& e) {

                    r.ready = false;
                    r.audit["package_id"] = job.package_id;
                    r.audit["name"] = job.human_name;

                    r.audit["ok"] = false;
                    r.audit["exception"] = e.what();
                    r.audit["completed_at_utc"] = now_utc_iso();

                } catch (...) {

                    r.ready = false;
                    r.audit["package_id"] = job.package_id;
                    r.audit["name"] = job.human_name;
                    r.audit["ok"] = false;
                    r.audit["exception"] = "excepcion_desconocida";
                    r.audit["completed_at_utc"] = now_utc_iso();
                }

                return r;
            };


            std::vector<MobilityPackageJob> mobility_jobs = {

                {"gtfs", mobility_gtfs_zip_path(), "zip", "gtfs", "GTFS CDMX", 1024},


                {"afluencia-diaria-del-metro-cdmx", mobility_metro_afluence_path(), "csv", "simple", "Afluencia diaria Metro", 1024},


                {"afluencia-diaria-de-metrobus-cdmx", mobility_metrobus_afluence_path(), "csv", "simple", "Afluencia diaria Metrobús", 1024}
            };


            const int mobility_workers = official_download_worker_count_for("TLALPOWA_DOWNLOAD_WORKERS_MOVILIDAD", static_cast<int>(mobility_jobs.size()), 24);
            manifest["parallel_workers"] = mobility_workers;


            manifest["download_strategy"] = "metadatos y recursos CKAN en paralelo acotado, con conexiones WinINet elevadas, buffer configurable y validacion atomica antes de compilar GTFS";


            manifest["env_workers"] = "TLALPOWA_DOWNLOAD_WORKERS_MOVILIDAD u TLALPOWA_DOWNLOAD_WORKERS";


            std::vector<std::future<MobilityPackageResult>> mobility_futures;


            mobility_futures.reserve(static_cast<size_t>(mobility_workers));
            size_t next_mobility_job = 0;

            bool gtfs_ready = false;

            set_phase("Descargando movilidad oficial en paralelo · trabajadores " + std::to_string(mobility_workers), attempted, ok_count);


            while (next_mobility_job < mobility_jobs.size() || !mobility_futures.empty()) {


                while (next_mobility_job < mobility_jobs.size() && mobility_futures.size() < static_cast<size_t>(mobility_workers)) {


                    mobility_futures.emplace_back(std::async(std::launch::async, fetch_package, mobility_jobs[next_mobility_job++]));
                }


                const size_t ready = wait_ready_future_index(mobility_futures, nullptr, 14);


                MobilityPackageResult r = mobility_futures[ready].get();


                mobility_futures.erase(mobility_futures.begin() + static_cast<std::ptrdiff_t>(ready));

                ++attempted;

                if (r.ready) ++ok_count;

                if (r.job.package_id == "gtfs") gtfs_ready = r.ready;

                r.audit["parallel_completed_order"] = attempted;
                r.audit["parallel_workers"] = mobility_workers;

                manifest["sources"].push_back(r.audit);

                set_phase((r.ready ? "Fuente lista: " : "Fuente no disponible: ") + r.job.human_name, attempted, ok_count);
            }

            if (gtfs_ready) {
                set_phase("Compilando red coordenada-a-coordenada desde GTFS oficial", attempted, ok_count);


                nlohmann::json gtfs_audit;

                const bool compiled = compile_mobility_from_gtfs_zip(mobility_gtfs_zip_path(), &gtfs_audit);

                manifest["gtfs_compilation"] = gtfs_audit;

                manifest["gtfs_compilation_ok"] = compiled;

                if (compiled) {


                    auto refreshed = load_mobility_lines_from_jsonl(mobility_consolidated_path());

                    auto refreshed_ptr = std::make_shared<const std::vector<MobilityLine>>(std::move(refreshed));


                    std::lock_guard<std::mutex> lock(ui.mu);

                    ui.mobility_lines.clear();
                    ui.mobility_lines.shrink_to_fit();
                    ui.mobility_lines_ptr = refreshed_ptr;
                    ui.mobility_status = "GTFS oficial compilado: trazos coordenada-a-coordenada, sin esquema aproximado.";
                    ui.mobility_revision.fetch_add(1, std::memory_order_relaxed);
                }
            }

            manifest["attempted"] = attempted;

            manifest["usable_files"] = ok_count;
            manifest["finished_at_utc"] = now_utc_iso();


            write_text_file_atomic(mobility_manifest_path(), manifest.dump(2) + "\n");



            std::lock_guard<std::mutex> lock(ui.mu);


            ui.mobility_downloading = false;


            ui.mobility_download_progress = 1.0f;


            ui.mobility_download_attempted = attempted;


            ui.mobility_download_ok = ok_count;


            ui.mobility_status = "Fuentes oficiales listas/usables: " + std::to_string(ok_count) + "/" + std::to_string(attempted) + " archivos. Archivos incompletos quedaron como .download reanudables.";


            ui.mobility_download_phase = "Descarga finalizada sin solapamiento";

        } catch (const std::exception& e) {


            try { write_text_file_atomic(mobility_manifest_path(), manifest.dump(2) + "\n"); } catch (...) {}


            std::lock_guard<std::mutex> lock(ui.mu);


            ui.mobility_downloading = false;
            ui.mobility_status = std::string("No pude completar descarga de movilidad; se conservaron archivos previos: ") + e.what();


            ui.mobility_download_phase = "Descarga protegida con error recuperable";
        }
    });
}





void download_epidemiology_sources_async(UiState& ui) {
    {


        std::lock_guard<std::mutex> lock(ui.mu);


        if (ui.epi_downloading) {
            ui.epi_status = "La descarga de boletines ya está en curso; no se iniciará otra para evitar solapamiento.";

            return;
        }


        if (ui.epi_download_thread.joinable()) ui.epi_download_thread.join();


        ui.epi_downloading = true;
        ui.epi_cancel_requested.store(false);


        ui.epi_download_attempted = 0;


        ui.epi_download_ok = 0;


        ui.epi_download_skipped = 0;


        ui.epi_download_total = 0;


        ui.epi_download_progress = 0.0f;


        ui.epi_download_phase = "Preparando cola epidemiológica segura";
        ui.epi_status = "Preparando descarga de boletines oficiales";


        reset_import_log_locked(ui, "Preparando descarga de boletines oficiales: primero se descargan todos los documentos; después se extraen y se compilan a .ixiptlah.");
    }



    const bool want_cdmx = ui.epi_download_cdmx;


    const bool want_edomex = ui.epi_download_edomex;


    const int year_start = ui.epi_year_start;

    const int year_end = ui.epi_year_end;



    ui.epi_download_thread = std::thread([&ui, want_cdmx, want_edomex, year_start, year_end]() {


        nlohmann::json manifest;
        manifest["dataset"] = "boletines_epidemiologicos_cdmx_edomex";
        manifest["storage_policy"] = "Datos/Boletines Epidemiológicos de la Ciudad de México y Datos/Boletines Epidemiológicos del Estado de México";


        manifest["atomic_policy"] = "descarga a .candidate/.download, validacion de firma PDF/ZIP, promocion atomica, extraccion de ZIP solo desde staging";
        manifest["started_at_utc"] = now_utc_iso();


        manifest["cdmx"] = nlohmann::json::array();


        manifest["edomex"] = nlohmann::json::array();


        manifest["extractions"] = nlohmann::json::array();


        manifest["journal"] = path_utf8(epidemiology_journal_path().filename());
        manifest["validation_policy"] = "PDF exige %PDF y %%EOF; ZIP exige PK y directorio central EOCD; HTML de error se manda a cuarentena; ningun recurso invalido reemplaza uno valido";



        append_epidemiology_journal({{"event", "batch_started"}, {"utc", now_utc_iso()}, {"year_start", year_start}, {"year_end", year_end}, {"cdmx", want_cdmx}, {"edomex", want_edomex}});

        int attempted = 0;
        int ok_count = 0;
        int skipped = 0;
        int total = 1;


        const auto set_phase = [&](const std::string& phase) {


            std::lock_guard<std::mutex> lock(ui.mu);


            ui.epi_download_phase = phase;


            ui.epi_download_attempted = attempted;


            ui.epi_download_ok = ok_count;


            ui.epi_download_skipped = skipped;


            ui.epi_download_total = total;


            ui.epi_download_progress = total > 0 ? std::clamp(static_cast<float>(attempted) / static_cast<float>(total), 0.0f, 1.0f) : 0.0f;
            ui.epi_status = phase + " (" + std::to_string(attempted) + "/" + std::to_string(total) + ", válidos " + std::to_string(ok_count) + ", omitidos " + std::to_string(skipped) + ")";
            append_import_log_locked(ui, ui.epi_status);
        };

        try {


            ensure_dir(epidemiology_download_root());
            ensure_dir(epidemiology_cdmx_zip_dir());
            ensure_dir(epidemiology_cdmx_extract_dir());

            ensure_dir(epidemiology_edomex_pdf_dir());
            ensure_dir(epidemiology_staging_dir());
            ensure_dir(epidemiology_quarantine_dir());

            prune_quarantine_if_needed();



            std::error_code staging_ec;
            fs::remove_all(epidemiology_staging_dir(), staging_ec);
            ensure_dir(epidemiology_staging_dir());



            ScopedDownloadFileLock global_lock(official_data_download_global_lock_path());

            if (!global_lock.acquired) {


                std::lock_guard<std::mutex> lock(ui.mu);


                ui.epi_downloading = false;
                ui.epi_status = "Ya existe otra descarga oficial activa; se evitó solapamiento global.";


                ui.epi_download_phase = "Descarga epidemiológica bloqueada por candado global";

                return;
            }


            ScopedDownloadFileLock batch_lock(epidemiology_manifest_path());

            if (!batch_lock.acquired) {


                std::lock_guard<std::mutex> lock(ui.mu);


                ui.epi_downloading = false;
                ui.epi_status = "Ya existe una descarga epidemiológica activa o un bloqueo reciente; se evitó solapamiento.";


                ui.epi_download_phase = "Descarga epidemiológica bloqueada por seguridad";

                return;
            }



            std::vector<CdmxZipDownloadJob> cdmx_zip_jobs;


            std::vector<CdmxBulletinDownloadJob> cdmx_pdf_jobs;


            const std::string cdmx_index_url = "https://sersalud.cdmx.gob.mx/sspcdmx/direccion_epi_preven.php";

            if (want_cdmx) {


                set_phase("Consultando índice CDMX de boletines semanales");


                const fs::path index_candidate = epidemiology_download_root() / "cdmx_indice_boletines.html";


                nlohmann::json idx_audit;


                const bool index_ok = download_validated_url_to_file(cdmx_index_url, index_candidate, "html", 512, 3, &idx_audit);
                manifest["cdmx_index"] = idx_audit;


                std::vector<std::string> cdmx_pdf_urls;


                std::vector<std::string> cdmx_zip_urls;


                if (index_ok || file_size_or_zero(index_candidate) >= 512) {

                    const std::string html = read_text_file(index_candidate);


                    cdmx_zip_urls = scrape_links_by_extension(html, cdmx_index_url, ".zip");


                    cdmx_pdf_urls = scrape_links_by_extension(html, cdmx_index_url, ".pdf");


                    std::sort(cdmx_zip_urls.begin(), cdmx_zip_urls.end());


                    cdmx_zip_urls.erase(std::unique(cdmx_zip_urls.begin(), cdmx_zip_urls.end()), cdmx_zip_urls.end());


                    std::sort(cdmx_pdf_urls.begin(), cdmx_pdf_urls.end());


                    cdmx_pdf_urls.erase(std::unique(cdmx_pdf_urls.begin(), cdmx_pdf_urls.end()), cdmx_pdf_urls.end());
                }


                cdmx_zip_jobs = cdmx_candidate_zip_jobs(year_start, year_end, cdmx_zip_urls);


                cdmx_pdf_jobs = cdmx_candidate_pdf_jobs(year_start, year_end, cdmx_pdf_urls);


                manifest["cdmx_visible_zip_links"] = cdmx_zip_urls.size();


                manifest["cdmx_visible_pdf_links"] = cdmx_pdf_urls.size();
            }



            std::vector<EdomexBulletinDownloadJob> edomex_pdf_jobs;

            if (want_edomex) {

                set_phase("Construyendo cola Edomex por patrón oficial semanal directo");


                std::vector<std::string> visible_edomex_urls;


                nlohmann::json idx_audit;
                idx_audit["policy"] = "consulta rápida del índice oficial si no se desactiva, pero la cola no depende del HTML; siempre existe fallback por patrón directo YYYY/bol-WWYY.pdf";

                if (env_flag_enabled_app("TLALPOWA_EDOMEX_CONSULTAR_INDICE")) {


                    const std::string edomex_index_url = "https://ddsisem.edomex.gob.mx/subepi/boletin/vista_subepibol.php";


                    const fs::path edomex_index = epidemiology_download_root() / "edomex_indice_boletines.html";


                    if (download_validated_url_to_file(edomex_index_url, edomex_index, "html", 512, 1, &idx_audit) || file_size_or_zero(edomex_index) >= 512) {


                        visible_edomex_urls = scrape_links_by_extension(read_text_file(edomex_index), edomex_index_url, ".pdf");


                        std::sort(visible_edomex_urls.begin(), visible_edomex_urls.end());


                        visible_edomex_urls.erase(std::unique(visible_edomex_urls.begin(), visible_edomex_urls.end()), visible_edomex_urls.end());
                    }
                } else {
                    idx_audit["disabled_by_default"] = "v61 usa patrón directo para evitar colapsos por HTML/locks del portal; activar TLALPOWA_EDOMEX_CONSULTAR_INDICE=1 sólo si se quiere enriquecer la cola con enlaces visibles";
                }


                edomex_pdf_jobs = edomex_candidate_pdf_jobs(year_start, year_end, visible_edomex_urls);
                manifest["edomex_index"] = idx_audit;


                manifest["edomex_visible_pdf_links"] = visible_edomex_urls.size();
            }



            std::stable_sort(cdmx_pdf_jobs.begin(), cdmx_pdf_jobs.end(), [](const CdmxBulletinDownloadJob& a, const CdmxBulletinDownloadJob& b) {

                return std::tie(a.year, a.week, a.target_filename) > std::tie(b.year, b.week, b.target_filename);

            });


            std::stable_sort(edomex_pdf_jobs.begin(), edomex_pdf_jobs.end(), [](const EdomexBulletinDownloadJob& a, const EdomexBulletinDownloadJob& b) {

                return std::tie(a.year, a.week, a.target_filename) > std::tie(b.year, b.week, b.target_filename);
            });


            std::stable_sort(cdmx_zip_jobs.begin(), cdmx_zip_jobs.end(), [](const CdmxZipDownloadJob& a, const CdmxZipDownloadJob& b) {

                return std::tie(a.year, a.target_filename) > std::tie(b.year, b.target_filename);
            });


            total = static_cast<int>(cdmx_zip_jobs.size() + cdmx_pdf_jobs.size() + edomex_pdf_jobs.size());

            if (total <= 0) total = 1;
            manifest["planned_cdmx_zip_count"] = cdmx_zip_jobs.size();

            manifest["planned_cdmx_pdf_jobs"] = cdmx_pdf_jobs.size();


            manifest["planned_edomex_week_jobs"] = edomex_pdf_jobs.size();
            manifest["cdmx_pattern_policy"] = "CDMX depende del HTML oficial direccion_epi_preven.php: PDFs visibles del anio actual y ZIPs visibles de anios cerrados 2019+ bajo Documentos/direccion/demp/boletin; no se descargan 2008-2018 y nunca se reutiliza patron Edomex";

            manifest["edomex_pattern_policy"] = "semanas 01-53 por año, con variantes BOL-/bol-/Bol-, nombre final canónico por año-semana y promoción atómica";


            manifest["year_start"] = year_start;

            manifest["year_end"] = year_end;


            const int pdf_total = static_cast<int>(cdmx_pdf_jobs.size() + edomex_pdf_jobs.size());


            const int pdf_workers = official_download_worker_count_for("TLALPOWA_DOWNLOAD_WORKERS_PDF", pdf_total, 96);


            const int zip_workers = official_download_worker_count_for("TLALPOWA_DOWNLOAD_WORKERS_ZIP", static_cast<int>(cdmx_zip_jobs.size()), 32);
            manifest["parallel_pdf_workers"] = pdf_workers;
            manifest["parallel_zip_workers"] = zip_workers;


            manifest["download_strategy"] = "descarga no lineal agresiva: años recientes primero, CDMX/Edomex intercalados, PDFs concurrentes, ZIPs concurrentes, conexiones WinINet elevadas, fast-fail HTTP, buffer configurable y extraccion validada posterior";


            manifest["env_workers"] = "TLALPOWA_DOWNLOAD_WORKERS_PDF / TLALPOWA_DOWNLOAD_WORKERS_ZIP / TLALPOWA_DOWNLOAD_WORKERS";


            manifest["env_buffer_kib"] = "TLALPOWA_DOWNLOAD_BUFFER_KIB";




            std::vector<std::future<EpiPdfParallelResult>> pdf_futures;


            pdf_futures.reserve(static_cast<size_t>(std::max(1, pdf_workers)));
            size_t next_cdmx = 0;
            size_t next_edomex = 0;


            const auto launch_cdmx_pdf = [&]() -> bool {


                if (next_cdmx >= cdmx_pdf_jobs.size()) return false;


                const CdmxBulletinDownloadJob job = cdmx_pdf_jobs[next_cdmx++];


                pdf_futures.emplace_back(std::async(std::launch::async, [job]() -> EpiPdfParallelResult {
                    EpiPdfParallelResult r;
                    r.source = "cdmx_pdf";

                    r.year = job.year;

                    r.week = job.week;

                    r.label = job.year > 0 ? (std::to_string(job.year) + " SE" + two_digit_int(job.week)) : job.target_filename;
                    try {


                        r.ok = download_cdmx_bulletin_pdf_job(job, epidemiology_cdmx_root(), &r.audit);

                    } catch (const std::exception& e) {
                        r.ok = false;
                        r.audit["exception"] = e.what();

                    } catch (...) {
                        r.ok = false;
                        r.audit["exception"] = "excepcion_desconocida";
                    }

                    return r;
                }));

                return true;
            };


            const auto launch_edomex_pdf = [&]() -> bool {


                if (next_edomex >= edomex_pdf_jobs.size()) return false;


                const EdomexBulletinDownloadJob job = edomex_pdf_jobs[next_edomex++];


                pdf_futures.emplace_back(std::async(std::launch::async, [job]() -> EpiPdfParallelResult {
                    EpiPdfParallelResult r;
                    r.source = "edomex";

                    r.year = job.year;

                    r.week = job.week;

                    r.label = std::to_string(job.year) + " SE" + two_digit_int(job.week);
                    try {


                        r.ok = download_edomex_bulletin_job(job, epidemiology_edomex_pdf_dir(), &r.audit);

                    } catch (const std::exception& e) {
                        r.ok = false;
                        r.audit["exception"] = e.what();

                    } catch (...) {
                        r.ok = false;
                        r.audit["exception"] = "excepcion_desconocida";
                    }

                    return r;
                }));

                return true;
            };


            const auto launch_next_pdf = [&]() -> bool {


                if (ui.epi_cancel_requested.load()) return false;
                const bool prefer_cdmx = ((next_cdmx + next_edomex) % 2) == 0;


                if (prefer_cdmx) return launch_cdmx_pdf() || launch_edomex_pdf();


                return launch_edomex_pdf() || launch_cdmx_pdf();
            };


            const auto drain_one_pdf = [&]() {


                const size_t ready = wait_ready_future_index(pdf_futures, &ui.epi_cancel_requested, 12);


                EpiPdfParallelResult r = pdf_futures[ready].get();


                pdf_futures.erase(pdf_futures.begin() + static_cast<std::ptrdiff_t>(ready));
                ++attempted;

                if (r.ok) ++ok_count; else ++skipped;
                r.audit["parallel_completed_order"] = attempted;


                r.audit["parallel_workers"] = pdf_workers;

                if (r.source == "edomex") manifest["edomex"].push_back(r.audit);

                else manifest["cdmx"].push_back(r.audit);


                append_epidemiology_journal({{"event", r.ok ? "resource_processed" : "resource_unavailable"}, {"source", r.source}, {"year", r.year}, {"week", r.week}, {"utc", now_utc_iso()}, {"audit", r.audit}});
                set_phase((r.ok ? "PDF válido: " : "PDF no disponible: ") + r.source + " " + r.label +
                          " · " + std::to_string(attempted) + "/" + std::to_string(total));
            };


            set_phase("Descargando PDFs epidemiológicos en paralelo · trabajadores " + std::to_string(pdf_workers));


            while ((next_cdmx < cdmx_pdf_jobs.size() || next_edomex < edomex_pdf_jobs.size()) || !pdf_futures.empty()) {


                while (!ui.epi_cancel_requested.load() &&
                       (next_cdmx < cdmx_pdf_jobs.size() || next_edomex < edomex_pdf_jobs.size()) &&


                       pdf_futures.size() < static_cast<size_t>(std::max(1, pdf_workers))) {


                    if (!launch_next_pdf()) break;
                }


                if (!pdf_futures.empty()) drain_one_pdf();
                else break;
            }


            std::vector<fs::path> valid_cdmx_zip_paths;

            valid_cdmx_zip_paths.reserve(cdmx_zip_jobs.size());


            std::vector<std::future<CdmxZipParallelResult>> zip_futures;


            zip_futures.reserve(static_cast<size_t>(std::max(1, zip_workers)));
            size_t next_zip = 0;

            const auto launch_next_zip = [&]() -> bool {


                if (ui.epi_cancel_requested.load() || next_zip >= cdmx_zip_jobs.size()) return false;


                const CdmxZipDownloadJob job = cdmx_zip_jobs[next_zip++];


                zip_futures.emplace_back(std::async(std::launch::async, [job]() -> CdmxZipParallelResult {
                    CdmxZipParallelResult r;


                    r.url = job.urls.empty() ? std::string() : job.urls.front();

                    r.year = job.year;

                    r.label = job.year > 0 ? std::to_string(job.year) : job.target_filename;

                    r.fname = job.target_filename.empty() ? cdmx_zip_target_filename(job.year) : job.target_filename;
                    try {


                        r.ok = download_cdmx_zip_job(job, r.zip_path, &r.audit);

                        r.fname = path_utf8(r.zip_path.filename());

                    } catch (const std::exception& e) {
                        r.ok = false;
                        r.audit["exception"] = e.what();

                    } catch (...) {
                        r.ok = false;
                        r.audit["exception"] = "excepcion_desconocida";
                    }
                    r.audit["completed_at_utc"] = now_utc_iso();

                    return r;
                }));

                return true;
            };

            const auto drain_one_zip = [&]() {


                const size_t ready = wait_ready_future_index(zip_futures, &ui.epi_cancel_requested, 12);


                CdmxZipParallelResult r = zip_futures[ready].get();


                zip_futures.erase(zip_futures.begin() + static_cast<std::ptrdiff_t>(ready));
                ++attempted;

                const bool valid_zip = r.ok || strong_zip_validation(r.zip_path, 4096);
                r.audit["parallel_completed_order"] = attempted;
                r.audit["parallel_workers"] = zip_workers;

                if (valid_zip) {

                    if (!r.ok) r.audit["preserved_previous_valid_zip"] = true;

                    valid_cdmx_zip_paths.push_back(r.zip_path);
                    ++ok_count;
                } else {
                    ++skipped;
                }

                manifest["cdmx"].push_back(r.audit);


                append_epidemiology_journal({{"event", valid_zip ? "zip_downloaded_valid" : "resource_unavailable"}, {"source", "cdmx_zip"}, {"year", r.year}, {"utc", now_utc_iso()}, {"audit", r.audit}});
                set_phase(std::string(valid_zip ? "ZIP CDMX descargado y validado: " : "ZIP CDMX no disponible: ") + r.fname +
                          " · " + std::to_string(attempted) + "/" + std::to_string(total));
            };



            if (!cdmx_zip_jobs.empty()) set_phase("Descargando ZIPs CDMX en paralelo · trabajadores " + std::to_string(zip_workers));


            while (next_zip < cdmx_zip_jobs.size() || !zip_futures.empty()) {


                while (!ui.epi_cancel_requested.load() && next_zip < cdmx_zip_jobs.size() &&


                       zip_futures.size() < static_cast<size_t>(std::max(1, zip_workers))) {

                    if (!launch_next_zip()) break;
                }


                if (!zip_futures.empty()) drain_one_zip();
                else break;
            }


            int preserved_zip_count = 0;


            for (const auto& existing_zip : valid_cdmx_zip_paths_in_pool(epidemiology_cdmx_zip_dir())) {

                const size_t before = valid_cdmx_zip_paths.size();

                add_unique_path_by_text(valid_cdmx_zip_paths, existing_zip);

                if (valid_cdmx_zip_paths.size() != before) ++preserved_zip_count;
            }
            manifest["preserved_existing_cdmx_zip_count"] = preserved_zip_count;

            if (preserved_zip_count > 0) {


                append_epidemiology_journal({{"event", "existing_zip_detected_after_download"}, {"source", "cdmx_zip"}, {"utc", now_utc_iso()}, {"count", preserved_zip_count}});
            }



            set_phase("Descarga documental cerrada; iniciando extracción CDMX posterior a todas las descargas");

            const int extract_total = static_cast<int>(valid_cdmx_zip_paths.size());


            const int extract_workers = official_download_worker_count_for("TLALPOWA_EXTRACT_WORKERS_ZIP", extract_total, 6);
            manifest["extract_workers"] = extract_workers;


            std::vector<std::future<CdmxZipExtractResult>> extract_futures;


            extract_futures.reserve(static_cast<size_t>(std::max(1, extract_workers)));
            size_t next_extract = 0;
            int extract_done = 0;

            const auto launch_next_extract = [&]() -> bool {


                if (ui.epi_cancel_requested.load() || next_extract >= valid_cdmx_zip_paths.size()) return false;

                const fs::path zip_path = valid_cdmx_zip_paths[next_extract++];


                extract_futures.emplace_back(std::async(std::launch::async, [zip_path]() -> CdmxZipExtractResult {
                    CdmxZipExtractResult r;

                    r.zip_path = zip_path;
                    try {


                        r.ok = expand_zip_safely_to_pdf_pool(zip_path, epidemiology_cdmx_extract_dir(), &r.audit);

                    } catch (const std::exception& e) {

                        r.ok = false;
                        r.audit["exception"] = e.what();

                    } catch (...) {
                        r.ok = false;
                        r.audit["exception"] = "excepcion_desconocida";
                    }
                    r.audit["completed_at_utc"] = now_utc_iso();

                    return r;
                }));


                return true;
            };

            const auto drain_one_extract = [&]() {


                const size_t ready = wait_ready_future_index(extract_futures, &ui.epi_cancel_requested, 20);


                CdmxZipExtractResult r = extract_futures[ready].get();


                extract_futures.erase(extract_futures.begin() + static_cast<std::ptrdiff_t>(ready));
                ++extract_done;
                r.audit["extract_completed_order"] = extract_done;

                r.audit["extract_workers"] = extract_workers;

                manifest["extractions"].push_back(r.audit);

                append_epidemiology_journal({{"event", r.ok ? "zip_extracted" : "zip_extract_failed"}, {"source", "cdmx_zip"}, {"utc", now_utc_iso()}, {"audit", r.audit}});

                set_phase(std::string(r.ok ? "ZIP CDMX extraído: " : "ZIP CDMX con extracción fallida: ") + path_utf8(r.zip_path.filename()) +
                          " · extracción " + std::to_string(extract_done) + "/" + std::to_string(std::max(1, extract_total)));
            };


            if (extract_total > 0) set_phase("Extrayendo ZIPs CDMX después de terminar todas las descargas · trabajadores " + std::to_string(extract_workers));


            while (next_extract < valid_cdmx_zip_paths.size() || !extract_futures.empty()) {


                while (!ui.epi_cancel_requested.load() && next_extract < valid_cdmx_zip_paths.size() &&


                       extract_futures.size() < static_cast<size_t>(std::max(1, extract_workers))) {

                    if (!launch_next_extract()) break;
                }


                if (!extract_futures.empty()) drain_one_extract();
                else break;
            }



            nlohmann::json cdmx_pdf_norm_audit;


            const auto cdmx_pdf_norm = normalize_cdmx_pdf_names_in_pool_until_stable(epidemiology_cdmx_root(), &cdmx_pdf_norm_audit);


            manifest["cdmx_pdf_name_normalization"] = cdmx_pdf_norm_audit;


            append_epidemiology_journal({{"event", "cdmx_pdf_names_normalized_after_download_extract"}, {"source", "cdmx_pdf"}, {"utc", now_utc_iso()}, {"audit", cdmx_pdf_norm_audit}});


            if (cdmx_pdf_norm.renamed_or_moved > 0 || cdmx_pdf_norm.duplicate_removed > 0 || cdmx_pdf_norm.empty_dirs_removed > 0) {
                set_phase("PDFs CDMX normalizados: " + std::to_string(cdmx_pdf_norm.renamed_or_moved) +
                          " renombrados/movidos, " + std::to_string(cdmx_pdf_norm.duplicate_removed) +

                          " duplicados retirados, " + std::to_string(cdmx_pdf_norm.empty_dirs_removed) + " carpetas vacías eliminadas");
            }

            manifest["attempted"] = attempted;

            manifest["cancel_requested"] = ui.epi_cancel_requested.load();
            manifest["valid_or_preserved"] = ok_count;
            manifest["skipped_or_unavailable"] = skipped;
            manifest["finished_at_utc"] = now_utc_iso();


            write_text_file_atomic(epidemiology_manifest_path(), manifest.dump(2) + "\n");
            append_epidemiology_journal({{"event", "batch_finished"}, {"utc", now_utc_iso()}, {"attempted", attempted}, {"valid_or_preserved", ok_count}, {"skipped", skipped}, {"cancel_requested", ui.epi_cancel_requested.load()}});



            std::lock_guard<std::mutex> lock(ui.mu);


            ui.epi_downloading = false;


            ui.epi_download_progress = 1.0f;


            ui.epi_download_attempted = attempted;


            ui.epi_download_ok = ok_count;


            ui.epi_download_skipped = skipped;


            ui.epi_download_total = total;


            ui.epi_download_phase = ui.epi_cancel_requested.load() ? "Descarga epidemiológica detenida de forma segura" : "Descarga epidemiológica finalizada con validación";


            const bool auto_compile_requested = ui.pending_import_after_epi_download && !ui.epi_cancel_requested.load();
            ui.epi_status = std::string(ui.epi_cancel_requested.load() ? "Descarga detenida sin corromper archivos. " : "") + "Boletines listos/usables: " + std::to_string(ok_count) + "/" + std::to_string(attempted) + "; omitidos/no disponibles: " + std::to_string(skipped) + ".";


            if (auto_compile_requested) ui.epi_status += " Conversión .ixiptlah encolada sobre los PDFs existentes.";


            append_import_log_locked(ui, ui.epi_status + " Listo para compilar .ixiptlah sin mezclar descarga y extracción.");
            ui.epi_cancel_requested.store(false);

        } catch (const std::exception& e) {
            try {
                manifest["error"] = e.what();
                manifest["failed_at_utc"] = now_utc_iso();


                write_text_file_atomic(epidemiology_manifest_path(), manifest.dump(2) + "\n");
                append_epidemiology_journal({{"event", "batch_error"}, {"utc", now_utc_iso()}, {"error", e.what()}});
            } catch (...) {}


            std::lock_guard<std::mutex> lock(ui.mu);


            ui.epi_downloading = false;
            ui.epi_status = std::string("No pude completar boletines; archivos válidos previos fueron preservados: ") + e.what();


            ui.epi_download_phase = "Descarga epidemiológica protegida con error recuperable";
            append_import_log_locked(ui, ui.epi_status);
            ui.epi_cancel_requested.store(false);
        }
    });
}




GeoBounds viewport_lonlat_bounds(const MapViewport& view) {
    const double left = view_left_world_px(view);
    const double right = view_right_world_px(view);
    const double top = view_top_world_px(view);
    const double bottom = view_bottom_world_px(view);

    const Point2 a = world_px_to_lonlat(left, top, view.z);

    const Point2 b = world_px_to_lonlat(right, bottom, view.z);
    GeoBounds g;

    g.lon_min = std::min(a.x, b.x);

    g.lon_max = std::max(a.x, b.x);

    g.lat_min = std::min(a.y, b.y);

    g.lat_max = std::max(a.y, b.y);
    g.valid = true;

    return g;
}



std::string mobility_system_group(const std::string& system) {


    const std::string s = normalize_key(system);



    if (s.find("metrobus") != std::string::npos || s.find("metro bus") != std::string::npos) return "metrobus";

    if (s == "pumabus" || s.find("puma") != std::string::npos || s.find("unam") != std::string::npos) return "pumabus";

    if (s == "rtp" || s.find("red de transporte de pasajeros") != std::string::npos) return "rtp";

    if (s.find("conces") != std::string::npos || s.find("corredor") != std::string::npos || s.find("colectivo") != std::string::npos || s.find("microbus") != std::string::npos || s.find("combi") != std::string::npos) return "concesionado";

    if (s == "ste" || s.find("electrico") != std::string::npos || s.find("trole") != std::string::npos || s.find("tren ligero") != std::string::npos) return "electrico";

    if (s == "trenes" || s.find("suburbano") != std::string::npos || s.find("interurbano") != std::string::npos || s.find("ferrocarril") != std::string::npos || s.find("el insurgente") != std::string::npos) return "trenes";

    if (s == "metro" || s == "stc" || s.find("sistema de transporte colectivo") != std::string::npos) return "metro";

    return "otros";
}



bool mobility_line_is_tren_ligero(const MobilityLine& line) {




    const std::string txt = normalize_key(line.system + " " + line.name);

    if (txt.find("tren ligero") != std::string::npos) return true;

    if (txt.find("transportes electricos") != std::string::npos) {

        if (txt == "transportes electricos linea 1" || txt.find("transportes electricos linea 1 ") != std::string::npos) return true;
        bool has_tasquena = false;
        bool has_xochimilco = false;

        for (const auto& st : line.stations) {


            const std::string sn = normalize_key(st.name);

            if (sn.find("tasquena") != std::string::npos) has_tasquena = true;

            if (sn.find("xochimilco") != std::string::npos) has_xochimilco = true;

            if (has_tasquena && has_xochimilco) return true;
        }
    }

    return false;
}



bool mobility_line_prefers_dense_geometry(const MobilityLine& line, const std::string& group) {



    return group == "metro" || mobility_line_is_tren_ligero(line);
}



int mobility_draw_rank(const MobilityLine& line) {


    const std::string g = mobility_system_group(line.system);

    if (g == "concesionado") return 0;

    if (g == "pumabus") return 1;

    if (g == "rtp") return 2;

    if (g == "otros") return 3;

    if (g == "electrico") return 4;

    if (g == "trenes") return 5;

    if (g == "metrobus") return 6;

    if (g == "metro") return 7;


    return 3;
}




bool mobility_system_visible(const MobilityLine& line, const UiState& ui) {
    const std::string group = mobility_system_group(line.system);

    if (group == "metro") return ui.mobility_show_metro;

    if (group == "metrobus") return ui.mobility_show_metrobus;

    if (group == "electrico") return ui.mobility_show_electric;

    if (group == "trenes") return ui.mobility_show_trains;

    if (group == "rtp") return ui.mobility_show_rtp;

    if (group == "pumabus") return ui.mobility_show_pumabus;

    if (group == "concesionado") return ui.mobility_show_concessioned;

    return ui.mobility_show_other;
}



