std::string mobility_station_icon_key(const std::string& station_name) {


    std::string s = normalize_key(station_name);
    ozmvm_mobility_station_icon_key_inplace(s.data(), s.size() + 1);


    return safe_filename(trim(s));
}



std::vector<fs::path> mobility_icon_roots() {




    static std::mutex mu;

    static std::vector<fs::path> cached_roots;
    static std::uint64_t last_probe_frame = 0;


    std::lock_guard<std::mutex> lock(mu);

    if (!cached_roots.empty() && g_map_frame_counter < last_probe_frame + 3600) return cached_roots;

    std::vector<fs::path> candidates = {
        workspace_root() / "Recursos_Legado" / "movilidad_iconos",
        datos_externos_root() / L"Íconos",
        datos_externos_root() / L"íconos",
        datos_externos_root() / "Iconos",
        datos_externos_root() / "iconos"
    };

    std::vector<fs::path> roots;

    std::set<std::string> seen;
    std::error_code ec;

    for (const auto& c : candidates) {

        ec.clear();

        if (!fs::exists(c, ec) || ec || !fs::is_directory(c, ec) || ec) continue;

        fs::path canon = c;
        try { canon = fs::weakly_canonical(c, ec); if (ec) canon = c; } catch (...) { canon = c; }


        const std::string k = normalize_key(path_utf8(canon));

        if (seen.insert(k).second) roots.push_back(c);
    }




    if (roots.empty()) roots.push_back(workspace_root() / "Recursos_Legado" / "movilidad_iconos");
    cached_roots = roots;

    last_probe_frame = g_map_frame_counter;

    return cached_roots;
}




fs::path metro_chronology_path() {


    return ui_config_root() / "metro_cronologia_red.json";
}



struct MetroStationEra {
    std::string line;

    std::string canonical_name;
    std::string display_name;
    int from = 1900;
    int to = 9999;

    std::vector<std::string> icon_keys;

    std::vector<std::string> aliases;
};



struct MetroHistoryDb {
    bool loaded = false;

    std::map<std::string, std::vector<MetroStationEra>> by_line_alias;

    std::map<std::string, int> open_year_by_line_alias;
};


int year_from_iso_date(const std::string& s, int fallback = 1900) {

    if (s.size() >= 4 && std::isdigit(static_cast<unsigned char>(s[0])) && std::isdigit(static_cast<unsigned char>(s[1])) && std::isdigit(static_cast<unsigned char>(s[2])) && std::isdigit(static_cast<unsigned char>(s[3]))) {
        try { return std::stoi(s.substr(0, 4)); } catch (...) {}
    }

    return fallback;
}



std::string metro_route_key_from_text(const std::string& text) {


    std::string s = normalize_key(text);
    char key[8];
    const size_t n = ozmvm_metro_route_key_copy(s.data(), s.size(), key, sizeof(key));
    if (n > 0 && n < sizeof(key)) return std::string(key, n);

    return {};
}



std::string metro_route_key_from_line(const MobilityLine& line) {
    std::string k = metro_route_key_from_text(line.name + " " + line.id);

    if (!k.empty()) return k;


    const std::string id = normalize_key(line.id);
    char key[8];
    const size_t n = ozmvm_metro_route_key_copy(id.data(), id.size(), key, sizeof(key));
    if (n > 0 && n < sizeof(key)) return std::string(key, n);

    return {};
}



void add_unique_string(std::vector<std::string>& v, const std::string& s) {

    if (!s.empty() && std::find(v.begin(), v.end(), s) == v.end()) v.push_back(s);
}

std::string compact_route_name_variant_c(const std::string& s, int mode) {
    std::string out(s.size() + 1u, '\0');
    const size_t n = ozmvm_compact_route_name_copy(s.data(), s.size(), mode, out.data(), out.size());
    out.resize(std::min(n, s.size()));
    return out;
}




MetroHistoryDb& metro_history_db() {
    static MetroHistoryDb db;


    static std::mutex mu;


    std::lock_guard<std::mutex> lock(mu);

    if (db.loaded) return db;
    db.loaded = true;
    try {


        std::vector<fs::path> candidates = { metro_chronology_path(), datos_externos_root() / L"Íconos" / "metro_diccionario_estaciones.json" };

        fs::path chosen;
        std::error_code ec;

        for (const auto& p : candidates) if (fs::exists(p, ec) && !ec) { chosen = p; break; }

        if (chosen.empty()) return db;


        auto j = nlohmann::json::parse(read_text_file(chosen), nullptr, false);

        if (j.is_discarded() || !j.is_object()) return db;
        const auto stations = j.find("stations");


        if (stations == j.end() || !stations->is_array()) return db;

        for (const auto& st : *stations) {

            if (!st.is_object()) continue;


            const std::string line = normalize_key(st.value("line", ""));
            const std::string current_name = st.value("current_name", st.value("base_name_in_gtfs_or_seed", ""));

            if (line.empty() || current_name.empty()) continue;

            const int open_year = year_from_iso_date(st.value("open_date", ""), 1900);

            std::vector<std::string> base_aliases;
            add_unique_string(base_aliases, mobility_station_icon_key(current_name));
            add_unique_string(base_aliases, mobility_station_icon_key(st.value("base_name_in_gtfs_or_seed", current_name)));
            const auto aliases_j = st.find("aliases");


            if (aliases_j != st.end() && aliases_j->is_array()) for (const auto& a : *aliases_j) if (a.is_string()) add_unique_string(base_aliases, safe_filename(normalize_key(a.get<std::string>())));

            for (const auto& a : base_aliases) db.open_year_by_line_alias[line + "|" + a] = open_year;

            const auto eras = st.find("eras");

            if (eras == st.end() || !eras->is_array()) continue;

            for (const auto& ej : *eras) {

                if (!ej.is_object()) continue;
                MetroStationEra era;
                era.line = line;
                era.canonical_name = current_name;
                era.display_name = ej.value("name", current_name);

                era.from = year_from_iso_date(ej.value("from", st.value("open_date", "")), open_year);
                const auto to_it = ej.find("to");

                era.to = (to_it == ej.end() || to_it->is_null()) ? 9999 : year_from_iso_date(to_it->is_string() ? to_it->get<std::string>() : std::to_string(to_it->get<int>()), 9999);

                if (era.to < era.from) std::swap(era.to, era.from);
                add_unique_string(era.icon_keys, mobility_station_icon_key(era.display_name));
                add_unique_string(era.icon_keys, mobility_station_icon_key(current_name));

                const std::string icon_file = ej.value("icon_file", "");

                if (!icon_file.empty()) {

                    fs::path ip(icon_file);

                    add_unique_string(era.icon_keys, mobility_station_icon_key(path_utf8(ip.stem())));
                }
                const auto ialias = ej.find("aliases");

                if (ialias != ej.end() && ialias->is_array()) {

                    for (const auto& a : *ialias) if (a.is_string()) {


                        const std::string ak = safe_filename(normalize_key(a.get<std::string>()));
                        add_unique_string(era.aliases, ak);
                        add_unique_string(era.icon_keys, ak);
                    }
                }

                std::vector<std::string> all_aliases = base_aliases;
                add_unique_string(all_aliases, mobility_station_icon_key(era.display_name));

                for (const auto& a : era.aliases) add_unique_string(all_aliases, a);

                for (const auto& a : all_aliases) {

                    db.by_line_alias[line + "|" + a].push_back(era);

                    db.open_year_by_line_alias[line + "|" + a] = open_year;
                }
            }
        }
    } catch (...) {}

    for (auto& [_, eras] : db.by_line_alias) std::stable_sort(eras.begin(), eras.end(), [](const auto& a, const auto& b){ return a.from < b.from; });

    return db;
}



std::optional<MetroStationEra> metro_station_era_for(const std::string& line_key, const std::string& station_name, int render_year) {

    if (line_key.empty()) return std::nullopt;
    auto& db = metro_history_db();


    std::vector<std::string> keys{mobility_station_icon_key(station_name), safe_filename(normalize_key(station_name))};

    for (const auto& k : keys) {


        auto it = db.by_line_alias.find(normalize_key(line_key) + "|" + k);

        if (it == db.by_line_alias.end()) continue;
        const MetroStationEra* best = nullptr;

        for (const auto& era : it->second) {


            if (render_year >= era.from && render_year <= era.to) best = &era;
        }

        if (best) return *best;
    }

    return std::nullopt;
}



int metro_station_open_year_for(const std::string& line_key, const std::string& station_name, int fallback) {

    if (line_key.empty()) return fallback;
    auto& db = metro_history_db();


    std::vector<std::string> keys{mobility_station_icon_key(station_name), safe_filename(normalize_key(station_name))};

    for (const auto& k : keys) {


        auto it = db.open_year_by_line_alias.find(normalize_key(line_key) + "|" + k);

        if (it != db.open_year_by_line_alias.end()) return it->second;
    }

    return fallback;
}



std::string metro_station_display_name_for(const std::string& group, const std::string& line_name, const std::string& station_name, int render_year) {

    if (group != "metro") return station_name;
    const std::string lk = metro_route_key_from_text(line_name);

    if (const auto era = metro_station_era_for(lk, station_name, render_year)) return era->display_name;

    return station_name;
}



std::string metro_station_canonical_key_for(const std::string& group, const std::string& line_name, const std::string& station_name, int render_year) {

    if (group != "metro") return mobility_station_icon_key(station_name);
    const std::string lk = metro_route_key_from_text(line_name);

    if (const auto era = metro_station_era_for(lk, station_name, render_year)) return mobility_station_icon_key(era->canonical_name);

    return mobility_station_icon_key(station_name);
}



std::vector<std::string> metro_station_icon_keys_for(const std::string& group, const std::string& line_name, const std::string& station_name, int render_year) {

    std::vector<std::string> out;

    if (group != "metro") return out;
    const std::string lk = metro_route_key_from_text(line_name);

    if (const auto era = metro_station_era_for(lk, station_name, render_year)) {

        for (const auto& k : era->icon_keys) add_unique_string(out, k);
        add_unique_string(out, mobility_station_icon_key(era->display_name));
        add_unique_string(out, mobility_station_icon_key(era->canonical_name));
    }

    return out;
}



void apply_metro_historical_overrides(std::vector<MobilityLine>& lines) {

    for (auto& ml : lines) {

        if (mobility_system_group(ml.system) != "metro") continue;
        const std::string line_key = metro_route_key_from_line(ml);

        if (line_key.empty()) continue;
        int min_open = 9999;

        for (auto& st : ml.stations) {

            const int oy = metro_station_open_year_for(line_key, st.name, st.valid_from);
            st.valid_from = oy;
            min_open = std::min(min_open, oy);
        }

        if (min_open < 9999) ml.valid_from = std::min(ml.valid_from, min_open);

        if (ml.points.empty() || ml.stations.empty()) continue;

        if (ml.point_valid_from.size() != ml.points.size()) ml.point_valid_from.assign(ml.points.size(), ml.valid_from);

        std::vector<std::pair<size_t, int>> anchors;

        anchors.reserve(ml.stations.size());

        for (const auto& st : ml.stations) {
            size_t best_i = 0;
            double best_d = std::numeric_limits<double>::max();

            for (size_t i = 0; i < ml.points.size(); ++i) {

                const double dx = ml.points[i].x - st.lon;

                const double dy = ml.points[i].y - st.lat;
                const double d = dx * dx + dy * dy;

                if (d < best_d) { best_d = d; best_i = i; }
            }

            anchors.push_back({best_i, st.valid_from});
        }
        std::sort(anchors.begin(), anchors.end(), [](const auto& a, const auto& b){ return a.first < b.first; });


        anchors.erase(std::unique(anchors.begin(), anchors.end(), [](const auto& a, const auto& b){ return a.first == b.first; }), anchors.end());

        if (anchors.empty()) continue;

        for (size_t i = 0; i < ml.points.size(); ++i) ml.point_valid_from[i] = anchors.front().second;

        for (size_t a = 0; a + 1 < anchors.size(); ++a) {

            const size_t i0 = anchors[a].first;
            const size_t i1 = anchors[a + 1].first;
            const int y = std::max(anchors[a].second, anchors[a + 1].second);

            for (size_t i = i0; i <= i1 && i < ml.point_valid_from.size(); ++i) ml.point_valid_from[i] = y;
        }

        for (size_t i = anchors.back().first; i < ml.point_valid_from.size(); ++i) ml.point_valid_from[i] = anchors.back().second;
    }
}



bool icon_path_has_image_extension(const fs::path& p) {


    const std::string ext = normalize_key(path_utf8(p.extension()));



    return ext == "png" || ext == "jpg" || ext == "jpeg";
}



struct IconYearRange {
    int from = 0;
    int to = 9999;
    bool valid = false;
};




IconYearRange parse_icon_year_range(const fs::path& p) {

    IconYearRange r;


    const std::string stem = normalize_key(path_utf8(p.stem()));
    int from = 0;
    int to = 9999;
    if (ozmvm_icon_year_range_from_stem(stem.data(), stem.size(), &from, &to)) {
        r.from = from;
        r.to = to;
        r.valid = true;
    }

    return r;
}


std::optional<fs::path> find_historical_mobility_station_icon_in_subdir(const fs::path& root, const std::string& dir,

                                                                        const std::string& history_subdir,


                                                                        const std::vector<std::string>& keys, int render_year) {




    static std::mutex mu;

    static std::map<std::string, bool> history_dir_exists;

    static std::map<std::string, std::optional<fs::path>> result_cache;

    const fs::path base_history = root / dir / history_subdir;


    const std::string hkey = normalize_key(path_utf8(base_history));
    {


        std::lock_guard<std::mutex> lock(mu);
        auto hit = history_dir_exists.find(hkey);

        if (hit == history_dir_exists.end()) {
            std::error_code ec;

            const bool ok = fs::exists(base_history, ec) && !ec && fs::is_directory(base_history, ec) && !ec;
            history_dir_exists[hkey] = ok;

            if (!ok) return std::nullopt;
        } else if (!hit->second) return std::nullopt;
        std::ostringstream ck;

        ck << hkey << "|" << render_year;


        for (const auto& k : keys) ck << "|" << normalize_key(k);
        auto rit = result_cache.find(ck.str());

        if (rit != result_cache.end()) return rit->second;
    }


    fs::path best;
    int best_from = -999999;

    for (const auto& k : keys) {

        if (k.empty()) continue;


        const fs::path hdir = base_history / k;
        std::error_code ec;

        if (!fs::exists(hdir, ec) || ec || !fs::is_directory(hdir, ec) || ec) continue;

        for (fs::directory_iterator it(hdir, fs::directory_options::skip_permission_denied, ec), end; !ec && it != end; it.increment(ec)) {

            const fs::path p = it->path();

            if (!it->is_regular_file(ec) || ec || !icon_path_has_image_extension(p)) { ec.clear(); continue; }


            const IconYearRange yr = parse_icon_year_range(p);

            if (!yr.valid) continue;

            if (render_year >= yr.from && render_year <= yr.to && yr.from >= best_from) {
                best = p;
                best_from = yr.from;
            }
        }
    }

    std::optional<fs::path> out = best.empty() ? std::optional<fs::path>{} : std::optional<fs::path>{best};
    {


        std::lock_guard<std::mutex> lock(mu);
        std::ostringstream ck;

        ck << hkey << "|" << render_year;


        for (const auto& k : keys) ck << "|" << normalize_key(k);

        if (result_cache.size() > 12000) result_cache.clear();
        result_cache[ck.str()] = out;
    }

    return out;
}


std::optional<fs::path> find_historical_mobility_station_icon(const fs::path& root, const std::string& dir,


                                                              const std::vector<std::string>& keys, int render_year) {

    return find_historical_mobility_station_icon_in_subdir(root, dir, "_historia", keys, render_year);
}



struct MobilityIconDirIndex {
    bool loaded = false;
    bool loading = false;

    std::map<std::string, fs::path> by_key;
};



std::map<std::string, fs::path> build_runtime_icon_index_for_dir(const fs::path& base_dir) {

    std::map<std::string, fs::path> out;

    const fs::path png_dir = base_dir / "png";
    std::error_code ec;

    if (!fs::exists(png_dir, ec) || ec || !fs::is_directory(png_dir, ec) || ec) return out;

    for (fs::directory_iterator it(png_dir, fs::directory_options::skip_permission_denied, ec), end; !ec && it != end; it.increment(ec)) {

        const fs::path p = it->path();

        if (!it->is_regular_file(ec) || ec || !icon_path_has_image_extension(p)) { ec.clear(); continue; }

        const std::string stem_raw = path_utf8(p.stem());

        std::vector<std::string> aliases = {


            safe_filename(trim(stem_raw)),


            safe_filename(normalize_key(stem_raw))
        };


        std::string no_prefix = stem_raw;
        std::string no_prefix_buf(stem_raw.size() + 1u, '\0');
        const size_t no_prefix_n = ozmvm_strip_metro_route_prefix_copy(stem_raw.data(), stem_raw.size(), no_prefix_buf.data(), no_prefix_buf.size());
        if (no_prefix_n <= stem_raw.size()) {
            no_prefix_buf.resize(no_prefix_n);
            no_prefix = std::move(no_prefix_buf);
        }


        aliases.push_back(safe_filename(trim(no_prefix)));


        aliases.push_back(safe_filename(normalize_key(no_prefix)));

        for (const auto& a : aliases) if (!a.empty() && out.find(a) == out.end()) out[a] = p;
    }

    return out;
}



std::optional<fs::path> find_direct_runtime_icon_indexed(const fs::path& base_dir, const std::vector<std::string>& lookup_keys) {




    static std::mutex mu;

    static std::map<std::string, MobilityIconDirIndex> indexes;


    const std::string base_key = normalize_key(path_utf8(base_dir));

    if (base_key.empty()) return std::nullopt;

    bool should_spawn = false;
    {


        std::lock_guard<std::mutex> lock(mu);
        auto& idx = indexes[base_key];

        if (!idx.loaded && !idx.loading) { idx.loading = true; should_spawn = true; }


        if (idx.loaded) {

            for (const auto& k : lookup_keys) {


                const std::string raw = safe_filename(trim(k));
                auto it = idx.by_key.find(raw);

                if (it != idx.by_key.end()) return it->second;


                const std::string norm = safe_filename(normalize_key(k));
                it = idx.by_key.find(norm);

                if (it != idx.by_key.end()) return it->second;
            }
        }
    }


    if (should_spawn) {
        auto* mu_ptr = &mu;
        auto* indexes_ptr = &indexes;


        std::thread([base_dir, base_key, mu_ptr, indexes_ptr]() {

            std::map<std::string, fs::path> built;

            try { built = build_runtime_icon_index_for_dir(base_dir); } catch (...) { built.clear(); }


            std::lock_guard<std::mutex> lock(*mu_ptr);
            auto& idx = (*indexes_ptr)[base_key];
            idx.by_key.swap(built);
            idx.loaded = true;
            idx.loading = false;

        }).detach();
    }

    return std::nullopt;
}



struct EmbeddedIconSprite {

    GLuint texture = 0;
    ImVec2 uv0 = ImVec2(0, 0);
    ImVec2 uv1 = ImVec2(1, 1);
    float aspect = 1.0f;
};



struct EmbeddedIconAtlasState {
    bool loaded = false;

    GLuint texture = 0;
    int width = 0;
    int height = 0;

    std::map<std::string, EmbeddedIconSprite> by_system_key;
};




EmbeddedIconAtlasState& embedded_mi_icon_atlas() {
    static EmbeddedIconAtlasState state;


    static std::mutex mu;


    std::lock_guard<std::mutex> lock(mu);

    if (state.loaded) return state;
    state.loaded = true;
    const unsigned char* png = obs_embedded_mi_icon_atlas_png_data();
    const std::size_t png_size = obs_embedded_mi_icon_atlas_png_size();


    const unsigned char* manifest_data = obs_embedded_mi_icon_atlas_json_data();


    const std::size_t manifest_size = obs_embedded_mi_icon_atlas_json_size();

    if (!png || png_size == 0 || !manifest_data || manifest_size == 0) return state;

    int w = 0, h = 0, comp = 0;

    unsigned char* pixels = stbi_load_from_memory(png, static_cast<int>(png_size), &w, &h, &comp, 4);

    if (!pixels || w <= 0 || h <= 0) {

        if (pixels) stbi_image_free(pixels);

        return state;
    }

    GLuint tex = 0;

    glGenTextures(1, &tex);

    glBindTexture(GL_TEXTURE_2D, tex);

    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);

    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);

    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);

    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);


    glPixelStorei(GL_UNPACK_ALIGNMENT, 1);

    glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, w, h, 0, GL_RGBA, GL_UNSIGNED_BYTE, pixels);

    stbi_image_free(pixels);

    state.texture = tex;
    state.width = w;
    state.height = h;

    try {
        const std::string manifest(reinterpret_cast<const char*>(manifest_data), reinterpret_cast<const char*>(manifest_data) + manifest_size);


        auto j = nlohmann::json::parse(manifest, nullptr, false);

        if (j.is_discarded() || !j.is_object()) return state;
        const auto icons = j.find("icons");

        if (icons == j.end() || !icons->is_array()) return state;

        for (const auto& item : *icons) {

            if (!item.is_object()) continue;

            const std::string system = item.value("system", "");
            const int x = item.value("x", 0);
            const int y = item.value("y", 0);
            const int iw = std::max(1, item.value("w", 1));
            const int ih = std::max(1, item.value("h", 1));
            EmbeddedIconSprite sp;

            sp.texture = tex;
            sp.uv0 = ImVec2(static_cast<float>(x) / static_cast<float>(w), static_cast<float>(y) / static_cast<float>(h));
            sp.uv1 = ImVec2(static_cast<float>(x + iw) / static_cast<float>(w), static_cast<float>(y + ih) / static_cast<float>(h));
            sp.aspect = static_cast<float>(iw) / static_cast<float>(ih);
            const auto keys = item.find("keys");

            if (keys == item.end() || !keys->is_array()) continue;

            for (const auto& kj : *keys) {

                if (!kj.is_string()) continue;
                const std::string raw = kj.get<std::string>();

                const std::vector<std::string> variants = {


                    safe_filename(trim(raw)),


                    safe_filename(normalize_key(raw))
                };

                for (const auto& dir_name : mobility_icon_system_dirs(mobility_system_group(system))) {


                    for (const auto& v : variants) if (!v.empty()) state.by_system_key[normalize_key(dir_name) + "|" + v] = sp;
                }


                for (const auto& v : variants) if (!v.empty()) state.by_system_key[normalize_key(system) + "|" + v] = sp;
            }
        }
    } catch (...) {}

    return state;
}



std::vector<std::string> mobility_station_icon_lookup_keys_for_runtime(const std::string& group, const std::string& station_name, int render_year, bool prefer_monochrome, const std::string& line_name) {
    (void)prefer_monochrome;

    std::vector<std::string> keys;

    auto add_key = [&](const std::string& k) {

        if (!k.empty() && std::find(keys.begin(), keys.end(), k) == keys.end()) keys.push_back(k);
    };

    add_key(mobility_station_icon_key(station_name));

    for (const auto& hk : metro_station_icon_keys_for(group, line_name, station_name, render_year)) add_key(hk);

    auto replace_all_local = [](std::string& target, const std::string& from, const std::string& to) {

        if (from.empty()) return;
        size_t pos = 0;

        while ((pos = target.find(from, pos)) != std::string::npos) {
            target.replace(pos, from.size(), to);
            pos += to.size();
        }
    };


    std::string simplified = std::string(" ") + normalize_key(station_name) + " ";
    const std::array<std::string, 5> station_stop_words = {" de ", " del ", " la ", " las ", " los "};

    for (const std::string& w : station_stop_words) replace_all_local(simplified, w, " ");


    add_key(safe_filename(trim(simplified)));

    static const std::map<std::string, std::vector<std::string>> aliases = {

        {"parque_de_los_venados", {"parque_venados"}},
        {"hospital_20_de_noviembre", {"hospital_20_nov", "hospital_20_noviembre"}},

        {"eje_central", {"eje_central_popocatepetl"}},
        {"periferico_oriente", {"periferico_ote", "periferico_ote_vergel"}},
        {"periferico_ote", {"periferico_oriente", "periferico_ote_vergel"}},
        {"tlaltenco", {"tlaltenco_v2"}},
        {"la_villa_basilica", {"la_villa", "6_10_la_villa"}},
        {"deportivo_18_de_marzo", {"dep_18_montevideo", "deportivo_18_montevideo", "deportivo_18_marzo", "deportivo_18"}},
        {"uam_i", {"uam_iztapalapa", "uam_i_iztapalapa"}},
        {"uam_iztapalapa", {"uam_i", "uam_i_iztapalapa"}},
        {"uam_i_iztapalapa", {"uam_i", "uam_iztapalapa"}},
        {"uam_azcapotzalco", {"azcapotzalco"}},
        {"azcapotzalco", {"uam_azcapotzalco"}},
        {"fray_servando", {"fary_servando"}},
        {"fary_servando", {"fray_servando"}},
        {"ricardo_flores_magon", {"rifloma"}},
        {"rifloma", {"ricardo_flores_magon"}},
        {"zocalo_tenochtitlan", {"zocalo"}},
        {"zocalo", {"zocalo_tenochtitlan"}},

        {"boulevard_puerto_aereo", {"aeropuerto"}},
        {"aeropuerto", {"boulevard_puerto_aereo"}},
        {"ferreria_arena_cdmx", {"ferreria", "ferreria_arena_ciudad_de_mexico"}},
        {"ferreria_arena_ciudad_de_mexico", {"ferreria", "ferreria_arena_cdmx"}},
        {"nezahualcoyotl", {"continentes"}},
        {"continentes", {"nezahualcoyotl"}},
        {"etiopia_plaza_de_la_transparencia", {"etiopia"}},
        {"etiopia", {"etiopia_plaza_de_la_transparencia"}},
        {"basilica", {"deportivo_18_de_marzo", "deportivo_18_marzo", "dep_18_montevideo"}},
        {"la_purisima", {"uam_i", "uam_iztapalapa", "uam_i_iztapalapa"}}
    };
    const std::string base_key = mobility_station_icon_key(station_name);

    if (auto it = aliases.find(base_key); it != aliases.end()) for (const auto& a : it->second) add_key(a);

    const std::string route_key_raw = metro_route_key_from_text(line_name);
    std::string route_label = route_key_raw;
    std::transform(route_label.begin(), route_label.end(), route_label.begin(), [](unsigned char c){ return static_cast<char>(std::toupper(c)); });

    auto add_line_name_stems = [&](const std::string& nm) {

        if (route_label.empty() || nm.empty()) return;
        add_key(route_label + " " + nm);
        std::string route_label_lower = route_label;
        std::transform(route_label_lower.begin(), route_label_lower.end(), route_label_lower.begin(), [](unsigned char c){ return static_cast<char>(std::tolower(c)); });
        add_key(route_label_lower + " " + nm);

        add_key(route_label + " " + compact_route_name_variant_c(nm, 0));
        add_key(route_label + " " + compact_route_name_variant_c(nm, 1));


        add_key(safe_filename(normalize_key(route_label + " " + nm)));
    };
    add_line_name_stems(station_name);

    if (group == "metro" && !route_key_raw.empty()) {

        if (const auto era = metro_station_era_for(route_key_raw, station_name, render_year)) {
            add_line_name_stems(era->display_name);
            add_line_name_stems(era->canonical_name);
        }
    }

    if (prefer_monochrome) {

        std::vector<std::string> mono;

        mono.reserve(keys.size() * 5);

        for (const auto& k : keys) {
            add_unique_string(mono, k + " [monócrama]");
            add_unique_string(mono, k + " [monocroma]");
            add_unique_string(mono, k + " [monocromo]");

            add_unique_string(mono, k + " [un solo color]");
            add_unique_string(mono, k);
        }
        keys.swap(mono);
    }

    return keys;
}



std::optional<EmbeddedIconSprite> find_embedded_mobility_station_icon_sprite(const std::string& group, const std::string& station_name, int render_year, bool prefer_monochrome, const std::string& line_name) {
    EmbeddedIconAtlasState& atlas = embedded_mi_icon_atlas();

    if (atlas.texture == 0 || atlas.by_system_key.empty()) return std::nullopt;

    const auto keys = mobility_station_icon_lookup_keys_for_runtime(group, station_name, render_year, prefer_monochrome, line_name);

    for (const auto& dir_name : mobility_icon_system_dirs(group)) {


        const std::string sys_key = normalize_key(dir_name);

        for (const auto& k : keys) {


            const std::string raw = safe_filename(trim(k));
            auto it = atlas.by_system_key.find(sys_key + "|" + raw);

            if (it != atlas.by_system_key.end()) return it->second;


            const std::string norm = safe_filename(normalize_key(k));
            it = atlas.by_system_key.find(sys_key + "|" + norm);

            if (it != atlas.by_system_key.end()) return it->second;
        }
    }

    return std::nullopt;
}



std::optional<fs::path> find_mobility_station_icon_impl(const std::string& group, const std::string& station_name, int render_year, bool prefer_monochrome = false, const std::string& line_name = "") {
    const std::string dir = mobility_icon_system_dir(group);
    const std::string key = mobility_station_icon_key(station_name);

    if (key.empty()) return std::nullopt;

    std::vector<std::string> keys{key};

    auto add_key = [&](const std::string& k) {

        if (!k.empty() && std::find(keys.begin(), keys.end(), k) == keys.end()) keys.push_back(k);
    };

    for (const auto& hk : metro_station_icon_keys_for(group, line_name, station_name, render_year)) add_key(hk);

    auto replace_all_local = [](std::string& target, const std::string& from, const std::string& to) {

        if (from.empty()) return;
        size_t pos = 0;

        while ((pos = target.find(from, pos)) != std::string::npos) {
            target.replace(pos, from.size(), to);
            pos += to.size();
        }
    };


    std::string simplified = std::string(" ") + normalize_key(station_name) + " ";
    const std::array<std::string, 5> station_stop_words = {" de ", " del ", " la ", " las ", " los "};

    for (const std::string& w : station_stop_words) replace_all_local(simplified, w, " ");


    add_key(safe_filename(trim(simplified)));

    static const std::map<std::string, std::vector<std::string>> aliases = {
        {"parque_de_los_venados", {"parque_venados"}},
        {"hospital_20_de_noviembre", {"hospital_20_nov", "hospital_20_noviembre"}},
        {"eje_central", {"eje_central_popocatepetl"}},
        {"periferico_oriente", {"periferico_ote", "periferico_ote_vergel"}},
        {"periferico_ote", {"periferico_oriente", "periferico_ote_vergel"}},
        {"tlaltenco", {"tlaltenco_v2"}},
        {"la_villa_basilica", {"la_villa", "6_10_la_villa"}},
        {"deportivo_18_de_marzo", {"dep_18_montevideo", "deportivo_18_montevideo", "deportivo_18_marzo", "deportivo_18"}},
        {"uam_i", {"uam_iztapalapa", "uam_i_iztapalapa"}},
        {"uam_iztapalapa", {"uam_i", "uam_i_iztapalapa"}},
        {"uam_i_iztapalapa", {"uam_i", "uam_iztapalapa"}},
        {"uam_azcapotzalco", {"azcapotzalco"}},
        {"azcapotzalco", {"uam_azcapotzalco"}},
        {"fray_servando", {"fary_servando"}},
        {"fary_servando", {"fray_servando"}},
        {"ricardo_flores_magon", {"rifloma"}},

        {"rifloma", {"ricardo_flores_magon"}},
        {"zocalo_tenochtitlan", {"zocalo"}},

        {"zocalo", {"zocalo_tenochtitlan"}},
        {"boulevard_puerto_aereo", {"aeropuerto"}},
        {"aeropuerto", {"boulevard_puerto_aereo"}},
        {"ferreria_arena_cdmx", {"ferreria", "ferreria_arena_ciudad_de_mexico"}},
        {"ferreria_arena_ciudad_de_mexico", {"ferreria", "ferreria_arena_cdmx"}},
        {"nezahualcoyotl", {"continentes"}},
        {"continentes", {"nezahualcoyotl"}},
        {"etiopia_plaza_de_la_transparencia", {"etiopia"}},
        {"etiopia", {"etiopia_plaza_de_la_transparencia"}},
        {"basilica", {"deportivo_18_de_marzo", "deportivo_18_marzo", "dep_18_montevideo"}},
        {"la_purisima", {"uam_i", "uam_iztapalapa", "uam_i_iztapalapa"}}
    };

    if (auto it = aliases.find(key); it != aliases.end()) for (const auto& a : it->second) add_key(a);


    const std::string route_key_raw = metro_route_key_from_text(line_name);
    std::string route_label = route_key_raw;

    std::transform(route_label.begin(), route_label.end(), route_label.begin(), [](unsigned char c){ return static_cast<char>(std::toupper(c)); });

    auto add_line_name_stems = [&](const std::string& nm) {

        if (route_label.empty() || nm.empty()) return;
        add_key(route_label + " " + nm);
        std::string route_label_lower = route_label;
        std::transform(route_label_lower.begin(), route_label_lower.end(), route_label_lower.begin(), [](unsigned char c){ return static_cast<char>(std::tolower(c)); });
        add_key(route_label_lower + " " + nm);

        add_key(route_label + " " + compact_route_name_variant_c(nm, 0));
        add_key(route_label + " " + compact_route_name_variant_c(nm, 1));


        add_key(safe_filename(normalize_key(route_label + " " + nm)));
    };
    add_line_name_stems(station_name);

    if (group == "metro" && !route_key_raw.empty()) {

        if (const auto era = metro_station_era_for(route_key_raw, station_name, render_year)) {
            add_line_name_stems(era->display_name);
            add_line_name_stems(era->canonical_name);
        }
    }



    auto find_direct = [&](const fs::path& base_dir, const std::vector<std::string>& lookup_keys) -> std::optional<fs::path> {

        return find_direct_runtime_icon_indexed(base_dir, lookup_keys);
    };

    for (const auto& root : mobility_icon_roots()) {

        for (const auto& dir_name : mobility_icon_system_dirs(group)) {

            if (prefer_monochrome) {

                std::vector<std::string> mono_keys;

                mono_keys.reserve(keys.size() * 5);

                for (const auto& k : keys) {
                    add_unique_string(mono_keys, k + " [monócrama]");
                    add_unique_string(mono_keys, k + " [monocroma]");
                    add_unique_string(mono_keys, k + " [monocromo]");
                    add_unique_string(mono_keys, k + " [un solo color]");
                    add_unique_string(mono_keys, k);
                }

                if (const auto historic_single = find_historical_mobility_station_icon_in_subdir(root, dir_name, "_historia_un_solo_color", mono_keys, render_year)) return historic_single;

                if (const auto single = find_direct(root / dir_name / "_un_solo_color", mono_keys)) return single;

                if (const auto direct_mono = find_direct(root / dir_name, mono_keys)) return direct_mono;
            }

            if (const auto historic = find_historical_mobility_station_icon(root, dir_name, keys, render_year)) return historic;

            if (const auto direct = find_direct(root / dir_name, keys)) return direct;
        }
    }

    return std::nullopt;
}


std::optional<fs::path> find_mobility_station_icon(const std::string& group, const std::string& station_name, int render_year, bool prefer_monochrome = false, const std::string& line_name = "") {


    static std::mutex mu;

    static std::map<std::string, std::optional<fs::path>> cache;
    std::ostringstream key;


    key << normalize_key(group) << "|" << mobility_station_icon_key(station_name) << "|" << render_year << "|" << (prefer_monochrome ? "mono" : "color") << "|" << normalize_key(line_name);
    const std::string k = key.str();
    {


        std::lock_guard<std::mutex> lock(mu);


        auto it = cache.find(k);

        if (it != cache.end()) return it->second;

        if (cache.size() > 24000) cache.clear();
    }

    auto found = find_mobility_station_icon_impl(group, station_name, render_year, prefer_monochrome, line_name);



    if (found) {


        std::lock_guard<std::mutex> lock(mu);
        cache[k] = found;
    }

    return found;
}




PreviewTexture load_persistent_icon_texture(const fs::path& path) {

    struct IconTextureEntry {

        PreviewTexture tex;
        std::uint64_t last_used = 0;
    };


    static std::mutex mu;

    static std::map<std::string, IconTextureEntry> cache;


    fs::path image_path = path;


    const std::string ext = normalize_key(path_utf8(path.extension()));

    if (ext == "svg" || ext == "webp") {

        std::error_code ec;

        fs::path sidecar = path;
        sidecar.replace_extension(".png");

        if (fs::exists(sidecar, ec) && !ec) image_path = sidecar;
        else return {};
    }

    const std::string key = path_utf8(image_path);


    const std::string image_ext = normalize_key(path_utf8(image_path.extension()));

    if (key.empty() || !(image_ext == "png" || image_ext == "jpg" || image_ext == "jpeg")) return {};

    {


        std::lock_guard<std::mutex> lock(mu);
        auto it = cache.find(key);

        if (it != cache.end()) {

            it->second.last_used = g_map_frame_counter;

            return it->second.tex;
        }
    }



    if (g_icon_texture_loads_remaining <= 0) return {};

    --g_icon_texture_loads_remaining;


    PreviewTexture tex = load_texture_from_file(image_path);

    if (tex.id == 0 || tex.width <= 0 || tex.height <= 0) return {};



    std::lock_guard<std::mutex> lock(mu);

    cache[key] = IconTextureEntry{tex, g_map_frame_counter};

    if (cache.size() > kMaxResidentIconTextures) {

        std::vector<std::string> keys;

        keys.reserve(cache.size());

        for (const auto& [k, _] : cache) keys.push_back(k);

        std::sort(keys.begin(), keys.end(), [&](const std::string& a, const std::string& b) {

            return cache[a].last_used < cache[b].last_used;
        });

        for (const auto& k : keys) {

            if (cache.size() <= kMaxResidentIconTextures) break;
            auto it = cache.find(k);

            if (it == cache.end()) continue;

            if (g_map_frame_counter <= it->second.last_used + 180 && cache.size() < kMaxResidentIconTextures + 64) continue;

            if (it->second.tex.id != 0) glDeleteTextures(1, &it->second.tex.id);

            cache.erase(it);
        }
    }

    return tex;
}



struct MobilityStationAggregate {
    std::string system;
    std::string group;
    std::string name;

    std::string line_hint;
    std::string line_names;

    std::set<std::string> line_name_set;
    std::string color_hex;

    double lon_sum = 0.0;

    double lat_sum = 0.0;
    int count = 0;
    bool has_icon = false;

    fs::path icon_path;
    bool has_embedded_icon = false;
    bool has_embedded_mono_icon = false;
    EmbeddedIconSprite embedded_icon;
    EmbeddedIconSprite embedded_mono_icon;
};



struct ScreenRectF {
    float x1 = 0.0f, y1 = 0.0f, x2 = 0.0f, y2 = 0.0f;
};



bool screen_rect_intersects(const ScreenRectF& a, const ScreenRectF& b) {

    return !(a.x2 < b.x1 || b.x2 < a.x1 || a.y2 < b.y1 || b.y2 < a.y1);
}



bool line_intersects_bounds(const MobilityLine& line, const GeoBounds& b) {

    if (!b.valid) return true;
    const double pad = 0.04;

    return !(line.max_lon < b.lon_min - pad || line.min_lon > b.lon_max + pad || line.max_lat < b.lat_min - pad || line.min_lat > b.lat_max + pad);
}


void draw_mobility_layer(ImDrawList* dl, const std::vector<MobilityLine>& lines, const MapViewport& view,
                         const ImVec2& origin, const ImVec2& size, const UiState& ui,


                         int render_year, ImVec2 mouse, std::string& hovered_mobility) {

    if (!ui.mobility_layer_enabled || lines.empty()) return;

    const GeoBounds vb = viewport_lonlat_bounds(view);

    const bool station_detail = view.z >= kMapZmvmTileZoom && ui.zoom >= 3.4f;

    const bool station_icon_detail = view.z >= kMapFiveHundredTileZoom || ui.zoom >= 12.0f;
    const bool hover_check = (mouse.x >= origin.x && mouse.x <= origin.x + size.x && mouse.y >= origin.y && mouse.y <= origin.y + size.y);


    const float zf = static_cast<float>(view.z);

    const double geo_pad = (view.z >= kMapScale30kTileZoom) ? 0.010 : ((view.z >= kMapScale90kTileZoom) ? 0.020 : 0.045);
    const double station_pad = station_icon_detail ? 0.006 : 0.014;


    auto point_in_geo = [&](const Point2& gp, double pad) {

        return gp.x >= vb.lon_min - pad && gp.x <= vb.lon_max + pad && gp.y >= vb.lat_min - pad && gp.y <= vb.lat_max + pad;
    };

    auto segment_maybe_visible = [&](const Point2& a, const Point2& b, double pad) {
        const double minx = std::min(a.x, b.x), maxx = std::max(a.x, b.x);
        const double miny = std::min(a.y, b.y), maxy = std::max(a.y, b.y);

        return !(maxx < vb.lon_min - pad || minx > vb.lon_max + pad || maxy < vb.lat_min - pad || miny > vb.lat_max + pad);
    };


    std::vector<const MobilityLine*> visible;

    visible.reserve(lines.size());

    for (const auto& line : lines) {

        if (!valid_in_year(line.valid_from, line.valid_to, render_year)) continue;

        if (!mobility_system_visible(line, ui)) continue;

        if (!line_intersects_bounds(line, vb)) continue;

        visible.push_back(&line);
    }

    std::stable_sort(visible.begin(), visible.end(), [](const MobilityLine* a, const MobilityLine* b) {

        const int ra = mobility_draw_rank(*a);
        const int rb = mobility_draw_rank(*b);

        if (ra != rb) return ra < rb;

        return a->name < b->name;
    });

    dl->PushClipRect(origin, ImVec2(origin.x + size.x, origin.y + size.y), true);


    std::unordered_map<std::string, MobilityStationAggregate> station_groups;

    if (station_detail) station_groups.reserve(768);


    for (const MobilityLine* lp : visible) {

        const MobilityLine& line = *lp;
        const std::string group = mobility_system_group(line.system);

        const bool tren_ligero_geometry = mobility_line_is_tren_ligero(line);


        size_t mobility_point_step = 1u;

        if (group == "metro" || tren_ligero_geometry) {

            mobility_point_step = (view.z < kMapZmvmTileZoom) ? 7u : ((view.z < kMapScale90kTileZoom) ? 5u : ((view.z < kMapScale30kTileZoom) ? 3u : ((view.z < kMapScale15kIdleTileZoom) ? 2u : 1u)));

        } else if (group == "trenes") {

            mobility_point_step = (view.z < kMapZmvmTileZoom) ? 15u : ((view.z < kMapScale90kTileZoom) ? 10u : ((view.z < kMapScale30kTileZoom) ? 6u : ((view.z < kMapScale15kIdleTileZoom) ? 4u : 2u)));

        } else {


            mobility_point_step = 1u;
        }


        const float thickness = meters_to_screen_pixels(view, mobility_corridor_width_meters(group, tren_ligero_geometry),
                                                         group == "metro" ? 0.46f : 0.28f,
                                                         group == "metro" ? 8.5f : 5.2f);


        std::vector<ImVec2> pts;

        pts.reserve(std::min<size_t>(line.points.size(), group == "trenes" ? 512u : 2048u));
        ImVec2 last(-1e9f, -1e9f);


        auto flush_segment = [&]() {

            if (pts.size() >= 2) {
                dl->AddPolyline(pts.data(), static_cast<int>(pts.size()), mobility_color_u32(line, group == "metro" ? 154 : 112), 0, thickness);

                if (hover_check) {

                    for (size_t i = 1; i < pts.size(); ++i) {
                        const float dist = distance_to_segment(mouse, pts[i-1], pts[i]);

                        if (dist <= thickness + 3.0f) { hovered_mobility = line.system + " · " + line.name; break; }
                    }
                }
            }

            pts.clear();
            last = ImVec2(-1e9f, -1e9f);
        };


        for (size_t idx = 0; idx < line.points.size(); ++idx) {
            const bool keep_endpoint = (idx == 0 || idx + 1 == line.points.size());

            if (!keep_endpoint && mobility_point_step > 1u && (idx % mobility_point_step) != 0u) continue;

            const int pyear = (idx < line.point_valid_from.size()) ? line.point_valid_from[idx] : line.valid_from;


            if (pyear > render_year) { flush_segment(); continue; }
            const Point2& gp = line.points[idx];

            if (!point_in_geo(gp, geo_pad)) {
                bool maybe_crosses = false;

                if (idx > 0) maybe_crosses = segment_maybe_visible(line.points[idx - 1], gp, geo_pad);

                if (!maybe_crosses && idx + 1 < line.points.size()) maybe_crosses = segment_maybe_visible(gp, line.points[idx + 1], geo_pad);


                if (!maybe_crosses) { flush_segment(); continue; }
            }

            const ImVec2 p = project_lonlat(gp, view);

            if (p.x < origin.x - 90 || p.x > origin.x + size.x + 90 || p.y < origin.y - 90 || p.y > origin.y + size.y + 90) {

                flush_segment();
                continue;
            }

            if (!pts.empty()) {
                const float dx = p.x - last.x;
                const float dy = p.y - last.y;



                const float lod_eps2 = (group == "metro" || tren_ligero_geometry)

                    ? ((view.z >= 18) ? 0.026f : ((view.z >= 16) ? 0.070f : ((view.z >= 14) ? 0.170f : ((view.z >= kMapZmvmTileZoom) ? 0.42f : 1.18f))))
                    : (group == "trenes")

                        ? ((view.z >= 18) ? 0.050f : ((view.z >= 16) ? 0.140f : ((view.z >= 14) ? 0.330f : ((view.z >= kMapZmvmTileZoom) ? 0.78f : 1.85f))))

                        : ((view.z >= 18) ? 0.0004f : ((view.z >= 16) ? 0.0012f : ((view.z >= 14) ? 0.0045f : ((view.z >= kMapZmvmTileZoom) ? 0.018f : 0.070f))));

                if ((dx * dx + dy * dy) < lod_eps2 && idx + 1 < line.points.size()) continue;
            }

            pts.push_back(p);
            last = p;
        }

        flush_segment();


        if (station_detail && !line.stations.empty()) {

            for (const auto& st : line.stations) {

                const Point2 sp{st.lon, st.lat};


                if (!point_in_geo(sp, station_pad)) continue;

                const ImVec2 projected = project_lonlat(sp, view);

                if (projected.x < origin.x - 42 || projected.x > origin.x + size.x + 42 || projected.y < origin.y - 42 || projected.y > origin.y + size.y + 42) continue;
                int station_valid_from = st.valid_from;

                if (group == "metro") station_valid_from = metro_station_open_year_for(metro_route_key_from_text(line.name), st.name, st.valid_from);

                if (!valid_in_year(station_valid_from, st.valid_to, render_year)) continue;

                const std::string canonical_station_key = metro_station_canonical_key_for(group, line.name, st.name, render_year);
                const std::string sk = group + "|" + canonical_station_key;

                if (sk.size() <= group.size() + 1) continue;
                MobilityStationAggregate& ag = station_groups[sk];

                if (ag.count == 0) {
                    ag.system = st.system.empty() ? line.system : st.system;

                    ag.group = group;

                    ag.name = metro_station_display_name_for(group, line.name, st.name, render_year);
                    ag.line_hint = line.name;
                    ag.color_hex = line.color_hex;
                }

                ag.lon_sum += st.lon;

                ag.lat_sum += st.lat;
                ag.count += 1;

                if (ag.line_name_set.insert(line.name).second) {


                    if (!ag.line_names.empty()) ag.line_names += ", ";
                    ag.line_names += line.name;
                }
            }
        }
    }


    if (station_detail && !station_groups.empty()) {

        std::vector<const MobilityStationAggregate*> ordered;

        ordered.reserve(station_groups.size());

        for (const auto& kv : station_groups) if (kv.second.count > 0) ordered.push_back(&kv.second);

        std::stable_sort(ordered.begin(), ordered.end(), [](const MobilityStationAggregate* a, const MobilityStationAggregate* b) {
            const int ra = (a->group == "metro") ? 8 : (a->group == "metrobus" ? 7 : (a->group == "trenes" ? 6 : (a->group == "electrico" ? 5 : 2)));
            const int rb = (b->group == "metro") ? 8 : (b->group == "metrobus" ? 7 : (b->group == "trenes" ? 6 : (b->group == "electrico" ? 5 : 2)));

            if (a->line_name_set.size() != b->line_name_set.size()) return a->line_name_set.size() > b->line_name_set.size();

            if (ra != rb) return ra > rb;

            return a->name < b->name;
        });


        static const std::set<std::string> current_transfer_station_keys = {
            "pantitlan", "tacubaya", "balderas", "salto_del_agua", "pino_suarez", "candelaria", "san_lazaro",
            "hidalgo", "bellas_artes", "chabacano", "centro_medico", "zapata", "ermita", "atlalilco", "mixcoac",
            "instituto_del_petroleo", "deportivo_18_de_marzo", "la_raza", "consulado", "morelos", "martin_carrera",
            "jamaica", "garibaldi_lagunilla", "oceania", "el_rosario", "guerrero"
        };


        std::vector<ScreenRectF> placed_icons;

        placed_icons.reserve(std::min<size_t>(ordered.size(), kMaxMobilityIconsPerFrame));

        int icons_drawn = 0;
        int dots_drawn = 0;

        const int max_icons_this_frame = (view.z >= kMapScale15kIdleTileZoom) ? kMaxMobilityIconsPerFrame : (station_icon_detail ? 74 : 0);

        const int max_dots_this_frame = (view.z >= kMapScale30kTileZoom) ? kMaxMobilityStationDotsPerFrame : 360;


        auto rect_collides = [&](const ScreenRectF& r) {

            for (const auto& q : placed_icons) {

                ScreenRectF padded{q.x1 - kMobilityIconMinPixelSpacing, q.y1 - kMobilityIconMinPixelSpacing, q.x2 + kMobilityIconMinPixelSpacing, q.y2 + kMobilityIconMinPixelSpacing};

                if (screen_rect_intersects(r, padded)) return true;
            }

            return false;
        };


        for (const MobilityStationAggregate* ap : ordered) {
            const MobilityStationAggregate& ag = *ap;

            const Point2 gp{ag.lon_sum / static_cast<double>(ag.count), ag.lat_sum / static_cast<double>(ag.count)};

            if (!point_in_geo(gp, station_pad)) continue;

            const ImVec2 p = project_lonlat(gp, view);

            if (p.x < origin.x - 30 || p.x > origin.x + size.x + 30 || p.y < origin.y - 30 || p.y > origin.y + size.y + 30) continue;



            bool drawn_icon = false;

            if (station_icon_detail && icons_drawn < max_icons_this_frame) {
                const bool transfer_station = ag.line_name_set.size() >= 2 || current_transfer_station_keys.count(mobility_station_icon_key(ag.name)) > 0;
                const float icon_size = std::clamp((transfer_station ? 24.5f : 21.0f) + std::max(0.0f, zf - 15.0f) * 1.72f,
                                                   transfer_station ? 23.0f : 20.0f,
                                                   transfer_station ? 33.0f : 30.0f);
                const float half = icon_size * 0.5f;
                const ScreenRectF r{p.x - half - 1.5f, p.y - half - 1.5f, p.x + half + 1.5f, p.y + half + 1.5f};

                if (!rect_collides(r)) {

                    if (const auto sprite0 = find_embedded_mobility_station_icon_sprite(ag.group, ag.name, render_year, false, ag.line_hint)) {
                        EmbeddedIconSprite sprite = *sprite0;

                        if (transfer_station) if (const auto mono_sprite = find_embedded_mobility_station_icon_sprite(ag.group, ag.name, render_year, true, ag.line_hint)) sprite = *mono_sprite;
                        const ImVec2 a(p.x - half, p.y - half);
                        const ImVec2 b(p.x + half, p.y + half);

                        dl->AddImageRounded((ImTextureID)(intptr_t)sprite.texture, a, b, sprite.uv0, sprite.uv1, IM_COL32(255,255,255,255), 3.0f, ImDrawFlags_RoundCornersAll);

                        placed_icons.push_back(r);
                        ++icons_drawn;

                        drawn_icon = true;


                        if (hover_check && std::hypot(mouse.x - p.x, mouse.y - p.y) <= half + 4.0f) hovered_mobility = ag.system + " · " + ag.name + (ag.line_names.empty() ? "" : " · " + ag.line_names);
                    } else {

                        std::optional<fs::path> icon = find_mobility_station_icon(ag.group, ag.name, render_year, transfer_station, ag.line_hint);

                        if (!icon && transfer_station) icon = find_mobility_station_icon(ag.group, ag.name, render_year, false, ag.line_hint);

                        if (icon) {

                            const PreviewTexture tex = load_persistent_icon_texture(*icon);

                            if (tex.id != 0) {
                                const ImVec2 a(p.x - half, p.y - half);
                                const ImVec2 b(p.x + half, p.y + half);

                                dl->AddImageRounded((ImTextureID)(intptr_t)tex.id, a, b, ImVec2(0,0), ImVec2(1,1), IM_COL32(255,255,255,255), 3.0f, ImDrawFlags_RoundCornersAll);

                                placed_icons.push_back(r);
                                ++icons_drawn;
                                drawn_icon = true;


                                if (hover_check && std::hypot(mouse.x - p.x, mouse.y - p.y) <= half + 4.0f) hovered_mobility = ag.system + " · " + ag.name + (ag.line_names.empty() ? "" : " · " + ag.line_names);
                            }
                        }
                    }
                }
            }

            if (drawn_icon) continue;

            if (dots_drawn >= max_dots_this_frame) continue;

            if (view.z < kMapScale90kTileZoom && (ag.group == "rtp" || ag.group == "pumabus" || ag.group == "otros" || ag.group == "concesionado")) continue;
            const float dot_r = (ag.group == "metro" || ag.group == "metrobus") ? 2.10f : 1.55f;
            dl->AddCircleFilled(p, dot_r, color_from_hex_string(ag.color_hex, 214), 8);

            if (view.z >= kMapScale30kTileZoom) dl->AddCircle(p, dot_r + 1.10f, IM_COL32(255, 255, 255, 72), 8, 0.70f);
            ++dots_drawn;


            if (hover_check && std::hypot(mouse.x - p.x, mouse.y - p.y) <= dot_r + 5.0f) hovered_mobility = ag.system + " · " + ag.name + (ag.line_names.empty() ? "" : " · " + ag.line_names);
        }
    }

    dl->PopClipRect();
}



std::string read_file_or_empty(const fs::path& p);



fs::path pipeline_progress_dir(const fs::path& output_dir);



struct ObservationCandidateProfile {

    fs::path path;

    fs::path run_root;

    size_t rows = 0;

    size_t usable_rows = 0;

    size_t strong_weeks = 0;

    size_t weak_weeks = 0;
    size_t reference_disease_count = 0;

    std::map<std::string, std::set<std::string>> week_diseases;

    bool canceled_or_incomplete = false;
    bool run_completed = false;
    int64_t score = std::numeric_limits<int64_t>::min();


    std::map<std::string, size_t> week_rows;
};



fs::path infer_run_root_from_observations_path(fs::path p) {



    for (int i = 0; i < 5 && !p.empty(); ++i) {


        if (fs::exists(p / "run_state.ixiptlah") || fs::exists(p / "observations.jsonl") || fs::exists(p / "observaciones.jsonl") ||


            fs::exists(p / "progress") || fs::exists(p / "accepted") || fs::exists(p / "base")) return p;

        p = p.parent_path();
    }

    return p;
}



bool run_state_is_complete(const fs::path& run_root) {

    std::string latest;


    for (const auto& state : {pipeline_progress_dir(run_root) / "run_state.ixiptlah",


                              run_root / "run_state.ixiptlah",


                              run_root / "progress" / "run_state.ixiptlah"}) {

        if (!fs::exists(state)) continue;


        ixiptlah_read_records(state, [&](IxiptlahRecordType type, std::uint32_t schema, std::istream& in) {


            if (type != IxiptlahRecordType::RunState || schema != 1) return true;
            std::string status;


            if (!ixiptlah_read_string(in, status)) return false;

            latest = status;

            return true;

        });

        if (!latest.empty()) break;
    }


    return normalize_key(latest) == "complete";
}




bool run_state_is_incomplete_or_canceled(const fs::path& run_root) {


    if (fs::exists(pipeline_progress_dir(run_root) / "cancel_requested.flag") || fs::exists(run_root / "cancel_requested.flag") || fs::exists(run_root / "progress" / "cancel_requested.flag")) return true;

    std::string latest;


    for (const auto& state : {pipeline_progress_dir(run_root) / "run_state.ixiptlah",


                              run_root / "run_state.ixiptlah",


                              run_root / "progress" / "run_state.ixiptlah"}) {

        if (!fs::exists(state)) continue;


        ixiptlah_read_records(state, [&](IxiptlahRecordType type, std::uint32_t schema, std::istream& in) {


            if (type != IxiptlahRecordType::RunState || schema != 1) return true;
            std::string status;


            if (!ixiptlah_read_string(in, status)) return false;

            latest = status;

            return true;
        });

        if (!latest.empty()) break;
    }

    if (latest.empty()) return false;


    const std::string status = normalize_key(latest);


    return status == "running" || status == "cancelled" || status == "canceled" || status == "aborted" || status == "error";
}




std::string observation_week_from_line(const std::string& line) {


    std::string week = get_json_string(line, "week");

    if (!week.empty()) return week;


    const int64_t y = get_json_int(line, "bulletin_year");


    const int64_t w = get_json_int(line, "bulletin_week");

    if (y >= 1970 && w >= 1 && w <= 53) {
        std::ostringstream os;

        os << y << '-' << std::setw(2) << std::setfill('0') << w;

        return os.str();
    }

    return {};
}



fs::path epidemiology_last_good_dir();




void clear_epidemiology_runtime_view(UiState& ui, bool clear_loaded_observations);




size_t configured_epidemiological_disease_universe_count() {


    static std::once_flag once;
    static size_t cached = 0;


    std::call_once(once, [] {

        std::set<std::string> ids;

        const std::vector<fs::path> files = {

            ui_config_root() / "diseases_historial.tsv",

            ui_config_root() / "diseases.tsv"
        };

        for (const auto& f : files) {


            std::ifstream in(f, std::ios::binary);

            if (!in) continue;

            std::string line;

            while (std::getline(in, line)) {

                line = trim(line);

                if (line.empty()) continue;

                if (line.size() >= 3 && static_cast<unsigned char>(line[0]) == 0xEF && static_cast<unsigned char>(line[1]) == 0xBB && static_cast<unsigned char>(line[2]) == 0xBF) line.erase(0, 3);

                if (line.empty() || line[0] == '#') continue;
                const auto tab = line.find('	');

                std::string id = trim(tab == std::string::npos ? line : line.substr(0, tab));

                if (!id.empty() && id != "id") ids.insert(id);
            }
        }
        cached = ids.size();
    });

    return cached;
}




ObservationCandidateProfile profile_observation_candidate(const fs::path& obs_path) {

    ObservationCandidateProfile p;

    p.path = obs_path;

    p.run_root = infer_run_root_from_observations_path(obs_path.parent_path());
    p.run_completed = run_state_is_complete(p.run_root);

    p.canceled_or_incomplete = run_state_is_incomplete_or_canceled(p.run_root);


    std::ifstream in(obs_path, std::ios::binary);

    if (!in) return p;
    std::string line;

    while (std::getline(in, line)) {


        if (trim(line).empty()) continue;

        ++p.rows;

        const std::string week = observation_week_from_line(line);


        const std::string geo = get_json_string(line, "jurisdiction_id");


        const std::string disease = get_json_string(line, "disease_id");

        if (week.empty() || geo.empty() || disease.empty()) continue;

        ++p.usable_rows;

        ++p.week_rows[week];

        p.week_diseases[week].insert(disease);
    }

    for (const auto& [_, ids] : p.week_diseases) p.reference_disease_count = std::max(p.reference_disease_count, ids.size());

    const size_t configured_universe = configured_epidemiological_disease_universe_count();

    if (configured_universe >= 8) p.reference_disease_count = std::max(p.reference_disease_count, configured_universe);



    const size_t min_diseases_for_valid_week = p.reference_disease_count == 0 ? 0 : static_cast<size_t>(std::floor(static_cast<double>(p.reference_disease_count) * 0.80)) + 1;

    for (const auto& [week, n] : p.week_rows) {

        const auto dit = p.week_diseases.find(week);

        const size_t disease_count = dit == p.week_diseases.end() ? 0 : dit->second.size();

        if (disease_count >= min_diseases_for_valid_week && disease_count >= 8) ++p.strong_weeks;

        else if (n > 0) ++p.weak_weeks;
    }



    p.score = static_cast<int64_t>(p.usable_rows)

            + static_cast<int64_t>(p.strong_weeks) * 250000LL
            + static_cast<int64_t>(p.reference_disease_count) * 25000LL

            - static_cast<int64_t>(p.weak_weeks) * 80000LL;

    if (p.run_completed) p.score += 2000000000LL;


    if (p.canceled_or_incomplete) p.score -= 1200000000LL;

    if (p.usable_rows == 0) p.score = std::numeric_limits<int64_t>::min() / 2;


    return p;
}



std::string infer_group_for_uncatalogued_disease(const std::string& id, const std::string& name, const std::string& cie10) {


    const std::string n = normalize_key(id + " " + name + " " + cie10);
    const auto has = [&](const std::string& needle) { return n.find(needle) != std::string::npos; };

    if (has("rubeola") || has("tetanos") || has("tos ferina") || has("varicela") || has("parotiditis") || has("vacun")) return "prevenibles_vacunacion";

    if (has("colera") || has("intoxicacion alimentaria") || has("gastro") || has("intestinal") || has("diar") || has("helmint") || has("protozo")) return "digestivas";

    if (has("influenza") || has("neumonia") || has("respiratoria") || has("faringitis") || has("otitis")) return "respiratorias";

    if (has("vih") || has("sifilis") || has("gonoc") || has("genital") || has("venereo") || has("tricomon")) return "transmision_sexual";

    if (has("dengue") || has("zika") || has("chikungunya") || has("paludismo") || has("leishman") || has("oncocerc") || has("oeste del nilo") || has("ricketts")) return "vectores";

    if (has("rabia") || has("brucel") || has("leptosp") || has("teniasis") || has("cisticerc") || has("triquinos")) return "zoonosis";

    if (has("accidente") || has("morded") || has("picadura") || has("arma") || has("quemadura") || has("traumatico") || has("avisp") || has("abej")) return "accidentes";

    if (has("desnutric") || has("obesidad") || has("anorexia") || has("bulimia")) return "nutricion";

    if (has("anencef") || has("encefalocele") || has("bifida") || has("microcef") || has("paladar hendido")) return "defectos_nacer";

    if (has("depresion") || has("alzheimer") || has("parkinson") || has("neurolog")) return "neurologicas_salud_mental";

    if (!cie10.empty()) {

        const char c = static_cast<char>(std::toupper(static_cast<unsigned char>(cie10[0])));

        if (c == 'A' || c == 'B') return "otras_enfermedades_transmisibles";

        if (c == 'J') return "respiratorias";

        if (c == 'V' || c == 'W' || c == 'X' || c == 'Y') return "accidentes";

        if (c == 'E') return "no_transmisibles";

        if (c == 'C' || c == 'D' || c == 'I' || c == 'K' || c == 'N' || c == 'O' || c == 'Q' || c == 'T') return "no_transmisibles";
    }

    return "sin_categoria";
}



fs::path first_existing_observation_file(std::initializer_list<fs::path> paths) {
    std::error_code ec;

    for (const auto& p : paths) {


        if (!p.empty() && fs::exists(p, ec) && !ec && fs::is_regular_file(p, ec) && !ec && file_size_or_zero(p) > 32) return p;

        ec.clear();
    }

    return {};
}



