std::string jurisdiction_display_name_from_id(const std::string& id) {


    static const std::map<std::string, std::string> names = {
        {"alvaro_obregon", "Alvaro Obregon"},
        {"azcapotzalco", "Azcapotzalco"},
        {"benito_juarez", "Benito Juarez"},
        {"coyoacan", "Coyoacan"},
        {"cuajimalpa", "Cuajimalpa"},
        {"cuauhtemoc", "Cuauhtemoc"},
        {"gustavo_a_madero", "Gustavo A. Madero"},
        {"iztacalco", "Iztacalco"},
        {"iztapalapa", "Iztapalapa"},
        {"magdalena_contreras", "Magdalena Contreras"},
        {"miguel_hidalgo", "Miguel Hidalgo"},
        {"milpa_alta", "Milpa Alta"},
        {"tlahuac", "Tlahuac"},
        {"tlalpan", "Tlalpan"},

        {"venustiano_carranza", "Venustiano Carranza"},
        {"xochimilco", "Xochimilco"}
    };

    const auto it = names.find(id);


    if (it != names.end()) return it->second;
    std::string out = id;
    std::replace(out.begin(), out.end(), '_', ' ');
    bool word = true;

    for (char& c : out) {

        if (std::isspace(static_cast<unsigned char>(c))) {
            word = true;


        } else if (word) {
            c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
            word = false;
        }
    }

    return out;
}



bool is_internal_extraction_disease_id(const std::string& id) {

    return id.rfind("auto_", 0) == 0;
}



std::string humanize_disease_id(const std::string& id) {
    std::string out = id;

    if (out.rfind("auto_", 0) == 0) out = out.substr(5);
    std::replace(out.begin(), out.end(), '_', ' ');
    bool word = true;

    for (char& c : out) {

        if (std::isspace(static_cast<unsigned char>(c))) {
            word = true;

        } else if (word) {
            c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
            word = false;
        }
    }

    return out.empty() ? "Enfermedad sin nombre" : out;
}




