bool ixiptlah_decade_file_parts_for_runtime(const fs::path& path, const char* category_stem, int* decade) {
    if (lower_ascii(path_utf8(path.extension())) != ".ixiptlah") return false;
    const std::string stem = lower_ascii(path_utf8(path.stem()));
    const std::string prefix = lower_ascii(std::string(category_stem ? category_stem : "DatosEpidemiologicos") + "_");
    if (stem.rfind(prefix, 0) != 0 || stem.size() != prefix.size() + 4u) return false;
    int y = 0;
    for (std::size_t i = prefix.size(); i < stem.size(); ++i) {
        const unsigned char ch = static_cast<unsigned char>(stem[i]);
        if (!std::isdigit(ch)) return false;
        y = y * 10 + (stem[i] - '0');
    }
    if (y < 0 || y > 9990 || y % 10 != 0) return false;
    if (decade) *decade = y;
    return true;
}

std::vector<fs::path> ixiptlah_decade_paths_for_runtime(const char* category_stem) {
    struct CachedDecadeList {
        std::vector<fs::path> paths;
        std::int64_t directory_tick = 0;
        std::chrono::steady_clock::time_point loaded{};
    };

    static std::mutex cache_mu;
    static std::map<std::string, CachedDecadeList> cache;

    const fs::path root = datos_root();
    const std::string stem = category_stem ? category_stem : "DatosEpidemiologicos";
    const std::string key = path_utf8(root) + "|" + lower_ascii(stem);
    std::error_code ec;
    if (!fs::exists(root, ec) || ec) return {};
    ec.clear();
    const auto dir_time = fs::last_write_time(root, ec);
    const std::int64_t dir_tick = ec ? 0 : static_cast<std::int64_t>(dir_time.time_since_epoch().count());
    const auto now = std::chrono::steady_clock::now();

    {
        std::lock_guard<std::mutex> lock(cache_mu);
        const auto it = cache.find(key);
        if (it != cache.end() && it->second.directory_tick == dir_tick &&
            now - it->second.loaded < std::chrono::milliseconds(1200)) {
            return it->second.paths;
        }
    }

    std::vector<std::pair<int, fs::path>> files;
    ec.clear();
    for (fs::directory_iterator it(root, fs::directory_options::skip_permission_denied, ec), end; !ec && it != end; it.increment(ec)) {
        std::error_code item_ec;
        if (!it->is_regular_file(item_ec) || item_ec) { ec.clear(); continue; }
        const fs::path path = it->path();
        int decade = 0;
        if (!ixiptlah_decade_file_parts_for_runtime(path, stem.c_str(), &decade)) continue;
        if (file_size_or_zero(path) <= 16) continue;
        files.emplace_back(decade, path);
    }
    std::sort(files.begin(), files.end(), [](const auto& a, const auto& b) {
        if (a.first != b.first) return a.first > b.first;
        return path_utf8(a.second) > path_utf8(b.second);
    });
    std::vector<fs::path> out;
    out.reserve(files.size());
    for (auto& entry : files) out.push_back(std::move(entry.second));

    {
        std::lock_guard<std::mutex> lock(cache_mu);
        CachedDecadeList& c = cache[key];
        c.paths = out;
        c.directory_tick = dir_tick;
        c.loaded = now;
        if (cache.size() > 16u) cache.erase(cache.begin());
    }
    return out;
}

std::string ixiptlah_element_token_for_runtime(const std::string& raw) {
    std::string n = normalize_key(raw);
    std::string out;
    out.reserve(n.size() + 8);
    bool sep = false;
    for (unsigned char ch : n) {
        if (std::isalnum(ch)) {
            if (sep && !out.empty()) out.push_back('_');
            out.push_back(static_cast<char>(std::toupper(ch)));
            sep = false;
        } else {
            sep = true;
        }
    }
    while (!out.empty() && out.back() == '_') out.pop_back();
    if (out.empty()) out = "ELEMENTO";
    if (out.size() > 96) out.resize(96);
    return out;
}

fs::path ixiptlah_element_path_for_runtime(const char* category_stem, const std::string& element_key) {
    return ixiptlah_path(datos_root(), std::string(category_stem ? category_stem : "DATOS_EPIDEMIOLOGICOS") + "__" + ixiptlah_element_token_for_runtime(element_key));
}

