bool tlalpowa_selected_key_is_meteorological_runtime(const std::string& key) {
    const std::string k = atmospheric_parameter_key(key);
    return ozmvm_atm_key_is_meteorological(k.data(), k.size()) != 0;
}

std::set<std::string> ixiptlah_atmospheric_load_keys_for_runtime(const std::set<std::string>& selected_pollutants) {
    std::set<std::string> keys;
    for (const auto& selected : selected_pollutants) {
        const std::string k = atmospheric_parameter_key(selected);
        const bool offered = !k.empty() &&
            (ozmvm_atm_key_is_meteorological(k.data(), k.size()) != 0 ||
             ozmvm_atm_key_is_contaminant(k.data(), k.size()) != 0);
        if (offered) keys.insert(k);
        // Dirección del viento es una capa aislada; WSP sólo se agrega como auxiliar
        // de longitud de flecha. No se dibuja como pin salvo que su casilla esté activa.
        if (k == "wdr") keys.insert("wsp");
    }
    return keys;
}


bool ixiptlah_weekly_file_parts_for_runtime(const fs::path& path, int* year, int* month, int* day) {
    if (lower_ascii(path_utf8(path.extension())) != ".ixiptlah") return false;
    const std::string stem = path_utf8(path.stem());
    return tlal_ix_week_name_parts(stem.data(), stem.size(), year, month, day) != 0;
}

std::vector<fs::path> ixiptlah_weekly_paths_for_runtime(const fs::path& root) {
    std::vector<fs::path> out;
    std::error_code ec;
    if (root.empty() || !fs::exists(root, ec) || ec) return out;
    for (fs::directory_iterator it(root, fs::directory_options::skip_permission_denied, ec), end; !ec && it != end; it.increment(ec)) {
        const fs::path path = it->path();
        std::error_code item_ec;
        if (!it->is_regular_file(item_ec) || item_ec) { ec.clear(); continue; }
        int y = 0, m = 0, d = 0;
        if (!ixiptlah_weekly_file_parts_for_runtime(path, &y, &m, &d)) continue;
        if (file_size_or_zero(path) <= 16) continue;
        out.push_back(path);
    }
    std::sort(out.begin(), out.end(), [](const fs::path& a, const fs::path& b) {
        int ay = 0, am = 0, ad = 0, by = 0, bm = 0, bd = 0;
        const bool ak = ixiptlah_weekly_file_parts_for_runtime(a, &ay, &am, &ad);
        const bool bk = ixiptlah_weekly_file_parts_for_runtime(b, &by, &bm, &bd);
        if (ak && bk) {
            if (ay != by) return ay > by;
            if (am != bm) return am > bm;
            if (ad != bd) return ad > bd;
        }
        return path_utf8(a) > path_utf8(b);
    });
    out.erase(std::unique(out.begin(), out.end()), out.end());
    return out;
}

unsigned ixiptlah_week_start_day_for_runtime(unsigned day) {
    if (day < 1u) return 1u;
    return static_cast<unsigned>(((static_cast<int>(day) - 1) / 7) * 7 + 1);
}

fs::path ixiptlah_weekly_path_for_runtime(int year, unsigned month, unsigned day) {
    const unsigned safe_month = static_cast<unsigned>(std::clamp<int>(static_cast<int>(month), 1, 12));
    const unsigned safe_day = ixiptlah_week_start_day_for_runtime(day);
    std::ostringstream os;
    os << std::setw(4) << std::setfill('0') << std::clamp(year, 0, 9999) << '_'
       << std::setw(2) << std::setfill('0') << safe_month << '_'
       << std::setw(2) << std::setfill('0') << std::clamp<unsigned>(safe_day, 1u, 29u);
    return ixiptlah_path(datos_root(), os.str());
}

std::vector<fs::path> ixiptlah_weekly_paths_for_runtime_range(int64_t lo_hour, int64_t hi_hour) {
    if (hi_hour < lo_hour) std::swap(lo_hour, hi_hour);
    const int64_t lo_day = floor_div_i64(lo_hour, 24);
    const int64_t hi_day = floor_div_i64(hi_hour, 24);
    std::vector<fs::path> out;
    out.reserve(static_cast<std::size_t>(std::min<int64_t>(64, std::max<int64_t>(1, hi_day - lo_day + 1))));
    std::set<std::string> seen;
    for (int64_t d = lo_day; d <= hi_day; ++d) {
        int y = 0; unsigned m = 1, day = 1;
        civil_from_days(timeline_epoch_days() + d, y, m, day);
        fs::path p = ixiptlah_weekly_path_for_runtime(y, m, day);
        const std::string key = path_utf8(p.lexically_normal());
        if (seen.insert(key).second) out.push_back(std::move(p));
        if (out.size() >= 64u) break;
    }
    return out;
}

std::vector<fs::path> ixiptlah_weekly_paths_for_runtime_year(int year) {
    std::vector<fs::path> out;
    out.reserve(62u);
    for (unsigned month = 1u; month <= 12u; ++month) {
        const unsigned starts[] = {1u, 8u, 15u, 22u, 29u};
        for (unsigned d : starts) {
            const fs::path p = ixiptlah_weekly_path_for_runtime(year, month, d);
            if (fs::exists(p) && file_size_or_zero(p) > 16) out.push_back(p);
        }
    }
    out.erase(std::unique(out.begin(), out.end()), out.end());
    return out;
}

std::vector<fs::path> ixiptlah_atmospheric_paths_for_runtime(const std::set<std::string>& selected_pollutants) {
    const std::set<std::string> keys = ixiptlah_atmospheric_load_keys_for_runtime(selected_pollutants);
    if (keys.empty()) return {};

    // IXIPTLAH v12 local: RAMA, REDMET y RUOA/PEMBU ya no viven en núcleos
    // separados por red. Todos los registros de una semana están en el archivo
    // físico AAAA_MM_DD.ixiptlah; la red y la variable se filtran por tags/capa
    // antes de leer payload. Esta función queda sólo como barrido diagnóstico.
    return ixiptlah_weekly_paths_for_runtime(datos_root());
}


std::set<std::uint64_t> ixiptlah_atmospheric_layer_hashes_for_runtime(const std::set<std::string>& selected_pollutants) {
    std::set<std::uint64_t> out;
    for (const auto& k : ixiptlah_atmospheric_load_keys_for_runtime(selected_pollutants)) {
        if (!k.empty()) out.insert(ixiptlah_layer_hash(k));
    }
    return out;
}

int ixiptlah_atmospheric_temporal_year(std::uint64_t key) {
    return static_cast<int>(key / 100000000ull);
}

int ixiptlah_atmospheric_temporal_month(std::uint64_t key) {
    return static_cast<int>((key / 1000000ull) % 100ull);
}

std::uint64_t ixiptlah_atmospheric_month_key(int year, unsigned month) {
    return static_cast<std::uint64_t>(std::clamp(year, 0, 9999)) * 100ull +
           static_cast<std::uint64_t>(std::clamp<int>(static_cast<int>(month), 1, 12));
}

std::uint64_t ixiptlah_atmospheric_temporal_month_key(std::uint64_t temporal_key) {
    if (temporal_key == 0ull) return 0ull;
    const int y = ixiptlah_atmospheric_temporal_year(temporal_key);
    const int m = ixiptlah_atmospheric_temporal_month(temporal_key);
    if (y <= 0 || m < 1 || m > 12) return 0ull;
    return static_cast<std::uint64_t>(y) * 100ull + static_cast<std::uint64_t>(m);
}

bool ixiptlah_atmospheric_temporal_month_matches(std::uint64_t temporal_key, int year, unsigned month) {
    if (temporal_key == 0ull) return true; // Conservador para registros importados a mano.
    return ixiptlah_atmospheric_temporal_month_key(temporal_key) == ixiptlah_atmospheric_month_key(year, month);
}

std::uint64_t ixiptlah_atmospheric_temporal_month_begin_key(int year, unsigned month) {
    const std::uint64_t y = static_cast<std::uint64_t>(std::clamp(year, 0, 9999));
    const std::uint64_t m = static_cast<std::uint64_t>(std::clamp<int>(static_cast<int>(month), 1, 12));
    return (((y * 100ull + m) * 100ull) * 100ull) * 100ull;
}

std::uint64_t ixiptlah_atmospheric_temporal_month_end_key(int year, unsigned month) {
    int y = std::clamp(year, 0, 9999);
    unsigned m = static_cast<unsigned>(std::clamp<int>(static_cast<int>(month), 1, 12));
    if (m == 12u) { if (y < 9999) { ++y; m = 1u; } }
    else { ++m; }
    return ixiptlah_atmospheric_temporal_month_begin_key(y, m);
}

std::uint64_t ixiptlah_atmospheric_temporal_instant_key(int year, unsigned month, unsigned day, unsigned hour, unsigned minute) {
    const std::uint64_t y = static_cast<std::uint64_t>(std::clamp(year, 0, 9999));
    const std::uint64_t m = static_cast<std::uint64_t>(std::clamp<int>(static_cast<int>(month), 1, 12));
    const std::uint64_t d = static_cast<std::uint64_t>(std::clamp<int>(static_cast<int>(day), 1, 31));
    const std::uint64_t h = static_cast<std::uint64_t>(std::clamp<int>(static_cast<int>(hour), 0, 23));
    const std::uint64_t mi = static_cast<std::uint64_t>(std::clamp<int>(static_cast<int>(minute), 0, 59));
    return (((y * 100ull + m) * 100ull + d) * 100ull + h) * 100ull + mi;
}

bool ixiptlah_atmospheric_temporal_month_between(std::uint64_t temporal_key,
                                                std::uint64_t lo_month_key,
                                                std::uint64_t hi_month_key) {
    if (temporal_key == 0ull) return true;
    const std::uint64_t mk = ixiptlah_atmospheric_temporal_month_key(temporal_key);
    return mk != 0ull && mk >= lo_month_key && mk <= hi_month_key;
}

fs::path ixiptlah_month_path_for_runtime(int year, unsigned month) {
    return ixiptlah_weekly_path_for_runtime(year, month, 1u);
}


std::string atmospheric_parameter_key(const std::string& pollutant);
std::string atmospheric_parameter_label(const std::string& pollutant);

std::string atmospheric_catalog_group_for_key(const std::string& raw_key) {
    const std::string key = atmospheric_parameter_key(raw_key);
    char group[48];
    ozmvm_atm_catalog_group_copy(key.data(), key.size(), group, sizeof(group));
    return group;
}


double atmospheric_station_representative_radius_meters(const std::string& pollutant);
double atmospheric_health_ratio(const std::string& pollutant, double value, const std::string& unit);



std::string pollutant_filter_signature(const std::set<std::string>& selected_pollutants) {



    if (selected_pollutants.empty()) return "__TLALPOWA_NONE_SELECTED__";
    std::ostringstream os;
    bool first = true;

    for (const auto& p : selected_pollutants) {

        if (!first) os << '|';
        first = false;
        os << p;
    }

    return os.str();
}



std::string atmosphere_station_identity_key(const TemporalAtmospherePackedStation& station) {


    std::ostringstream os;
    os << station.id << "\t" << station.name << "\t"

       << std::fixed << std::setprecision(6) << station.lon << "\t" << station.lat << "\t"

       << std::setprecision(1) << station.alt;

    return os.str();
}


std::string atmosphere_value_key(const TemporalAtmospherePackedStation& station,
                                 const std::string& pollutant,

                                 const std::string& unit) {



    return atmosphere_station_identity_key(station) + "\t" + pollutant + "\t" + unit;
}



