struct RamaIxiptlahCachedSample {
    std::uint8_t day = 0;

    std::uint8_t hour = 0;

    std::uint8_t minute = 0;
    std::uint32_t station_index = 0;
    std::uint32_t pollutant_index = 0;
    std::uint32_t unit_index = 0;
    double value = 0.0;
    std::uint64_t ordinal = 0;
};


bool read_ixiptlah_atmosphere_direct_sample(std::istream& in,
                                            std::uint32_t schema,
                                            TemporalAtmospherePackedSample& sample) {
    sample = {};
    if (schema != 1) return false;
    std::uint16_t minute_of_day = 0;
    std::uint16_t station16 = 0;
    std::uint8_t unit8 = 0;
    float value32 = 0.0f;
    if (!ixiptlah_read_value(in, sample.day) ||
        !ixiptlah_read_value(in, minute_of_day) ||
        !ixiptlah_read_value(in, station16) ||
        !ixiptlah_read_value(in, unit8) ||
        !ixiptlah_read_value(in, value32)) return false;
    if (minute_of_day >= 1440u) return false;
    sample.hour = static_cast<std::uint8_t>(minute_of_day / 60u);
    sample.minute = static_cast<std::uint8_t>(minute_of_day % 60u);
    sample.station_index = static_cast<std::uint32_t>(station16);
    sample.pollutant_index = 0u; // IXIPTLAH-ATM V1: variable implícita por record etiquetado.
    sample.unit_index = static_cast<std::uint32_t>(unit8);
    sample.value = static_cast<double>(value32);
    return true;
}




struct RamaIxiptlahCachedBatch {

    int year = 0;


    int month = 0;

    std::vector<TemporalAtmospherePackedStation> stations;

    std::vector<std::string> pollutants;

    std::vector<std::string> pollutant_keys;

    std::vector<std::string> units;


    std::array<std::vector<RamaIxiptlahCachedSample>, 32> samples_by_day;


    std::array<std::unordered_map<std::string, std::vector<RamaIxiptlahCachedSample>>, 32> samples_by_day_series;



    std::array<std::unordered_map<std::string, std::vector<std::string>>, 32> series_keys_by_day_pollutant;

    std::array<std::unordered_map<std::string, std::vector<std::uint32_t>>, 32> sample_indices_by_day_pollutant;
};




struct RamaIxiptlahMonthlyCache {

    fs::path path;


    std::uintmax_t file_size = 0;

    std::filesystem::file_time_type write_time{};
    bool valid = false;


    std::vector<RamaIxiptlahCachedBatch> batches;
};




std::shared_ptr<const RamaIxiptlahMonthlyCache> load_rama_ixiptlah_monthly_cache(const fs::path& block) {




    static std::mutex cache_mu;


    static std::map<std::string, std::shared_ptr<const RamaIxiptlahMonthlyCache>> cache_by_path;

    static std::deque<std::string> cache_lru;


    const std::size_t kMaxResidentRamaIxiptlahMonths = static_cast<std::size_t>(env_int_clamped_app("TLALPOWA_RAMA_MONTHLY_CACHE_LIMIT", 8, 1, 32));

    auto touch_lru = [](std::deque<std::string>& lru, const std::string& touched) {

        lru.erase(std::remove(lru.begin(), lru.end(), touched), lru.end());

        lru.push_back(touched);
    };

    if (block.empty() || !fs::exists(block)) return {};
    std::error_code ec;


    const std::uintmax_t sz = fs::file_size(block, ec);

    if (ec) return {};

    ec.clear();

    const auto wt = fs::last_write_time(block, ec);

    if (ec) return {};

    const std::string key = path_utf8(block);
    {


        std::lock_guard<std::mutex> lock(cache_mu);

        auto it = cache_by_path.find(key);

        if (it != cache_by_path.end()) {
            const auto& live = it->second;


            if (live && live->valid && live->file_size == sz && live->write_time == wt) {
                touch_lru(cache_lru, key);

                return live;
            }

            cache_by_path.erase(it);

            cache_lru.erase(std::remove(cache_lru.begin(), cache_lru.end(), key), cache_lru.end());
        }
    }


    auto cache = std::make_shared<RamaIxiptlahMonthlyCache>();

    cache->path = block;


    cache->file_size = sz;

    cache->write_time = wt;
    cache->valid = true;


    ixiptlah_read_selected_records_tagged_temporal_exact(block,
        IxiptlahRecordType::MonthlyAtmosphereMeasurementBatch, 1, {}, false, 0ull, 0ull,
        [&](IxiptlahRecordType, std::uint32_t schema, std::istream& in) {

            std::string source_id, source_file, source_path, domain;


            int year = 0, month = 0;
            std::uint32_t station_count = 0, pollutant_count = 0, unit_count = 0;


            if (!ixiptlah_read_string(in, source_id) ||


                !ixiptlah_read_string(in, source_file) ||


                !ixiptlah_read_string(in, source_path) ||


                !ixiptlah_read_string(in, domain) ||


                !ixiptlah_read_value(in, year) ||


                !ixiptlah_read_value(in, month) ||


                !ixiptlah_read_value(in, station_count) ||
                station_count > 200000u) {



                return true;
            }


            RamaIxiptlahCachedBatch batch;

            batch.year = year;


            batch.month = month;

            batch.stations.resize(station_count);

            for (auto& station : batch.stations) {


                if (!ixiptlah_read_string(in, station.id) ||


                    !ixiptlah_read_string(in, station.name) ||


                    !ixiptlah_read_value(in, station.lon) ||


                    !ixiptlah_read_value(in, station.lat) ||


                    !ixiptlah_read_value(in, station.alt)) return true;
            }


            if (!ixiptlah_read_value(in, pollutant_count) || pollutant_count > 10000u) return true;

            batch.pollutants.resize(pollutant_count);

            batch.pollutant_keys.resize(pollutant_count);

            for (std::uint32_t i = 0; i < pollutant_count; ++i) {


                if (!ixiptlah_read_string(in, batch.pollutants[static_cast<std::size_t>(i)])) return true;

                batch.pollutant_keys[static_cast<std::size_t>(i)] = atmospheric_parameter_key(batch.pollutants[static_cast<std::size_t>(i)]);
            }


            if (!ixiptlah_read_value(in, unit_count) || unit_count > 10000u) return true;

            batch.units.resize(unit_count);


            for (auto& unit : batch.units) if (!ixiptlah_read_string(in, unit)) return true;
            std::uint64_t sample_count = 0;


            if (!ixiptlah_read_value(in, sample_count) || sample_count > 100000000ull) return true;

            for (std::uint64_t i = 0; i < sample_count; ++i) {

                TemporalAtmospherePackedSample sample;


                if (!read_ixiptlah_atmosphere_direct_sample(in, schema, sample)) return true;

                const unsigned dim = timeline_navigation_days_in_month(year, static_cast<unsigned>(std::clamp(month, 1, 12)));
                if (sample.day == 0 || sample.day > dim || sample.day >= batch.samples_by_day.size()) continue;
                if (sample.hour > 23 || sample.minute > 59) continue;

                if (sample.station_index >= batch.stations.size() || sample.pollutant_index >= batch.pollutants.size() || sample.unit_index >= batch.units.size()) continue;

                if (!std::isfinite(sample.value)) continue;

                const auto& station = batch.stations[static_cast<std::size_t>(sample.station_index)];

                if (station.lon < -103.0 || station.lon > -96.0 || station.lat < 17.0 || station.lat > 22.0) continue;


                RamaIxiptlahCachedSample cached;
                cached.day = sample.day;

                cached.hour = sample.hour;

                cached.minute = sample.minute;
                cached.station_index = sample.station_index;
                cached.pollutant_index = sample.pollutant_index;
                cached.unit_index = sample.unit_index;
                cached.value = sample.value;
                cached.ordinal = i;

                batch.samples_by_day[static_cast<std::size_t>(sample.day)].push_back(cached);
            }

            for (std::size_t day_i = 0; day_i < batch.samples_by_day.size(); ++day_i) {
                auto& day_samples = batch.samples_by_day[day_i];


                std::stable_sort(day_samples.begin(), day_samples.end(), [](const RamaIxiptlahCachedSample& a, const RamaIxiptlahCachedSample& b) {

                    const int ma = static_cast<int>(a.hour) * 60 + static_cast<int>(a.minute);

                    const int mb = static_cast<int>(b.hour) * 60 + static_cast<int>(b.minute);

                    if (ma != mb) return ma < mb;

                    return a.ordinal < b.ordinal;
                });
                auto& series = batch.samples_by_day_series[day_i];
                auto& series_by_pollutant = batch.series_keys_by_day_pollutant[day_i];
                auto& sample_indices_by_pollutant = batch.sample_indices_by_day_pollutant[day_i];

                series.reserve(std::min<std::size_t>(day_samples.size(), 4096));

                sample_indices_by_pollutant.reserve(std::min<std::size_t>(batch.pollutant_keys.size(), 32));

                series_by_pollutant.reserve(std::min<std::size_t>(batch.pollutant_keys.size(), 32));

                for (std::size_t sample_i = 0; sample_i < day_samples.size(); ++sample_i) {
                    const auto& cached_sample = day_samples[sample_i];

                    if (cached_sample.station_index >= batch.stations.size() ||
                        cached_sample.pollutant_index >= batch.pollutant_keys.size() ||
                        cached_sample.unit_index >= batch.units.size()) continue;
                    const auto& station = batch.stations[static_cast<std::size_t>(cached_sample.station_index)];
                    const std::string& pollutant = batch.pollutant_keys[static_cast<std::size_t>(cached_sample.pollutant_index)];

                    const std::string& unit = batch.units[static_cast<std::size_t>(cached_sample.unit_index)];


                    const std::string key = atmosphere_value_key(station, pollutant, unit);
                    auto& one_series = series[key];

                    if (one_series.empty()) {



                        series_by_pollutant[pollutant].push_back(key);
                    }

                    one_series.push_back(cached_sample);

                    if (sample_i <= static_cast<std::size_t>(std::numeric_limits<std::uint32_t>::max())) {



                        sample_indices_by_pollutant[pollutant].push_back(static_cast<std::uint32_t>(sample_i));
                    }
                }
            }

            cache->batches.push_back(std::move(batch));

            (void)source_id; (void)source_file; (void)source_path; (void)domain;

            return true;
        });
    {


        std::lock_guard<std::mutex> lock(cache_mu);

        cache_by_path[key] = cache;
        touch_lru(cache_lru, key);


        while (cache_lru.size() > kMaxResidentRamaIxiptlahMonths) {
            const std::string victim = cache_lru.front();
            cache_lru.pop_front();

            if (victim == key) {

                cache_lru.push_back(victim);
                break;
            }

            cache_by_path.erase(victim);
        }
    }

    return cache;
}


AtmosphericCloudPoint make_atmospheric_cloud_point(const TemporalAtmospherePackedStation& station,

                                                    const std::string& pollutant,

                                                    const std::string& unit,
                                                    double mean,
                                                    double min_value,
                                                    double max_value,
                                                    double sum_value,
                                                    int64_t count,

                                                    int year,


                                                    int month,
                                                    int day,

                                                    int hour_of_day,

                                                    int minute) {
    AtmosphericCloudPoint c;
    c.station_id = station.id;
    c.station = station.name;
    c.pollutant = pollutant;
    c.unit = unit;

    c.lon = station.lon;

    c.lat = station.lat;
    c.alt = station.alt;
    c.mean = mean;
    c.min_value = min_value;
    c.max_value = max_value;
    c.sum_value = sum_value;

    c.representative_radius_m = atmospheric_station_representative_radius_meters(c.pollutant);
    const double health = atmospheric_health_ratio(c.pollutant, c.mean, c.unit);
    c.visual_level = health >= 0.0 ? static_cast<float>(std::clamp(health / 1.35, 0.0, 1.0)) : -1.0f;

    c.year = year;


    c.month = month;

    c.minute = std::clamp(minute, 0, 59);


    c.hour = timeline_hour_from_civil(year, static_cast<unsigned>(std::clamp(month, 1, 12)),
                                      static_cast<unsigned>(std::clamp(day, 1, 31)),

                                      static_cast<unsigned>(std::clamp(hour_of_day, 0, 23)));
    c.count = count;
    c.network_mask = atmosphere_network_mask_for_payload(std::string{}, std::string{}, std::string{}, std::string{}, pollutant);

    return c;
}





