void draw_preview_status_badge(const ExtractionPreview& current, const ImVec4& accent) {

    if (current.page <= 0 && current.status.empty()) return;

    ImDrawList* dl = ImGui::GetWindowDrawList();

    const ImVec2 a = ImGui::GetItemRectMin();
    const std::string txt = "procesando pagina " + std::to_string(current.page) + (current.status.empty() ? std::string{} : " | " + current.status);
    const ImVec2 pad(8.0f, 4.0f);

    const ImVec2 ts = ImGui::CalcTextSize(txt.c_str());
    const ImVec2 p0(a.x + 10.0f, a.y + 10.0f);
    const ImVec2 p1(p0.x + ts.x + pad.x * 2.0f, p0.y + ts.y + pad.y * 2.0f);
    dl->AddRectFilled(p0, p1, IM_COL32(16, 22, 28, 190), 5.0f);

    dl->AddRect(p0, p1, u32(accent, 0.70f), 5.0f, 0, 1.0f);
    dl->AddText(ImVec2(p0.x + pad.x, p0.y + pad.y), IM_COL32(245, 248, 252, 238), txt.c_str());
}




void draw_page_mask_canvas(const ExtractionPreview& p, const ImVec4& accent) {
    (void)accent;

    ImVec2 avail = ImGui::GetContentRegionAvail();

    const float requested_h = pdf_page_canvas_height(p, std::max(220.0f, avail.x));
    // El lienzo vectorial respeta la altura del contenedor cuando la ventana de
    // importación trabaja en modo horizontal página+tablas. Si no se acota aquí,
    // una página carta fuerza crecimiento vertical y cancela la proporción ancha
    // requerida para revisar varios encabezados epidemiológicos simultáneos.
    if (avail.y > 140.0f) avail.y = std::clamp(requested_h, 120.0f, avail.y);
    else avail.y = requested_h;

    ImDrawList* dl = ImGui::GetWindowDrawList();

    const ImVec2 pos = ImGui::GetCursorScreenPos();
    const bool preview_light = preview_surface_light_theme();
    dl->AddRectFilled(pos, ImVec2(pos.x + avail.x, pos.y + avail.y), preview_canvas_background_col());

    const bool allow_raster_page = preview_raster_enabled_by_env_app();
    const PreviewTexture tex = allow_raster_page ? load_preview_texture(p.page_image) : PreviewTexture{};
    const bool has_raster_page = allow_raster_page && tex.id != 0;
    const double pw = std::max(1.0, p.page_width > 0.0 ? p.page_width : (has_raster_page ? static_cast<double>(std::max(1, tex.width)) : 612.0));
    const double ph = std::max(1.0, p.page_height > 0.0 ? p.page_height : (has_raster_page ? static_cast<double>(std::max(1, tex.height)) : 792.0));

    // La página ya no escala sólo contra el ancho: en la retícula áurea nueva
    // la columna de página crece a 0.618033... del renglón, y el límite real
    // alterna entre el ancho dominante y la altura disponible del mapa. Escalar
    // por ambos ejes preserva la hoja completa sin recortar el pie del boletín.
    const float page_pad_y = std::max(2.0f, ImGui::GetFontSize() * 0.22f);
    const float scale_x = (avail.x / static_cast<float>(pw)) * 0.940f;
    const float scale_y = (std::max(1.0f, avail.y - page_pad_y * 2.0f) / static_cast<float>(ph)) * 0.985f;
    const float scale = std::max(0.0001f, std::min(scale_x, scale_y));

    const ImVec2 paper(pos.x + (avail.x - static_cast<float>(pw) * scale) * 0.5f,
                       pos.y + (avail.y - static_cast<float>(ph) * scale) * 0.5f);

    const ImVec2 paper2(paper.x + static_cast<float>(pw) * scale, paper.y + static_cast<float>(ph) * scale);

    auto P = [&](double x, double y) { return ImVec2(paper.x + static_cast<float>(x) * scale, paper.y + static_cast<float>(y) * scale); };

    if (!preview_light) {
        dl->AddRectFilled(ImVec2(paper.x - 3.0f, paper.y - 3.0f), ImVec2(paper2.x + 3.0f, paper2.y + 3.0f), IM_COL32(0, 0, 0, 112), 2.0f);
    }
    dl->AddRectFilled(paper, paper2, IM_COL32(255, 255, 255, 255));

    if (has_raster_page) {

        dl->AddImage((ImTextureID)(intptr_t)tex.id, paper, paper2);

    } else if (!p.tokens.empty()) {



        ImFont* font = ImGui::GetFont();

        float vector_font = ImGui::GetFontSize();
        int drawn = 0;

        for (const auto& t : p.tokens) {

            if (drawn++ >= 600) break;

            if (t.text.empty() || t.text.size() > 42) continue;
            const ImVec2 a = P(t.box.x0, t.box.y0);
            const ImVec2 b = P(t.box.x1, t.box.y1);

            if (b.x < paper.x || a.x > paper2.x || b.y < paper.y || a.y > paper2.y) continue;
            const float token_h = b.y - a.y;
            if (token_h < 6.5f) continue;
            vector_font = std::clamp(token_h * 0.82f, 5.4f, ImGui::GetFontSize() * 0.68f);
            dl->AddText(font, vector_font, ImVec2(a.x, a.y - 0.6f), IM_COL32(28, 34, 42, 145), t.text.c_str());
        }
    }
    dl->AddRect(paper, paper2, preview_light ? IM_COL32(178, 188, 198, 255) : IM_COL32(86, 98, 112, 220), 0.0f, 0, 1.0f);

    const ImU32 token_box = has_raster_page ? IM_COL32(58, 74, 90, 10) : IM_COL32(58, 74, 90, 24);

    int token_count = 0;

    for (const auto& t : p.tokens) {

        if (token_count++ >= 1200) break;
        const ImVec2 a = P(t.box.x0, t.box.y0);
        const ImVec2 b = P(t.box.x1, t.box.y1);

        if (b.x < paper.x || a.x > paper2.x || b.y < paper.y || a.y > paper2.y) continue;
        dl->AddRect(a, b, token_box, 1.0f, 0, has_raster_page ? 0.20f : 0.45f);
    }

    float table_y0 = paper.y;
    float table_y1 = paper2.y;

    if (!p.rows.empty()) {

        table_y0 = paper.y + static_cast<float>(p.rows.front().y0) * scale;

        table_y1 = paper.y + static_cast<float>(p.rows.back().y1) * scale;
    }



    
    
    const ImU32 row_line = has_raster_page ? IM_COL32(226, 92, 0, 18) : IM_COL32(226, 92, 0, 32);

    for (const auto& r : p.rows) {

        const float ym = paper.y + static_cast<float>(r.y_mid) * scale;

        if (!p.columns.empty()) {
            for (const auto& c : p.columns) {
                const float lane_x0 = std::max(paper.x, paper.x + static_cast<float>(c.x0) * scale);
                const float lane_x1 = std::min(paper2.x, paper.x + static_cast<float>(c.x1) * scale);
                if (lane_x1 <= lane_x0 + 0.5f) continue;
                dl->AddLine(ImVec2(lane_x0, ym), ImVec2(lane_x1, ym),
                            column_role_line_color(c, has_raster_page ? 18 : 46),
                            has_raster_page ? 2.40f : 6.40f);
            }
        } else {
            dl->AddLine(ImVec2(paper.x, ym), ImVec2(paper2.x, ym), row_line, has_raster_page ? 2.20f : 5.60f);
        }
    }



    for (const auto& c : p.columns) {

        const float xm = paper.x + static_cast<float>(c.x_mid) * scale;

        double src_y0 = (!p.rows.empty() ? p.rows.front().y0 : 0.0);

        if (rect_has_preview_area(c.header_box)) src_y0 = std::min(src_y0, c.header_box.y0);

        const float y0 = std::max(paper.y, paper.y + static_cast<float>(src_y0) * scale);
        const float lane_x0 = std::max(paper.x, paper.x + static_cast<float>(c.x0) * scale);
        const float lane_x1 = std::min(paper2.x, paper.x + static_cast<float>(c.x1) * scale);
        if (!has_raster_page && lane_x1 > lane_x0 + 0.5f) {
            dl->AddRectFilled(ImVec2(lane_x0, y0), ImVec2(lane_x1, table_y1), column_role_line_color(c, 12));
        }


        dl->AddLine(ImVec2(xm, y0), ImVec2(xm, table_y1), column_role_line_color(c, has_raster_page ? 28 : 58), has_raster_page ? 3.20f : 10.80f);

        if (rect_has_preview_area(c.header_box)) {
            const ImVec2 ha = P(c.header_box.x0, c.header_box.y0);
            const ImVec2 hb = P(c.header_box.x1, c.header_box.y1);

            dl->AddLine(ImVec2(ha.x, hb.y + 1.4f), ImVec2(hb.x, hb.y + 1.4f), column_role_line_color(c, has_raster_page ? 30 : 64), has_raster_page ? 2.80f : 9.00f);
            if (!has_raster_page && p.columns.size() <= 64) {
                std::string raw_label = !c.expected_role.empty() ? c.expected_role : c.role;
                if (raw_label.empty()) raw_label = c.header_text.empty() ? "columna" : c.header_text;
                const std::string label = compact_label(raw_label, 14);
                const ImVec2 label_size = ImGui::CalcTextSize(label.c_str());
                const float chip_w = std::min(std::max(label_size.x + 8.0f, 26.0f), std::max(26.0f, lane_x1 - lane_x0 + 16.0f));
                float chip_x = xm - chip_w * 0.5f;
                if (chip_x + chip_w > paper2.x - 2.0f) chip_x = paper2.x - chip_w - 2.0f;
                if (chip_x < paper.x + 2.0f) chip_x = paper.x + 2.0f;
                const float chip_y = std::max(paper.y + 5.0f, y0 - 15.0f);
                dl->AddRectFilled(ImVec2(chip_x, chip_y), ImVec2(chip_x + chip_w, chip_y + 13.0f), column_role_line_color(c, 62), 3.0f);
                dl->AddText(ImGui::GetFont(), 7.4f, ImVec2(chip_x + 4.0f, chip_y + 2.0f), IM_COL32(28, 34, 42, 220), label.c_str());
            }
        }
    }


    const ImU32 disease_underline = has_raster_page ? IM_COL32(130, 62, 190, 28) : IM_COL32(130, 62, 190, 64);
    const ImU32 cie10_underline = has_raster_page ? IM_COL32(0, 128, 150, 26) : IM_COL32(0, 128, 150, 58);

    std::set<std::string> underlined;

    for (const auto& c : p.columns) {

        if (rect_has_preview_area(c.disease_box)) {
            const std::string key = rect_preview_key(c.disease_box, "disease");

            if (underlined.insert(key).second) {
                const ImVec2 a = P(c.disease_box.x0, c.disease_box.y1 + 2.0);
                const ImVec2 b = P(c.disease_box.x1, c.disease_box.y1 + 2.0);
                dl->AddLine(a, b, disease_underline, has_raster_page ? 2.60f : 10.00f);
            }
        }

        if (rect_has_preview_area(c.cie10_box)) {
            const std::string key = rect_preview_key(c.cie10_box, "cie10");

            if (underlined.insert(key).second) {
                const ImVec2 a = P(c.cie10_box.x0, c.cie10_box.y1 + 2.0);
                const ImVec2 b = P(c.cie10_box.x1, c.cie10_box.y1 + 2.0);
                dl->AddLine(a, b, cie10_underline, has_raster_page ? 2.40f : 9.20f);
            }
        }
    }



    const double tol_page = std::max(2.0, 6.2 / std::max(0.10f, scale));

    const float small_font = has_raster_page ? 0.0f : std::min(ImGui::GetFontSize() * 0.72f, 8.5f);

    ImFont* font = ImGui::GetFont();
    
    int white_count = 0;

    if (!has_raster_page) for (const auto& t : p.tokens) {

        if (white_count++ >= 900) break;

        if (t.text.empty() || t.text.size() > 28) continue;

        if (!token_intersects_highlight(t, p, tol_page)) continue;
        const ImVec2 a = P(t.box.x0, t.box.y0);
        const ImVec2 b = P(t.box.x1, t.box.y1);

        if (b.x < paper.x || a.x > paper2.x || b.y < paper.y || a.y > paper2.y) continue;
        const float token_h = b.y - a.y;
        if (token_h < 6.0f) continue;
        const float overlay_font = std::clamp(token_h * 0.86f, 5.2f, std::max(5.2f, small_font));
        dl->AddText(font, overlay_font, ImVec2(a.x, a.y - 0.8f), IM_COL32(28, 34, 42, 210), t.text.c_str());
    }


    if (p.rows.size() * p.columns.size() <= 360) {

        for (const auto& c : p.columns) {

            const ImU32 dot = column_role_line_color(c, 82);

            for (const auto& r : p.rows) {
                const ImVec2 q = P(c.x_mid, r.y_mid);
                dl->AddCircleFilled(q, 1.45f, IM_COL32(255, 255, 255, 145));
                dl->AddCircle(q, 2.80f, dot, 0, 1.40f);
            }
        }
    }

    if (!has_raster_page) for (const auto& r : p.rows) {

        const float y = paper.y + static_cast<float>(r.y_mid) * scale;
        const std::string label = compact_label(r.jurisdiction, 17);
        if (small_font >= 5.0f) {
            dl->AddText(font, small_font, ImVec2(paper.x + 5, y - 4), IM_COL32(35, 43, 51, 150), label.c_str());
        }
    }


    const std::string title = p.pdf_file + " | pagina " + std::to_string(p.page);

    dl->AddText(font, ImGui::GetFontSize(), ImVec2(pos.x + 10, pos.y + 10), IM_COL32(25, 31, 38, 208), title.c_str());

    ImGui::InvisibleButton("page-mask-canvas", avail);
}



struct PreviewDistributionRow {
    const Observation* obs = nullptr;
    std::string distribution;
    int distribution_rank = 99;
    int jurisdiction_rank = 1000000;
    int source_rank = 0;
};

struct PreviewDiseaseTable {
    std::string key;
    std::string disease;
    std::string cie10;
    std::vector<PreviewDistributionRow> rows;
    int first_column_index = 1000000;
    int first_accepted_rank = 1000000;
    int source_order = 1000000;
    int detected_column_count = 0;
    unsigned distribution_mask = 0u;
};

bool preview_text_is_resolved_identity(const std::string& s) {
    const std::string k = normalize_key(s);
    return !k.empty() && k != "unknown" && k != "desconocido" &&
           k != "enfermedad_no_resuelta" && k != "cie_10_no_resuelto";
}

std::string preview_identity_or_fallback(const std::string& value, const char* fallback) {
    return preview_text_is_resolved_identity(value) ? trim(value) : std::string(fallback);
}

std::string preview_distribution_label_from_parts(const std::string& period,
                                                  const std::string& sex,
                                                  const std::string& expected_role,
                                                  const std::string& role,
                                                  const std::string& header_text) {
    const std::string p = normalize_key(period);
    const std::string sx = normalize_key(sex);
    const std::string er = normalize_key(expected_role);
    const std::string rr = normalize_key(role);
    const std::string hh = normalize_key(header_text);

    auto has = [](const std::string& haystack, const char* needle) {
        return haystack.find(needle) != std::string::npos;
    };

    // La previsualización epidemiológica no vuelve a expandir el contrato largo
    // de IXIPTLAH. Aquí se proyecta una vista humana mínima por tabla detectada:
    // la identidad enfermedad/CIE-10 vive en el encabezado de tarjeta y los
    // renglones sólo conservan Alcaldía, distribución canónica y valor. Esta
    // compactación es estrictamente visual; los núcleos IXIPTLAH siguen siendo
    // capaces de portar epidemiología y atmósfera con sus metadatos completos.
    if (er == "sem_total" || p == "sem" || p == "semana" || has(p, "sem") || has(hh, "seman")) return "total";

    if (er == "acum_f" || er == "acumulado_f" || er == "acum_femenino" ||
        (has(er, "acum") && (has(er, "_f") || has(er, "fem"))) ||
        (has(rr, "accum") && (has(rr, "female") || has(rr, "femen"))) ||
        ((p == "acum" || has(p, "acum")) && (sx == "f" || sx == "fem" || sx == "femenino" || has(sx, "femen")))) {
        return "acum_F";
    }

    if (er == "acum_m" || er == "acumulado_m" || er == "acum_masculino" ||
        (has(er, "acum") && (has(er, "_m") || has(er, "masc"))) ||
        (has(rr, "accum") && (has(rr, "male") || has(rr, "mascul"))) ||
        ((p == "acum" || has(p, "acum")) && (sx == "m" || sx == "masc" || sx == "masculino" || has(sx, "mascul")))) {
        return "acum_M";
    }

    // Los acumulados totales y el año previo se omiten en esta vista porque el
    // usuario revisa únicamente la tríada operativa total/acum_F/acum_M. No se
    // descartan del flujo analítico ni de escritura persistente.
    return {};
}

std::string preview_distribution_label(const Observation& o) {
    return preview_distribution_label_from_parts(o.period, o.sex, {}, {}, {});
}

std::string preview_distribution_label(const ColumnBand& c) {
    return preview_distribution_label_from_parts(c.period, c.sex, c.expected_role, c.role, c.header_text);
}

int preview_distribution_rank(const std::string& distribution) {
    if (distribution == "total") return 0;
    if (distribution == "acum_F") return 1;
    if (distribution == "acum_M") return 2;
    return 99;
}

unsigned preview_distribution_bit(const std::string& distribution) {
    if (distribution == "total") return 1u << 0;
    if (distribution == "acum_F") return 1u << 1;
    if (distribution == "acum_M") return 1u << 2;
    return 0u;
}

const char* preview_distribution_compact_header() {
    // Cabecera compacta para que la columna semántica no le robe espacio a la
    // alcaldía. El contenido de celda conserva total/acum_F/acum_M; sólo el
    // rótulo se acorta porque la identidad de enfermedad/CIE-10 ya vive arriba.
    return "dist.";
}

std::string preview_distribution_cell_text(const std::string& distribution) {
    // Celda mínima: la semántica completa sigue siendo total/acum_F/acum_M y se
    // conserva en row.distribution/tooltip, pero el glifo visible usa tres marcas
    // inequívocas para que valor y alcaldía no se empalmen en tarjetas de 0.372.
    if (distribution == "total") return "T";
    if (distribution == "acum_F") return "F";
    if (distribution == "acum_M") return "M";
    return compact_label(distribution, 3);
}

std::vector<PreviewDiseaseTable> build_preview_disease_tables(const ExtractionPreview& p) {
    std::unordered_map<std::string, int> jurisdiction_rank;
    jurisdiction_rank.reserve(p.rows.size() * 2 + 8);
    for (size_t i = 0; i < p.rows.size(); ++i) {
        const std::string k = normalize_key(p.rows[i].jurisdiction);
        if (!k.empty() && jurisdiction_rank.find(k) == jurisdiction_rank.end()) {
            jurisdiction_rank.emplace(k, static_cast<int>(i));
        }
    }

    std::unordered_map<std::string, size_t> disease_index;
    disease_index.reserve(p.accepted.size() / 8 + p.columns.size() / 3 + 8);
    std::vector<PreviewDiseaseTable> tables;
    std::vector<std::unordered_map<std::string, size_t>> row_slot_by_table;

    const auto disease_key_from_parts = [](const std::string& disease_id, const std::string& disease, const std::string& cie10) {
        const std::string id = normalize_key(disease_id);
        if (!id.empty() && id != "unknown" && id != "desconocido") return id;
        return normalize_key(disease + "|" + cie10);
    };

    auto ensure_table = [&](const std::string& disease_id,
                            const std::string& disease,
                            const std::string& cie10,
                            int column_index,
                            int accepted_rank) -> size_t {
        std::string key = disease_key_from_parts(disease_id, disease, cie10);
        if (key.empty()) key = "enfermedad_" + std::to_string(tables.size() + 1);

        auto it = disease_index.find(key);
        if (it == disease_index.end()) {
            PreviewDiseaseTable table;
            table.key = key;
            table.disease = preview_identity_or_fallback(disease, "Enfermedad no resuelta");
            table.cie10 = preview_identity_or_fallback(cie10, "CIE-10 no resuelto");
            table.first_column_index = column_index >= 0 ? column_index : 1000000;
            table.first_accepted_rank = accepted_rank >= 0 ? accepted_rank : 1000000;
            table.source_order = static_cast<int>(tables.size());
            tables.push_back(std::move(table));
            row_slot_by_table.emplace_back();
            const size_t pos = tables.size() - 1;
            disease_index.emplace(key, pos);
            return pos;
        }

        PreviewDiseaseTable& table = tables[it->second];
        if (!preview_text_is_resolved_identity(table.disease) && preview_text_is_resolved_identity(disease)) table.disease = trim(disease);
        if (!preview_text_is_resolved_identity(table.cie10) && preview_text_is_resolved_identity(cie10)) table.cie10 = trim(cie10);
        if (column_index >= 0) table.first_column_index = std::min(table.first_column_index, column_index);
        if (accepted_rank >= 0) table.first_accepted_rank = std::min(table.first_accepted_rank, accepted_rank);
        return it->second;
    };

    // Se registra primero cada encabezado de enfermedad observado en las bandas
    // de columna. Así la fila de revisión muestra dos, tres o más tablas de la
    // página aunque la materialización de valores todavía esté parcialmente en
    // cuarentena. Las columnas Acum_total/año previo permanecen fuera de esta
    // proyección, porque no pertenecen al contrato visual solicitado.
    for (const auto& c : p.columns) {
        const std::string distribution = preview_distribution_label(c);
        if (distribution.empty()) continue;
        const size_t pos = ensure_table(c.disease_id, c.disease, c.cie10, c.index, -1);
        tables[pos].detected_column_count += 1;
        tables[pos].distribution_mask |= preview_distribution_bit(distribution);
    }

    int source_rank = 0;
    for (const auto& o : p.accepted) {
        const std::string distribution = preview_distribution_label(o);
        if (distribution.empty()) continue;

        const size_t pos = ensure_table(o.disease_id, o.disease, o.cie10, -1, source_rank);
        tables[pos].distribution_mask |= preview_distribution_bit(distribution);

        PreviewDistributionRow row;
        row.obs = &o;
        row.distribution = distribution;
        row.distribution_rank = preview_distribution_rank(distribution);
        const std::string jr = normalize_key(o.jurisdiction);
        auto rank_it = jurisdiction_rank.find(jr);
        row.jurisdiction_rank = rank_it == jurisdiction_rank.end() ? 1000000 + source_rank : rank_it->second;
        row.source_rank = source_rank;

        const std::string row_key = jr + "|" + distribution;
        auto& row_slots = row_slot_by_table[pos];
        auto slot_it = row_slots.find(row_key);
        if (slot_it == row_slots.end()) {
            row_slots.emplace(row_key, tables[pos].rows.size());
            tables[pos].rows.push_back(row);
        } else {
            PreviewDistributionRow& previous = tables[pos].rows[slot_it->second];
            const double prev_conf = previous.obs ? previous.obs->confidence : -1.0;
            const double next_conf = row.obs ? row.obs->confidence : -1.0;
            if (next_conf > prev_conf) previous = row;
        }
        ++source_rank;
    }

    for (auto& table : tables) {
        if (!preview_text_is_resolved_identity(table.disease)) table.disease = "Enfermedad no resuelta";
        if (!preview_text_is_resolved_identity(table.cie10)) table.cie10 = "CIE-10 no resuelto";
        std::stable_sort(table.rows.begin(), table.rows.end(), [](const PreviewDistributionRow& a, const PreviewDistributionRow& b) {
            if (a.jurisdiction_rank != b.jurisdiction_rank) return a.jurisdiction_rank < b.jurisdiction_rank;
            if (a.distribution_rank != b.distribution_rank) return a.distribution_rank < b.distribution_rank;
            return a.source_rank < b.source_rank;
        });
    }

    std::stable_sort(tables.begin(), tables.end(), [](const PreviewDiseaseTable& a, const PreviewDiseaseTable& b) {
        if (a.first_column_index != b.first_column_index) return a.first_column_index < b.first_column_index;
        if (a.first_accepted_rank != b.first_accepted_rank) return a.first_accepted_rank < b.first_accepted_rank;
        return a.source_order < b.source_order;
    });

    return tables;
}

void draw_preview_card_background(float height) {
    ImDrawList* dl = ImGui::GetWindowDrawList();
    const ImVec2 a = ImGui::GetCursorScreenPos();
    const float w = std::max(1.0f, ImGui::GetContentRegionAvail().x);
    const ImVec2 b(a.x + w, a.y + height);
    dl->AddRectFilled(a, b, preview_card_background_col(), 8.0f);
    dl->AddRect(a, b, preview_card_border_col(), 8.0f, 0, 1.0f);
}

void commit_manual_preview_card_extent(const ImVec2& origin, float height) {
    (void)origin;
    (void)height;
    // Obsoleto deliberadamente: se conserva como ancla histórica para evitar
    // reintroducir el patrón problemático SetCursorScreenPos(+alto). Las
    // tarjetas nuevas avanzan sólo con ítems secuenciales reales.
}

void seal_preview_card_extent_with_real_item(const ImVec2& origin, float required_height) {
    // Dear ImGui sólo considera válido el tamaño de contenido cuando existe un
    // ítem real que lo respalda. Este sello jamás mueve el cursor de forma
    // absoluta: agrega un Dummy mínimo si el contenido visible fue más bajo que
    // la tarjeta reservada. Con ello las tarjetas mantienen altura exacta dentro
    // de celdas/children estrechos sin depender de SetCursorPos/SetCursorScreenPos
    // ni de efectos colaterales obsoletos de CursorMaxPos.
    const float used = ImGui::GetCursorScreenPos().y - origin.y;
    const float missing = required_height - used;
    if (missing > 0.5f) ImGui::Dummy(ImVec2(1.0f, missing));
}

void draw_epidemiology_table_card(const PreviewDiseaseTable& table, float height, const ImVec4& accent, int index) {
    const float safe_h = std::max(150.0f, height);
    const ImVec2 origin = ImGui::GetCursorScreenPos();
    const float w = std::max(1.0f, ImGui::GetContentRegionAvail().x);
    ImDrawList* dl = ImGui::GetWindowDrawList();

    // Tarjeta uniforme: todas las enfermedades reservan exactamente el mismo
    // bloque de título, subcódigo CIE-10, regla magenta y tabla. No hay scroll
    // vertical persistente dentro de la tarjeta: el error visual donde la primera
    // tabla reaparecía desplazada a mitad de alcaldías venía de estados de scroll
    // heredados por ID. La previsualización debe mostrar el mismo origen lógico
    // en cada tarjeta; la lectura completa queda en IXIPTLAH, no en este widget.
    draw_preview_card_background(safe_h);

    ImGui::PushID(index);
    const float pad_x = std::clamp(w * kGoldenN8, 2.0f, 4.0f);
    const float top_pad = std::clamp(safe_h * kGoldenN10, 2.0f, 4.0f);
    const float bottom_pad = std::clamp(safe_h * kGoldenN10, 2.0f, 4.0f);
    const float inner_w = std::max(1.0f, w - pad_x * 2.0f);
    const float text_h = ImGui::GetTextLineHeight();
    const float header_gap = 2.0f;

    ImGui::Dummy(ImVec2(1.0f, top_pad));
    ImGui::Indent(pad_x);

    // Una sola línea por identidad. El recorte lo aporta el child/clip rect de
    // ImGui; no se usa wrap porque títulos largos no deben empujar hacia abajo
    // sólo una tarjeta y desalinearla con sus vecinas.
    ImGui::PushStyleColor(ImGuiCol_Text, preview_main_text_col());
    ImGui::TextUnformatted(table.disease.c_str());
    if (ImGui::IsItemHovered() && table.disease.size() > 24) ImGui::SetTooltip("%s", table.disease.c_str());
    ImGui::PopStyleColor();
    ImGui::PushStyleColor(ImGuiCol_Text, preview_soft_text_col());
    ImGui::TextUnformatted(table.cie10.c_str());
    if (ImGui::IsItemHovered() && table.cie10.size() > 12) ImGui::SetTooltip("%s", table.cie10.c_str());
    ImGui::PopStyleColor();

    const ImVec2 line_a = ImGui::GetCursorScreenPos();
    dl->AddRectFilled(ImVec2(line_a.x, line_a.y + 1.0f),
                      ImVec2(line_a.x + inner_w, line_a.y + 3.0f), u32(accent, 0.72f), 1.0f);
    ImGui::Dummy(ImVec2(inner_w, 5.0f));

    const float table_h = std::max(42.0f, origin.y + safe_h - ImGui::GetCursorScreenPos().y - bottom_pad);
    const bool table_region_valid = inner_w >= 44.0f && table_h >= 38.0f;

    ImGui::PushStyleVar(ImGuiStyleVar_CellPadding, ImVec2(1.0f, 1.3f));
    ImGui::PushStyleColor(ImGuiCol_Text, preview_main_text_col());
    ImGui::PushStyleColor(ImGuiCol_TableHeaderBg, preview_table_header_col());
    ImGui::PushStyleColor(ImGuiCol_TableRowBg, preview_card_background_col());
    ImGui::PushStyleColor(ImGuiCol_TableRowBgAlt, preview_table_alt_col());

    // Cotas ultracompactas: cuatro tarjetas conviven dentro de la banda 0.372.
    // La distribución visible usa T/F/M y el valor queda en columna numérica fija;
    // la alcaldía absorbe todo el excedente, evitando que "acum" y el valor se
    // fusionen visualmente como si fueran una sola celda.
    const float value_w = std::clamp(inner_w * kGoldenN9, 18.0f, 24.0f);
    const float distribution_w = std::clamp(inner_w * kGoldenN11, 10.0f, 13.0f);

    if (table_region_valid) {
        ImGui::BeginChild("epidemiologia-preview-body-no-persistent-scroll", ImVec2(inner_w, table_h), false,
                          ImGuiWindowFlags_NoScrollbar | ImGuiWindowFlags_NoScrollWithMouse | ImGuiWindowFlags_NoSavedSettings);
        // Cada frame se fija el origen visible de la tarjeta. Al no haber scroll
        // propio, la primera tabla y las siguientes siempre empiezan por la misma
        // fila canónica, aunque el usuario haya girado la rueda sobre una tarjeta
        // en un frame anterior.
        ImGui::SetScrollY(0.0f);
        if (ImGui::BeginTable("epidemiologia-preview-compacta", 3,
                              ImGuiTableFlags_RowBg | ImGuiTableFlags_SizingStretchProp | ImGuiTableFlags_NoSavedSettings,
                              ImVec2(inner_w, 0.0f))) {
            ImGui::TableSetupColumn("Alcaldía", ImGuiTableColumnFlags_WidthStretch, 1.0f);
            ImGui::TableSetupColumn("d", ImGuiTableColumnFlags_WidthFixed, distribution_w);
            ImGui::TableSetupColumn("v", ImGuiTableColumnFlags_WidthFixed, value_w);
            ImGui::TableHeadersRow();

            const float row_px = std::max(1.0f, ImGui::GetTextLineHeightWithSpacing());
            const int max_visible_rows = std::max(1, static_cast<int>(std::floor((table_h - text_h - header_gap) / row_px)));
            const int row_count = static_cast<int>(table.rows.size());
            const int draw_count = std::min(row_count, max_visible_rows);

            if (row_count <= 0) {
                ImGui::TableNextRow();
                ImGui::TableSetColumnIndex(0);
                ImGui::TextDisabled("Sin valores aceptados");
                ImGui::TableSetColumnIndex(1);
                ImGui::TextDisabled("-");
                ImGui::TableSetColumnIndex(2);
                ImGui::TextDisabled("-");
            } else {
                for (int ri = 0; ri < draw_count; ++ri) {
                    const PreviewDistributionRow& row = table.rows[static_cast<size_t>(ri)];
                    if (!row.obs) continue;
                    ImGui::TableNextRow();
                    ImGui::TableSetColumnIndex(0);
                    ImGui::TextUnformatted(row.obs->jurisdiction.c_str());
                    if (ImGui::IsItemHovered()) ImGui::SetTooltip("%s", row.obs->jurisdiction.c_str());
                    ImGui::TableSetColumnIndex(1);
                    const std::string compact_distribution = preview_distribution_cell_text(row.distribution);
                    ImGui::TextUnformatted(compact_distribution.c_str());
                    if (ImGui::IsItemHovered()) ImGui::SetTooltip("%s", row.distribution.c_str());
                    ImGui::TableSetColumnIndex(2);
                    ImGui::Text("%lld", static_cast<long long>(row.obs->value));
                }
                if (draw_count < row_count && draw_count < max_visible_rows) {
                    ImGui::TableNextRow();
                    ImGui::TableSetColumnIndex(0);
                    ImGui::TextDisabled("...");
                    ImGui::TableSetColumnIndex(1);
                    ImGui::TextDisabled("+");
                    ImGui::TableSetColumnIndex(2);
                    ImGui::TextDisabled("%d", row_count - draw_count);
                }
            }
            ImGui::EndTable();
        }
        ImGui::EndChild();
    } else {
        ImGui::TextDisabled("Vista demasiado estrecha");
    }

    ImGui::PopStyleColor(4);
    ImGui::PopStyleVar();
    ImGui::Unindent(pad_x);
    seal_preview_card_extent_with_real_item(origin, safe_h);
    ImGui::PopID();
}

void draw_empty_epidemiology_table_card(const ExtractionPreview& p, float height, const ImVec4& accent) {
    const float safe_h = std::max(150.0f, height);
    const ImVec2 origin = ImGui::GetCursorScreenPos();
    const float w = std::max(1.0f, ImGui::GetContentRegionAvail().x);
    ImDrawList* dl = ImGui::GetWindowDrawList();
    draw_preview_card_background(safe_h);

    const float pad_x = std::clamp(w * kGoldenN8, 3.0f, 6.0f);
    ImGui::Dummy(ImVec2(1.0f, std::clamp(safe_h * kGoldenN10, 3.0f, 5.0f)));
    ImGui::Indent(pad_x);
    ImGui::PushStyleColor(ImGuiCol_Text, preview_main_text_col());
    ImGui::TextUnformatted(p.quarantine.empty() ? "Esperando tabla validada" : "Columnas en cuarentena");
    ImGui::PopStyleColor();
    ImGui::TextDisabled("Sin encabezados epidemiológicos verificables.");
    const ImVec2 line_a = ImGui::GetCursorScreenPos();
    dl->AddRectFilled(ImVec2(line_a.x, line_a.y + 2.0f),
                      ImVec2(origin.x + w - pad_x, line_a.y + 4.0f), u32(accent, 0.48f), 1.0f);
    ImGui::Dummy(ImVec2(std::max(1.0f, w - pad_x * 2.0f), 8.0f));
    int count = 0;
    for (const auto& q : p.quarantine) {
        if (count++ >= 8) break;
        ImGui::TextWrapped("%s: %s", q.reason.c_str(), q.detail.c_str());
    }
    ImGui::Unindent(pad_x);
    seal_preview_card_extent_with_real_item(origin, safe_h);
}



void draw_excel_build_preview(const PipelineStats& stats, const ExtractionPreview& p, const fs::path& out) {

    ImGui::Text("Base larga: %lld observaciones aceptadas", static_cast<long long>(stats.observations_accepted));

    ImGui::Text("Cuarentena: %lld elementos", static_cast<long long>(stats.quarantine_items));

    ImGui::Text("Tablas detectadas: %d", stats.tables_detected);

    ImGui::Separator();

    ImGui::TextUnformatted("Excel maestro");


    ImGui::BulletText("Archivo: %s", path_utf8(out / "HistorialEpidemiologicoCDMX_generado.xlsx").c_str());


    ImGui::BulletText("Colores: grupos epidemiologicos + max/min por enfermedad");

    ImGui::BulletText("Ultima pagina aceptada: %d filas, %d columnas", static_cast<int>(p.rows.size()), static_cast<int>(p.columns.size()));

    if (!p.quarantine.empty()) {

        ImGui::Separator();

        ImGui::TextUnformatted("Ultima cuarentena");
        int count = 0;

        for (const auto& q : p.quarantine) {

            if (count++ >= 5) break;

            ImGui::BulletText("%s: %s", q.reason.c_str(), q.detail.c_str());
        }
    }
}



std::pair<int, int> infer_year_week_label(const std::string& name) {
    int year = 0;
    int week = 0;
    if (ozmvm_year_week_label(name.data(), name.size(), &year, &week)) return {year, week};

    return {0, 0};
}




void accent_progress_bar(float fraction, const ImVec2& size, const char* overlay, const ImVec4& accent) {
    const float pct = std::clamp(fraction, 0.0f, 1.0f);

    const float avail = std::max(1.0f, ImGui::GetContentRegionAvail().x);
    const float w = size.x < 0.0f ? avail : (size.x > 0.0f ? size.x : avail);
    const float h = size.y > 0.0f ? size.y : 3.0f;

    const ImVec2 p = ImGui::GetCursorScreenPos();

    ImDrawList* dl = ImGui::GetWindowDrawList();
    const ImVec2 a(p.x, p.y);
    const ImVec2 b(p.x + w, p.y + h);
    dl->AddRectFilled(a, b, IM_COL32(224, 230, 238, 188), h * 0.5f);

    if (pct > 0.0f) dl->AddRectFilled(a, ImVec2(a.x + w * pct, b.y), u32(accent, 0.76f), h * 0.5f);

    ImGui::Dummy(ImVec2(w, h + 1.0f));

    if (overlay && overlay[0] && h >= 12.0f) {

        const ImVec2 ts = ImGui::CalcTextSize(overlay);

        dl->AddText(ImVec2(a.x + std::max(5.0f, (w - ts.x) * 0.5f), a.y + std::max(0.0f, (h - ts.y) * 0.5f)),
                    IM_COL32(75, 84, 96, 210), overlay);
    }
}





struct ImportProgressEdgeState {
    bool visible = false;
    float fraction = 0.0f;
    std::string label;
};




ImportProgressEdgeState import_progress_edge_state(const UiState& ui, const PipelineStats& stats, const ExtractionPreview& preview) {
    ImportProgressEdgeState r;
    const bool pipeline_visible = ui.running.load() || stats.progress > 0.001 || !stats.current_pdf.empty() ||


                                  !preview.pdf_file.empty() || stats.observations_accepted > 0 || stats.quarantine_items > 0;

    if (pipeline_visible) {
        r.visible = true;

        r.fraction = static_cast<float>(std::clamp(stats.progress, 0.0, 1.0));

        if (ui.running.load()) r.fraction = std::min(r.fraction, 0.985f);


        r.label = stats.status.empty() ? "Procesando PDF epidemiologico" : stats.status;

        return r;
    }


    if (ui.satellite_importing || ui.satellite_import_progress > 0.001f) {
        r.visible = true;
        r.fraction = std::clamp(ui.satellite_import_progress, 0.0f, 1.0f);


        r.label = ui.satellite_import_status.empty() ? "Procesando IXIPTLAH satelital elemental IXIPTLAH" : ui.satellite_import_status;

        return r;
    }


    if (ui.external_importing || ui.external_import_progress > 0.001f) {
        r.visible = true;
        r.fraction = std::clamp(ui.external_import_progress, 0.0f, 1.0f);

        r.label = ui.external_import_status.empty() ? "Indexando inventario de datos multifuente" : ui.external_import_status;

        return r;
    }


    if (ui.atmosphere_importing || ui.atmosphere_import_progress > 0.001f) {
        r.visible = true;


        r.fraction = std::clamp(ui.atmosphere_import_progress, 0.0f, 1.0f);
        r.label = ui.atmosphere_import_status.empty() ? "Procesando RAMA/REDMET" : ui.atmosphere_import_status;

        return r;
    }


    if (ui.epi_downloading || ui.epi_download_progress > 0.001f) {
        r.visible = true;


        r.fraction = std::clamp(ui.epi_download_progress, 0.0f, 1.0f);


        r.label = ui.epi_download_phase.empty() ? "Descargando boletines epidemiologicos" : ui.epi_download_phase;

        return r;
    }


    if (ui.mobility_downloading || ui.mobility_download_progress > 0.001f) {
        r.visible = true;


        r.fraction = std::clamp(ui.mobility_download_progress, 0.0f, 1.0f);


        r.label = ui.mobility_download_phase.empty() ? "Actualizando movilidad" : ui.mobility_download_phase;

        return r;
    }

    return r;
}






float tlalpowa_import_track_visual_thickness();

void accent_progress_bar_exact_no_intrinsic_gap(float fraction, const ImVec2& size, const char* overlay, const ImVec4& accent, bool live_pulse = false) {
    
    const float pct = std::clamp(fraction, 0.0f, 1.0f);
    const float avail = std::max(1.0f, ImGui::GetContentRegionAvail().x);
    const float w = size.x < 0.0f ? avail : (size.x > 0.0f ? size.x : avail);
    const float h = size.y > 0.0f ? size.y : tlalpowa_import_track_visual_thickness();
    const ImVec2 p = ImGui::GetCursorScreenPos();
    ImDrawList* dl = ImGui::GetWindowDrawList();
    const ImVec2 a(p.x, p.y);
    const ImVec2 b(p.x + w, p.y + h);
    dl->AddRectFilled(a, b, IM_COL32(224, 230, 238, 188), h * 0.5f);
    if (pct > 0.0f) dl->AddRectFilled(a, ImVec2(a.x + w * pct, b.y), u32(accent, 0.76f), h * 0.5f);
    if (live_pulse && pct < 0.997f && w > 48.0f) {
        /* Pulso de vida no semántico: sólo evidencia que el hilo sigue reportando/respirando.
           Nunca altera progreso real ni contadores, y evita la ilusión visual de bloqueo en CSV enormes. */
        const double t = ImGui::GetTime();
        const float span = std::clamp(w * 0.118f, 30.0f, 132.0f);
        const float travel = std::max(1.0f, w + span * 2.0f);
        const float head = a.x - span + static_cast<float>(std::fmod(t * 190.0, static_cast<double>(travel)));
        const float x0 = std::clamp(head, a.x, b.x);
        const float x1 = std::clamp(head + span, a.x, b.x);
        if (x1 > x0) dl->AddRectFilled(ImVec2(x0, a.y), ImVec2(x1, b.y), u32(accent, 0.34f), h * 0.5f);
    }
    if (overlay && overlay[0] && h >= 12.0f) {
        const ImVec2 ts = ImGui::CalcTextSize(overlay);
        dl->AddText(ImVec2(a.x + (w - ts.x) * 0.5f, a.y + (h - ts.y) * 0.5f), IM_COL32(255, 255, 255, 236), overlay);
    }
    ImGui::SetCursorScreenPos(ImVec2(p.x, p.y + h));
    ImGui::Dummy(ImVec2(1.0f, 0.1f));
}

void draw_import_top_edge_progress(UiState& ui, const PipelineStats& stats, const ExtractionPreview& preview, const ImVec4& accent) {
    const ImportProgressEdgeState st = import_progress_edge_state(ui, stats, preview);

    if (!st.visible) return;

    const ImVec2 win_pos = ImGui::GetWindowPos();

    const ImVec2 win_size = ImGui::GetWindowSize();

    if (win_size.x <= 2.0f || win_size.y <= 2.0f) return;

    ImDrawList* dl = ImGui::GetForegroundDrawList();
    
    const float h = tlalpowa_import_track_visual_thickness();
    const ImVec2 a(win_pos.x, win_pos.y);
    const ImVec2 b(win_pos.x + win_size.x, win_pos.y + h);
    dl->AddRectFilled(a, b, IM_COL32(228, 234, 242, 205), 0.0f);
    dl->AddRectFilled(a, ImVec2(a.x + (b.x - a.x) * std::clamp(st.fraction, 0.0f, 1.0f), b.y), u32(accent, 0.96f), 0.0f);

    if (ImGui::IsWindowHovered(ImGuiHoveredFlags_RootAndChildWindows) && ImGui::GetIO().MousePos.y <= win_pos.y + 11.0f) {

        ImGui::SetTooltip("%3.0f%% | %s", std::clamp(st.fraction, 0.0f, 1.0f) * 100.0f, st.label.c_str());
    }
}



