bool import_template_combo(const char* id, int& current, const char* const* items, int count, float width, const ImVec4& accent, bool light) {
    /*
     * Plantilla centralizada para menús de Importar.  Proscribe Combo()
     * directo en esta ventana: el menú cerrado y cada elemento desplegado
     * deben conservar el mismo alto, radio y padding que botones/cajas.
     */
    if (!items || count <= 0) return false;
    current = std::clamp(current, 0, count - 1);
    ImGui::SetNextItemWidth(std::max(1.0f, width));
    bool changed = false;
    ImGui::PushStyleVar(ImGuiStyleVar_FrameRounding, golden_tab_rounding());
    ImGui::PushStyleVar(ImGuiStyleVar_FramePadding, ImVec2(golden_tab_frame_pad_x(), golden_tab_frame_pad_y()));
    if (ImGui::BeginCombo(id, items[current])) {
        ImGui::PushStyleVar(ImGuiStyleVar_ItemSpacing, ImVec2(0.0f, 0.0f));
        for (int i = 0; i < count; ++i) {
            ImGui::PushID(i);
            const bool selected = (i == current);
            if (ImGui::Selectable(items[i], selected, 0, ImVec2(0.0f, tlalpowa_import_control_height()))) {
                current = i;
                changed = true;
            }
            if (selected) ImGui::SetItemDefaultFocus();
            ImGui::PopID();
        }
        ImGui::PopStyleVar();
        ImGui::EndCombo();
    }
    ImGui::PopStyleVar(2);
    (void)accent;
    (void)light;
    return changed;
}





