void draw_import_progress_dialog(UiState& ui, const PipelineStats& stats, const ImVec4& accent) {
    std::deque<std::string> log;
    std::string detail;
    bool active = false;
    bool running_active = false;
    bool epi_active = false;
    bool atmosphere_active = false;
    int epi_attempted = 0, epi_total = 0, epi_ok = 0, epi_skipped = 0;
    int mobility_attempted = 0, mobility_total = 0, mobility_ok = 0;
    int atmosphere_indexed = 0, atmosphere_total_files = 0, atmosphere_detected = 0;
    long long atmosphere_current_rows = 0;
    unsigned long long atmosphere_current_bytes = 0, atmosphere_total_bytes = 0;
    std::string atmosphere_current_file;

    float epi_progress = 0.0f, mobility_progress = 0.0f, atmosphere_progress = 0.0f;
    {


        std::lock_guard<std::mutex> lock(ui.mu);
        log = ui.import_progress_log;
        detail = ui.import_progress_detail;
        running_active = ui.running.load();


        epi_active = ui.epi_downloading;
        atmosphere_active = ui.atmosphere_importing;


        active = epi_active || ui.mobility_downloading || atmosphere_active || running_active || !log.empty();


        epi_attempted = ui.epi_download_attempted;


        epi_total = ui.epi_download_total;


        epi_ok = ui.epi_download_ok;


        epi_skipped = ui.epi_download_skipped;


        epi_progress = ui.epi_download_progress;


        mobility_attempted = ui.mobility_download_attempted;


        mobility_total = ui.mobility_download_total;


        mobility_ok = ui.mobility_download_ok;


        mobility_progress = ui.mobility_download_progress;
        atmosphere_progress = ui.atmosphere_import_progress;
        atmosphere_indexed = ui.atmosphere_import_indexed;
        atmosphere_total_files = ui.atmosphere_import_total_files;
        atmosphere_detected = ui.atmosphere_import_detected;
        atmosphere_current_rows = ui.atmosphere_import_current_rows;
        atmosphere_current_bytes = ui.atmosphere_import_current_bytes;
        atmosphere_total_bytes = ui.atmosphere_import_total_bytes;
        atmosphere_current_file = ui.atmosphere_import_current_file;
    }

    if (!active) return;


    const float w = ImGui::GetContentRegionAvail().x;

    const ImVec2 p = ImGui::GetCursorScreenPos();
    const float h = std::min(190.0f, std::max(92.0f, 72.0f + static_cast<float>(std::min<size_t>(log.size(), 6)) * 16.0f));

    ImDrawList* dl = ImGui::GetWindowDrawList();

    dl->AddRectFilled(p, ImVec2(p.x + w, p.y + h), IM_COL32(247, 250, 254, 226), 10.0f);
    dl->AddRectFilled(ImVec2(p.x, p.y), ImVec2(p.x + w, p.y + 2.0f), u32(accent, 0.40f), 1.0f);

    ImGui::SetCursorScreenPos(ImVec2(p.x + 10.0f, p.y + 8.0f));

    ImGui::TextDisabled("Progreso detallado");

    ImGui::SameLine();

    ImGui::TextDisabled("· %s", detail.empty() ? "en espera" : detail.c_str());
    const float bar_w = std::max(120.0f, w - 20.0f);

    ImGui::SetCursorScreenPos(ImVec2(p.x + 10.0f, p.y + 30.0f));

    const float combined = running_active ? static_cast<float>(std::clamp(stats.progress, 0.0, 1.0)) :
                           (epi_active ? epi_progress : (atmosphere_active ? atmosphere_progress : mobility_progress));
    accent_progress_bar(combined, ImVec2(bar_w, 3.0f), nullptr, accent);

    ImGui::SetCursorScreenPos(ImVec2(p.x + 10.0f, p.y + 40.0f));


    if (atmosphere_active || atmosphere_progress > 0.001f) {
        auto compact_bytes = [](unsigned long long bytes) {
            const char* units[] = {"B", "KB", "MB", "GB"};
            double v = static_cast<double>(bytes);
            int unit = 0;
            while (v >= 1024.0 && unit < 3) { v /= 1024.0; ++unit; }
            std::ostringstream os;
            if (unit == 0) os << bytes << units[unit];
            else os << std::fixed << std::setprecision(v >= 100.0 ? 0 : 1) << v << units[unit];
            return os.str();
        };
        const int total = std::max({1, atmosphere_total_files, atmosphere_detected});
        ImGui::TextDisabled("Atm %d/%d archivos · %lld filas actuales · %s/%s · %s",
                            atmosphere_indexed, total, atmosphere_current_rows,
                            compact_bytes(atmosphere_current_bytes).c_str(),
                            compact_bytes(atmosphere_total_bytes).c_str(),
                            compact_label(atmosphere_current_file, 60).c_str());
    } else {
        ImGui::TextDisabled("PDF %d/%d · páginas %d · Epi %d/%d válidos %d omitidos %d · Mov %d/%d válidos %d",
                            stats.pdf_done, stats.pdf_total, stats.pages_done,
                            epi_attempted, epi_total, epi_ok, epi_skipped,
                            mobility_attempted, mobility_total, mobility_ok);
    }

    ImGui::SetCursorScreenPos(ImVec2(p.x + 10.0f, p.y + 60.0f));


    ImGui::BeginChild("##import_progress_log", ImVec2(bar_w, std::max(24.0f, h - 68.0f)), false,
                      ImGuiWindowFlags_NoScrollbar | ImGuiWindowFlags_NoSavedSettings);

    if (log.empty()) {

        ImGui::TextDisabled("Sin eventos recientes.");
    } else {
        const size_t first = log.size() > 10 ? log.size() - 10 : 0;

        for (size_t i = first; i < log.size(); ++i) ImGui::TextDisabled("%s", log[i].c_str());
    }

    ImGui::EndChild();

    ImGui::SetCursorScreenPos(ImVec2(p.x, p.y + h + 7.0f));
    ImGui::Dummy(ImVec2(1.0f, 0.1f));
}




void terminate_windows_process_tree(unsigned long root_pid, unsigned int exit_code) {
#ifdef _WIN32


    if (root_pid == 0) return;
    const DWORD root = static_cast<DWORD>(root_pid);

    std::vector<DWORD> children;

    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);

    if (snap != INVALID_HANDLE_VALUE) {


        PROCESSENTRY32W pe{};
        pe.dwSize = sizeof(pe);


        if (Process32FirstW(snap, &pe)) {

            do {


                if (pe.th32ParentProcessID == root) children.push_back(pe.th32ProcessID);
            } while (Process32NextW(snap, &pe));
        }
        CloseHandle(snap);
    }




    for (DWORD child : children) terminate_windows_process_tree(child, exit_code);
    HANDLE h = OpenProcess(PROCESS_TERMINATE | SYNCHRONIZE, FALSE, root);

    if (!h) return;

    TerminateProcess(h, static_cast<UINT>(exit_code));
    WaitForSingleObject(h, 900);
    CloseHandle(h);
#else

    (void)root_pid;
    (void)exit_code;
#endif
}




void terminate_import_child_now(UiState& ui, unsigned int exit_code = 130) {
#ifdef _WIN32


    const unsigned long pid = ui.import_child_pid.load(std::memory_order_relaxed);


    if (pid == 0) return;
    terminate_windows_process_tree(pid, exit_code);
#else
    (void)ui;
    (void)exit_code;
#endif
}




void clear_epidemiology_runtime_view(UiState& ui, bool clear_loaded_observations) {


    std::lock_guard<std::mutex> lock(ui.mu);
    ui.stats = PipelineStats{};
    ui.preview = ExtractionPreview{};

    ui.last_output = epidemiology_output_root();

    if (clear_loaded_observations) {

        ui.observations.clear();
        ui.observations.shrink_to_fit();
        ui.observations_ptr.reset();

        ui.weeks.clear();

        ui.week_start = 0;

        ui.week_end = 0;

        ui.selected_week = 0;
        ui.observations_revision.fetch_add(1, std::memory_order_relaxed);
    }
}















