void draw_window_progress(UiState& ui, const PipelineStats& stats, const ExtractionPreview& preview, const ImVec4& accent) {
    const bool has_visible_work = ui.running.load() || stats.progress > 0.001 || !stats.current_pdf.empty() ||


                                  !preview.pdf_file.empty() || stats.observations_accepted > 0 || stats.quarantine_items > 0;

    if (!has_visible_work) {

        ImGui::Dummy(ImVec2(1.0f, 2.0f));

        return;
    }


    ImGui::PushStyleVar(ImGuiStyleVar_FramePadding, ImVec2(golden_tab_frame_pad_x(), golden_tab_frame_pad_y()));

    if (ui.running.load()) {

        if (golden_small_button("R")) request_restart_pipeline(ui);

        if (ImGui::IsItemHovered()) ImGui::SetTooltip("Reiniciar procesamiento desde cero");

        ImGui::SameLine(0.0f, std::max(1.0f, golden_w(kGoldenN12)));

        if (golden_small_button("II")) {
            tlalpowa_request_immediate_pause(ui, "Pausa inmediata solicitada desde barra compacta.");
        }

        if (ImGui::IsItemHovered()) ImGui::SetTooltip("Pausar de forma segura: cerrar IXIPTLAH, recargar y reanudar despues sin lectura viva");

        ImGui::SameLine(0.0f, std::max(1.0f, golden_w(kGoldenN12)));

        if (golden_small_button("Stop")) request_stop_pipeline_keep_window(ui);

        if (ImGui::IsItemHovered()) ImGui::SetTooltip("Detener proceso actual sin cerrar esta ventana");

        ImGui::SameLine(0.0f, std::max(1.0f, golden_w(kGoldenN12)));

        ImGui::PushStyleColor(ImGuiCol_Button, ImVec4(0.82f, 0.10f, 0.12f, 0.92f));

        ImGui::PushStyleColor(ImGuiCol_ButtonHovered, ImVec4(0.96f, 0.14f, 0.16f, 0.96f));

        ImGui::PushStyleColor(ImGuiCol_ButtonActive, ImVec4(0.62f, 0.06f, 0.08f, 1.0f));


        if (golden_small_button("X")) request_force_close_import_window(ui);


        if (ImGui::IsItemHovered()) ImGui::SetTooltip("Cancelar y volver a estado basal sin cerrar esta ventana");

        ImGui::PopStyleColor(3);

        ImGui::SameLine(0.0f, 8.0f);
    }

    ImGui::PopStyleVar();



    const std::string file = compact_label(preview.pdf_file.empty() ? stats.current_pdf : preview.pdf_file, 58);
    const int cur = std::max({1, stats.pages_done, stats.detail_done});
    int total = std::max({1, cur, stats.pages_total, stats.detail_total});

    if (ui.running.load() && cur >= total) total = cur + 1;

    const float pct = static_cast<float>(std::clamp(stats.progress, 0.0, 1.0));

    ImGui::TextDisabled("%3.0f%% · proceso %d/%d · %s · aceptados %lld · cuarentena %lld",

                        pct * 100.0f, cur, total, file.c_str(),

                        static_cast<long long>(stats.observations_accepted),

                        static_cast<long long>(stats.quarantine_items));

    ImGui::Dummy(ImVec2(1.0f, 2.0f));
    (void)accent;
}



struct ImportCompactHeaderSnapshot {
    float fraction = 0.0f;
    std::string header;
    std::string detail_a;
    std::string detail_b;
};





ImportCompactHeaderSnapshot build_import_compact_header_snapshot(UiState& ui, const PipelineStats& stats, const ExtractionPreview& preview, const std::string& context_detail) {
    ImportCompactHeaderSnapshot h;
    std::string log_detail;
    std::string epi_phase;
    std::string epi_status;
    std::string mobility_phase;
    std::string mobility_status;
    std::string atmosphere_status;
    std::string satellite_status;

    std::string external_status;
    bool running = ui.running.load();
    bool epi_active = false;
    bool mobility_active = false;
    bool atmosphere_active = false;
    bool satellite_active = false;

    bool external_active = false;

    int epi_attempted = 0, epi_total = 0, epi_ok = 0, epi_skipped = 0;
    int mobility_attempted = 0, mobility_total = 0, mobility_ok = 0;
    int atmosphere_detected = 0, atmosphere_indexed = 0, atmosphere_cloud_points = 0, atmosphere_total_files = 0;
    long long atmosphere_current_rows = 0;
    unsigned long long atmosphere_current_bytes = 0, atmosphere_total_bytes = 0;
    std::string atmosphere_current_file;
    int satellite_detected = 0, satellite_indexed = 0;

    int external_detected = 0, external_indexed = 0;
    float epi_progress = 0.0f, mobility_progress = 0.0f, atmosphere_progress = 0.0f, satellite_progress = 0.0f, external_progress = 0.0f;
    {


        std::lock_guard<std::mutex> lock(ui.mu);
        log_detail = ui.import_progress_detail;


        epi_phase = ui.epi_download_phase;
        epi_status = ui.epi_status;


        mobility_phase = ui.mobility_download_phase;
        mobility_status = ui.mobility_status;
        atmosphere_status = ui.atmosphere_import_status;

        satellite_status = ui.satellite_import_status;
        external_status = ui.external_import_status;


        epi_active = ui.epi_downloading;


        mobility_active = ui.mobility_downloading;
        atmosphere_active = ui.atmosphere_importing;
        satellite_active = ui.satellite_importing;

        external_active = ui.external_importing;


        epi_attempted = ui.epi_download_attempted;


        epi_total = ui.epi_download_total;


        epi_ok = ui.epi_download_ok;


        epi_skipped = ui.epi_download_skipped;


        epi_progress = ui.epi_download_progress;


        mobility_attempted = ui.mobility_download_attempted;


        mobility_total = ui.mobility_download_total;


        mobility_ok = ui.mobility_download_ok;


        mobility_progress = ui.mobility_download_progress;
        atmosphere_progress = ui.atmosphere_import_progress;
        atmosphere_detected = ui.atmosphere_import_detected;

        atmosphere_indexed = ui.atmosphere_import_indexed;
        atmosphere_total_files = ui.atmosphere_import_total_files;
        atmosphere_current_rows = ui.atmosphere_import_current_rows;
        atmosphere_current_bytes = ui.atmosphere_import_current_bytes;
        atmosphere_total_bytes = ui.atmosphere_import_total_bytes;
        atmosphere_current_file = ui.atmosphere_import_current_file;
        atmosphere_cloud_points = ui.atmosphere_import_cloud_points;


        satellite_progress = ui.satellite_import_progress;
        satellite_detected = ui.satellite_import_detected;
        satellite_indexed = ui.satellite_import_indexed;

        external_progress = ui.external_import_progress;
        external_detected = ui.external_import_detected;
        external_indexed = ui.external_import_indexed;
    }


    if (running) {

        h.fraction = static_cast<float>(std::clamp(stats.progress, 0.0, 1.0));


        const std::string file = compact_label(preview.pdf_file.empty() ? stats.current_pdf : preview.pdf_file, 68);


        h.header = "Compilando .ixiptlah epidemiologico";

        if (!file.empty()) h.header += " · " + file;


    } else if (epi_active || epi_progress > 0.001f) {
        h.fraction = std::clamp(epi_progress, 0.0f, 1.0f);
        h.header = "Descarga documental epidemiologica oficial";

        if (!epi_phase.empty()) h.header += " · " + compact_label(epi_phase, 80);


    } else if (satellite_active || satellite_progress > 0.001f) {




        h.fraction = std::clamp(satellite_progress, 0.0f, 1.0f);


        h.header = "IXIPTLAH satelital elemental IXIPTLAH";

        if (!satellite_status.empty()) h.header += " · " + compact_label(satellite_status, 92);


    } else if (external_active || external_progress > 0.001f) {
        h.fraction = std::clamp(external_progress, 0.0f, 1.0f);
        h.header = "Catálogo de datos multifuente";


        if (!external_status.empty()) h.header += " · " + compact_label(external_status, 92);


    } else if (atmosphere_active || atmosphere_progress > 0.001f) {
        h.fraction = std::clamp(atmosphere_progress, 0.0f, 1.0f);
        h.header = "RAMA/REDMET atmosferico";

        if (!atmosphere_status.empty()) h.header += " · " + compact_label(atmosphere_status, 92);


    } else if (mobility_active || mobility_progress > 0.001f) {
        h.fraction = std::clamp(mobility_progress, 0.0f, 1.0f);
        h.header = "Movilidad oficial";

        if (!mobility_phase.empty()) h.header += " · " + compact_label(mobility_phase, 92);
    } else {
        h.fraction = 0.0f;

        h.header = log_detail.empty() ? "Importador en espera" : ("Ultimo estado · " + compact_label(log_detail, 96));
    }

    std::ostringstream a;

    a << "PDF " << stats.pdf_done << '/' << stats.pdf_total
      << " · paginas " << stats.pages_done

      << " · observaciones " << static_cast<long long>(stats.observations_accepted)

      << " · cuarentena " << static_cast<long long>(stats.quarantine_items)
      << " · epi " << epi_attempted << '/' << epi_total << " validos " << epi_ok << " omitidos " << epi_skipped;
    h.detail_a = a.str();

    std::ostringstream b;

    if (!context_detail.empty()) {
        b << context_detail;


    } else if (mobility_active || mobility_progress > 0.001f) {
        b << "movilidad " << mobility_attempted << '/' << mobility_total << " validos " << mobility_ok << " · descarga paralela validada · " << mobility_status;


    } else if (satellite_active || satellite_progress > 0.001f) {


        b << "satelital " << satellite_indexed << '/' << satellite_detected << " archivos indexados · núcleo mensual en Datos/AAAA_MM.ixiptlah::satelital · crudo separado";


    } else if (external_active || external_progress > 0.001f) {


        b << "inventario de datos " << external_indexed << '/' << external_detected << " archivos/recetas · ixiptlah mensual/inventarial · sin activar capas visibles por sí mismo";


    } else if (atmosphere_active || atmosphere_progress > 0.001f) {
        auto compact_bytes = [](unsigned long long bytes) {
            const char* units[] = {"B", "KB", "MB", "GB"};
            double v = static_cast<double>(bytes);
            int unit = 0;
            while (v >= 1024.0 && unit < 3) { v /= 1024.0; ++unit; }
            std::ostringstream os;
            if (unit == 0) os << bytes << units[unit];
            else os << std::fixed << std::setprecision(v >= 100.0 ? 0 : 1) << v << units[unit];
            return os.str();
        };
        const int total = std::max({1, atmosphere_total_files, atmosphere_detected});
        b << "atmosfera " << atmosphere_indexed << '/' << total << " archivos";
        if (!atmosphere_current_file.empty()) b << " · " << compact_label(atmosphere_current_file, 48);
        if (atmosphere_total_bytes > 0) b << " · " << compact_bytes(atmosphere_current_bytes) << '/' << compact_bytes(atmosphere_total_bytes);
        if (atmosphere_current_rows > 0) b << " · " << atmosphere_current_rows << " filas actuales";
        b << " · " << atmosphere_cloud_points << " puntos visibles";

    } else if (!epi_status.empty()) {
        b << epi_status;
    } else {
        b << (log_detail.empty() ? "Sin tareas activas." : log_detail);
    }
    h.detail_b = compact_label(b.str(), 170);

    return h;
}


































void start_satellite_import_async(UiState& ui);
void start_atmospheric_csv_import_async(UiState& ui);
void start_external_import_async(UiState& ui);

bool tlalpowa_import_any_activity_active(const UiState& ui) {
    return ui.running.load() ||
           ui.epi_downloading ||
           ui.mobility_downloading ||
           ui.atmosphere_importing ||
           ui.satellite_importing ||
           ui.external_importing ||
           ui.import_child_pid.load(std::memory_order_relaxed) != 0;
}

void tlalpowa_force_import_to_configuration_only(UiState& ui) {
    // El importador vive únicamente como página interna de Configuración.
    // Al retirar la ventana de salida duplicada no queda ventana hermana que sincronizar; este
    // cierre idempotente evita estados fantasma sin tocar el proceso activo.
    ui.show_import_window = false;
    ui.import_window_force_closed.store(true);
}

void tlalpowa_reset_import_visible_state(UiState& ui, const char* message) {
    
    
    
    
    ui.pause_requested.store(false);
    ui.restart_requested.store(false);
    ui.cancel_requested.store(false);
    ui.clean_outputs_requested.store(false);
    ui.pending_import_after_epi_download = false;
    ui.epi_cancel_requested.store(false);
    ui.running.store(false);
    ui.import_child_pid.store(0, std::memory_order_relaxed);
    ui.import_progress_detail.clear();
    ui.epi_download_phase.clear();
    ui.epi_downloading = false;
    ui.mobility_downloading = false;
    ui.atmosphere_importing = false;
    ui.satellite_importing = false;
    ui.external_importing = false;
    ui.epi_download_progress = 0.0f;
    ui.mobility_download_progress = 0.0f;
    ui.atmosphere_import_progress = 0.0f;
    ui.atmosphere_import_total_files = 0;
    ui.atmosphere_import_current_rows = 0;
    ui.atmosphere_import_current_bytes = 0;
    ui.atmosphere_import_total_bytes = 0;
    ui.atmosphere_import_scanned_entries = 0;
    ui.atmosphere_import_import_errors = 0;
    ui.atmosphere_import_external_errors = 0;
    ui.atmosphere_import_current_file.clear();
    ui.ruoa_station_done.fill(0);
    ui.ruoa_station_total.fill(0);
    ui.ruoa_station_downloaded.fill(0);
    ui.ruoa_station_skipped.fill(0);
    ui.ruoa_station_failed.fill(0);
    ui.ruoa_total = 0;
    ui.ruoa_done = 0;
    ui.ruoa_downloaded = 0;
    ui.ruoa_usable = 0;
    ui.ruoa_skipped = 0;
    ui.ruoa_failed = 0;
    ui.ruoa_current_label.clear();
    ui.ruoa_current_phase.clear();
    ui.satellite_import_progress = 0.0f;
    ui.external_import_progress = 0.0f;
    ui.preview = ExtractionPreview{};
    ui.show_extraction = false;
    ui.extraction_hidden_by_user = false;
    ui.show_settings_window = true;
    ui.settings_page = 1;
    tlalpowa_force_import_to_configuration_only(ui);
    {
        std::lock_guard<std::mutex> lock(ui.mu);
        ui.status = message ? message : "Importacion detenida; estado visual restablecido.";
    }
}


void tlalpowa_force_stop_import_now(UiState& ui, unsigned int exit_code, bool reset_visual, const char* reason) {
    ui.pause_requested.store(false);
    ui.restart_requested.store(false);
    ui.clean_outputs_requested.store(false);
    ui.cancel_requested.store(true);
    ui.epi_cancel_requested.store(true);
    ui.pending_import_after_epi_download = false;

    const unsigned long pid = ui.import_child_pid.load(std::memory_order_relaxed);
    if (pid != 0) terminate_import_child_now(ui, exit_code);

    {
        std::lock_guard<std::mutex> lock(ui.mu);
        ui.status = reason && reason[0] ? reason : "Detencion fuerte solicitada.";
        append_import_log_locked(ui, ui.status + (pid != 0 ? " PID terminado." : " Sin proceso hijo vivo; cancelacion cooperativa marcada."));
        if (reset_visual && pid != 0) {
            ui.import_child_pid.store(0, std::memory_order_relaxed);
            ui.running.store(false);
            ui.epi_downloading = false;
            ui.mobility_downloading = false;
            ui.atmosphere_importing = false;
            ui.satellite_importing = false;
            ui.external_importing = false;
        }
    }
}

void tlalpowa_request_immediate_pause(UiState& ui, const char* reason) {
    ui.restart_requested.store(false);
    ui.clean_outputs_requested.store(false);
    ui.pending_import_after_epi_download = false;
    ui.pause_requested.store(true);
    ui.cancel_requested.store(true);
    ui.epi_cancel_requested.store(true);

    const unsigned long pid = ui.import_child_pid.load(std::memory_order_relaxed);
    if (pid != 0) terminate_import_child_now(ui, 130u);

    {
        std::lock_guard<std::mutex> lock(ui.mu);
        ui.status = reason && reason[0] ? reason : "Pausa inmediata solicitada.";
        append_import_log_locked(ui, ui.status + (pid != 0 ? " Proceso hijo cortado en el acto." : " Conversor integrado observara el flag antes de la siguiente escritura."));
    }
}

void tlalpowa_abort_import_to_idle(UiState& ui) {
    const bool active = tlalpowa_import_any_activity_active(ui);
    tlalpowa_force_stop_import_now(ui, 137u, true, "Detencion total solicitada; se fuerza el cierre del importador.");
    if (!active) tlalpowa_reset_import_visible_state(ui, "Importacion detenida totalmente; controles restaurados.");
}

void tlalpowa_start_import_for_current_selection(UiState& ui);

void tlalpowa_restart_current_import_processing(UiState& ui) {
    
    
    
    
    
    if (tlalpowa_import_any_activity_active(ui)) {
        ui.pause_requested.store(false);
        ui.restart_requested.store(true);
        ui.clean_outputs_requested.store(true);
        ui.cancel_requested.store(true);
        ui.epi_cancel_requested.store(true);
        terminate_import_child_now(ui, 138);
        {
            std::lock_guard<std::mutex> lock(ui.mu);
            ui.status = "Reinicio solicitado: se reprocesaran datos sin redescargar.";
        }
        return;
    }
    ui.cancel_requested.store(false);
    ui.pause_requested.store(false);
    ui.restart_requested.store(false);
    ui.clean_outputs_requested.store(true);
    tlalpowa_start_import_for_current_selection(ui);
}

void tlalpowa_start_import_for_current_selection(UiState& ui) {
    
    
    
    
    tlalpowa_force_import_to_configuration_only(ui);
    ui.show_settings_window = true;
    ui.settings_page = 1;
    ui.pause_requested.store(false);
    ui.restart_requested.store(false);
    ui.cancel_requested.store(false);
    ui.epi_cancel_requested.store(false);
    if (tlalpowa_import_any_activity_active(ui)) return;

    if (ui.import_tab == 4) {
        start_external_import_async(ui);
        return;
    }
    if (ui.import_tab == 3) {
        start_satellite_import_async(ui);
        return;
    }
    if (ui.import_tab == 0) {
        start_atmospheric_csv_import_async(ui);
        return;
    }
    if (ui.import_tab == 2) {
        const bool web_downloadable_source = ui.import_from_web && (((ui.import_pdf_source >= 0) && (ui.import_pdf_source <= 3)) || ui.import_pdf_source == 4);
        if (web_downloadable_source) {
            ui.epi_download_cdmx = (ui.import_pdf_source >= 0) && (ui.import_pdf_source <= 3);
            ui.epi_download_edomex = ui.import_pdf_source == 4;
            ui.pending_import_after_epi_download = true;
            ui.epi_status = "Modo web: se descargan documentos oficiales y luego se compila a .ixiptlah.";
            append_import_log(ui, ui.epi_status);
            download_epidemiology_sources_async(ui);
        } else {
            start_pipeline(ui);
        }
        return;
    }
    {
        std::lock_guard<std::mutex> lock(ui.mu);
        ui.status = "No hay importador seleccionado para iniciar.";
    }
}

std::string tlalpowa_import_progress_line(UiState& ui, const PipelineStats& stats, const ExtractionPreview& preview) {
    bool epi_active = false;
    bool mobility_active = false;
    bool atmosphere_active = false;
    bool satellite_active = false;
    bool external_active = false;
    int epi_attempted = 0, epi_total = 0, epi_ok = 0, epi_skipped = 0;
    int mobility_attempted = 0, mobility_total = 0, mobility_ok = 0;
    int atmosphere_detected = 0, atmosphere_indexed = 0, atmosphere_cloud_points = 0, atmosphere_total_files = 0;
    long long atmosphere_current_rows = 0;
    unsigned long long atmosphere_current_bytes = 0, atmosphere_total_bytes = 0;
    unsigned long long atmosphere_scanned_entries = 0;
    unsigned long long atmosphere_import_errors = 0, atmosphere_external_errors = 0;
    std::string atmosphere_current_file;
    int ruoa_usable = 0, ruoa_failed = 0;
    int csv_import_source_snapshot = 0;
    int satellite_detected = 0, satellite_indexed = 0;
    int external_detected = 0, external_indexed = 0;
    float epi_progress = 0.0f, mobility_progress = 0.0f, atmosphere_progress = 0.0f, satellite_progress = 0.0f, external_progress = 0.0f;
    std::string atmosphere_status;
    {
        std::lock_guard<std::mutex> lock(ui.mu);
        epi_active = ui.epi_downloading;
        mobility_active = ui.mobility_downloading;
        atmosphere_active = ui.atmosphere_importing;
        satellite_active = ui.satellite_importing;
        external_active = ui.external_importing;
        epi_attempted = ui.epi_download_attempted;
        epi_total = ui.epi_download_total;
        epi_ok = ui.epi_download_ok;
        epi_skipped = ui.epi_download_skipped;
        epi_progress = ui.epi_download_progress;
        mobility_attempted = ui.mobility_download_attempted;
        mobility_total = ui.mobility_download_total;
        mobility_ok = ui.mobility_download_ok;
        mobility_progress = ui.mobility_download_progress;
        atmosphere_progress = ui.atmosphere_import_progress;
        atmosphere_detected = ui.atmosphere_import_detected;
        atmosphere_indexed = ui.atmosphere_import_indexed;
        atmosphere_total_files = ui.atmosphere_import_total_files;
        atmosphere_current_rows = ui.atmosphere_import_current_rows;
        atmosphere_current_bytes = ui.atmosphere_import_current_bytes;
        atmosphere_total_bytes = ui.atmosphere_import_total_bytes;
        atmosphere_scanned_entries = ui.atmosphere_import_scanned_entries;
        atmosphere_import_errors = ui.atmosphere_import_import_errors;
        atmosphere_external_errors = ui.atmosphere_import_external_errors;
        atmosphere_current_file = ui.atmosphere_import_current_file;
        atmosphere_cloud_points = ui.atmosphere_import_cloud_points;
        ruoa_usable = ui.ruoa_usable;
        ruoa_failed = ui.ruoa_failed;
        csv_import_source_snapshot = ui.import_csv_source;
        atmosphere_status = ui.atmosphere_import_status;
        satellite_progress = ui.satellite_import_progress;
        satellite_detected = ui.satellite_import_detected;
        satellite_indexed = ui.satellite_import_indexed;
        external_progress = ui.external_import_progress;
        external_detected = ui.external_import_detected;
        external_indexed = ui.external_import_indexed;
    }

    const bool running = ui.running.load();
    auto pct_text = [](double value) {
        std::ostringstream os;
        os << std::fixed << std::setprecision(0) << std::clamp(value, 0.0, 1.0) * 100.0 << "%";
        return os.str();
    };
    auto compact_bytes_local = [](unsigned long long bytes) {
        const char* units[] = {"B", "KB", "MB", "GB"};
        double v = static_cast<double>(bytes);
        int unit = 0;
        while (v >= 1024.0 && unit < 3) { v /= 1024.0; ++unit; }
        std::ostringstream os;
        if (unit == 0) os << bytes << units[unit];
        else os << std::fixed << std::setprecision(v >= 100.0 ? 0 : 1) << v << units[unit];
        return os.str();
    };
    auto compact_count_local = [](unsigned long long n) {
        const char* units[] = {"", "k", "M", "G"};
        double v = static_cast<double>(n);
        int unit = 0;
        while (v >= 1000.0 && unit < 3) { v /= 1000.0; ++unit; }
        std::ostringstream os;
        if (unit == 0) os << n;
        else os << std::fixed << std::setprecision(v >= 100.0 ? 0 : 1) << v << units[unit];
        return os.str();
    };
    auto file_leaf_local = [](const std::string& path) {
        const std::size_t cut = path.find_last_of("/\\");
        return cut == std::string::npos ? path : path.substr(cut + 1);
    };
    auto live_suffix = []() {
        const int dots = 1 + (static_cast<int>(std::floor(ImGui::GetTime() * 3.0)) % 3);
        return std::string("vivo") + std::string(static_cast<std::size_t>(dots), '.');
    };
    auto one_line = [&](double fraction, long long completed, long long external_errors,
                         long long import_errors, const std::string& detail) {
        /*
         * Invariante visual absoluta del importador:
         *   porcentaje | completados | errores ajenos a la importacion | errores de importacion | detalle util fino
         * Es una unica linea. Queda prohibido renderizar sublineas, origen,
         * encabezado tecnico o detalle extendido debajo. La ultima celda debe
         * concentrar el estado operativo real sin saltos ni separadores internos.
         */
        std::string safe_detail = trim(detail);
        if (safe_detail.empty()) safe_detail = "en espera";
        for (char& c : safe_detail) {
            if (c == '\r' || c == '\n' || c == '\t') c = ' ';
            else if (c == '|') c = '/';
        }
        safe_detail = compact_label(safe_detail, 204);
        std::ostringstream os;
        os << pct_text(fraction) << " | " << std::max(0LL, completed) << " completados | "
           << std::max(0LL, external_errors) << " ajenos | "
           << std::max(0LL, import_errors) << " importacion | " << safe_detail;
        return compact_label(os.str(), 340);
    };
    auto year_span = [](int a, int b) {
        if (a <= 0 && b <= 0) return std::string("actual");
        if (a <= 0) a = b;
        if (b <= 0) b = a;
        if (a == b) return std::to_string(a);
        return std::to_string(std::min(a, b)) + "-" + std::to_string(std::max(a, b));
    };
    auto week_from_preview = [&]() {
        for (const auto& o : preview.accepted) if (o.bulletin_week > 0) return o.bulletin_week;
        const std::string label = normalize_key(!preview.pdf_file.empty() ? preview.pdf_file : stats.current_pdf);
        return ozmvm_epi_week_contextual(label.data(), label.size());
    };
    auto year_from_preview = [&]() {
        for (const auto& o : preview.accepted) if (o.bulletin_year > 0) return o.bulletin_year;
        const std::string label = normalize_key(!preview.pdf_file.empty() ? preview.pdf_file : stats.current_pdf);
        const int y = ozmvm_first_epi_year_1900_2099(label.data(), label.size());
        if (y >= 2000 && y <= 2100) return y;
        return 0;
    };

    if (epi_active || epi_progress > 0.001f) {
        const int reviewed = std::max(epi_attempted, epi_ok + epi_skipped);
        const int failed = std::max(0, reviewed - epi_ok - epi_skipped);
        std::ostringstream detail;
        detail << "descarga epidemiologica " << year_span(ui.epi_year_start, ui.epi_year_end)
               << "; rev " << reviewed << '/' << std::max(reviewed, epi_total)
               << "; ok " << epi_ok << "; omit " << epi_skipped;
        if (epi_active) detail << "; " << live_suffix();
        return one_line(epi_progress, epi_ok, failed, 0, detail.str());
    }
    if (mobility_active || mobility_progress > 0.001f) {
        const int reviewed = std::max(mobility_attempted, mobility_ok);
        const int failed = std::max(0, reviewed - mobility_ok);
        std::ostringstream detail;
        detail << "descarga movilidad " << year_span(ui.mobility_year_start, ui.mobility_year_end)
               << "; rev " << reviewed << '/' << std::max(reviewed, mobility_total)
               << "; ok " << mobility_ok;
        if (mobility_active) detail << "; " << live_suffix();
        return one_line(mobility_progress, mobility_ok, failed, 0, detail.str());
    }
    if (satellite_active || satellite_progress > 0.001f) {
        std::ostringstream detail;
        detail << "satelital index; detect " << satellite_detected << "; index " << satellite_indexed;
        if (satellite_active) detail << "; " << live_suffix();
        return one_line(satellite_progress, satellite_indexed, 0, 0, detail.str());
    }
    if (external_active || external_progress > 0.001f) {
        std::ostringstream detail;
        detail << "tabular index; detect " << external_detected << "; index " << external_indexed;
        if (external_active) detail << "; " << live_suffix();
        return one_line(external_progress, external_indexed, 0, 0, detail.str());
    }
    if (atmosphere_active || atmosphere_progress > 0.001f) {
        const int total_files = std::max({1, atmosphere_total_files, atmosphere_detected, atmosphere_indexed});
        const double byte_fraction = atmosphere_total_bytes > 0
            ? std::clamp(static_cast<double>(atmosphere_current_bytes) / static_cast<double>(atmosphere_total_bytes), 0.0, 1.0)
            : 0.0;
        const int current_slot = std::min(total_files, std::max(0, atmosphere_indexed) + ((atmosphere_current_bytes > 0 || !atmosphere_current_file.empty()) ? 1 : 0));
        const long long accepted = (csv_import_source_snapshot == 3 && ruoa_usable > 0) ? ruoa_usable : atmosphere_indexed;
        const char* source_short = csv_import_source_snapshot == 1 ? "RAMA" : (csv_import_source_snapshot == 0 ? "REDMET" : (csv_import_source_snapshot == 3 ? "RUOA/PEMBU" : "ATM"));

        std::string phase_raw = trim(atmosphere_status);
        if (phase_raw.empty()) phase_raw = "leyendo directorio atmosferico";
        const std::string phase_key = normalize_key(phase_raw);
        std::string phase;
        if (phase_key.find("explor") != std::string::npos) phase = "escaneo";
        else if (phase_key.find("reemplaz") != std::string::npos || phase_key.find("sobrescrit") != std::string::npos || phase_key.find("purga") != std::string::npos) phase = "purga IX";
        else if (phase_key.find("descarg") != std::string::npos) phase = "descarga";
        else if (phase_key.find("encabez") != std::string::npos) phase = "encabezados";
        else if (phase_key.find("leyendo casillas") != std::string::npos || phase_key.find("carg") != std::string::npos) phase = "carga mapa";
        else if (phase_key.find("listo") != std::string::npos || atmosphere_progress >= 0.995f) phase = "listo";
        else if (!atmosphere_current_file.empty() || atmosphere_current_bytes > 0) phase = "lectura CSV";
        else phase = compact_label(phase_raw, 28);

        struct ImportRateState {
            std::string file;
            unsigned long long bytes = 0;
            long long rows = 0;
            double time = 0.0;
            double mbps = 0.0;
            double rows_per_second = 0.0;
        };
        static ImportRateState atmosphere_rate;
        const double now_time = ImGui::GetTime();
        if (atmosphere_rate.time <= 0.0 || atmosphere_rate.file != atmosphere_current_file ||
            atmosphere_current_bytes < atmosphere_rate.bytes || atmosphere_current_rows < atmosphere_rate.rows) {
            atmosphere_rate.file = atmosphere_current_file;
            atmosphere_rate.bytes = atmosphere_current_bytes;
            atmosphere_rate.rows = atmosphere_current_rows;
            atmosphere_rate.time = now_time;
            atmosphere_rate.mbps = 0.0;
            atmosphere_rate.rows_per_second = 0.0;
        } else {
            const double dt = now_time - atmosphere_rate.time;
            if (dt >= 0.22) {
                const unsigned long long byte_delta = atmosphere_current_bytes - atmosphere_rate.bytes;
                const long long row_delta = atmosphere_current_rows - atmosphere_rate.rows;
                const double inst_mbps = (static_cast<double>(byte_delta) / (1024.0 * 1024.0)) / std::max(0.001, dt);
                const double inst_rps = static_cast<double>(std::max(0LL, row_delta)) / std::max(0.001, dt);
                atmosphere_rate.mbps = atmosphere_rate.mbps <= 0.0 ? inst_mbps : (atmosphere_rate.mbps * 0.70 + inst_mbps * 0.30);
                atmosphere_rate.rows_per_second = atmosphere_rate.rows_per_second <= 0.0 ? inst_rps : (atmosphere_rate.rows_per_second * 0.70 + inst_rps * 0.30);
                atmosphere_rate.bytes = atmosphere_current_bytes;
                atmosphere_rate.rows = atmosphere_current_rows;
                atmosphere_rate.time = now_time;
            }
        }

        std::ostringstream detail;
        detail << source_short << ' ' << phase;
        detail << "; arch " << current_slot << '/' << total_files;
        if (!atmosphere_current_file.empty()) detail << ' ' << compact_label(file_leaf_local(atmosphere_current_file), 30);
        if (atmosphere_detected > 0) detail << "; csv " << atmosphere_detected;
        if (atmosphere_scanned_entries > 0) detail << "; esc " << compact_count_local(atmosphere_scanned_entries);
        if (atmosphere_total_bytes > 0) {
            detail << "; pos " << compact_bytes_local(atmosphere_current_bytes) << '/' << compact_bytes_local(atmosphere_total_bytes)
                   << ' ' << pct_text(byte_fraction);
        }
        if (atmosphere_current_rows > 0) detail << "; filas " << compact_count_local(static_cast<unsigned long long>(atmosphere_current_rows));
        if (atmosphere_rate.rows_per_second >= 1.0) detail << "; " << compact_count_local(static_cast<unsigned long long>(atmosphere_rate.rows_per_second)) << " filas/s";
        if (atmosphere_rate.mbps >= 0.05) detail << "; " << std::fixed << std::setprecision(atmosphere_rate.mbps >= 10.0 ? 0 : 1) << atmosphere_rate.mbps << "MB/s";
        if (atmosphere_cloud_points > 0) detail << "; pts " << compact_count_local(static_cast<unsigned long long>(atmosphere_cloud_points));
        if (atmosphere_import_errors > 0 || atmosphere_external_errors > 0) {
            detail << "; err i/e " << atmosphere_import_errors << '/' << atmosphere_external_errors;
        }
        if (atmosphere_active) detail << "; " << live_suffix();
        const long long external_errors = static_cast<long long>(std::min<unsigned long long>(
            atmosphere_external_errors + ((csv_import_source_snapshot == 3 && ruoa_failed > 0) ? static_cast<unsigned long long>(ruoa_failed) : 0ull),
            static_cast<unsigned long long>(std::numeric_limits<long long>::max())));
        const long long import_errors = static_cast<long long>(std::min<unsigned long long>(
            atmosphere_import_errors, static_cast<unsigned long long>(std::numeric_limits<long long>::max())));
        return one_line(atmosphere_progress, accepted, external_errors, import_errors, detail.str());
    }

    const long long ok_items = std::max(0LL, static_cast<long long>(stats.observations_accepted));
    const long long incorrect = std::max(0LL, static_cast<long long>(stats.quarantine_items));

    long long processed_docs = std::max(0, stats.pdf_done);
    long long total_docs = std::max(processed_docs, static_cast<long long>(std::max(0, stats.pdf_total)));
    if (total_docs == 0 && preview.pdf_total > 0) {
        processed_docs = std::max(0, preview.pdf_index);
        total_docs = std::max(processed_docs, static_cast<long long>(preview.pdf_total));
    }

    std::string action;
    const int week = week_from_preview();
    if (running && week > 0) {
        const int year = year_from_preview();
        action = "SE " + std::to_string(week);
        if (year > 0) action += "/" + std::to_string(year);
    }
    else if (running && (stats.current_page > 0 || preview.page > 0)) action = "tabla epidemiologica";
    else if (running && (stats.progress > 0.90 || stats.status == "terminado")) action = "cierre IX";
    else if (running || stats.progress > 0.001 || total_docs > 0) action = "busqueda PDF";
    else action = "listo";

    const int shown_page = preview.page > 0 ? preview.page : stats.current_page;
    const std::string shown_pdf = !preview.pdf_file.empty() ? preview.pdf_file : stats.current_pdf;
    std::ostringstream detail;
    detail << "epi " << action;
    if (total_docs > 0) detail << "; pdf " << processed_docs << '/' << total_docs;
    if (shown_page > 0) detail << "; pag " << shown_page;
    if (stats.pages_done > 0 || stats.pages_total > 0) detail << "; paginas " << stats.pages_done << '/' << std::max(stats.pages_done, stats.pages_total);
    if (!shown_pdf.empty()) detail << "; " << compact_label(file_leaf_local(shown_pdf), 34);
    if (stats.tables_detected > 0) detail << "; tablas " << stats.tables_detected;
    if (incorrect > 0) detail << "; cuar " << incorrect;
    if (running) detail << "; " << live_suffix();

    const double fraction = running || stats.progress > 0.001 ? stats.progress : 0.0;
    return one_line(fraction, ok_items, 0, incorrect, detail.str());
}

void draw_import_compact_header(UiState& ui, const PipelineStats& stats, const ExtractionPreview& preview, const ImVec4& accent, const std::string& context_detail) {
    
    
    
    
    
    const ImportCompactHeaderSnapshot h = build_import_compact_header_snapshot(ui, stats, preview, context_detail);
    const float pct = std::clamp(h.fraction, 0.0f, 1.0f);
    accent_progress_bar_exact_no_intrinsic_gap(pct, ImVec2(-1.0f, tlalpowa_import_track_visual_thickness()), nullptr, accent, tlalpowa_import_any_activity_active(ui));
    golden_manual_gap_y(tlalpowa_import_gap_above_progress_text());

    auto compact_to_pixel_width = [](std::string text, float max_w) {
        if (max_w <= 8.0f) return compact_label(text, 24);
        if (ImGui::CalcTextSize(text.c_str()).x <= max_w) return text;
        std::size_t lo = 8;
        std::size_t hi = text.size();
        std::size_t best = 8;
        while (lo <= hi) {
            const std::size_t mid = lo + (hi - lo) / 2;
            const std::string probe = compact_label(text, mid);
            if (ImGui::CalcTextSize(probe.c_str()).x <= max_w) {
                best = mid;
                lo = mid + 1;
            } else {
                if (mid == 0) break;
                hi = mid - 1;
            }
        }
        return compact_label(text, best);
    };
    const float reserved_buttons_w = 164.0f + 150.0f + ImGui::GetStyle().ItemSpacing.x * 5.0f + 24.0f;
    const float line_max_w = std::max(80.0f, ImGui::GetContentRegionAvail().x - reserved_buttons_w);
    const std::string line = compact_to_pixel_width(tlalpowa_import_progress_line(ui, stats, preview), line_max_w);
    /* Sin PushTextWrapPos: TextDisabled conserva una sola línea; el recorte por ancho ya se resolvió arriba. */
    ImGui::TextDisabled("%s", line.c_str());

    const bool any_active = tlalpowa_import_any_activity_active(ui);
    ImGui::SameLine(ImGui::GetContentRegionAvail().x > 360.0f ? ImGui::GetCursorPosX() + std::max(0.0f, ImGui::GetContentRegionAvail().x - 322.0f) : 0.0f);
    if (import_soft_button("Reiniciar procesamiento", accent, false, ImVec2(164.0f, 0.0f))) {
        tlalpowa_restart_current_import_processing(ui);
    }
    ImGui::SameLine(0.0f, std::max(1.0f, golden_w(kGoldenN11)));

    static double click_window_start = 0.0;
    static int click_count = 0;
    const bool ruoa_active = any_active && ui.atmosphere_importing && ui.import_csv_source == 3;
    const char* cycle_label = any_active ? (ruoa_active ? "Detener RUOA" : (ui.pause_requested.load() ? "Reanudar" : "Pausar / detener")) : "Iniciar importacion";
    const bool cycle_clicked = import_soft_button(cycle_label, accent, true, ImVec2(150.0f, 0.0f));
    if (cycle_clicked) {
        if (ruoa_active) {
            ui.pause_requested.store(false);
            ui.cancel_requested.store(true);
            ui.epi_cancel_requested.store(true);
            std::lock_guard<std::mutex> lock(ui.mu);
            ui.status = "RUOA_UNAM: detencion solicitada; se cierra el CSV actual y no se compila IXIPTLAH parcial.";
            append_import_log_locked(ui, ui.status);
            return;
        }
        const double now = ImGui::GetTime();
        if (now - click_window_start > 1.05) {
            click_window_start = now;
            click_count = 0;
        }
        ++click_count;
        if (!any_active) {
            click_count = 0;
            tlalpowa_start_import_for_current_selection(ui);
        } else if (click_count >= 4) {
            click_count = 0;
            tlalpowa_force_stop_import_now(ui, 140u, true, "Cuarto clic: detencion total forzada y estado visual restaurado.");
        } else if (click_count >= 3) {
            tlalpowa_force_stop_import_now(ui, 139u, false, "Tercer clic: detencion fuerte del proceso de importacion.");
        } else if (ui.pause_requested.load() && !ui.cancel_requested.load()) {
            ui.pause_requested.store(false);
            std::lock_guard<std::mutex> lock(ui.mu);
            ui.status = "Importacion reanudada.";
            append_import_log_locked(ui, ui.status);
        } else {
            tlalpowa_request_immediate_pause(ui, "Primer clic: pausa inmediata del importador epidemiologico.");
        }
    }

    /*
     * Invariante visual estricta del importador: el diálogo de progreso NO puede
     * abrir una segunda ni tercera línea de estado.  El usuario debe ver una sola
     * línea formal original: porcentaje | completados | errores ajenos | errores importacion | detalle util.
     * Header, origen, fuente y detalle extendido se conservan como estado interno, pero
     * queda prohibido renderizarlos debajo de la línea principal porque simulan
     * un bloqueo cuando RAMA/REDMET tarda en purgar o recorrer directorios grandes.
     */
    (void)any_active;
    (void)h;
}






void draw_import_pipeline_controls_inline(UiState& ui, const ImVec4& accent) {

    if (!ui.running.load()) return;

    ImGui::SameLine(0.0f, 8.0f);


    if (import_soft_button("Pausar", accent, false, ImVec2(70.0f, 0.0f))) {
        tlalpowa_request_immediate_pause(ui, "Pausa inmediata solicitada: se corta el proceso activo y se preservan checkpoints/IXIPTLAH cerrables.");
    }

    if (ImGui::IsItemHovered()) ImGui::SetTooltip("Pausar de forma segura: no mantiene IXIPTLAH abiertos ni permite lectura viva");

    ImGui::SameLine(0.0f, std::max(1.0f, golden_w(kGoldenN11)));


    if (import_soft_button("Detener", accent, false, ImVec2(78.0f, 0.0f))) request_stop_pipeline_keep_window(ui);

    ImGui::SameLine(0.0f, std::max(1.0f, golden_w(kGoldenN11)));


    if (import_soft_button("Reiniciar", accent, false, ImVec2(84.0f, 0.0f))) request_restart_pipeline(ui);
}



void draw_linear_child_preview_card(const PipelineStats& stats, const ExtractionPreview& preview, const ImVec4& accent) {

    ImDrawList* dl = ImGui::GetWindowDrawList();

    const ImVec2 a = ImGui::GetCursorScreenPos();
    const float h = 118.0f;

    const ImVec2 b(a.x + ImGui::GetContentRegionAvail().x, a.y + h);
    dl->AddRectFilled(a, b, IM_COL32(245, 247, 249, 255), 7.0f);
    dl->AddRect(a, b, u32(accent, 0.36f), 7.0f, 0, 1.0f);


    const int shown_page = preview.page > 0 ? preview.page : stats.current_page;
    const std::string shown_file = !preview.pdf_file.empty() ? preview.pdf_file : (!stats.current_pdf.empty() ? stats.current_pdf : "Preparando boletines PDF");
    const std::string title = shown_page > 0 ? (shown_file + " | pagina " + std::to_string(shown_page)) : shown_file;
    dl->AddText(ImVec2(a.x + 14, a.y + 13), IM_COL32(28, 38, 48, 235), title.c_str());
    std::string status = preview.status.empty() ? stats.status : preview.status;
    if (status.empty() || status == "listo") status = "Esperando primera pagina validada del conversor";
    dl->AddText(ImVec2(a.x + 14, a.y + 39), IM_COL32(82, 94, 106, 230), status.c_str());


    const float pct = static_cast<float>(std::clamp(stats.progress, 0.0, 1.0));
    const float x0 = a.x + 14;
    const float x1 = b.x - 14;
    const float y = b.y - 28;
    dl->AddRectFilled(ImVec2(x0, y), ImVec2(x1, y + 8), IM_COL32(210, 218, 226, 255), 5.0f);
    dl->AddRectFilled(ImVec2(x0, y), ImVec2(x0 + (x1 - x0) * pct, y + 8), u32(accent, 0.88f), 5.0f);

    ImGui::Dummy(ImVec2(1.0f, h));
}





void draw_import_preview_stack(const PipelineStats& stats, const ExtractionPreview& preview, const fs::path& out, const ImVec4& accent) {
    (void)out;

    static ExtractionPreview last_drawable_preview;

    if (preview_has_drawable_page(preview)) last_drawable_preview = preview;
    const ExtractionPreview& page_preview = preview_has_drawable_page(preview) ? preview : last_drawable_preview;
    const bool has_page_preview = preview_has_drawable_page(page_preview);

    const std::vector<PreviewDiseaseTable> disease_tables = build_preview_disease_tables(preview);
    const int disease_table_count = static_cast<int>(disease_tables.size());
    const int visible_table_count = std::max(1, disease_table_count);

    const float avail_w = std::max(1.0f, ImGui::GetContentRegionAvail().x);
    const float avail_h = ImGui::GetContentRegionAvail().y;
    const float map_like_h = (avail_h > 240.0f) ? std::clamp(avail_h - 2.0f, 280.0f, std::max(280.0f, avail_h - 2.0f)) : 360.0f;

    // Retícula áurea final del importador: 0.618033... se reserva estrictamente
    // a la página procesada; 0.372000 aloja la banda completa de tarjetas. El
    // remanente, cercano al 1 %, se usa sólo como costura óptica. Las tarjetas
    // se disponen con BeginChild/SameLine y no con una tabla exterior: así se
    // elimina otra fuente de invariantes de columnas cuando una página trae más
    // enfermedades que las esperadas, y el scroll horizontal depende únicamente
    // de ítems reales de ImGui.
    constexpr float kPreviewPageGoldenRatio = kGoldenN1;
    constexpr float kPreviewTablesRightRatio = 0.372000000000000f;
    const float raw_page_w = std::floor(avail_w * kPreviewPageGoldenRatio);
    const float raw_cluster_w = std::floor(avail_w * kPreviewTablesRightRatio);
    const float min_page_w = std::min(360.0f, std::max(220.0f, avail_w * 0.520f));
    const float page_w = std::clamp(raw_page_w, min_page_w, std::max(min_page_w, avail_w * 0.6185f));
    const float table_cluster_w = std::max(1.0f, raw_cluster_w);
    const float page_table_gap = std::clamp(avail_w - page_w - table_cluster_w, 1.0f, std::max(1.0f, avail_w * 0.011f));
    // El ancho se calcula siempre contra cuatro ranuras áureas dentro de 0.372.
    // Así 2 o 3 tablas no se inflan; simplemente quedan más aireadas a la derecha,
    // y una página con 4 enfermedades todavía cabe sin invadir la hoja 0.618.
    constexpr int table_slots_for_width = 4;
    const float table_gap = std::clamp(table_cluster_w * kGoldenN14, 0.50f, 1.15f);
    const float table_w = std::max(58.0f, std::floor((table_cluster_w - table_gap * static_cast<float>(table_slots_for_width - 1)) / static_cast<float>(table_slots_for_width)));
    const float row_h = std::clamp(pdf_page_canvas_height(has_page_preview ? page_preview : preview, std::max(220.0f, page_w)), 308.0f, map_like_h);

    const float total_content_w = page_w + page_table_gap + static_cast<float>(visible_table_count) * table_w + table_gap * static_cast<float>(std::max(0, visible_table_count - 1));
    ImGui::SetNextWindowContentSize(ImVec2(std::max(avail_w, total_content_w), row_h));
    ImGui::BeginChild("pdf-preview-row-page-and-tables", ImVec2(0.0f, row_h + ImGui::GetStyle().ScrollbarSize + 2.0f), false,
                      ImGuiWindowFlags_HorizontalScrollbar | ImGuiWindowFlags_NoSavedSettings);

    ImGui::PushStyleVar(ImGuiStyleVar_ItemSpacing, ImVec2(0.0f, 0.0f));

    // Columna 0 visual = página PDF procesada. Cada tarjeta siguiente es un
    // child independiente, no una columna de tabla exterior, para que el conteo
    // de enfermedades no pueda invalidar el layout ni reutilizar tamaños viejos.
    ImGui::BeginChild("pdf-preview-page-cell", ImVec2(page_w, row_h), false,
                      ImGuiWindowFlags_NoScrollbar | ImGuiWindowFlags_NoScrollWithMouse | ImGuiWindowFlags_NoSavedSettings);
    if (has_page_preview) {
        draw_page_mask_canvas(page_preview, accent);
        if (!preview_has_drawable_page(preview) && preview.page > 0) draw_preview_status_badge(preview, accent);
    } else {
        draw_linear_child_preview_card(stats, preview, accent);
    }
    ImGui::EndChild();

    ImGui::SameLine(0.0f, page_table_gap);

    if (disease_tables.empty()) {
        ImGui::BeginChild("pdf-preview-empty-epi-table", ImVec2(table_w, row_h), false,
                          ImGuiWindowFlags_NoScrollbar | ImGuiWindowFlags_NoSavedSettings);
        draw_empty_epidemiology_table_card(preview, row_h, accent);
        ImGui::EndChild();
    } else {
        for (size_t i = 0; i < disease_tables.size(); ++i) {
            if (i > 0) ImGui::SameLine(0.0f, table_gap);
            ImGui::PushID(static_cast<int>(i));
            ImGui::BeginChild("pdf-preview-disease-table", ImVec2(table_w, row_h), false,
                              ImGuiWindowFlags_NoScrollbar | ImGuiWindowFlags_NoSavedSettings);
            draw_epidemiology_table_card(disease_tables[i], row_h, accent, static_cast<int>(i));
            ImGui::EndChild();
            ImGui::PopID();
        }
    }

    ImGui::PopStyleVar();
    ImGui::EndChild();

    // Esta fila es deliberadamente sólo una proyección visual de revisión: la
    // tabla larga persistente mantiene enfermedad, CIE-10, periodo, sexo, año y
    // metadatos en IXIPTLAH; el importador únicamente los compacta en columnas
    // humanas para detectar errores de OCR sin duplicar identidad por renglón.
}



