fs::path cleanup_normalized_path(const fs::path& p) {
    std::error_code ec;

    fs::path q = fs::weakly_canonical(p, ec);

    if (!ec && !q.empty()) return q.lexically_normal();

    ec.clear();

    q = fs::absolute(p, ec);

    if (!ec && !q.empty()) return q.lexically_normal();

    return p.lexically_normal();
}



bool cleanup_path_same_or_inside(const fs::path& candidate, const fs::path& root) {

    const fs::path c = cleanup_normalized_path(candidate);

    const fs::path r = cleanup_normalized_path(root);

    if (c.empty() || r.empty()) return false;
    auto ci = c.begin();
    auto ri = r.begin();

    for (; ri != r.end(); ++ri, ++ci) {

        if (ci == c.end()) return false;

        if (*ci != *ri) return false;
    }

    return true;
}



bool cleanup_path_same(const fs::path& a, const fs::path& b) {

    return cleanup_normalized_path(a) == cleanup_normalized_path(b);
}



bool cleanup_is_protected_root(const fs::path& p) {

    return cleanup_path_same(p, workspace_root()) ||


           cleanup_path_same(p, datos_root()) ||

           cleanup_path_same(p, datos_externos_root()) ||

           cleanup_path_same(p, build_runtime_root()) ||

           cleanup_path_same(p, ui_config_root());
}



bool cleanup_path_allowed_for_importer(const fs::path& p) {

    if (p.empty()) return false;

    if (cleanup_is_protected_root(p)) return false;

    return cleanup_path_same_or_inside(p, datos_root()) ||

           cleanup_path_same_or_inside(p, datos_externos_root()) ||

           cleanup_path_same_or_inside(p, build_runtime_root());
}



std::uintmax_t cleanup_remove_import_path(const fs::path& p, std::vector<std::string>& notes) {

    if (!cleanup_path_allowed_for_importer(p)) {

        if (!p.empty()) notes.push_back("protegi ruta no acotada: " + path_utf8(p));

        return 0;
    }
    std::error_code ec;
    const std::uintmax_t removed = fs::remove_all(p, ec);

    if (ec) {

        notes.push_back("no pude borrar " + path_utf8(p) + ": " + ec.message());

        return 0;
    }

    if (removed > 0) notes.push_back("borrado " + std::to_string(static_cast<unsigned long long>(removed)) + " elemento(s): " + path_utf8(p));

    return removed;
}



