std::uintmax_t cleanup_remove_unified_monthly_ixiptlah(std::vector<std::string>& notes) {


    std::uintmax_t removed = 0;

    std::vector<fs::path> shards = temporal_ixiptlah_files(datos_root());
    std::sort(shards.begin(), shards.end());

    shards.erase(std::unique(shards.begin(), shards.end(), [](const fs::path& a, const fs::path& b) {

        return path_utf8(a.lexically_normal()) == path_utf8(b.lexically_normal());
    }), shards.end());

    for (const auto& shard : shards) {

        removed += cleanup_remove_import_path(shard, notes);
    }

    if (removed == 0) notes.push_back("no habia shards mensuales .ixiptlah que borrar en Datos/");

    else notes.push_back("shards mensuales unificados removidos; se reconstruiran como Datos/AAAA_MM.ixiptlah");

    return removed;
}



fs::path satellite_catalog_manifest_path();



std::uintmax_t cleanup_import_internal_for_selection(UiState& ui, std::vector<std::string>& notes) {
    std::uintmax_t removed = 0;

    if (ui.import_tab == 0) {

        if (ui.import_csv_source == 4 || ui.import_csv_source == 5) {
            removed += cleanup_remove_import_path(build_runtime_root() / "fuentes_datos_descargables_manifest.json", notes);
            ui.external_import_progress = 0.0f;
            ui.external_import_detected = 0;
            ui.external_import_indexed = 0;
            notes.push_back("fuentes externas tabulares reiniciadas sin tocar REDMET/RAMA/RUOA");
        } else {

            const int year_start = std::min(ui.atmosphere_year_start, ui.atmosphere_year_end);

            const int year_end = std::max(ui.atmosphere_year_start, ui.atmosphere_year_end);

            const std::string category = atmosphere_category_for_source(ui.import_csv_source);

            const int purged = temporal_purge_atmosphere_category(atmosphere_output_root_for_source(ui.import_csv_source),
                                                                  category,

                                                                  year_start,

                                                                  year_end);

            if (purged > 0) {

                notes.push_back("purgados " + std::to_string(purged) + " registro(s) Ixiptlah de " +


                    category + " " + std::to_string(year_start) + "-" + std::to_string(year_end) +
                    "; se preservaron otros dominios y categorias del mismo shard mensual");
                ++removed;
            } else {

                notes.push_back("no habia registros Ixiptlah de " + category + " en " +

                    std::to_string(year_start) + "-" + std::to_string(year_end) + " para purgar");
            }

            removed += cleanup_remove_import_path(datos_root() / "nube_atmosferica_ligera.jsonl", notes);

            removed += cleanup_remove_import_path(datos_root() / "atmosfera.jsonl", notes);

            removed += cleanup_remove_import_path(datos_root() / "atmosfera_archivos.json", notes);

            removed += cleanup_remove_import_path(datos_root() / "web_atmosfera.jsonl", notes);

            cleanup_reset_atmosphere_runtime_view(ui);
        }

    } else if (ui.import_tab == 3) {

        const int year_start = std::min(ui.satellite_year_start, ui.satellite_year_end);

        const int year_end = std::max(ui.satellite_year_start, ui.satellite_year_end);

        const int purged = temporal_purge_atmosphere_category(satellite_ixiptlah_root(), "satelital", year_start, year_end);

        if (purged > 0) {

            notes.push_back("purgados " + std::to_string(purged) + " registro(s) del nucleo satelital mensual IXIPTLAH");
            ++removed;
        } else {

            notes.push_back("no habia registros satelitales purgables en el intervalo elegido; se conservaron otros dominios del shard mensual");
        }

        removed += cleanup_remove_import_path(satellite_catalog_manifest_path(), notes);
        ui.satellite_import_progress = 0.0f;
        ui.satellite_import_detected = 0;
        ui.satellite_import_indexed = 0;

        ui.satellite_import_status = "Archivos internos satelitales marcados para reconstruccion.";

    } else if (ui.import_tab == 4) {



        removed += cleanup_remove_import_path(build_runtime_root() / "fuentes_datos_descargables_manifest.json", notes);
        ui.external_import_progress = 0.0f;
        ui.external_import_detected = 0;
        ui.external_import_indexed = 0;

        ui.external_import_status = "Manifiestos de datos auxiliares marcados para reconstruccion; shards IXIPTLAH compartidos preservados.";

        notes.push_back("preserve shards Datos/AAAA_MM.ixiptlah: limpieza de datos no destructiva para evitar borrar dominios estables");
    } else {

        removed += cleanup_remove_unified_monthly_ixiptlah(notes);
        try { reset_generated_pipeline_outputs(epidemiology_output_root()); } catch (...) {}

        removed += cleanup_remove_import_path(epidemiology_staging_dir(), notes);

        removed += cleanup_remove_import_path(epidemiology_quarantine_dir(), notes);

        cleanup_reset_pdf_runtime_view(ui);

        notes.push_back("salida .ixiptlah mensual unificada reiniciada");
    }

    return removed;
}



std::uintmax_t cleanup_import_downloads_for_selection(UiState& ui, std::vector<std::string>& notes) {
    std::uintmax_t removed = 0;

    if (ui.import_tab == 0) {

        if (ui.import_csv_source == 4 || ui.import_csv_source == 5) {
            removed += cleanup_remove_import_path(ui.local_external_dir.empty() ? selected_csv_source_root(ui.import_csv_source) : ui.local_external_dir, notes);
            removed += cleanup_remove_import_path(build_runtime_root() / "fuentes_datos_descargables_manifest.json", notes);
        } else {

            removed += cleanup_remove_import_path(selected_csv_source_root(ui.import_csv_source), notes);

            removed += cleanup_remove_import_path(build_runtime_root() / "atmosfera_descargas_manifest.json", notes);
        }

    } else if (ui.import_tab == 3) {

        removed += cleanup_remove_import_path(satellite_source_root(ui.import_satellite_source), notes);

        removed += cleanup_remove_import_path(satellite_catalog_manifest_path(), notes);


    } else if (ui.import_tab == 4) {

        const fs::path sci_root = ui.local_external_dir.empty() ? (datos_externos_root() / "Fuentes_Datos") : ui.local_external_dir;

        removed += cleanup_remove_import_path(sci_root, notes);

        removed += cleanup_remove_import_path(build_runtime_root() / "fuentes_datos_descargables_manifest.json", notes);
        ui.external_import_progress = 0.0f;
        ui.external_import_detected = 0;
        ui.external_import_indexed = 0;
        ui.external_import_status = "Descargas/recetas de datos marcadas para volver a descargar.";
    } else {

        if (ui.import_pdf_source == 4) {

            removed += cleanup_remove_import_path(epidemiology_edomex_root(), notes);
        } else {

            removed += cleanup_remove_import_path(epidemiology_cdmx_root(), notes);
        }

        removed += cleanup_remove_import_path(epidemiology_manifest_path(), notes);

        removed += cleanup_remove_import_path(datos_externos_root() / "boletines_epidemiologicos_journal.jsonl", notes);

        removed += cleanup_remove_import_path(official_data_download_global_lock_path(), notes);
    }

    return removed;
}



bool import_cleanup_busy(const UiState& ui) {

    return ui.running.load() || ui.epi_downloading || ui.atmosphere_importing || ui.satellite_importing ||

           ui.external_importing || ui.mobility_downloading || ui.atmosphere_snapshot_loading;
}



void execute_import_cleanup_now(UiState& ui, bool also_downloads) {

    std::vector<std::string> notes;
    const std::string scope = import_cleanup_scope_label(ui);
    const std::uintmax_t internal_removed = cleanup_import_internal_for_selection(ui, notes);

    std::uintmax_t download_removed = 0;

    if (also_downloads) download_removed = cleanup_import_downloads_for_selection(ui, notes);
    std::ostringstream msg;

    msg << (also_downloads ? "Volver a descargar" : "Rehacer archivos internos")

        << " · " << scope << " · internos " << static_cast<unsigned long long>(internal_removed)

        << " · descargas " << static_cast<unsigned long long>(download_removed);
    {

        std::lock_guard<std::mutex> lock(ui.mu);
        ui.status = msg.str();
        ui.import_progress_detail = msg.str();
    }
    append_import_log(ui, msg.str());

    for (const std::string& n : notes) append_import_log(ui, n);
}



void execute_import_cleanup_action(UiState& ui, bool also_downloads) {

    if (import_cleanup_busy(ui)) {
        const std::string scope = import_cleanup_scope_label(ui);
        ui.cancel_requested.store(true);
        ui.pause_requested.store(false);
        ui.epi_cancel_requested.store(true);
        {

            std::lock_guard<std::mutex> lock(ui.mu);
            ui.import_cleanup_queued = true;

            ui.import_cleanup_queued_downloads = also_downloads;
            ui.import_cleanup_queued_tab = ui.import_tab;

            ui.import_cleanup_queued_csv_source = ui.import_csv_source;
            ui.import_cleanup_queued_pdf_source = ui.import_pdf_source;
            ui.import_cleanup_queued_satellite_source = ui.import_satellite_source;
            ui.import_cleanup_queued_scope = scope;

            ui.import_progress_detail = std::string(also_downloads ? "Volver a descargar" : "Rehacer archivos internos") +
                                        " quedo en cola para cuando cierre la tarea activa.";
            ui.status = ui.import_progress_detail;
            append_import_log_locked(ui, ui.import_progress_detail + " Ambito: " + scope);
        }

        return;
    }

    execute_import_cleanup_now(ui, also_downloads);
}




void maybe_execute_queued_import_cleanup(UiState& ui) {
    bool should_run = false;

    bool also_downloads = false;
    std::string scope;
    {

        std::lock_guard<std::mutex> lock(ui.mu);

        if (ui.import_cleanup_queued && !import_cleanup_busy(ui)) {
            should_run = true;

            also_downloads = ui.import_cleanup_queued_downloads;
            scope = ui.import_cleanup_queued_scope;
            ui.import_tab = ui.import_cleanup_queued_tab;

            ui.import_csv_source = ui.import_cleanup_queued_csv_source;
            ui.import_pdf_source = ui.import_cleanup_queued_pdf_source;
            ui.import_satellite_source = ui.import_cleanup_queued_satellite_source;
            ui.import_cleanup_queued = false;

            ui.import_cleanup_queued_downloads = false;

            ui.import_cleanup_queued_scope.clear();
        }
    }

    if (!should_run) return;
    append_import_log(ui, "Ejecutando limpieza en cola: " + scope);

    execute_import_cleanup_now(ui, also_downloads);
}





