std::string satellite_catalog_url(int source) {
    switch (source) {

        case 0: return "https://cmr.earthdata.nasa.gov/search/collections.json?instrument[]=TROPOMI&page_size=10";

        case 1: return "https://cmr.earthdata.nasa.gov/search/collections.json?instrument[]=OMI&page_size=10";

        case 2: return "https://cmr.earthdata.nasa.gov/search/collections.json?short_name=MCD19A2&page_size=10";

        case 3: return "https://cmr.earthdata.nasa.gov/search/collections.json?instrument[]=ABI&page_size=10";
        default: return {};
    }
}



