std::vector<std::string> satellite_visual_parameters(int source) {
    switch (source) {
        case 0: return {"no2", "o3", "so2", "co"};
        case 1: return {"uvai", "no2", "o3"};
        case 2: return {"aod"};
        case 3: return {"aod", "brightness"};
        default: return {"aod"};
    }
}

std::string csv_field(std::string s) {
    bool quote = false;
    for (char c : s) {
        if (c == ',' || c == '"' || c == '\r' || c == '\n') {
            quote = true;
            break;
        }
    }
    if (!quote) return s;
    std::string out = "\"";
    for (char c : s) {
        if (c == '"') out += "\"\"";
        else out += c;
    }
    out += '"';
    return out;
}

bool parse_satellite_box_string(const std::string& text, SatelliteCatalogBox& box) {
    std::istringstream in(text);
    double south = 0.0, west = 0.0, north = 0.0, east = 0.0;
    if (!(in >> south >> west >> north >> east)) return false;
    if (!std::isfinite(south) || !std::isfinite(west) || !std::isfinite(north) || !std::isfinite(east)) return false;
    box.south = std::min(south, north);
    box.north = std::max(south, north);
    box.west = std::min(west, east);
    box.east = std::max(west, east);
    box.valid = true;
    return true;
}

bool parse_satellite_geojson_bbox(const nlohmann::json& bbox, SatelliteCatalogBox& box) {
    if (!bbox.is_array() || bbox.size() < 4) return false;
    if (!bbox[0].is_number() || !bbox[1].is_number() || !bbox[2].is_number() || !bbox[3].is_number()) return false;
    const double west = bbox[0].get<double>();
    const double south = bbox[1].get<double>();
    const double east = bbox[2].get<double>();
    const double north = bbox[3].get<double>();
    if (!std::isfinite(south) || !std::isfinite(west) || !std::isfinite(north) || !std::isfinite(east)) return false;
    box.south = std::min(south, north);
    box.north = std::max(south, north);
    box.west = std::min(west, east);
    box.east = std::max(west, east);
    box.valid = true;
    return true;
}

SatelliteCatalogBox satellite_box_from_catalog_entry(const nlohmann::json& entry) {
    SatelliteCatalogBox box;
    if (entry.contains("boxes") && entry["boxes"].is_array()) {
        for (const auto& raw : entry["boxes"]) {
            if (raw.is_string() && parse_satellite_box_string(raw.get<std::string>(), box)) return box;
        }
    }
    if (entry.contains("bbox") && parse_satellite_geojson_bbox(entry["bbox"], box)) return box;
    if (entry.contains("geometry") && entry["geometry"].contains("bbox") &&
        parse_satellite_geojson_bbox(entry["geometry"]["bbox"], box)) {
        return box;
    }
    box.valid = true;
    return box;
}

std::string satellite_entry_string(const nlohmann::json& entry, std::initializer_list<const char*> keys) {
    for (const char* key : keys) {
        if (entry.contains(key) && entry[key].is_string()) return entry[key].get<std::string>();
    }
    if (entry.contains("properties") && entry["properties"].is_object()) {
        const auto& props = entry["properties"];
        for (const char* key : keys) {
            if (props.contains(key) && props[key].is_string()) return props[key].get<std::string>();
        }
    }
    return {};
}

std::vector<std::string> satellite_catalog_concept_ids(const fs::path& catalog_path, int limit = 4) {
    std::vector<std::string> ids;
    if (file_size_or_zero(catalog_path) < 32) return ids;
    const auto parsed = nlohmann::json::parse(read_text_file(catalog_path), nullptr, false);
    if (parsed.is_discarded()) return ids;
    std::vector<nlohmann::json> entries;
    if (parsed.contains("feed") && parsed["feed"].contains("entry") && parsed["feed"]["entry"].is_array()) {
        for (const auto& entry : parsed["feed"]["entry"]) entries.push_back(entry);
    } else if (parsed.contains("features") && parsed["features"].is_array()) {
        for (const auto& entry : parsed["features"]) entries.push_back(entry);
    }
    for (const auto& entry : entries) {
        const std::string id = satellite_entry_string(entry, {"id", "concept_id", "concept-id"});
        if (!id.empty()) ids.push_back(id);
        if (static_cast<int>(ids.size()) >= limit) break;
    }
    return ids;
}

std::string cmr_query_escape(const std::string& value) {
    std::ostringstream out;
    out << std::uppercase << std::hex;
    for (unsigned char c : value) {
        if (std::isalnum(c) || c == '-' || c == '_' || c == '.' || c == '~') out << static_cast<char>(c);
        else out << '%' << std::setw(2) << std::setfill('0') << static_cast<int>(c);
    }
    return out.str();
}

std::string satellite_granules_url(int source, const fs::path& catalog_path, int year_start, int year_end) {
    std::ostringstream url;
    url << "https://cmr.earthdata.nasa.gov/search/granules.json?bounding_box=-100,18,-98,20"
        << "&temporal=" << year_start << "-01-01T00:00:00Z," << year_end << "-12-31T23:59:59Z"
        << "&page_size=200";
    const auto concept_ids = satellite_catalog_concept_ids(catalog_path);
    if (!concept_ids.empty()) {
        for (const std::string& id : concept_ids) url << "&collection_concept_id[]=" << cmr_query_escape(id);
        return url.str();
    }
    if (source == 2) url << "&short_name=MCD19A2";
    return url.str();
}

int year_prefix_or_zero(const std::string& value) {
    if (value.size() < 4) return 0;
    for (int i = 0; i < 4; ++i) {
        if (!std::isdigit(static_cast<unsigned char>(value[static_cast<size_t>(i)]))) return 0;
    }
    return std::stoi(value.substr(0, 4));
}

bool satellite_point_in_box(const SatelliteCoveragePoint& point, const SatelliteCatalogBox& box) {
    if (!box.valid) return true;
    return point.lat >= box.south && point.lat <= box.north &&
           point.lon >= box.west && point.lon <= box.east;
}

int write_satellite_catalog_coverage_sidecar(int source, const fs::path& catalog_path, int year_start, int year_end) {
    if (file_size_or_zero(catalog_path) < 32) return 0;
    const auto parsed = nlohmann::json::parse(read_text_file(catalog_path), nullptr, false);
    if (parsed.is_discarded()) return 0;

    std::vector<nlohmann::json> entries;
    if (parsed.contains("feed") && parsed["feed"].contains("entry") && parsed["feed"]["entry"].is_array()) {
        for (const auto& entry : parsed["feed"]["entry"]) entries.push_back(entry);
    } else if (parsed.contains("features") && parsed["features"].is_array()) {
        for (const auto& entry : parsed["features"]) entries.push_back(entry);
    } else if (parsed.is_array()) {
        for (const auto& entry : parsed) entries.push_back(entry);
    } else if (parsed.is_object()) {
        entries.push_back(parsed);
    }

    static const std::array<SatelliteCoveragePoint, 6> points = {{
        {"cdmx_centro", 19.4326, -99.1332},
        {"iztapalapa", 19.3574, -99.0671},
        {"gustavo_a_madero", 19.4847, -99.1133},
        {"ecatepec", 19.6018, -99.0507},
        {"nezahualcoyotl", 19.4006, -99.0148},
        {"toluca", 19.2826, -99.6557},
    }};
    const auto visual_parameters = satellite_visual_parameters(source);
    std::ostringstream parameters;
    for (size_t i = 0; i < visual_parameters.size(); ++i) {
        if (i) parameters << '|';
        parameters << visual_parameters[i];
    }
    std::ostringstream csv;
    csv << "coverage_date,site_id,latitude,longitude,available_parameters,collection_id,coverage_kind\n";
    int rows = 0;
    int entry_index = 0;
    for (const auto& entry : entries) {
        if (entry_index >= 32 || rows >= 8000) break;
        const SatelliteCatalogBox box = satellite_box_from_catalog_entry(entry);
        const std::string entry_id = satellite_entry_string(entry, {"entry_id", "id", "short_name", "title"});
        const int start_year = year_prefix_or_zero(satellite_entry_string(entry, {"time_start", "startDate", "start_date", "beginningDateTime"}));
        const int end_year_raw = year_prefix_or_zero(satellite_entry_string(entry, {"time_end", "completionDate", "end_date", "endingDateTime"}));
        const int overlap_start = std::max(year_start, start_year > 0 ? start_year : year_start);
        const int overlap_end = std::min(year_end, end_year_raw > 0 ? end_year_raw : year_end);
        const bool temporal_overlap = overlap_start <= overlap_end;
        const int effective_start = temporal_overlap ? overlap_start : year_start;
        const int effective_end = temporal_overlap ? overlap_end : year_end;
        if (effective_start > effective_end) {
            ++entry_index;
            continue;
        }
        for (int year = effective_start; year <= effective_end && rows < 8000; ++year) {
            for (int month = 1; month <= 12 && rows < 8000; ++month) {
                std::ostringstream date;
                date << year << '-' << std::setw(2) << std::setfill('0') << month << "-15";
                for (const auto& point : points) {
                    if (!satellite_point_in_box(point, box)) continue;
                    csv << date.str() << ','
                        << csv_field(std::string(point.id) + "_" + satellite_product_key(source) + "_" + std::to_string(entry_index)) << ','
                        << std::fixed << std::setprecision(6) << point.lat << ','
                        << std::fixed << std::setprecision(6) << point.lon << ','
                        << csv_field(parameters.str()) << ','
                        << csv_field(entry_id.empty() ? satellite_product_key(source) : entry_id) << ','
                        << (temporal_overlap ? "catalog_bbox" : "catalog_bbox_temporal_extent_outside_requested_years") << "\n";
                    ++rows;
                }
            }
        }
        ++entry_index;
    }
    if (rows > 0) {
        write_text_file_atomic(satellite_catalog_coverage_sidecar_path(source), csv.str());
    }
    return rows;
}

bool download_satellite_catalog_for_import(UiState& ui, int source, int year_start, int year_end) {

    const fs::path root = satellite_source_root(source);
    ensure_dir(root);

    const std::string url = satellite_catalog_url(source);

    if (url.empty()) return false;

    nlohmann::json audit;

    const fs::path target = root / (satellite_product_key(source) + "_catalog.json");

    const bool ok = download_validated_url_to_file(url, target, "json", 128, 3, &audit);

    nlohmann::json manifest;
    manifest["domain"] = "satelital_atmosferico";
    manifest["product"] = satellite_product_label(source);
    manifest["product_key"] = satellite_product_key(source);

    manifest["raw_root"] = path_utf8(root);

    manifest["ixiptlah_root"] = path_utf8(satellite_ixiptlah_root());

    manifest["ixiptlah_storage"] = "Datos/AAAA_MM.ixiptlah::nucleo_satelital";

    manifest["year_start"] = year_start;

    manifest["year_end"] = year_end;

    manifest["catalog_url"] = url;

    manifest["catalog_downloaded"] = ok;
    manifest["catalog_audit"] = audit;

    const fs::path granules_target = root / (satellite_product_key(source) + "_granules_" +
        std::to_string(year_start) + "_" + std::to_string(year_end) + ".json");
    nlohmann::json granules_audit;
    const std::string granules_url = satellite_granules_url(source, target, year_start, year_end);
    const bool granules_ok = download_validated_url_to_file(granules_url, granules_target, "json", 128, 3, &granules_audit);
    int coverage_rows = 0;
    try {
        coverage_rows = write_satellite_catalog_coverage_sidecar(source,
            (granules_ok || file_size_or_zero(granules_target) >= 128) ? granules_target : target,
            year_start, year_end);
    } catch (...) {
        coverage_rows = 0;
    }
    manifest["coverage_sidecar"] = path_utf8(satellite_catalog_coverage_sidecar_path(source));
    manifest["coverage_sidecar_rows"] = coverage_rows;
    manifest["granules_url"] = granules_url;
    manifest["granules_file"] = path_utf8(granules_target);
    manifest["granules_downloaded"] = granules_ok;
    manifest["granules_audit"] = granules_audit;
    manifest["note"] = "Catálogo y granules satelitales CMR descargados para preparar ingesta; el crudo queda separado de RAMA/SIMAT y cada variable satelital se materializa como .ixiptlah elemental directo, sin resumen persistente.";

    try { write_text_file_atomic(satellite_catalog_manifest_path(), manifest.dump(2) + "\n"); } catch (...) {}

    append_import_log(ui, std::string((ok || granules_ok) ? "Granules satelitales preparados: " : "No se pudo descargar catalogo/granules satelitales: ") +
        path_utf8(granules_ok ? granules_target : target));

    return ok || granules_ok || file_size_or_zero(target) >= 128 || file_size_or_zero(granules_target) >= 128;
}



void start_satellite_import_async(UiState& ui) {
    {

        std::lock_guard<std::mutex> lock(ui.mu);


        if (ui.satellite_importing) {
            ui.satellite_import_status = "Ya hay una importacion satelital en curso.";

            return;
        }
        ui.satellite_importing = true;
        ui.satellite_import_progress = 0.02f;

        ui.satellite_import_detected = 0;
        ui.satellite_import_indexed = 0;

        ui.satellite_import_status = "Preparando IXIPTLAH satelital elemental";
        ui.import_progress_detail = ui.satellite_import_status;
    }
    save_user_location_state(ui);
    const int source_id = ui.import_satellite_source;
    const bool from_web = ui.satellite_from_web;

    const int year_start = std::min(ui.satellite_year_start, ui.satellite_year_end);

    const int year_end = std::max(ui.satellite_year_start, ui.satellite_year_end);

    fs::path source = resolve_satellite_input_root(ui);

    if (ui.satellite_import_thread.joinable()) ui.satellite_import_thread.join();

    ui.satellite_import_thread = std::thread([&ui, source, source_id, from_web, year_start, year_end]() mutable {
        try {

            append_import_log(ui, "Importacion satelital elemental iniciada: " + std::string(satellite_product_label(source_id)) + " -> Datos/<CATEGORIA>__<ELEMENTO>.ixiptlah");

            if (from_web) {
                {

                    std::lock_guard<std::mutex> lock(ui.mu);

                    ui.satellite_import_status = "Descargando catálogo satelital oficial; el crudo queda separado y cada variable irá a su IXIPTLAH elemental.";
                    ui.satellite_import_progress = 0.08f;
                    ui.import_progress_detail = ui.satellite_import_status;
                }

                download_satellite_catalog_for_import(ui, source_id, year_start, year_end);
                source = satellite_source_root(source_id);
            }
            ensure_dir(source);
            const auto sources = list_satellite_sources_recursive_limited(source, 16000);
            {

                std::lock_guard<std::mutex> lock(ui.mu);
                ui.satellite_import_detected = static_cast<int>(sources.size());
                ui.satellite_import_progress = 0.18f;
                ui.satellite_import_status = "Archivos satelitales detectados: " + std::to_string(sources.size());
                ui.import_progress_detail = ui.satellite_import_status;
            }

            if (sources.empty()) {

                throw std::runtime_error("no hay archivos satelitales compatibles en " + path_utf8(source));
            }
            AtmosphereFoundationOptions af;
            af.source_root = source;

            af.output_root = satellite_ixiptlah_root();
            af.resume = true;


            af.forced_domain = "satelital";
            af.forced_provider = satellite_product_label(source_id);
            af.inventory_only = false;

            af.max_files = 30000;

            af.sample_lines_per_file = 32;

            af.live_flush_every_files = 20;

            af.year_start = year_start;

            af.year_end = year_end;

            af.progress_callback = [&ui](int files_done, int rows_written, const std::string& phase) {

                std::lock_guard<std::mutex> lock(ui.mu);

                ui.satellite_import_indexed = rows_written;

                ui.satellite_import_progress = std::clamp(0.18f + static_cast<float>(files_done) / 16000.0f * 0.76f, 0.18f, 0.94f);

                ui.satellite_import_status = "Indexando IXIPTLAH satelital elemental: " + std::to_string(files_done) + " archivos · " + phase;
                ui.import_progress_detail = ui.satellite_import_status;
            };
            const auto report = AtmosphericReconstructionEngine::prepare_foundation(af);

            temporal_rebuild_all_json_indexes(satellite_ixiptlah_root());
            load_atmospheric_clouds(ui, true);
            if (report.cloud_points <= 0) {
                throw std::runtime_error(
                    "se importaron catalogos y cobertura, pero no hay granulos o mallas con valores cientificos; "
                    "no se fabricaron mediciones satelitales");
            }
            {


                std::lock_guard<std::mutex> lock(ui.mu);

                ui.satellite_import_detected = report.discovered_files;

                ui.satellite_import_indexed = report.indexed_files;
                ui.satellite_import_progress = 1.0f;
                ui.satellite_importing = false;

                ui.satellite_import_status = "IXIPTLAH satelital elemental IXIPTLAH listo: " + std::to_string(report.indexed_files) +

                    " archivos asentados como IXIPTLAH elemental directo; crudo separado de RAMA/SIMAT.";
                ui.import_progress_detail = ui.satellite_import_status;
                ui.status = ui.satellite_import_status;

                ui.map_revision.fetch_add(1, std::memory_order_relaxed);
            }
            append_import_log(ui, ui.satellite_import_status);

        } catch (const std::exception& e) {

            std::lock_guard<std::mutex> lock(ui.mu);
            ui.satellite_importing = false;
            ui.satellite_import_progress = 0.0f;
            ui.satellite_import_status = std::string("No pude importar datos satelitales: ") + e.what();
            ui.import_progress_detail = ui.satellite_import_status;
            ui.status = ui.satellite_import_status;

        } catch (...) {

            std::lock_guard<std::mutex> lock(ui.mu);
            ui.satellite_importing = false;
            ui.satellite_import_progress = 0.0f;
            ui.satellite_import_status = "No pude importar datos satelitales.";
            ui.import_progress_detail = ui.satellite_import_status;
            ui.status = ui.satellite_import_status;
        }
    });
}



void start_atmospheric_csv_import_async(UiState& ui) {

    if (ui.import_csv_source == 2 && ui.csv_from_web) {
        /* RUOA_UNAM web no posee endpoint mensual estable; en modo local esta
         * misma opción lee Descargas/Atmosfericos/RUOA_PEMBU sin forzar login. */
        std::lock_guard<std::mutex> lock(ui.mu);
        ui.atmosphere_import_status = "RUOA_UNAM web no tiene endpoint mensual estable; usa Local en Descargas/Atmosfericos/RUOA_PEMBU o PEMBU_RUOA_UNAM.";
        ui.status = ui.atmosphere_import_status;
        return;
    }

    fs::path source = resolve_csv_input_root(ui);

    const bool from_web = ui.csv_from_web;

    const int import_source = ui.import_csv_source;

    const int year_start = std::min(ui.atmosphere_year_start, ui.atmosphere_year_end);

    const int year_end = std::max(ui.atmosphere_year_start, ui.atmosphere_year_end);
    {

        std::lock_guard<std::mutex> lock(ui.mu);

        if (ui.atmosphere_importing) {
            ui.atmosphere_import_status = "La importacion atmosferica ya esta en curso.";

            return;
        }
    }

    if (ui.atmosphere_import_thread.joinable()) ui.atmosphere_import_thread.join();

    {

        std::lock_guard<std::mutex> lock(ui.mu);
        ui.atmosphere_importing = true;
        ui.atmosphere_import_progress = 0.03f;
        ui.atmosphere_import_detected = 0;
        ui.atmosphere_import_indexed = 0;
        ui.atmosphere_import_total_files = 0;
        ui.atmosphere_import_current_rows = 0;
        ui.atmosphere_import_current_bytes = 0;
        ui.atmosphere_import_total_bytes = 0;
        ui.atmosphere_import_scanned_entries = 0;
        ui.atmosphere_import_import_errors = 0;
        ui.atmosphere_import_external_errors = 0;
        ui.atmosphere_import_current_file.clear();
        ui.atmosphere_import_cloud_points = 0;

        ui.local_csv_dir = source;

        ui.last_saved_csv_dir = source;

        const char* import_source_name = (import_source == 2 || import_source == 3) ? "RUOA_PEMBU" : (import_source == 1 ? "RAMA" : "REDMET");
        ui.atmosphere_import_status = std::string("Preparando importacion ") + import_source_name + "; explorando carpeta sin bloquear la interfaz.";
        ui.import_progress_detail = ui.atmosphere_import_status;
        ui.status = ui.atmosphere_import_status;
        reset_import_log_locked(ui, ui.atmosphere_import_status + " Ruta: " + path_utf8(source));
    }
    save_user_location_state(ui);


    ui.atmosphere_import_thread = std::thread([&ui, source, from_web, import_source, year_start, year_end]() mutable {
#ifdef _WIN32


        SetThreadPriority(GetCurrentThread(), THREAD_PRIORITY_BELOW_NORMAL);
#endif
        try {

            if (from_web) {
                {

                    std::lock_guard<std::mutex> lock(ui.mu);
                    ui.atmosphere_import_status = (import_source == 3)
                        ? "Etapa 1/2: descargando RUOA_UNAM PEMBU con puente respetuoso antes de compilar."
                        : "Etapa 1/2: descargando y validando todos los archivos RAMA/REDMET antes de compilar.";
                    ui.status = ui.atmosphere_import_status;
                    append_import_log_locked(ui, ui.atmosphere_import_status);
                }

                const bool downloads_ready = (import_source == 3)
                    ? download_ruoa_pembu_source_for_import(ui, year_start, year_end)
                    : download_atmosphere_source_for_import(ui, import_source, year_start, year_end);

                source = resolve_csv_input_root(ui);
                const auto csvs_after_download = list_csvs_recursive_limited(source, 0);
                if (!downloads_ready && csvs_after_download.empty()) {

                    throw std::runtime_error(import_source == 3
                        ? "La descarga web RUOA_UNAM quedo incompleta y no hay CSV locales procesables."
                        : "La descarga web RAMA/REDMET quedo incompleta y no hay CSV locales procesables.");
                }
                if (!downloads_ready && !csvs_after_download.empty()) {
                    std::lock_guard<std::mutex> lock(ui.mu);
                    ui.atmosphere_import_status = "Descarga oficial parcial; compilando los CSV locales validos ya disponibles.";
                    ui.status = ui.atmosphere_import_status;
                    append_import_log_locked(ui, ui.atmosphere_import_status);
                }

                source = resolve_csv_input_root(ui);
                {

                    std::lock_guard<std::mutex> lock(ui.mu);

                    ui.atmosphere_import_status = "Etapa 2/2: descarga cerrada; compilando bloques .ixiptlah atmosfericos.";
                    ui.status = ui.atmosphere_import_status;
                    append_import_log_locked(ui, ui.atmosphere_import_status);
                }
            }

            if (source.empty()) throw std::runtime_error("No hay carpeta CSV seleccionada.");
            std::error_code ec;

            if (!fs::exists(source, ec) || ec || !fs::is_directory(source, ec) || ec) {

                throw std::runtime_error("No existe la carpeta CSV: " + path_utf8(source));
            }

            {
                std::lock_guard<std::mutex> lock(ui.mu);
                ui.atmosphere_import_progress = std::max(ui.atmosphere_import_progress, 0.08f);
                ui.atmosphere_import_status = "Explorando todo el directorio RAMA/REDMET; sin limite de archivos.";
                ui.import_progress_detail = ui.atmosphere_import_status;
                ui.status = ui.atmosphere_import_status;
                append_import_log_locked(ui, ui.atmosphere_import_status + " Ruta: " + path_utf8(source));
            }
            const char* scan_source_label = import_source == 1 ? "RAMA" : (import_source == 0 ? "REDMET" : "ATM");
            auto scan_last_report = std::make_shared<std::chrono::steady_clock::time_point>(
                std::chrono::steady_clock::now() - std::chrono::seconds(2));
            const auto scan_callback = [&ui, scan_source_label, scan_last_report](std::size_t visited_entries,
                                                                                  std::size_t csv_files,
                                                                                  const fs::path& current_path) {
                const auto now = std::chrono::steady_clock::now();
                const bool urgent = csv_files <= 4u || (csv_files % 25u) == 0u || (visited_entries % 512u) == 0u;
                if (!urgent && std::chrono::duration_cast<std::chrono::milliseconds>(now - *scan_last_report).count() < 180) return;
                *scan_last_report = now;
                std::ostringstream os;
                os << "Explorando " << scan_source_label << " · " << csv_files << " CSV · "
                   << visited_entries << " entradas";
                const std::string name = compact_label(path_utf8(current_path.filename()), 44);
                if (!name.empty()) os << " · " << name;
                std::lock_guard<std::mutex> lock(ui.mu);
                ui.atmosphere_import_detected = static_cast<int>(std::min<std::size_t>(csv_files, static_cast<std::size_t>(std::numeric_limits<int>::max())));
                ui.atmosphere_import_total_files = ui.atmosphere_import_detected;
                ui.atmosphere_import_scanned_entries = static_cast<unsigned long long>(std::min<std::size_t>(visited_entries, static_cast<std::size_t>(std::numeric_limits<unsigned long long>::max())));
                ui.atmosphere_import_current_file = name;
                const double soft = 1.0 - std::exp(-static_cast<double>(visited_entries) / 2400.0);
                ui.atmosphere_import_progress = std::max(ui.atmosphere_import_progress,
                    std::clamp(0.08f + 0.10f * static_cast<float>(soft), 0.08f, 0.18f));
                ui.atmosphere_import_status = os.str();
                ui.import_progress_detail = ui.atmosphere_import_status;
                ui.status = ui.atmosphere_import_status;
            };
            const auto csvs = list_csvs_recursive_limited(source, 0, scan_callback);

            if (csvs.empty()) throw std::runtime_error("No se detectaron archivos CSV en " + path_utf8(source));
            {

                std::lock_guard<std::mutex> lock(ui.mu);
                ui.atmosphere_import_progress = 0.22f;
                ui.atmosphere_import_detected = static_cast<int>(csvs.size());
                ui.atmosphere_import_total_files = static_cast<int>(csvs.size());
                ui.atmosphere_import_current_rows = 0;
                ui.atmosphere_import_current_bytes = 0;
                ui.atmosphere_import_total_bytes = 0;
                ui.atmosphere_import_scanned_entries = 0;
                ui.atmosphere_import_import_errors = 0;
                ui.atmosphere_import_external_errors = 0;
                ui.atmosphere_import_current_file.clear();

                ui.atmosphere_import_status = "Reemplazando categoria atmosferica previa y preparando capa ligera de pines radiales.";
                ui.status = ui.atmosphere_import_status;
            }
            const int purged = temporal_purge_atmosphere_category(atmosphere_output_root_for_source(import_source),
                                                                  atmosphere_category_for_source(import_source),

                                                                  year_start,

                                                                  year_end);
            {

                std::lock_guard<std::mutex> lock(ui.mu);

                append_import_log_locked(ui, "Sobrescritura Ixiptlah atmosferica: " + std::to_string(purged) +
                    " registros previos de " + atmosphere_category_for_source(import_source) + " " +

                    std::to_string(year_start) + "-" + std::to_string(year_end) +

                    " retirados; se recompila desde CSV actuales.");
                ui.atmosphere_import_status = "Indexando encabezados y preparando pines radiales atmosfericos ligeros.";
                ui.status = ui.atmosphere_import_status;
            }

            AtmosphereFoundationOptions af;

            af.source_root = source;
            af.output_root = atmosphere_output_root_for_source(import_source);
            af.forced_source_family = atmosphere_forced_source_family_for_import_source(import_source);
            af.resume = false;

            af.max_files = 0; /* 0 = sin límite: RAMA puede venir particionada por año/contaminante/estación. */

            af.sample_lines_per_file = 40;

            af.live_flush_every_files = 1;

            af.year_start = year_start;

            af.year_end = year_end;

            auto last_live_cloud_load = std::make_shared<std::chrono::steady_clock::time_point>(std::chrono::steady_clock::now() - std::chrono::seconds(5));

            af.progress_callback = [&ui, last_live_cloud_load](int files_done, int rows_written, const std::string& phase) {
                {

                    std::lock_guard<std::mutex> lock(ui.mu);

                    const int total_files = std::max(1, ui.atmosphere_import_total_files > 0 ? ui.atmosphere_import_total_files : ui.atmosphere_import_detected);
                    ui.atmosphere_import_indexed = files_done;

                    ui.atmosphere_import_cloud_points = rows_written;

                    const float coarse = static_cast<float>(files_done) / static_cast<float>(total_files);
                    ui.atmosphere_import_progress = std::clamp(0.24f + 0.58f * coarse, 0.24f, 0.84f);

                    ui.atmosphere_import_status = phase.empty()
                        ? ("IXv1 " + std::to_string(files_done) + "/" + std::to_string(total_files) + " archivos")
                        : phase;

                    ui.import_progress_detail = ui.atmosphere_import_status;
                    ui.status = ui.atmosphere_import_status;


                    if (files_done <= 3 || files_done % 6 == 0) append_import_log_locked(ui, ui.atmosphere_import_status);
                }

                const auto now = std::chrono::steady_clock::now();

                if (std::chrono::duration_cast<std::chrono::milliseconds>(now - *last_live_cloud_load).count() >= 1200) {
                    *last_live_cloud_load = now;
                    try { load_atmospheric_clouds(ui); } catch (...) {}
                }
            };

            af.detail_progress_callback = [&ui, import_source](int files_done, int total_files, std::int64_t current_rows,
                                                              std::uint64_t bytes_done, std::uint64_t bytes_total,
                                                              const std::string& current_file, const std::string& phase,
                                                              std::uint64_t import_errors, std::uint64_t external_errors) {
                auto compact_bytes = [](std::uint64_t bytes) {
                    const char* units[] = {"B", "KB", "MB", "GB"};
                    double v = static_cast<double>(bytes);
                    int unit = 0;
                    while (v >= 1024.0 && unit < 3) { v /= 1024.0; ++unit; }
                    std::ostringstream os;
                    if (unit == 0) os << static_cast<unsigned long long>(bytes) << units[unit];
                    else os << std::fixed << std::setprecision(v >= 100.0 ? 0 : 1) << v << units[unit];
                    return os.str();
                };
                const char* source_label = import_source == 1 ? "RAMA" : (import_source == 0 ? "REDMET" : "ATM");
                const int safe_total = std::max(1, total_files);
                const double part = bytes_total > 0 ? std::clamp(static_cast<double>(bytes_done) / static_cast<double>(bytes_total), 0.0, 1.0) : 0.0;
                const double unit_progress = (static_cast<double>(std::max(0, files_done)) + part) / static_cast<double>(safe_total);

                std::ostringstream status;
                status << source_label << " IXv1 " << std::min(safe_total, std::max(0, files_done) + (current_file.empty() ? 0 : 1))
                       << '/' << safe_total;
                if (!current_file.empty()) status << " · " << compact_label(current_file, 42);
                if (bytes_total > 0) status << " · " << compact_bytes(bytes_done) << '/' << compact_bytes(bytes_total)
                                          << " · " << std::fixed << std::setprecision(0) << (part * 100.0) << "% archivo";
                if (current_rows > 0) status << " · " << current_rows << " filas";
                if (import_errors > 0 || external_errors > 0) status << " · errores i/e " << import_errors << '/' << external_errors;
                if (!phase.empty() && current_file.empty()) status << " · " << compact_label(phase, 80);

                std::lock_guard<std::mutex> lock(ui.mu);
                ui.atmosphere_import_total_files = safe_total;
                ui.atmosphere_import_detected = std::max(ui.atmosphere_import_detected, safe_total);
                ui.atmosphere_import_indexed = std::max(0, files_done);
                ui.atmosphere_import_current_rows = static_cast<long long>(std::max<std::int64_t>(0, current_rows));
                ui.atmosphere_import_current_bytes = static_cast<unsigned long long>(bytes_done);
                ui.atmosphere_import_total_bytes = static_cast<unsigned long long>(bytes_total);
                ui.atmosphere_import_current_file = current_file;
                ui.atmosphere_import_import_errors = static_cast<unsigned long long>(import_errors);
                ui.atmosphere_import_external_errors = static_cast<unsigned long long>(external_errors);
                ui.atmosphere_import_progress = std::clamp(0.24f + 0.58f * static_cast<float>(unit_progress), 0.22f, 0.84f);
                ui.atmosphere_import_status = status.str();
                ui.import_progress_detail = ui.atmosphere_import_status;
                ui.status = ui.atmosphere_import_status;
            };
            AtmosphereFoundationReport report;
            {

                std::lock_guard<std::mutex> prepare_lock(g_atmosphere_prepare_mu);
                report = AtmosphericReconstructionEngine::prepare_foundation(af);
            }

            {

                std::lock_guard<std::mutex> lock(ui.mu);
                ui.atmosphere_import_progress = 0.86f;

                ui.atmosphere_import_detected = report.discovered_files;

                ui.atmosphere_import_indexed = report.indexed_files;
                ui.atmosphere_import_total_files = report.discovered_files;
                ui.atmosphere_import_current_rows = 0;
                ui.atmosphere_import_current_bytes = 0;
                ui.atmosphere_import_total_bytes = 0;
                ui.atmosphere_import_scanned_entries = 0;
                ui.atmosphere_import_import_errors = 0;
                ui.atmosphere_import_external_errors = 0;
                ui.atmosphere_import_current_file.clear();
                ui.atmosphere_import_cloud_points = report.cloud_points;

                ui.atmosphere_import_status = "IXv1 leyendo casillas activas";
                ui.import_progress_detail = ui.atmosphere_import_status;
                ui.status = ui.atmosphere_import_status;
            }
            load_atmospheric_clouds(ui, true);
            {

                std::lock_guard<std::mutex> lock(ui.mu);
                ui.atmospheric_show_rama_stations = false;
                ui.atmosphere_importing = false;
                ui.atmosphere_import_progress = 1.0f;

                ui.atmosphere_import_detected = report.discovered_files;

                ui.atmosphere_import_indexed = report.indexed_files;
                ui.atmosphere_import_total_files = report.discovered_files;
                ui.atmosphere_import_current_rows = 0;
                ui.atmosphere_import_current_bytes = 0;
                ui.atmosphere_import_total_bytes = 0;
                ui.atmosphere_import_scanned_entries = 0;
                ui.atmosphere_import_import_errors = 0;
                ui.atmosphere_import_external_errors = 0;
                ui.atmosphere_import_current_file.clear();
                ui.atmosphere_import_cloud_points = report.cloud_points;

                ui.atmosphere_import_status = "IXv1 listo " +

                    std::to_string(report.discovered_files) + " fuentes, " +
                    std::to_string(report.cloud_points) + " puntos";

                if (report.cloud_points <= 0) {

                    ui.atmosphere_import_status += (import_source == 1)
                        ? " RAMA: revisa que la carpeta contenga los CSV horarios oficiales o subcarpetas de contaminantes con station/parameter/value."
                        : " Revisa que la carpeta tenga cat_estacion.csv y columnas date/id_station/id_parameter/valor.";
                }
                ui.status = ui.atmosphere_import_status;

                ui.map_revision.fetch_add(1, std::memory_order_relaxed);
            }

        } catch (const std::exception& e) {

            std::lock_guard<std::mutex> lock(ui.mu);
            ui.atmosphere_importing = false;
            ui.atmosphere_import_progress = 0.0f;
            ui.atmosphere_import_current_rows = 0;
            ui.atmosphere_import_current_bytes = 0;
            ui.atmosphere_import_total_bytes = 0;
            ui.atmosphere_import_scanned_entries = 0;
            ui.atmosphere_import_import_errors = 0;
            ui.atmosphere_import_external_errors = 0;
            ui.atmosphere_import_current_file.clear();

            ui.atmosphere_import_status = std::string("No pude importar CSV atmosfericos: ") + e.what();
            ui.import_progress_detail = ui.atmosphere_import_status;
            ui.status = ui.atmosphere_import_status;
        }
    });
}




bool draw_year_range_slider(const char* id, int& year_start, int& year_end, int min_year, int max_year, const ImVec4& accent, const char* caption) {

    min_year = std::min(min_year, max_year);

    max_year = std::max(min_year, max_year);

    year_start = std::clamp(year_start, min_year, max_year);

    year_end = std::clamp(year_end, min_year, max_year);

    if (year_end < year_start) std::swap(year_start, year_end);

    bool changed = false;

    const int range = std::max(1, max_year - min_year);

    
    const bool captionless_inline_track = (caption != nullptr && caption[0] == '\0');
    
    const float requested_w = std::max(1.0f, ImGui::CalcItemWidth());
    const float available_w = std::max(1.0f, ImGui::GetContentRegionAvail().x);
    const float min_track_w = captionless_inline_track ? 148.0f : 260.0f;
    const float full_w = std::max(min_track_w, std::min(available_w, requested_w));
    const float h = captionless_inline_track ? tlalpowa_import_control_height() : std::max(tlalpowa_import_control_height(), tlalpowa_import_secondary_track_height() * (1.0f + kGoldenN1));
    const char* label = caption ? caption : "Periodo";

    const std::string value_label = std::to_string(year_start) + " - " + std::to_string(year_end);

    if (!captionless_inline_track) {
        ImGui::TextDisabled("%s", label);

        ImGui::SameLine(0.0f, 8.0f);

        ImGui::TextDisabled("%s", value_label.c_str());
    }

    const ImVec2 p = ImGui::GetCursorScreenPos();

    ImGui::InvisibleButton(id, ImVec2(full_w, h));

    const bool hovered = ImGui::IsItemHovered();

    const bool active = ImGui::IsItemActive();


    ImDrawList* dl = ImGui::GetWindowDrawList();
    const float pad = std::max(3.0f, h * kGoldenN2);
    const float x0 = p.x + pad;
    const float x1 = p.x + full_w - pad;
    
    const float inline_label_h = std::max(1.0f, ImGui::GetTextLineHeight());
    const float y = captionless_inline_track
        ? p.y + std::min(h - std::max(2.0f, tlalpowa_import_track_half_thickness()),
                         std::max(inline_label_h + std::max(1.0f, h * kGoldenN8), h * kGoldenN1))
        : p.y + std::max(8.0f, h * kGoldenN2);

    const auto x_for_year = [&](int yv) {

        return x0 + (static_cast<float>(std::clamp(yv, min_year, max_year) - min_year) / static_cast<float>(range)) * (x1 - x0);
    };

    const auto year_for_x = [&](float x) {
        const float t = std::clamp((x - x0) / std::max(1.0f, x1 - x0), 0.0f, 1.0f);

        return std::clamp(static_cast<int>(std::lround(static_cast<float>(min_year) + t * static_cast<float>(range))), min_year, max_year);
    };

    float xs = x_for_year(year_start);

    float xe = x_for_year(year_end);

    const float rail_half = captionless_inline_track ? tlalpowa_import_track_half_thickness() : std::max(1.0f, h * kGoldenN8);
    const float selected_half = captionless_inline_track ? tlalpowa_import_track_half_thickness() : std::max(1.0f, h * kGoldenN7);
    dl->AddRectFilled(ImVec2(x0, y - rail_half), ImVec2(x1, y + rail_half), IM_COL32(224, 231, 239, 210), rail_half);
    dl->AddRectFilled(ImVec2(xs, y - selected_half), ImVec2(xe, y + selected_half), u32(accent, 0.62f), selected_half);

    for (int yr = min_year; yr <= max_year; ++yr) {

        const bool major = (yr == min_year || yr == max_year || ((yr - min_year) % 5 == 0));

        if (!major) continue;

        const float x = x_for_year(yr);
        const float tick_a = y + std::max(2.0f, h * kGoldenN8);
        const float tick_b = std::min(p.y + h - 1.0f, y + std::max(4.0f, h * kGoldenN4));
        dl->AddLine(ImVec2(x, tick_a), ImVec2(x, tick_b), IM_COL32(130, 138, 150, 88), 0.7f);

        if (yr == min_year || yr == max_year || (full_w > 520.0f && ((yr - min_year) % 10 == 0))) {
            char lab[8];
            std::snprintf(lab, sizeof(lab), "%d", yr);

            const ImVec2 lab_sz = ImGui::CalcTextSize(lab);
            const float label_y = captionless_inline_track
                ? p.y + std::max(0.0f, (y - p.y - lab_sz.y - std::max(1.0f, h * kGoldenN10)) * 0.5f)
                : std::min(p.y + h - lab_sz.y, y + std::max(3.0f, h * kGoldenN3));
            dl->AddText(ImVec2(x - lab_sz.x * 0.5f, label_y), IM_COL32(100, 109, 121, 174), lab);
        }
    }
    const float r = hovered || active ? std::max(4.0f, h * kGoldenN4) : std::max(3.5f, h * kGoldenN5);
    dl->AddCircleFilled(ImVec2(xs, y), r, u32(accent, 0.90f), 24);
    dl->AddCircleFilled(ImVec2(xe, y), r, u32(accent, 0.90f), 24);

    static ImGuiID active_slider = 0;
    static int active_handle = 0;

    const ImGuiID slider_id = ImGui::GetID(id);

    if (hovered && ImGui::IsMouseClicked(ImGuiMouseButton_Left)) {
        active_slider = slider_id;

        const float mx = ImGui::GetIO().MousePos.x;
        active_handle = (std::fabs(mx - xs) <= std::fabs(mx - xe)) ? 1 : 2;
    }

    if (active && active_slider == slider_id && active_handle != 0) {

        int target = year_for_x(ImGui::GetIO().MousePos.x);

        if (active_handle == 1) {

            if (target > year_end) {

                year_start = year_end;

                year_end = target;
                active_handle = 2;
            } else {

                year_start = target;
            }
        } else {

            if (target < year_start) {

                year_end = year_start;

                year_start = target;
                active_handle = 1;
            } else {

                year_end = target;
            }
        }

        year_start = std::clamp(year_start, min_year, max_year);

        year_end = std::clamp(year_end, min_year, max_year);

        if (year_end < year_start) std::swap(year_start, year_end);
        changed = true;
    }

    if (!ImGui::IsMouseDown(ImGuiMouseButton_Left) && active_slider == slider_id) {

        active_slider = 0;
        active_handle = 0;
    }

    if (hovered) ImGui::SetTooltip("Arrastra inicio o fin en una sola barra.");

    return changed;
}




bool draw_year_range_slider_recent_first(const char* id, int& year_oldest, int& year_newest, int min_year, int max_year, const ImVec4& accent, const char* caption) {

    min_year = std::min(min_year, max_year);
    max_year = std::max(min_year, max_year);
    year_oldest = std::clamp(year_oldest, min_year, max_year);
    year_newest = std::clamp(year_newest, min_year, max_year);
    if (year_newest < year_oldest) std::swap(year_oldest, year_newest);

    bool changed = false;
    const int range = std::max(1, max_year - min_year);
    const bool captionless_inline_track = (caption != nullptr && caption[0] == '\0');
    const float requested_w = std::max(1.0f, ImGui::CalcItemWidth());
    const float available_w = std::max(1.0f, ImGui::GetContentRegionAvail().x);
    const float min_track_w = captionless_inline_track ? 148.0f : 260.0f;
    const float full_w = std::max(min_track_w, std::min(available_w, requested_w));
    const float h = captionless_inline_track ? tlalpowa_import_control_height() : std::max(tlalpowa_import_control_height(), tlalpowa_import_secondary_track_height() * (1.0f + kGoldenN1));
    const char* label = caption ? caption : "Periodo";

    const std::string value_label = std::to_string(year_newest) + " -> " + std::to_string(year_oldest);
    if (!captionless_inline_track) {
        ImGui::TextDisabled("%s", label);
        ImGui::SameLine(0.0f, 8.0f);
        ImGui::TextDisabled("%s", value_label.c_str());
    }

    const ImVec2 p = ImGui::GetCursorScreenPos();
    ImGui::InvisibleButton(id, ImVec2(full_w, h));
    const bool hovered = ImGui::IsItemHovered();
    const bool active = ImGui::IsItemActive();

    ImDrawList* dl = ImGui::GetWindowDrawList();
    const float pad = std::max(3.0f, h * kGoldenN2);
    const float x0 = p.x + pad;
    const float x1 = p.x + full_w - pad;
    const float inline_label_h = std::max(1.0f, ImGui::GetTextLineHeight());
    const float y = captionless_inline_track
        ? p.y + std::min(h - std::max(2.0f, tlalpowa_import_track_half_thickness()),
                         std::max(inline_label_h + std::max(1.0f, h * kGoldenN8), h * kGoldenN1))
        : p.y + std::max(8.0f, h * kGoldenN2);

    const auto x_for_year = [&](int yv) {
        return x0 + (static_cast<float>(max_year - std::clamp(yv, min_year, max_year)) / static_cast<float>(range)) * (x1 - x0);
    };
    const auto year_for_x = [&](float x) {
        const float t = std::clamp((x - x0) / std::max(1.0f, x1 - x0), 0.0f, 1.0f);
        return std::clamp(static_cast<int>(std::lround(static_cast<float>(max_year) - t * static_cast<float>(range))), min_year, max_year);
    };

    float x_new = x_for_year(year_newest);
    float x_old = x_for_year(year_oldest);
    if (x_old < x_new) std::swap(x_old, x_new);

    const float rail_half = captionless_inline_track ? tlalpowa_import_track_half_thickness() : std::max(1.0f, h * kGoldenN8);
    const float selected_half = captionless_inline_track ? tlalpowa_import_track_half_thickness() : std::max(1.0f, h * kGoldenN7);
    dl->AddRectFilled(ImVec2(x0, y - rail_half), ImVec2(x1, y + rail_half), IM_COL32(224, 231, 239, 210), rail_half);
    dl->AddRectFilled(ImVec2(x_new, y - selected_half), ImVec2(x_old, y + selected_half), u32(accent, 0.62f), selected_half);

    for (int yr = min_year; yr <= max_year; ++yr) {
        const bool major = (yr == min_year || yr == max_year || ((yr - min_year) % 5 == 0));
        if (!major) continue;
        const float x = x_for_year(yr);
        const float tick_a = y + std::max(2.0f, h * kGoldenN8);
        const float tick_b = std::min(p.y + h - 1.0f, y + std::max(4.0f, h * kGoldenN4));
        dl->AddLine(ImVec2(x, tick_a), ImVec2(x, tick_b), IM_COL32(130, 138, 150, 88), 0.7f);
        if (yr == min_year || yr == max_year || (full_w > 520.0f && ((yr - min_year) % 10 == 0))) {
            char lab[8];
            std::snprintf(lab, sizeof(lab), "%d", yr);
            const ImVec2 lab_sz = ImGui::CalcTextSize(lab);
            const float label_y = captionless_inline_track
                ? p.y + std::max(0.0f, (y - p.y - lab_sz.y - std::max(1.0f, h * kGoldenN10)) * 0.5f)
                : std::min(p.y + h - lab_sz.y, y + std::max(3.0f, h * kGoldenN3));
            dl->AddText(ImVec2(x - lab_sz.x * 0.5f, label_y), IM_COL32(100, 109, 121, 174), lab);
        }
    }

    const float r = hovered || active ? std::max(4.0f, h * kGoldenN4) : std::max(3.5f, h * kGoldenN5);
    const float x_new_handle = x_for_year(year_newest);
    const float x_old_handle = x_for_year(year_oldest);
    dl->AddCircleFilled(ImVec2(x_new_handle, y), r, u32(accent, 0.90f), 24);
    dl->AddCircleFilled(ImVec2(x_old_handle, y), r, u32(accent, 0.90f), 24);

    static ImGuiID active_slider = 0;
    static int active_handle = 0; // 1 = nuevo, 2 = antiguo
    const ImGuiID slider_id = ImGui::GetID(id);

    if (hovered && ImGui::IsMouseClicked(ImGuiMouseButton_Left)) {
        active_slider = slider_id;
        const float mx = ImGui::GetIO().MousePos.x;
        active_handle = (std::fabs(mx - x_new_handle) <= std::fabs(mx - x_old_handle)) ? 1 : 2;
    }

    if (active && active_slider == slider_id && active_handle != 0) {
        int target = year_for_x(ImGui::GetIO().MousePos.x);
        if (active_handle == 1) {
            year_newest = std::max(target, year_oldest);
        } else {
            year_oldest = std::min(target, year_newest);
        }
        year_oldest = std::clamp(year_oldest, min_year, max_year);
        year_newest = std::clamp(year_newest, min_year, max_year);
        if (year_newest < year_oldest) std::swap(year_oldest, year_newest);
        changed = true;
    }

    if (!ImGui::IsMouseDown(ImGuiMouseButton_Left) && active_slider == slider_id) {
        active_slider = 0;
        active_handle = 0;
    }

    if (hovered) ImGui::SetTooltip("RUOA descarga de reciente a antiguo: %d -> %d", year_newest, year_oldest);
    return changed;
}




