int external_source_count() {

    return static_cast<int>(external_data_source_registry().size());
}



const ExternalDataSourceSpec& external_source_spec(int source) {
    const auto& v = external_data_source_registry();
    const int idx = std::clamp(source, 0, std::max(0, static_cast<int>(v.size()) - 1));

    return v[static_cast<size_t>(idx)];
}



fs::path external_download_root() {

    return datos_externos_root() / "Fuentes_Datos";
}



fs::path external_source_root(int source) {
    const auto& spec = external_source_spec(source);

    return external_download_root() / fs::path(widen_utf8(spec.folder));
}



fs::path selected_external_source_root_for_mode(int source, bool from_web) {
    (void)from_web;

    return external_source_root(source);
}



fs::path resolve_external_input_root(const UiState& ui) {

    if (!ui.external_from_web && ui.external_dir_custom && !ui.local_external_dir.empty()) {

        return resolve_existing_path_relaxed(ui.local_external_dir);
    }

    return resolve_existing_path_relaxed(selected_external_source_root_for_mode(ui.external_source, ui.external_from_web));
}



bool is_supported_external_source_file(const fs::path& p) {

    const std::string ext = lower_ascii(path_utf8(p.extension()));

    return ext == ".csv" || ext == ".tsv" || ext == ".txt" || ext == ".json" || ext == ".jsonl" || ext == ".geojson" ||
           ext == ".nc" || ext == ".nc4" || ext == ".cdf" || ext == ".grib" || ext == ".grib2" || ext == ".grb" || ext == ".grb2" ||
           ext == ".hdf" || ext == ".h5" || ext == ".hdf5" || ext == ".he5" || ext == ".he4" ||
           ext == ".tif" || ext == ".tiff" || ext == ".geotiff" || ext == ".shp" || ext == ".shx" || ext == ".dbf" || ext == ".prj" ||
           ext == ".gpkg" || ext == ".gdb" || ext == ".kml" || ext == ".kmz" || ext == ".zip" || ext == ".xlsx" || ext == ".xls" || ext == ".ods" ||
           ext == ".parquet" || ext == ".feather" || ext == ".pbf" || ext == ".pdf" || ext == ".cpg";
}



bool is_tlalpowa_external_metadata_file(const fs::path& p) {



    const std::string name = normalize_key(path_utf8(p.filename()));

    const std::string full = normalize_key(path_utf8(p));

    if (full.find("/_metadatos/") != std::string::npos || full.find("\\_metadatos\\") != std::string::npos) return true;

    return name.find("_tlalpowa_recipe") != std::string::npos ||
           name.find("_catalog.") != std::string::npos ||
           name.find("_ckan_package_show") != std::string::npos ||

           name.find("_download_audit") != std::string::npos ||

           name == "fuentes_datos_descargables_manifest.json";
}


std::vector<fs::path> list_external_sources_recursive_limited(const fs::path& root, size_t limit = 0) {

    std::vector<fs::path> files;
    std::error_code ec;

    if (root.empty() || !fs::exists(root, ec) || ec) return files;

    for (fs::recursive_directory_iterator it(root, fs::directory_options::skip_permission_denied, ec), end; it != end; it.increment(ec)) {

        if (ec) { ec.clear(); continue; }
        std::error_code item_ec;

        if (!it->is_regular_file(item_ec) || item_ec) continue;

        if (!is_supported_external_source_file(it->path())) continue;

        if (is_tlalpowa_external_metadata_file(it->path())) continue;

        files.push_back(it->path());

        if (limit > 0 && files.size() >= limit) break;
    }

    std::sort(files.begin(), files.end(), [](const fs::path& a, const fs::path& b) { return path_utf8(a) < path_utf8(b); });

    return files;
}




