nlohmann::json external_source_manifest_json(int source, const fs::path& root, bool from_web, int year_start, int year_end) {
    const auto& spec = external_source_spec(source);

    nlohmann::json j;

    j["schema_version"] = "tlalpowa.external_source.v1";
    j["created_at_utc"] = now_utc_iso();
    j["source_index"] = source;
    j["id"] = spec.id;

    j["category"] = spec.category;
    j["label"] = spec.label;
    j["domain"] = spec.domain;
    j["provider"] = spec.provider;
    j["formats"] = spec.formats;

    j["documentation_url"] = spec.documentation_url;

    j["catalog_url"] = spec.catalog_url;
    j["requires_account_or_api_key"] = spec.requires_account;

    j["min_year"] = spec.min_year;

    j["year_start"] = year_start;

    j["year_end"] = year_end;

    j["raw_root"] = path_utf8(root);

    j["ixiptlah_root"] = path_utf8(datos_root());
    j["import_mode"] = from_web ? "web_catalog_or_recipe" : "local_inventory";
    j["note"] = spec.note;
    j["derivable_products"] = external_derivable_products_for_domain(spec.domain, spec.id);
    j["non_regression_contract"] = "La fuente se inventaria sin borrar crudo, sin reemplazar RAMA/PDF/movilidad/satelital estable y sin activar capas visuales automaticamente.";

    return j;
}




void write_external_download_scripts(int source, const fs::path& root, int year_start, int year_end) {
    const auto& spec = external_source_spec(source);

    const std::string id = normalize_key(spec.id);

    const fs::path scripts = root / "_metadatos" / "scripts_descarga";
    ensure_dir(scripts);

    if (id == "sentinel5p_tropomi") {
        const std::string bat =
            "@echo off\r\n"
            "REM Descarga Sentinel-5P por OData oficial de Copernicus Data Space.\r\n"
            "REM Requiere ACCESS_TOKEN ya generado; Tlalpowa tambien puede usar TLALPOWA_CDSE_ACCESS_TOKEN.\r\n"
            "set PRODUCT_ID=<PEGAR_UUID_PRODUCTO_ODATA>\r\n"

            "set ACCESS_TOKEN=<PEGAR_TOKEN_CDSE>\r\n"

            "curl -H \"Authorization: Bearer %ACCESS_TOKEN%\" \"https://download.dataspace.copernicus.eu/odata/v1/Products(%PRODUCT_ID%)/$value\" --location-trusted --output sentinel5p_producto.nc\r\n";

        (void)write_text_file_atomic(scripts / "descargar_sentinel5p_odata.cmd", bat);
    }

    if (id.find("modis") != std::string::npos || id.find("landsat") != std::string::npos) {
        const std::string cmd =
            "@echo off\r\n"
            "REM Descarga NASA Earthdata/LAADS. Use .netrc o token Bearer segun el DAAC.\r\n"
            "REM Tlalpowa usa TLALPOWA_NASA_EARTHDATA_TOKEN, TLALPOWA_LAADS_TOKEN o TLALPOWA_EARTHDATA_USE_NETRC=1.\r\n"

            "set URL=<PEGAR_URL_DE_GRANULO_CMR>\r\n"
            "set TOKEN=<PEGAR_TOKEN_SI_APLICA>\r\n"

            "curl --location-trusted --header \"Authorization: Bearer %TOKEN%\" \"%URL%\" --output granulo_descargado.hdf\r\n";

        (void)write_text_file_atomic(scripts / "descargar_nasa_earthdata.cmd", cmd);
    }

    if (id == "nasa_firms") {
        const std::string cmd =
            "@echo off\r\n"

            "REM Descarga FIRMS Area API en CSV para ZMVM.\r\n"

            "set MAP_KEY=<PEGAR_FIRMS_MAP_KEY>\r\n"

            "curl \"https://firms.modaps.eosdis.nasa.gov/api/area/csv/%MAP_KEY%/VIIRS_SNPP_NRT/-99.7,18.8,-98.6,20.2/5\" --output firms_zmvm_viirs.csv\r\n";

        (void)write_text_file_atomic(scripts / "descargar_firms_zmvm.cmd", cmd);
    }

    if (id.find("era5") != std::string::npos || id.find("cams") != std::string::npos) {
        std::ostringstream py;
        py << "# Descarga CDS/ADS para Tlalpowa. Requiere cdsapi y credenciales aceptadas en ~/.cdsapirc.\n";
        py << "# Ajuste variables/mes/dia/hora antes de ejecutar.\n";
        py << "import cdsapi\n";
        py << "c = cdsapi.Client()\n";

        if (id == "era5_land") py << "dataset = 'reanalysis-era5-land'\n";

        else if (id == "cams_eac4") py << "dataset = 'cams-global-reanalysis-eac4'\n";
        else py << "dataset = 'reanalysis-era5-single-levels'\n";
        py << "request = {\n";
        py << "    'product_type': ['reanalysis'],\n";
        py << "    'variable': ['2m_temperature', 'surface_pressure', '10m_u_component_of_wind', '10m_v_component_of_wind', 'total_precipitation'],\n";

        py << "    'year': ['" << std::max(year_start, year_end) << "'],\n";

        py << "    'month': ['01'],\n";
        py << "    'day': ['01'],\n";

        py << "    'time': ['00:00', '06:00', '12:00', '18:00'],\n";

        py << "    'data_format': 'netcdf',\n";
        py << "    'area': [20.2, -99.7, 18.8, -98.6],\n";
        py << "}\n";
        py << "c.retrieve(dataset, request, 'tlalpowa_cds_zmvm.nc')\n";

        (void)write_text_file_atomic(scripts / "descargar_cds_zmvm.py", py.str());
    }
}



bool write_external_registry_catalog_file() {

    nlohmann::json j;

    j["schema_version"] = "tlalpowa.external_registry.v1";
    j["generated_at_utc"] = now_utc_iso();

    j["raw_root"] = path_utf8(external_download_root());

    j["sources"] = nlohmann::json::array();
    int i = 0;

    for (const auto& spec : external_data_source_registry()) {

        nlohmann::json row;

        row["index"] = i++;

        row["id"] = spec.id;

        row["category"] = spec.category;

        row["label"] = spec.label;

        row["domain"] = spec.domain;

        row["provider"] = spec.provider;


        row["formats"] = spec.formats;

        row["folder"] = spec.folder;

        row["documentation_url"] = spec.documentation_url;

        row["catalog_url"] = spec.catalog_url;

        row["requires_account_or_api_key"] = spec.requires_account;

        row["min_year"] = spec.min_year;

        row["note"] = spec.note;

        row["derivable_products"] = external_derivable_products_for_domain(spec.domain, spec.id);

        j["sources"].push_back(row);
    }

    return write_text_file_atomic(external_catalog_manifest_path(), j.dump(2) + "\n");
}




std::string url_origin_from_url(const std::string& url) {

    const size_t scheme = url.find("://");

    if (scheme == std::string::npos) return std::string();
    const size_t start = scheme + 3;

    const size_t slash = url.find('/', start);

    return slash == std::string::npos ? url : url.substr(0, slash);
}



std::string url_query_stripped(const std::string& url) {

    const size_t q = url.find('?');

    return q == std::string::npos ? url : url.substr(0, q);
}



std::string ckan_dataset_id_from_url(const std::string& url) {



    const std::string u = url_query_stripped(url);
    const std::string needle = "/dataset/";

    const size_t pos = normalize_key(u).find(needle);

    if (pos == std::string::npos) return std::string();
    size_t start = pos + needle.size();

    size_t end = u.find('/', start);
    std::string id = end == std::string::npos ? u.substr(start) : u.substr(start, end - start);

    return safe_filename(html_entity_decode_basic(id));
}



std::vector<std::string> ckan_package_show_candidates(const std::string& dataset_url) {

    std::vector<std::string> out;

    const std::string origin = url_origin_from_url(dataset_url);

    const std::string id = ckan_dataset_id_from_url(dataset_url);

    if (origin.empty() || id.empty()) return out;

    out.push_back(origin + "/api/3/action/package_show?id=" + id);

    out.push_back(origin + "/es/api/3/action/package_show?id=" + id);

    return out;
}



