        add("https://datos.cdmx.gob.mx/api/3/action/package_show?id=afluencia-diaria-de-la-red-de-transporte-de-pasajeros");

        add("https://datos.cdmx.gob.mx/api/3/action/package_show?id=afluencia-diaria-servicio-de-transportes-electricos");

