// Sección de salida duplicada retirada: la aplicación ya no expone un
// árbol paralelo sin persistencia propia. Las únicas salidas vivas quedan en los flujos reales
// que sí consume el usuario: IXIPTLAH, cachés de render y descarga CSV puntual
// desde gráficas. No reintroducir un árbol exportable separado sin escribir
// primero una ruta persistente real; de lo contrario sólo vuelve a duplicar
// estado visual y a producir funciones muertas.




void apply_window_icon(GLFWwindow* window) {

    if (!window) return;



    const fs::path png = first_existing_path({
        workspace_root() / "Datos" / "icon" / "tlalpowa.png",
        executable_dir() / "Datos" / "icon" / "tlalpowa.png"
    });

    if (!png.empty()) {

        std::ifstream in(png, std::ios::binary);

        if (in) {

            std::vector<unsigned char> bytes((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());

            if (!bytes.empty() && bytes.size() <= static_cast<size_t>(std::numeric_limits<int>::max())) {
                int w = 0, h = 0, channels = 0;

                unsigned char* pixels = stbi_load_from_memory(bytes.data(), static_cast<int>(bytes.size()), &w, &h, &channels, 4);

                if (pixels && w > 0 && h > 0) {
                    (void)system_light_theme();
                    // Icono de ventana fijado en guinda Tlalpowa; no depende del tema
                    // para evitar que Windows/GLFW lo vuelva gris en la barra superior.
                    constexpr unsigned char r = 159u;
                    constexpr unsigned char g = 34u;
                    constexpr unsigned char b = 65u;
                    const std::uint64_t px_count = static_cast<std::uint64_t>(w) * static_cast<std::uint64_t>(h);
                    if (px_count <= 4096ull * 4096ull) {
                        for (std::uint64_t i = 0; i < px_count; ++i) {
                            unsigned char* px = pixels + i * 4ull;
                            if (px[3] == 0u) continue;
                            px[0] = r; px[1] = g; px[2] = b;
                        }
                    }
                    GLFWimage image{};
                    image.width = w;
                    image.height = h;

                    image.pixels = pixels;
                    glfwSetWindowIcon(window, 1, &image);
                }

                if (pixels) stbi_image_free(pixels);
            }
        }
    }

#ifdef _WIN32
    HWND hwnd = glfwGetWin32Window(window);

    if (!hwnd) return;

    constexpr int kTlalpowaIconResourceId = 101;

    const fs::path ico = first_existing_path({
        workspace_root() / "Fuente" / "Tlalpowa.ico",
        executable_dir() / "Fuente" / "Tlalpowa.ico"
    });

    auto load_native_icon = [&](int size) -> HICON {

        if (!ico.empty()) {
            std::error_code ec;

            if (fs::exists(ico, ec) && !ec) {

                if (HICON from_file = reinterpret_cast<HICON>(LoadImageW(nullptr, ico.wstring().c_str(), IMAGE_ICON, size, size, LR_LOADFROMFILE))) {

                    return from_file;
                }
            }
        }
        HINSTANCE instance = GetModuleHandleW(nullptr);

        if (!instance) return nullptr;

        return reinterpret_cast<HICON>(LoadImageW(instance, MAKEINTRESOURCEW(kTlalpowaIconResourceId), IMAGE_ICON, size, size, LR_DEFAULTCOLOR));
    };

    HICON big_icon = load_native_icon(256);
    HICON small_icon = load_native_icon(32);

    if (big_icon) {
        SendMessageW(hwnd, WM_SETICON, ICON_BIG, reinterpret_cast<LPARAM>(big_icon));

        SetClassLongPtrW(hwnd, GCLP_HICON, reinterpret_cast<LONG_PTR>(big_icon));
    }

    if (small_icon) {
        SendMessageW(hwnd, WM_SETICON, ICON_SMALL, reinterpret_cast<LPARAM>(small_icon));

        SetClassLongPtrW(hwnd, GCLP_HICONSM, reinterpret_cast<LONG_PTR>(small_icon));
    }
#endif
}




