bool point_in_polygon(const ImVec2& p, const std::vector<ImVec2>& poly) {
    bool inside = false;

    if (poly.size() < 3) return false;

    for (size_t i = 0, j = poly.size() - 1; i < poly.size(); j = i++) {
        const ImVec2& a = poly[i];
        const ImVec2& b = poly[j];
        float denom = b.y - a.y;

        if (std::abs(denom) < 0.0001f) denom = denom < 0.0f ? -0.0001f : 0.0001f;
        const bool crosses = ((a.y > p.y) != (b.y > p.y)) &&

            (p.x < (b.x - a.x) * (p.y - a.y) / denom + a.x);

        if (crosses) inside = !inside;
    }

    return inside;
}



ImVec2 polygon_center(const std::vector<ImVec2>& poly) {
    ImVec2 c(0, 0);

    if (poly.empty()) return c;

    for (const auto& p : poly) {
        c.x += p.x;
        c.y += p.y;
    }
    c.x /= static_cast<float>(poly.size());
    c.y /= static_cast<float>(poly.size());

    return c;
}



double polygon_screen_area(const std::vector<ImVec2>& poly) {

    if (poly.size() < 3) return 0.0;
    double a = 0.0;

    for (size_t i = 0, j = poly.size() - 1; i < poly.size(); j = i++) {
        a += static_cast<double>(poly[j].x) * poly[i].y - static_cast<double>(poly[i].x) * poly[j].y;
    }

    return std::abs(a) * 0.5;
}



ImVec2 polygon_centroid_area(const std::vector<ImVec2>& poly) {
    double cross_sum = 0.0;
    double cx = 0.0;
    double cy = 0.0;

    if (poly.size() < 3) return polygon_center(poly);

    for (size_t i = 0, j = poly.size() - 1; i < poly.size(); j = i++) {
        const double cross = static_cast<double>(poly[j].x) * poly[i].y - static_cast<double>(poly[i].x) * poly[j].y;
        cross_sum += cross;
        cx += (static_cast<double>(poly[j].x) + poly[i].x) * cross;
        cy += (static_cast<double>(poly[j].y) + poly[i].y) * cross;
    }

    if (std::abs(cross_sum) < 0.0001) return polygon_center(poly);

    return ImVec2(static_cast<float>(cx / (3.0 * cross_sum)), static_cast<float>(cy / (3.0 * cross_sum)));
}



float distance_to_segment(const ImVec2& p, const ImVec2& a, const ImVec2& b) {
    const float vx = b.x - a.x;

    const float vy = b.y - a.y;
    const float wx = p.x - a.x;
    const float wy = p.y - a.y;
    const float len2 = vx * vx + vy * vy;
    const float t = len2 <= 0.0001f ? 0.0f : std::clamp((wx * vx + wy * vy) / len2, 0.0f, 1.0f);
    const float dx = p.x - (a.x + t * vx);
    const float dy = p.y - (a.y + t * vy);

    return std::sqrt(dx * dx + dy * dy);
}



float distance_to_polygon_edge(const ImVec2& p, const std::vector<ImVec2>& poly) {
    float best = std::numeric_limits<float>::max();

    for (size_t i = 0, j = poly.size() - 1; i < poly.size(); j = i++) {
        best = std::min(best, distance_to_segment(p, poly[j], poly[i]));
    }

    return best;
}



ImVec2 best_label_point(const std::vector<ImVec2>& poly) {
    const ImVec2 centroid = polygon_centroid_area(poly);

    if (poly.empty()) return ImVec2(0, 0);
    ImVec2 minp = poly.front();
    ImVec2 maxp = poly.front();

    for (const auto& p : poly) {
        minp.x = std::min(minp.x, p.x); minp.y = std::min(minp.y, p.y);
        maxp.x = std::max(maxp.x, p.x); maxp.y = std::max(maxp.y, p.y);
    }
    ImVec2 best = point_in_polygon(centroid, poly) ? centroid : polygon_center(poly);
    float best_score = point_in_polygon(best, poly) ? distance_to_polygon_edge(best, poly) : -1.0f;
    constexpr int grid = 15;

    for (int iy = 0; iy < grid; ++iy) {

        for (int ix = 0; ix < grid; ++ix) {
            const ImVec2 p(
                minp.x + (maxp.x - minp.x) * (static_cast<float>(ix) + 0.5f) / static_cast<float>(grid),
                minp.y + (maxp.y - minp.y) * (static_cast<float>(iy) + 0.5f) / static_cast<float>(grid));

            if (!point_in_polygon(p, poly)) continue;
            const float score = distance_to_polygon_edge(p, poly);

            if (score > best_score) {
                best_score = score;
                best = p;
            }
        }
    }

    return best;
}


std::string compact_label(std::string s, size_t max_len = 18) {
    s = trim(std::move(s));

    if (s.size() <= max_len) return s;

    return s.substr(0, max_len - 1) + ".";
}



std::string compact_number(int64_t value) {
    const double v = static_cast<double>(value);
    std::ostringstream os;

    if (std::llabs(value) >= 1000000) {

        os << std::fixed << std::setprecision(1) << (v / 1000000.0) << "M";

    } else if (std::llabs(value) >= 1000) {

        os << std::fixed << std::setprecision(1) << (v / 1000.0) << "k";
    } else {
        os << value;
    }

    return os.str();
}




std::string sidebar_title_case_label(const std::string& raw) {
    
    std::string out;
    out.reserve(raw.size());
    bool word_start = true;
    for (unsigned char ch : raw) {
        const bool ascii_alpha = std::isalpha(ch) != 0;
        const bool ascii_digit = std::isdigit(ch) != 0;
        if (ascii_alpha) {
            out.push_back(static_cast<char>(word_start ? std::toupper(ch) : std::tolower(ch)));
            word_start = false;
        } else {
            out.push_back(static_cast<char>(ch));
            word_start = !(ascii_digit || ch == '.' || ch == '_');
        }
    }

    static const std::vector<std::pair<std::string, std::string>> acronym_repairs = {
        {"Cdmx", "CDMX"}, {"Repsa", "REPSA"}, {"Rama", "RAMA"}, {"Redma", "REDMA"},
        {"Rtp", "RTP"}, {"Uv", "UV"}, {"Pm10", "PM10"}, {"Pm2.5", "PM2.5"},
        {"Pm10-2.5", "PM10-2.5"}, {"No2", "NO2"}, {"So2", "SO2"}, {"Co2", "CO2"},
        {"Co", "CO"}, {"O3", "O3"}, {"Nox", "NOx"}, {"Hcho", "HCHO"}, {"Nh3", "NH3"},
        {"H2s", "H2S"}, {"Ndvi", "NDVI"}, {"Evi", "EVI"}, {"Aod", "AOD"}, {"Uvai", "UVAI"}
    };
    for (const auto& repair : acronym_repairs) {
        size_t pos = 0;
        while ((pos = out.find(repair.first, pos)) != std::string::npos) {
            out.replace(pos, repair.first.size(), repair.second);
            pos += repair.second.size();
        }
    }
    return out;
}

std::string sidebar_display_label(const std::string& raw, size_t max_chars = 36) {
    
    return compact_label(sidebar_title_case_label(raw), max_chars);
}

