float hue_to_rgb_component(float p, float q, float t) {

    if (t < 0.0f) t += 1.0f;

    if (t > 1.0f) t -= 1.0f;

    if (t < 1.0f / 6.0f) return p + (q - p) * 6.0f * t;

    if (t < 1.0f / 2.0f) return q;

    if (t < 2.0f / 3.0f) return p + (q - p) * (2.0f / 3.0f - t) * 6.0f;

    return p;
}


ImVec4 pastel_hsl(float hue_degrees, float saturation = 0.62f, float lightness = 0.70f) {
    float h = std::fmod(hue_degrees, 360.0f);

    if (h < 0.0f) h += 360.0f;
    h /= 360.0f;
    const float s = std::clamp(saturation, 0.0f, 1.0f);
    const float l = std::clamp(lightness, 0.0f, 1.0f);

    if (s <= 0.0001f) return ImVec4(l, l, l, 1.0f);
    const float q = l < 0.5f ? l * (1.0f + s) : l + s - l * s;
    const float p = 2.0f * l - q;

    return ImVec4(
        hue_to_rgb_component(p, q, h + 1.0f / 3.0f),

        hue_to_rgb_component(p, q, h),
        hue_to_rgb_component(p, q, h - 1.0f / 3.0f),
        1.0f);
}



float tlalpowa_equidistant_hue(size_t index, size_t count, float phase_degrees) {
    
    if (count == 0) return 0.0f;
    float hue = phase_degrees + (360.0f * static_cast<float>(index)) / static_cast<float>(count);
    hue = std::fmod(hue, 360.0f);
    if (hue < 0.0f) hue += 360.0f;
    return hue;
}

