int sidebar_group_nominal_burden(const std::string& group) {
    const std::string key = group.empty() ? "sin_categoria" : group;
    if (key == "no_transmisibles") return 40;
    if (key == "prevenibles_vacunacion") return 17;
    if (key == "vectores" || key == "zoonoticas_vectores") return 16;
    if (key == "digestivas" || key == "otras_enfermedades_transmisibles" || key == "otras_transmisibles") return 13;
    if (key == "transmision_sexual") return 12;
    if (key == "accidentes") return 10;
    if (key == "respiratorias") return 7;
    if (key == "zoonosis") return 6;
    if (key == "defectos_nacer" || key == "nutricion" || key == "enfermedades_bajo_vigilancia_sindromatica") return 5;
    if (key == "neurologicas_salud_mental" || key == "salud_mental") return 3;
    if (key == "otras_enfermedades_exantematicas") return 2;
    return 1;
}

bool sidebar_epidemiology_group_key_known(const std::string& group) {
    const std::string key = group.empty() ? "sin_categoria" : group;
    static const std::set<std::string> groups = {
        "accidentes", "defectos_nacer", "digestivas", "enfermedades_bajo_vigilancia_sindromatica",
        "neurologicas_salud_mental", "no_transmisibles", "nutricion", "otras_enfermedades_exantematicas",
        "otras_enfermedades_transmisibles", "otras_transmisibles", "prevenibles_vacunacion", "respiratorias",
        "transmision_sexual", "vectores", "zoonosis", "zoonoticas_vectores", "salud_mental"
    };
    return groups.count(key) > 0;
}

float sidebar_group_importance01(const std::string& group) {
    const std::string key = group.empty() ? "sin_categoria" : group;
    if (sidebar_epidemiology_group_key_known(key)) {
        return std::clamp((static_cast<float>(sidebar_group_nominal_burden(key)) - 1.0f) / 39.0f, 0.0f, 1.0f);
    }
    if (key == "contaminantes_atmosfericos" || key == "atmosfericos" || key == "contaminante_criterio") return 0.92f;
    if (key.find("gas") != std::string::npos || key.find("aerosol") != std::string::npos || key.find("carbono") != std::string::npos || key.find("metal") != std::string::npos || key == "cov") return 0.78f;
    if (key == "meteorologicos" || key == "meteorologico" || key == "radiacion" || key == "superficie") return 0.62f;
    if (key == "demograficos" || key == "historicos" || key == "movilidad" || key == "movilidad_sistemas") return 0.46f;
    return key == "sin_categoria" ? 0.0f : 0.38f;
}

float sidebar_member_importance01(const std::string& id, const std::string& group) {
    const std::string g = group.empty() ? "sin_categoria" : group;
    const std::string k = normalize_key(id + " " + g);

    if (k.find("pm25") != std::string::npos || k.find("pm2_5") != std::string::npos || k.find("particulas_pm2") != std::string::npos) return 1.00f;
    if (k.find("pm10") != std::string::npos || k.find("ozono") != std::string::npos || k.find("o3") != std::string::npos) return 0.96f;
    if (k.find("dioxido_de_nitrogeno") != std::string::npos || k.find("no2") != std::string::npos || k.find("nox") != std::string::npos) return 0.92f;
    if (k.find("dioxido_de_azufre") != std::string::npos || k.find("so2") != std::string::npos || k.find("monoxido_de_carbono") != std::string::npos || k.find(" co") != std::string::npos) return 0.88f;
    if (k.find("plomo") != std::string::npos || k.find("arsenico") != std::string::npos || k.find("cadmio") != std::string::npos || k.find("mercurio") != std::string::npos) return 0.84f;
    if (k.find("benceno") != std::string::npos || k.find("formaldehido") != std::string::npos || k.find("tolueno") != std::string::npos || k.find("xileno") != std::string::npos) return 0.80f;
    if (k.find("temperatura") != std::string::npos || k.find("precipitacion") != std::string::npos || k.find("humedad") != std::string::npos || k.find("viento") != std::string::npos) return 0.72f;
    if (k.find("presion") != std::string::npos || k.find("uv") != std::string::npos || k.find("radiacion") != std::string::npos || k.find("capa_limite") != std::string::npos) return 0.64f;

    const float group_i = sidebar_group_importance01(g);
    const std::string token = g + "|" + (id.empty() ? "unknown" : id);
    const uint64_t h = ozmvm_fnv1a64_u64(token.data(), token.size()) >> 17;
    const float local = static_cast<float>(h % 9u) / 8.0f;
    return std::clamp(group_i * 0.72f + local * 0.22f, 0.0f, 1.0f);
}

float group_saturation_for_sidebar(const std::string& group) {
    const std::string key = group.empty() ? "sin_categoria" : group;
    if (key == "sin_categoria") return 0.12f;
    const float importance = sidebar_group_importance01(key);
    float base = 0.58f;
    if (key.find("metal") != std::string::npos || key.find("aerosol") != std::string::npos || key.find("carbono") != std::string::npos || key == "cov") base = 0.60f;
    if (key == "meteorologico" || key == "meteorologicos" || key == "superficie") base = 0.55f;
    if (sidebar_epidemiology_group_key_known(key)) base = 0.64f;
    return std::clamp(base + importance * 0.10f, 0.18f, 0.78f);
}

float group_lightness_for_sidebar(const std::string& group) {
    const std::string key = group.empty() ? "sin_categoria" : group;
    if (key == "sin_categoria") return 0.62f;
    const float importance = sidebar_group_importance01(key);
    return std::clamp(0.56f - importance * 0.22f, 0.32f, 0.62f);
}

ImVec4 group_color_vec(const std::string& group) {
    const std::string key = group.empty() ? "sin_categoria" : group;
    if (key == "sin_categoria") return ImVec4(0.64f, 0.67f, 0.71f, 1.0f);
    return pastel_hsl(group_hue_degrees(key), group_saturation_for_sidebar(key), group_lightness_for_sidebar(key));
}

ImVec4 tonal_member_color_vec(const std::string& id, const std::string& group) {
    const std::string g = group.empty() ? "sin_categoria" : group;
    const std::string token = g + "|" + (id.empty() ? "unknown" : id);
    const uint64_t h = ozmvm_fnv1a64_u64(token.data(), token.size()) >> 16;
    const float local = static_cast<float>(h % 13u) / 12.0f;
    const float importance = sidebar_member_importance01(id, g);
    const float base_l = group_lightness_for_sidebar(g);
    const float dark_l = std::max(0.25f, base_l - 0.12f);
    const float light_l = std::min(0.84f, base_l + 0.24f);
    const float lightness = std::clamp(dark_l + (1.0f - importance) * (light_l - dark_l) + (local - 0.5f) * 0.030f, 0.25f, 0.84f);
    const float saturation = std::clamp(group_saturation_for_sidebar(g) + importance * 0.04f, 0.12f, 0.82f);
    return pastel_hsl(group_hue_degrees(g), saturation, lightness);
}

ImU32 group_color_u32(const std::string& group, float alpha = 1.0f) {

    return u32(group_color_vec(group), alpha);
}



ImVec4 disease_color_vec(const std::string& id, const std::string& group) {
    return tonal_member_color_vec(id, group.empty() ? "sin_categoria" : group);
}

ImU32 disease_color_u32(const std::string& id, const std::string& group, float alpha) {

    return u32(disease_color_vec(id, group), alpha);
}


