std::string atmospheric_quantity(double value, const std::string& unit) {

    if (!std::isfinite(value)) return "-";
    std::ostringstream os;
    const double av = std::fabs(value);

    if (av >= 100.0) os << std::fixed << std::setprecision(0);

    else if (av >= 10.0) os << std::fixed << std::setprecision(1);


    else os << std::fixed << std::setprecision(2);
    os << value;

    if (!unit.empty()) os << ' ' << unit;

    return os.str();
}

std::string atmospheric_quantity_for_parameter(const std::string& pollutant, double value, const std::string& unit) {
    if (!std::isfinite(value)) return "-";
    const std::string p = atmospheric_parameter_key(pollutant);
    std::string out_unit = unit;
    double v = value;
    const std::string u = lower_ascii(unit);
    if (p == "rh" && v >= 0.0 && v <= 1.25) { v *= 100.0; out_unit = "%"; }
    else if (p == "pa") {
        if (u.find("kpa") != std::string::npos) { v *= 10.0; out_unit = "hPa"; }
        else if (u.find("mmhg") != std::string::npos) { v *= 1.3332239; out_unit = "hPa"; }
        else if ((u.find("pa") != std::string::npos && u.find("hpa") == std::string::npos && std::fabs(v) > 2000.0) || v > 2000.0) { v /= 100.0; out_unit = "hPa"; }
        else if (v > 60.0 && v < 130.0) { v *= 10.0; out_unit = "hPa"; }
        else if (out_unit.empty()) out_unit = "hPa";
    } else if (p == "gr") {
        if (u.find("kw") != std::string::npos || (unit.empty() && v > 0.0 && v <= 1.6)) { v *= 1000.0; out_unit = "W/m2"; }
    } else if (p == "wsp" || p == "wgst" || p == "u10" || p == "v10") {
        if (u.find("km/h") != std::string::npos || u.find("kmh") != std::string::npos) { v /= 3.6; out_unit = "m/s"; }
        else if (u.find("mph") != std::string::npos) { v *= 0.44704; out_unit = "m/s"; }
        else if (u.find("kt") != std::string::npos || u.find("knot") != std::string::npos) { v *= 0.514444; out_unit = "m/s"; }
    } else if (p == "pp") {
        if (u.find("inch") != std::string::npos || u.find("in/") != std::string::npos) { v *= 25.4; out_unit = "mm"; }
        else if (out_unit.empty()) out_unit = "mm";
    }
    return atmospheric_quantity(v, out_unit);
}



std::string atmospheric_point_time_label(const AtmosphericCloudPoint& c) {

    if (c.hour >= 0) return format_timeline_long_spanish(c.hour, c.minute);

    if (c.month >= 1 && c.month <= 12) {
        std::ostringstream os;

        os << std::setw(4) << std::setfill('0') << c.year << '-'

           << std::setw(2) << std::setfill('0') << c.month;

        return os.str();
    }

    return std::to_string(c.year);
}



std::string atmospheric_popup_text(const AtmosphericPopupData& data) {
    
    const auto& c = data.point;
    std::ostringstream os;
    os << (c.station_id.empty() ? "RAM" : c.station_id.substr(0, 3)) << " " << c.station << "\n";
    const double health = atmospheric_health_ratio(c.pollutant, c.mean, c.unit);
    const int pct = (std::isfinite(health) && health >= 0.0)
        ? static_cast<int>(std::lround(std::clamp(health / 1.35, 0.0, 1.0) * 100.0))
        : -1;
    os << atmospheric_parameter_label(c.pollutant) << ": " << atmospheric_quantity_for_parameter(c.pollutant, c.mean, c.unit);
    if (pct >= 0) os << " (" << pct << "% " << atmospheric_measurement_band_label(c.pollutant, c.mean, c.unit) << ")";
    return os.str();
}



Point2 screen_to_lonlat(const ImVec2& p, const MapViewport& view) {

    const double scale = std::max(1.0e-9, static_cast<double>(view.scale));
    const ImVec2 flat = remove_map_pitch_from_screen(p, view);

    const double x = view.center_x + (static_cast<double>(flat.x - view.origin.x - view.size.x * 0.5f - view.pan.x) / scale);

    const double y = view.center_y + (static_cast<double>(flat.y - view.origin.y - view.size.y * 0.5f - view.pan.y) / scale);

    return world_px_to_lonlat(x, y, view.z);
}

struct Import3DOverlayGeometry {
    std::array<ImVec2, 4> full{};
    std::array<ImVec2, 4> control{};
    ImVec2 center{};
    ImVec2 alpha_min{};
    ImVec2 alpha_max{};
    bool valid = false;
};

Point2 import_3d_local_to_lonlat(const UiState& ui, double x, double y) {
    const double rotation = ui.import_3d_rotation_deg * 3.14159265358979323846 / 180.0;
    const double scale = std::max(0.000001, ui.import_3d_meters_per_unit);
    const double east = scale * (std::cos(rotation) * x - std::sin(rotation) * y);
    const double north = scale * (std::sin(rotation) * x + std::cos(rotation) * y);
    const double cos_lat = std::max(0.05, std::cos(ui.import_3d_center_lat * 3.14159265358979323846 / 180.0));
    return Point2{
        ui.import_3d_center_lon + east / (111320.0 * cos_lat),
        ui.import_3d_center_lat + north / 110574.0
    };
}

ImVec2 import_3d_uv_to_screen(const UiState& ui, const MapViewport& view, float u, float v) {
    const double x = (static_cast<double>(u) - 0.5) * ui.import_3d_model_width;
    const double y = (0.5 - static_cast<double>(v)) * ui.import_3d_model_height;
    return project_lonlat(import_3d_local_to_lonlat(ui, x, y), view);
}

Import3DOverlayGeometry import_3d_overlay_geometry(const UiState& ui, const MapViewport& view) {
    Import3DOverlayGeometry g;
    if (!ui.import_3d_aligning || !ui.import_3d_ready ||
        !(ui.import_3d_model_width > 0.0) || !(ui.import_3d_model_height > 0.0)) return g;
    g.full = {
        import_3d_uv_to_screen(ui, view, 0.0f, 0.0f),
        import_3d_uv_to_screen(ui, view, 1.0f, 0.0f),
        import_3d_uv_to_screen(ui, view, 1.0f, 1.0f),
        import_3d_uv_to_screen(ui, view, 0.0f, 1.0f)
    };
    g.control = {
        import_3d_uv_to_screen(ui, view, ui.import_3d_crop_u0, ui.import_3d_crop_v0),
        import_3d_uv_to_screen(ui, view, ui.import_3d_crop_u1, ui.import_3d_crop_v0),
        import_3d_uv_to_screen(ui, view, ui.import_3d_crop_u1, ui.import_3d_crop_v1),
        import_3d_uv_to_screen(ui, view, ui.import_3d_crop_u0, ui.import_3d_crop_v1)
    };
    g.center = import_3d_uv_to_screen(
        ui, view,
        (ui.import_3d_crop_u0 + ui.import_3d_crop_u1) * 0.5f,
        (ui.import_3d_crop_v0 + ui.import_3d_crop_v1) * 0.5f);
    g.alpha_min = ImVec2(view.origin.x + 22.0f, view.origin.y + 49.0f);
    g.alpha_max = ImVec2(g.alpha_min.x + 220.0f, g.alpha_min.y + 12.0f);
    g.valid = true;
    return g;
}

PreviewTexture& persistent_import_3d_preview_texture(const fs::path& path) {
    struct Entry { fs::path path; PreviewTexture texture; };
    static Entry entry;
    if (path.empty()) return entry.texture;
    if (entry.path != path || entry.texture.id == 0) {
        if (entry.texture.id != 0) glDeleteTextures(1, &entry.texture.id);
        entry.path = path;
        entry.texture = load_texture_from_file(path);
    }
    return entry.texture;
}

void draw_import_3d_alignment_overlay(UiState& ui, ImDrawList* dl, const MapViewport& view,
                                      const ImVec2& origin, const ImVec2& size,
                                      Import3DOverlayGeometry& geometry) {
    geometry = import_3d_overlay_geometry(ui, view);
    if (!geometry.valid || !dl) return;
    PreviewTexture& preview = persistent_import_3d_preview_texture(ui.import_3d_preview_file);
    if (preview.id != 0) {
        dl->AddImageQuad(
            (ImTextureID)(intptr_t)preview.id,
            geometry.full[0], geometry.full[1], geometry.full[2], geometry.full[3],
            ImVec2(0.0f, 0.0f), ImVec2(1.0f, 0.0f), ImVec2(1.0f, 1.0f), ImVec2(0.0f, 1.0f),
            IM_COL32(255, 255, 255, std::clamp(static_cast<int>(ui.import_3d_preview_alpha * 255.0f), 16, 255)));
    }
    const ImU32 edge = IM_COL32(255, 178, 42, 255);
    const ImU32 full_edge = IM_COL32(255, 255, 255, 205);
    for (int i = 0; i < 4; ++i) {
        dl->AddLine(geometry.full[i], geometry.full[(i + 1) % 4], full_edge, 1.5f);
        dl->AddLine(geometry.control[i], geometry.control[(i + 1) % 4], edge, 2.6f);
        dl->AddCircleFilled(geometry.control[i], 6.0f, edge, 16);
        dl->AddCircle(geometry.control[i], 8.0f, IM_COL32(20, 24, 28, 235), 16, 2.0f);
    }
    dl->AddCircleFilled(geometry.center, 6.0f, IM_COL32(78, 208, 255, 255), 18);
    dl->AddRect(origin, ImVec2(origin.x + size.x, origin.y + size.y), edge, 0.0f, 0, 3.0f);
    const char* help = ui.import_3d_ctrl_corner_count == 1
        ? "Ctrl + clic derecho: marca la segunda esquina"
        : (ui.import_3d_rotation_mode
            ? "ALT activo: arrastra sobre el mapa cenital para rotar con precision"
            : "Arrastra centro/esquinas | Mantén Alt + arrastra: rotar | Ctrl + 2 clics derechos: area | Enter: confirmar");
    const ImVec2 text_size = ImGui::CalcTextSize(help);
    const ImVec2 text_pos(origin.x + 14.0f, origin.y + 14.0f);
    const float badge_right = std::max(text_pos.x + text_size.x + 8.0f, geometry.alpha_max.x + 10.0f);
    dl->AddRectFilled(ImVec2(text_pos.x - 8.0f, text_pos.y - 6.0f),
                      ImVec2(badge_right, geometry.alpha_max.y + 9.0f),
                      IM_COL32(12, 16, 22, 218), 5.0f);
    dl->AddText(text_pos, IM_COL32(250, 250, 248, 255), help);
    char alpha_label[64];
    std::snprintf(alpha_label, sizeof(alpha_label), "Transparencia cenital  %d%%",
                  static_cast<int>(std::round(ui.import_3d_preview_alpha * 100.0f)));
    dl->AddText(ImVec2(geometry.alpha_min.x, geometry.alpha_min.y - 17.0f),
                IM_COL32(250, 250, 248, 255), alpha_label);
    dl->AddRectFilled(geometry.alpha_min, geometry.alpha_max, IM_COL32(20, 26, 34, 220), 6.0f);
    const float alpha_x = geometry.alpha_min.x +
        (geometry.alpha_max.x - geometry.alpha_min.x) * std::clamp(ui.import_3d_preview_alpha, 0.05f, 1.0f);
    dl->AddRectFilled(geometry.alpha_min, ImVec2(alpha_x, geometry.alpha_max.y), edge, 6.0f);
    dl->AddCircleFilled(ImVec2(alpha_x, (geometry.alpha_min.y + geometry.alpha_max.y) * 0.5f),
                        7.0f, IM_COL32(255, 255, 255, 255), 18);
}

bool import_3d_screen_to_uv(const Import3DOverlayGeometry& geometry, const ImVec2& point,
                            float& u, float& v) {
    const ImVec2 a = geometry.full[0];
    const ImVec2 e(geometry.full[1].x - a.x, geometry.full[1].y - a.y);
    const ImVec2 f(geometry.full[3].x - a.x, geometry.full[3].y - a.y);
    const ImVec2 d(point.x - a.x, point.y - a.y);
    const float det = e.x * f.y - e.y * f.x;
    if (std::fabs(det) < 0.0001f) return false;
    u = (d.x * f.y - d.y * f.x) / det;
    v = (e.x * d.y - e.y * d.x) / det;
    return true;
}

void import_3d_set_center_for_fixed_uv(UiState& ui, const Point2& fixed_geo, float u, float v) {
    const double x = (static_cast<double>(u) - 0.5) * ui.import_3d_model_width;
    const double y = (0.5 - static_cast<double>(v)) * ui.import_3d_model_height;
    const double rotation = ui.import_3d_rotation_deg * 3.14159265358979323846 / 180.0;
    const double east = ui.import_3d_meters_per_unit * (std::cos(rotation) * x - std::sin(rotation) * y);
    const double north = ui.import_3d_meters_per_unit * (std::sin(rotation) * x + std::cos(rotation) * y);
    const double center_lat = fixed_geo.y - north / 110574.0;
    const double cos_lat = std::max(0.05, std::cos(center_lat * 3.14159265358979323846 / 180.0));
    ui.import_3d_center_lat = center_lat;
    ui.import_3d_center_lon = fixed_geo.x - east / (111320.0 * cos_lat);
}



struct AtmosphericRenderPoint {
    const AtmosphericCloudPoint* source = nullptr;
    ImVec2 screen;
    float level = 0.0f;
};

struct TlalFogInputs {
    double rh = -1.0;
    double pm25 = -1.0;
    double aod = -1.0;
};

TlalFogInputs tlal_fog_inputs_for_view(const std::vector<AtmosphericCloudPoint>& clouds,
                                       const std::set<std::string>& selected_pollutants,
                                       const MapViewport& view,
                                       int64_t timeline_hour,
                                       int timeline_minute,
                                       int render_year) {
    TlalFogInputs out;
    int rh_n = 0, pm_n = 0, aod_n = 0;
    for (const AtmosphericCloudPoint& c : clouds) {
        const std::string k = atmospheric_parameter_key(c.pollutant);
        if (k != "rh" && k != "pm25" && k != "aod") continue;
        if (!selected_pollutants.empty() && !atmospheric_point_selected(c, selected_pollutants) && k != "rh") continue;
        if (!atmospheric_point_matches_time(c, timeline_hour, std::clamp(timeline_minute, 0, 59), render_year)) continue;
        if (!std::isfinite(c.mean)) continue;
        const ImVec2 p = project_lonlat(Point2{c.lon, c.lat}, view);
        const float pad = std::max(view.size.x, view.size.y) * 0.18f;
        if (p.x < view.origin.x - pad || p.x > view.origin.x + view.size.x + pad ||
            p.y < view.origin.y - pad || p.y > view.origin.y + view.size.y + pad) continue;
        if (k == "rh") { out.rh = out.rh < 0.0 ? c.mean : out.rh + c.mean; ++rh_n; }
        else if (k == "pm25") { out.pm25 = out.pm25 < 0.0 ? c.mean : out.pm25 + c.mean; ++pm_n; }
        else if (k == "aod") { out.aod = out.aod < 0.0 ? c.mean : out.aod + c.mean; ++aod_n; }
    }
    if (rh_n > 1) out.rh /= static_cast<double>(rh_n);
    if (pm_n > 1) out.pm25 /= static_cast<double>(pm_n);
    if (aod_n > 1) out.aod /= static_cast<double>(aod_n);
    return out;
}

void draw_tlal_fog_overlay(ImDrawList* dl, const ImVec2& origin, const ImVec2& size, float fog, float pitch, bool light_theme) {
    if (!dl || fog <= 0.003f || size.x <= 1.0f || size.y <= 1.0f) return;
    fog = tlal_fog_view(std::clamp(fog, 0.0f, 0.72f), std::clamp(pitch, 0.0f, kMapMaxPitch));
    if (fog <= 0.003f) return;
    const float p = std::clamp(pitch, 0.0f, kMapMaxPitch);
    const int veil_a = std::clamp(static_cast<int>(fog * 126.0f), 0, 98);
    const int edge_a = std::clamp(static_cast<int>(fog * (110.0f + 120.0f * p)), 0, 196);
    const int horizon_a = std::clamp(static_cast<int>(fog * 255.0f * p * p), 0, 210);
    const ImU32 veil = light_theme ? IM_COL32(241, 247, 250, veil_a / 3) : IM_COL32(205, 218, 224, veil_a / 4);
    const ImU32 edge = light_theme ? IM_COL32(244, 249, 252, edge_a) : IM_COL32(168, 184, 190, edge_a);
    const ImU32 far = light_theme ? IM_COL32(249, 252, 253, horizon_a) : IM_COL32(188, 201, 205, horizon_a);
    const ImVec2 a0 = origin;
    const ImVec2 b0(origin.x + size.x, origin.y + size.y);
    const float band_x = std::clamp(size.x * (0.10f + fog * 0.10f), 48.0f, size.x * 0.36f);
    const float band_y = std::clamp(size.y * (0.08f + fog * 0.16f + p * 0.10f), 34.0f, size.y * 0.46f);
    const float horizon_h = std::clamp(size.y * (0.12f + p * 0.32f), 28.0f, size.y * 0.58f);
    dl->AddRectFilled(a0, b0, veil, 0.0f);
    dl->AddRectFilledMultiColor(a0, ImVec2(b0.x, origin.y + horizon_h), far, far, veil, veil);
    dl->AddRectFilledMultiColor(a0, ImVec2(b0.x, origin.y + band_y), edge, edge, veil, veil);
    dl->AddRectFilledMultiColor(ImVec2(origin.x, b0.y - band_y * 0.55f), b0, veil, veil, edge, edge);
    dl->AddRectFilledMultiColor(a0, ImVec2(origin.x + band_x, b0.y), edge, veil, veil, edge);
    dl->AddRectFilledMultiColor(ImVec2(b0.x - band_x, origin.y), b0, veil, edge, edge, veil);
}

std::string tlalpowa_point_stack_key(const AtmosphericRenderPoint& rp) {
    if (rp.source && !rp.source->station_id.empty()) return "station:" + rp.source->station_id;
    if (rp.source && !rp.source->station.empty()) return "name:" + rp.source->station;
    const int x = static_cast<int>(std::lround(rp.screen.x / 2.0f));
    const int y = static_cast<int>(std::lround(rp.screen.y / 2.0f));
    return "xy:" + std::to_string(x) + ":" + std::to_string(y);
}

void tlalpowa_apply_point_pin_stack(std::vector<AtmosphericRenderPoint>& points, float step_px = 7.0f) {
    std::map<std::string, int> seen;
    for (AtmosphericRenderPoint& rp : points) {
        const std::string key = tlalpowa_point_stack_key(rp);
        const int idx = seen[key]++;
        if (idx <= 0) continue;
        const float angle = static_cast<float>((idx - 1) * 2.39996322972865332); // golden-angle stack: deterministic and compact.
        const float ring = step_px * static_cast<float>(1 + (idx - 1) / 6);
        rp.screen.x += std::cos(angle) * ring;
        rp.screen.y += std::sin(angle) * ring;
    }
}



float atmospheric_pin_radius_pixels(const MapViewport& view, const std::string& pollutant, float level) {
    const AtmosphericVisualSpec spec = atmospheric_visual_spec(pollutant);



    const double meters = 24.0 + 18.0 * static_cast<double>(std::clamp(level, 0.0f, 1.0f));

    return meters_to_screen_pixels(view, meters, spec.center_min_px, spec.center_max_px);
}



float atmospheric_halo_radius_pixels(const MapViewport& view, const std::string& pollutant) {
    const AtmosphericVisualSpec spec = atmospheric_visual_spec(pollutant);

    return meters_to_screen_pixels(view, spec.radius_m, spec.halo_min_px, spec.halo_max_px);
}



float atmospheric_halo_radius_pixels(const MapViewport& view, const AtmosphericCloudPoint& point) {
    const AtmosphericVisualSpec spec = atmospheric_visual_spec(point.pollutant);
    const double radius_m = point.representative_radius_m > 0.0 ? point.representative_radius_m : spec.radius_m;

    return meters_to_screen_pixels(view, radius_m, spec.halo_min_px, spec.halo_max_px);
}



struct AtmosphericCompositeDisc {
    const AtmosphericRenderPoint* rp = nullptr;
    ImVec2 center;

    float radius = 0.0f;
    int alpha = 0;
    ImVec4 color;
    float weight = 1.0f;
    bool aged_warning = false;
};



struct AtmosphericCompositeDsu {

    std::vector<int> parent;

    std::vector<unsigned char> rank;

    explicit AtmosphericCompositeDsu(std::size_t n = 0) { reset(n); }


    void reset(std::size_t n) {

        parent.resize(n);
        rank.assign(n, 0);

        for (std::size_t i = 0; i < n; ++i) parent[i] = static_cast<int>(i);
    }


    int find(int x) {
        int r = x;

        while (parent[r] != r) r = parent[r];

        while (parent[x] != x) {
            const int p = parent[x];
            parent[x] = r;
            x = p;
        }

        return r;
    }


    void unite(int a, int b) {
        int ra = find(a);
        int rb = find(b);

        if (ra == rb) return;

        if (rank[ra] < rank[rb]) std::swap(ra, rb);
        parent[rb] = ra;

        if (rank[ra] == rank[rb]) ++rank[ra];
    }
};



std::uint64_t atmospheric_composite_cell_key(int x, int y) {

    return (static_cast<std::uint64_t>(static_cast<std::uint32_t>(x)) << 32) |
           static_cast<std::uint32_t>(y);
}



bool atmospheric_discs_intersect(const AtmosphericCompositeDisc& a, const AtmosphericCompositeDisc& b) {
    const float dx = a.center.x - b.center.x;
    const float dy = a.center.y - b.center.y;

    const float r = a.radius + b.radius;

    return dx * dx + dy * dy <= r * r;
}



int atmospheric_segments_for_radius(float radius) {

    return radius > 180.0f ? 52 : (radius > 72.0f ? 40 : (radius > 30.0f ? 28 : 20));
}



ImU32 atmospheric_composite_color_from_parts(float r, float g, float b, int alpha) {
    const int rr = std::clamp(static_cast<int>(std::lround(r * 255.0f)), 0, 255);
    const int gg = std::clamp(static_cast<int>(std::lround(g * 255.0f)), 0, 255);
    const int bb = std::clamp(static_cast<int>(std::lround(b * 255.0f)), 0, 255);

    return IM_COL32(rr, gg, bb, std::clamp(alpha, 0, 255));
}


void draw_atmospheric_composite_discs(ImDrawList* dl,

                                      const std::vector<AtmosphericCompositeDisc>& discs,
                                      bool draw_as_pin,

                                      bool light_theme) {

    (void)light_theme;
    if (!dl || discs.empty()) return;



    for (const auto& d : discs) {

        if (d.radius <= 0.0f) continue;
        const int alpha = draw_as_pin ? 255 : std::clamp(d.alpha, 2, 166);
        const ImU32 col = atmospheric_composite_color_from_parts(d.color.x, d.color.y, d.color.z, alpha);
        if (!draw_as_pin) dl->AddCircleFilled(d.center, d.radius, col, atmospheric_segments_for_radius(d.radius));

        if (draw_as_pin && d.rp && d.rp->source) {
            const ImU32 fill = atmospheric_discrete_semaphore_color(d.rp->source->pollutant, d.rp->source->mean, d.rp->source->unit, alpha);
            const ImU32 outline = atmospheric_cloud_color(d.rp->source->pollutant, 255);
            draw_tlalpowa_solid_point_pin(dl, d.center, d.radius, fill, outline, 0.70f);
        }

        // No se dibuja anillo de envejecimiento: el pin puntual sólo puede
        // tener su contorno catalogal único. La caducidad se resuelve en la
        // etiqueta/estado, no con radios adicionales sobre el mapa.
    }
}




