bool atmospheric_is_mesh_field_parameter(const std::string& pollutant) {

    const std::string p = atmospheric_parameter_key(pollutant);
    return tlal_atm_mesh_enabled(p.data(), p.size()) != 0;
}



ImVec4 atmospheric_average_color_for_mesh(const AtmosphericCloudPoint& a, const AtmosphericCloudPoint& b) {
    const float ta = std::max(0.0f, atmospheric_measurement_t(a.pollutant, a.mean, a.unit));
    const float tb = std::max(0.0f, atmospheric_measurement_t(b.pollutant, b.mean, b.unit));

    const ImVec4 ca = ImGui::ColorConvertU32ToFloat4(atmospheric_health_color(a.pollutant, a.mean, a.unit, 64));

    const ImVec4 cb = ImGui::ColorConvertU32ToFloat4(atmospheric_health_color(b.pollutant, b.mean, b.unit, 64));
    const float wa = 0.50f + ta;
    const float wb = 0.50f + tb;
    const float w = std::max(0.001f, wa + wb);

    return ImVec4((ca.x * wa + cb.x * wb) / w,
                  (ca.y * wa + cb.y * wb) / w,
                  (ca.z * wa + cb.z * wb) / w,
                  64.0f / 255.0f);
}



float atmospheric_screen_cross(const ImVec2& o, const ImVec2& a, const ImVec2& b) {

    return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);
}




std::vector<ImVec2> atmospheric_convex_hull_screen(std::vector<ImVec2> pts) {



    std::sort(pts.begin(), pts.end(), [](const ImVec2& a, const ImVec2& b) {

        if (a.x == b.x) return a.y < b.y;

        return a.x < b.x;
    });

    pts.erase(std::unique(pts.begin(), pts.end(), [](const ImVec2& a, const ImVec2& b) {

        return std::fabs(a.x - b.x) < 0.75f && std::fabs(a.y - b.y) < 0.75f;
    }), pts.end());

    if (pts.size() <= 2) return pts;

    std::vector<ImVec2> h;

    h.reserve(pts.size() * 2);

    for (const ImVec2& p : pts) {

        while (h.size() >= 2 && atmospheric_screen_cross(h[h.size() - 2], h[h.size() - 1], p) <= 0.0f) h.pop_back();

        h.push_back(p);
    }
    const size_t lower = h.size();

    for (int i = static_cast<int>(pts.size()) - 2; i >= 0; --i) {
        const ImVec2& p = pts[static_cast<size_t>(i)];


        while (h.size() > lower && atmospheric_screen_cross(h[h.size() - 2], h[h.size() - 1], p) <= 0.0f) h.pop_back();

        h.push_back(p);
    }

    if (!h.empty()) h.pop_back();

    return h;
}



bool atmospheric_point_in_screen_polygon(const ImVec2& p, const std::vector<ImVec2>& poly) {

    if (poly.size() < 3) return false;
    bool inside = false;

    for (size_t i = 0, j = poly.size() - 1; i < poly.size(); j = i++) {
        const ImVec2& a = poly[i];
        const ImVec2& b = poly[j];
        const bool crosses = ((a.y > p.y) != (b.y > p.y));

        if (!crosses) continue;
        const float x = (b.x - a.x) * (p.y - a.y) / std::max(0.00001f, (b.y - a.y)) + a.x;

        if (p.x < x) inside = !inside;
    }

    return inside;
}



float atmospheric_distance_to_segment_px(const ImVec2& p, const ImVec2& a, const ImVec2& b) {
    const float vx = b.x - a.x;
    const float vy = b.y - a.y;
    const float wx = p.x - a.x;
    const float wy = p.y - a.y;
    const float len2 = std::max(0.0001f, vx * vx + vy * vy);
    const float t = std::clamp((wx * vx + wy * vy) / len2, 0.0f, 1.0f);
    const float dx = p.x - (a.x + vx * t);
    const float dy = p.y - (a.y + vy * t);

    return std::sqrt(dx * dx + dy * dy);
}



float atmospheric_distance_to_screen_polygon_edge_px(const ImVec2& p, const std::vector<ImVec2>& poly) {

    if (poly.empty()) return 1.0e9f;

    if (poly.size() == 1) {
        const float dx = p.x - poly.front().x;
        const float dy = p.y - poly.front().y;

        return std::sqrt(dx * dx + dy * dy);
    }
    float best = 1.0e9f;

    for (size_t i = 0, j = poly.size() - 1; i < poly.size(); j = i++) {
        best = std::min(best, atmospheric_distance_to_segment_px(p, poly[j], poly[i]));
    }

    return best;
}



float atmospheric_smoothstep01(float x) {
    x = std::clamp(x, 0.0f, 1.0f);

    return x * x * (3.0f - 2.0f * x);
}


float atmospheric_domain_fade_factor(const ImVec2& p,

                                     const std::vector<ImVec2>& domain_hull,

                                     float fringe_px) {


    const float fringe = std::max(1.0f, fringe_px);

    if (domain_hull.size() >= 3) {

        if (atmospheric_point_in_screen_polygon(p, domain_hull)) return 1.0f;
        const float d = atmospheric_distance_to_screen_polygon_edge_px(p, domain_hull);

        if (d >= fringe) return 0.0f;

        return 1.0f - atmospheric_smoothstep01(d / fringe);
    }

    if (domain_hull.size() == 2) {
        const float d = atmospheric_distance_to_segment_px(p, domain_hull[0], domain_hull[1]);

        if (d >= fringe) return 0.0f;

        return 1.0f - atmospheric_smoothstep01(d / fringe);
    }

    return 0.0f;
}



float atmospheric_soft_band_factor(float distance_px, float core_radius_px, float outer_radius_px) {
    const float core = std::max(0.0f, core_radius_px);
    const float outer = std::max(core + 1.0f, outer_radius_px);


    if (distance_px <= core) return 1.0f;

    if (distance_px >= outer) return 0.0f;

    return 1.0f - atmospheric_smoothstep01((distance_px - core) / (outer - core));
}



std::uint64_t atmospheric_mesh_edge_key(int a, int b) {
    const int lo = std::min(a, b);
    const int hi = std::max(a, b);

    return (static_cast<std::uint64_t>(static_cast<std::uint32_t>(lo)) << 32) |
           static_cast<std::uint32_t>(hi);
}



float atmospheric_organic_domain_outer_padding(float perimeter_radius_px,
                                               float nearest_neighbor_px,

                                               float canvas_span_px) {



    const float local = std::max(perimeter_radius_px * 1.34f, nearest_neighbor_px * 0.72f);

    return std::clamp(local, 38.0f, std::max(96.0f, canvas_span_px * 0.22f));
}



std::vector<AtmosphericMeshDomainEdge> atmospheric_build_organic_mesh_edges(

        const std::vector<AtmosphericGradualMeshNode>& nodes,
        float nearest_neighbor_px,

        float perimeter_radius_px,
        float hull_diag_px,

        float canvas_span_px) {



    std::vector<AtmosphericMeshDomainEdge> edges;
    const int n = static_cast<int>(nodes.size());

    if (n < 2) return edges;


    struct PairDistance { float d; int a; int b; };

    std::vector<PairDistance> pairs;

    pairs.reserve(static_cast<size_t>(n) * static_cast<size_t>(n - 1) / 2U);

    for (int i = 0; i < n; ++i) {

        for (int j = i + 1; j < n; ++j) {
            const float dx = nodes[i].p.x - nodes[j].p.x;

            const float dy = nodes[i].p.y - nodes[j].p.y;
            const float d = std::sqrt(dx * dx + dy * dy);

            if (std::isfinite(d) && d > 0.5f) pairs.push_back({d, i, j});
        }
    }

    std::sort(pairs.begin(), pairs.end(), [](const PairDistance& a, const PairDistance& b) {

        return a.d < b.d;
    });

    if (pairs.empty()) return edges;


    std::unordered_set<std::uint64_t> used;

    used.reserve(pairs.size());

    const float organic_padding = atmospheric_organic_domain_outer_padding(perimeter_radius_px, nearest_neighbor_px, canvas_span_px);


    auto add_edge = [&](int a, int b, float length) {

        if (a < 0 || b < 0 || a >= n || b >= n || a == b) return;
        const std::uint64_t key = atmospheric_mesh_edge_key(a, b);

        if (used.find(key) != used.end()) return;

        used.insert(key);

        const float ra = std::max(3.0f, nodes[static_cast<size_t>(a)].radius);
        const float rb = std::max(3.0f, nodes[static_cast<size_t>(b)].radius);
        const float station_radius = std::max(ra, rb);
        const float core = std::clamp(std::max(station_radius * 0.44f,
                                               std::min(length * 0.22f, nearest_neighbor_px * 0.56f)),
                                      8.0f,
                                      std::max(28.0f, organic_padding * 0.72f));
        const float outer = std::clamp(core + std::max(organic_padding * 0.74f, nearest_neighbor_px * 0.24f),
                                       core + 18.0f,
                                       std::max(core + 30.0f, organic_padding * 1.45f));

        edges.push_back({a, b, length, core, outer});
    };

    AtmosphericCompositeDsu dsu(static_cast<std::size_t>(n));

    int mst_edges = 0;

    for (const PairDistance& p : pairs) {

        if (dsu.find(p.a) == dsu.find(p.b)) continue;
        dsu.unite(p.a, p.b);

        add_edge(p.a, p.b, p.d);

        if (++mst_edges >= n - 1) break;
    }


    const float local_threshold = std::clamp(std::max(nearest_neighbor_px * 2.85f, perimeter_radius_px * 3.10f),
                                             54.0f,
                                             std::max(120.0f, hull_diag_px * 0.46f));
    const int k_nearest = std::clamp(n <= 8 ? 3 : 4, 1, std::max(1, n - 1));

    for (int i = 0; i < n; ++i) {
        int accepted = 0;

        for (const PairDistance& p : pairs) {

            if (p.a != i && p.b != i) continue;
            const int j = p.a == i ? p.b : p.a;
            (void)j;

            if (accepted < k_nearest || p.d <= local_threshold) {
                add_edge(p.a, p.b, p.d);
                ++accepted;
            }

            if (accepted >= k_nearest && p.d > local_threshold) break;
        }
    }


    return edges;
}



float atmospheric_organic_domain_fade_factor(const std::vector<AtmosphericGradualMeshNode>& nodes,

                                             const std::vector<AtmosphericMeshDomainEdge>& edges,
                                             const ImVec2& p,

                                             float perimeter_radius_px,
                                             float nearest_neighbor_px,

                                             float canvas_span_px) {



    if (nodes.empty()) return 0.0f;

    const float organic_padding = atmospheric_organic_domain_outer_padding(perimeter_radius_px, nearest_neighbor_px, canvas_span_px);
    float best = 0.0f;


    for (const AtmosphericGradualMeshNode& n : nodes) {
        const float dx = p.x - n.p.x;
        const float dy = p.y - n.p.y;

        const float d = std::sqrt(dx * dx + dy * dy);
        const float station_core = std::clamp(std::max(n.radius * 0.36f, nearest_neighbor_px * 0.08f), 4.0f, organic_padding * 0.52f);
        const float station_outer = std::max(station_core + 10.0f,
                                             station_core + std::max(organic_padding * 0.92f, n.radius * 0.72f));
        best = std::max(best, atmospheric_soft_band_factor(d, station_core, station_outer));

        if (best >= 0.999f) return 1.0f;
    }


    for (const AtmosphericMeshDomainEdge& e : edges) {

        if (e.a < 0 || e.b < 0 ||
            e.a >= static_cast<int>(nodes.size()) || e.b >= static_cast<int>(nodes.size())) continue;
        const float d = atmospheric_distance_to_segment_px(p, nodes[static_cast<size_t>(e.a)].p, nodes[static_cast<size_t>(e.b)].p);
        best = std::max(best, atmospheric_soft_band_factor(d, e.core_radius, e.outer_radius));

        if (best >= 0.999f) return 1.0f;
    }


    return atmospheric_smoothstep01(std::clamp(best, 0.0f, 1.0f));
}



float atmospheric_radial_envelope_factor(const std::vector<AtmosphericGradualMeshNode>& nodes,

                                         const ImVec2& p,

                                         float sigma_px) {



    if (nodes.empty()) return 0.0f;
    const float sigma = std::clamp(sigma_px, 48.0f, 760.0f);
    const double sigma2 = static_cast<double>(sigma) * static_cast<double>(sigma);
    const double broad_sigma = static_cast<double>(sigma) * 1.85;
    const double broad_sigma2 = broad_sigma * broad_sigma;
    double accum = 0.0;

    double strongest = 0.0;

    for (const AtmosphericGradualMeshNode& n : nodes) {
        const float dx = p.x - n.p.x;
        const float dy = p.y - n.p.y;
        const double d2 = static_cast<double>(dx) * static_cast<double>(dx) +
                          static_cast<double>(dy) * static_cast<double>(dy);
        const double local = std::exp(-d2 / (2.0 * sigma2));
        const double broad = std::exp(-d2 / (2.0 * broad_sigma2));
        const double intensity = 0.38 + 0.62 * static_cast<double>(std::clamp(n.level, 0.0f, 1.0f));

        const double support = (0.68 * local + 0.32 * broad) * intensity;
        accum += support;
        strongest = std::max(strongest, support);
    }
    const double fused = 1.0 - std::exp(-accum * 0.46);
    const double guarded = 0.58 * std::sqrt(std::clamp(fused, 0.0, 1.0)) +
                           0.42 * std::sqrt(std::clamp(strongest, 0.0, 1.0));

    return atmospheric_smoothstep01(static_cast<float>(std::clamp(guarded, 0.0, 1.0)));
}



ImU32 atmospheric_scale_color_alpha(ImU32 c, float factor) {

    ImVec4 v = ImGui::ColorConvertU32ToFloat4(c);
    v.w *= std::clamp(factor, 0.0f, 1.0f);

    if (v.w <= 0.0035f) return IM_COL32(0, 0, 0, 0);

    return ImGui::ColorConvertFloat4ToU32(v);
}



float atmospheric_nearest_neighbor_scale_px(const std::vector<AtmosphericGradualMeshNode>& nodes) {

    if (nodes.size() < 2) return 140.0f;

    std::vector<float> nearest;

    nearest.reserve(nodes.size());

    for (size_t i = 0; i < nodes.size(); ++i) {
        float best = 1.0e9f;

        for (size_t j = 0; j < nodes.size(); ++j) {

            if (i == j) continue;
            const float dx = nodes[i].p.x - nodes[j].p.x;
            const float dy = nodes[i].p.y - nodes[j].p.y;
            best = std::min(best, std::sqrt(dx * dx + dy * dy));
        }

        if (std::isfinite(best) && best < 1.0e8f) nearest.push_back(best);
    }

    if (nearest.empty()) return 140.0f;
    std::sort(nearest.begin(), nearest.end());

    return nearest[nearest.size() / 2];
}



ImU32 atmospheric_idw_mesh_color_at(const std::vector<AtmosphericGradualMeshNode>& nodes,

                                    const ImVec2& p,
                                    float sigma_px,

                                    int max_alpha) {


    double wr = 0.0;
    double wg = 0.0;
    double wb = 0.0;
    double wl = 0.0;
    double wsum = 0.0;
    float nearest = 1.0e9f;
    const float sigma = std::max(48.0f, sigma_px);
    const double sigma2 = static_cast<double>(sigma) * static_cast<double>(sigma);

    for (const AtmosphericGradualMeshNode& n : nodes) {
        const float dx = p.x - n.p.x;
        const float dy = p.y - n.p.y;
        const float d2f = dx * dx + dy * dy;
        const float d = std::sqrt(d2f);
        nearest = std::min(nearest, d);

        const double d2 = static_cast<double>(d2f);

        const double gaussian = 0.32 + 0.68 * std::exp(-d2 / (2.0 * sigma2));
        const double inverse = 1.0 / std::pow(static_cast<double>(d) + 24.0, 1.42);
        const double strength = 0.42 + 0.58 * std::clamp(static_cast<double>(n.level), 0.0, 1.0);
        const double w = gaussian * inverse * strength;
        wr += static_cast<double>(n.color.x) * w;
        wg += static_cast<double>(n.color.y) * w;
        wb += static_cast<double>(n.color.z) * w;
        wl += static_cast<double>(n.level) * w;
        wsum += w;
    }

    if (wsum <= 0.0) return IM_COL32(0, 0, 0, 0);
    const float r = static_cast<float>(wr / wsum);
    const float g = static_cast<float>(wg / wsum);
    const float b = static_cast<float>(wb / wsum);
    const float l = static_cast<float>(wl / wsum);
    const float nearest_softening = 0.84f + 0.16f * std::exp(-(nearest * nearest) / (2.0f * sigma * sigma));

    const float activity = (0.46f + 0.54f * std::clamp(l, 0.0f, 1.0f)) * nearest_softening;
    const int alpha = std::clamp(static_cast<int>(std::lround(static_cast<float>(max_alpha) * activity)),
                                 0, max_alpha);

    if (alpha <= 0) return IM_COL32(0, 0, 0, 0);

    return atmospheric_composite_color_from_parts(r, g, b, alpha);
}


void draw_atmospheric_soft_station_wash(ImDrawList* dl,

                                        const std::vector<AtmosphericGradualMeshNode>& nodes,

                                        const std::vector<AtmosphericMeshDomainEdge>& domain_edges,

                                        float perimeter_radius_px,
                                        float nearest_neighbor_px,
                                        float sigma_px,
                                        const ImVec2& origin,

                                        const ImVec2& size) {

    if (!dl || nodes.empty()) return;
    const float canvas_min_x = origin.x;
    const float canvas_min_y = origin.y;

    const float canvas_max_x = origin.x + size.x;
    const float canvas_max_y = origin.y + size.y;


    const int rings = 9;

    for (const AtmosphericGradualMeshNode& n : nodes) {

        if (n.radius <= 0.0f) continue;

        const float domain_fade = atmospheric_organic_domain_fade_factor(nodes, domain_edges, n.p, perimeter_radius_px, nearest_neighbor_px, std::max(size.x, size.y));

        if (domain_fade <= 0.006f) continue;
        const float wash_radius = std::clamp(std::max(n.radius * 1.16f, sigma_px * 0.46f),
                                             42.0f,
                                             std::max(82.0f, std::max(size.x, size.y) * 0.20f));

        if (n.p.x + wash_radius < canvas_min_x || n.p.x - wash_radius > canvas_max_x ||
            n.p.y + wash_radius < canvas_min_y || n.p.y - wash_radius > canvas_max_y) continue;
        const float strength = std::clamp(0.24f + 0.52f * n.level, 0.0f, 1.0f) * domain_fade;

        for (int i = rings; i >= 1; --i) {
            const float u = static_cast<float>(i) / static_cast<float>(rings);
            const float rr = wash_radius * u;
            const float a_shape = (1.0f - u) * (1.0f - u);

            const int alpha = std::clamp(static_cast<int>(std::lround((1.0f + 12.0f * a_shape) * strength)), 0, 14);

            if (alpha <= 0) continue;
            const ImU32 col = atmospheric_composite_color_from_parts(n.color.x, n.color.y, n.color.z, alpha);
            dl->AddCircleFilled(n.p, rr, col, atmospheric_segments_for_radius(rr));
        }
    }
}



void draw_atmospheric_gradual_field_mesh(ImDrawList* dl,

                                               const std::vector<AtmosphericRenderPoint>& points,

                                               const std::vector<MapStation>& station_domain,


                                               const MapViewport& view,

                                               const std::vector<MapFeature>& mask,
                                               const ImVec2& origin,

                                               const ImVec2& size) {

    if (!dl || points.size() < 2 || size.x <= 1.0f || size.y <= 1.0f) return;

    std::map<std::string, std::vector<AtmosphericGradualMeshNode>> by_pollutant;

    for (const AtmosphericRenderPoint& rp : points) {

        if (!rp.source) continue;

        if (!atmospheric_is_mesh_field_parameter(rp.source->pollutant)) continue;

        if (!mask.empty()) {

            const Point2 geo = screen_to_lonlat(rp.screen, view);

            if (!point_in_geo_features(geo, mask)) continue;
        }
        const float t = std::clamp(rp.level, 0.0f, 1.0f);

        if (t < 0.01f) continue;

        const float halo = atmospheric_halo_radius_pixels(view, *rp.source);

        by_pollutant[atmospheric_parameter_key(rp.source->pollutant)].push_back(
            AtmosphericGradualMeshNode{&rp, rp.screen, std::max(3.0f, halo), t,

                                       ImGui::ColorConvertU32ToFloat4(atmospheric_health_color(rp.source->pollutant, rp.source->mean, rp.source->unit, 64))});
    }

    (void)station_domain;


    for (auto& kv : by_pollutant) {
        auto& nodes = kv.second;

        if (nodes.size() < 2) continue;

        std::vector<ImVec2> raw_pts;

        raw_pts.reserve(nodes.size());
        const float canvas_min_x = origin.x;
        const float canvas_min_y = origin.y;
        const float canvas_max_x = origin.x + size.x;
        const float canvas_max_y = origin.y + size.y;
        float max_radius = 0.0f;

        for (const auto& n : nodes) {

            raw_pts.push_back(n.p);
            max_radius = std::max(max_radius, n.radius);
        }


        const std::vector<ImVec2> domain_hull = atmospheric_convex_hull_screen(raw_pts);

        if (domain_hull.size() < 2) continue;

        const float nn = atmospheric_nearest_neighbor_scale_px(nodes);
        float hull_min_x = canvas_max_x;
        float hull_min_y = canvas_max_y;
        float hull_max_x = canvas_min_x;

        float hull_max_y = canvas_min_y;

        for (const ImVec2& p : domain_hull) {
            hull_min_x = std::min(hull_min_x, p.x);
            hull_min_y = std::min(hull_min_y, p.y);
            hull_max_x = std::max(hull_max_x, p.x);
            hull_max_y = std::max(hull_max_y, p.y);
        }

        if (!std::isfinite(hull_min_x) || hull_min_x > hull_max_x || hull_min_y > hull_max_y) continue;
        const float hull_dx = hull_max_x - hull_min_x;
        const float hull_dy = hull_max_y - hull_min_y;
        const float hull_diag = std::sqrt(hull_dx * hull_dx + hull_dy * hull_dy);

        float perimeter_radius = 0.0f;

        for (const AtmosphericGradualMeshNode& n : nodes) {

            for (const ImVec2& hp : domain_hull) {
                const float dx = n.p.x - hp.x;
                const float dy = n.p.y - hp.y;

                if (dx * dx + dy * dy <= 9.0f) perimeter_radius = std::max(perimeter_radius, n.radius);
            }
        }

        if (perimeter_radius <= 0.0f) perimeter_radius = max_radius;



        const float canvas_span = std::max(size.x, size.y);

        const std::vector<AtmosphericMeshDomainEdge> domain_edges =

            atmospheric_build_organic_mesh_edges(nodes, nn, perimeter_radius, hull_diag, canvas_span);

        const float organic_padding = atmospheric_organic_domain_outer_padding(perimeter_radius, nn, canvas_span);

        const float sigma = std::clamp(nn * 1.58f + max_radius * 0.76f + hull_diag * 0.038f,
                                       76.0f,
                                       std::max(178.0f, canvas_span * 0.32f));

        float min_x = std::clamp(hull_min_x - organic_padding - 4.0f, canvas_min_x, canvas_max_x);
        float min_y = std::clamp(hull_min_y - organic_padding - 4.0f, canvas_min_y, canvas_max_y);
        float max_x = std::clamp(hull_max_x + organic_padding + 4.0f, canvas_min_x, canvas_max_x);
        float max_y = std::clamp(hull_max_y + organic_padding + 4.0f, canvas_min_y, canvas_max_y);
        const float raw_cell = std::clamp(canvas_span / 292.0f, 4.0f, 8.4f);

        const float bbox_area = std::max(1.0f, (max_x - min_x) * (max_y - min_y));

        const float cell = std::clamp(std::max(raw_cell, std::sqrt(bbox_area / 76000.0f)), 4.0f, 8.8f);


        // Prohibido dibujar pilas de radios concéntricos por estación: el único
        // radio permitido sobre contaminantes es el disco translúcido directo
        // de cada muestra puntual. La malla continua queda como campo, no como
        // anillos apilados alrededor del pin.
        (void)perimeter_radius;
        (void)nn;
        (void)sigma;



        for (float y = min_y; y < max_y; y += cell) {

            for (float x = min_x; x < max_x; x += cell) {
                const ImVec2 p0(x, y);
                const ImVec2 p1(std::min(x + cell, canvas_max_x), y);
                const ImVec2 p2(std::min(x + cell, canvas_max_x), std::min(y + cell, canvas_max_y));
                const ImVec2 p3(x, std::min(y + cell, canvas_max_y));
                const ImVec2 center((p0.x + p2.x) * 0.5f, (p0.y + p2.y) * 0.5f);


                const float gate_center = atmospheric_organic_domain_fade_factor(nodes, domain_edges, center, perimeter_radius, nn, canvas_span);

                const float gate0 = atmospheric_organic_domain_fade_factor(nodes, domain_edges, p0, perimeter_radius, nn, canvas_span);

                const float gate1 = atmospheric_organic_domain_fade_factor(nodes, domain_edges, p1, perimeter_radius, nn, canvas_span);

                const float gate2 = atmospheric_organic_domain_fade_factor(nodes, domain_edges, p2, perimeter_radius, nn, canvas_span);

                const float gate3 = atmospheric_organic_domain_fade_factor(nodes, domain_edges, p3, perimeter_radius, nn, canvas_span);
                const float gate_max = std::max({gate_center, gate0, gate1, gate2, gate3});

                if (gate_max <= 0.0015f) continue;


                if (!mask.empty()) {

                    const Point2 geo = screen_to_lonlat(center, view);

                    if (!point_in_geo_features(geo, mask)) continue;
                }

                const float support = atmospheric_radial_envelope_factor(nodes, center, sigma);


                const float support_mod = 0.62f + 0.38f * std::clamp(support, 0.0f, 1.0f);
                const float fade0 = std::clamp(gate0 * support_mod, 0.0f, 1.0f);
                const float fade1 = std::clamp(gate1 * support_mod, 0.0f, 1.0f);
                const float fade2 = std::clamp(gate2 * support_mod, 0.0f, 1.0f);
                const float fade3 = std::clamp(gate3 * support_mod, 0.0f, 1.0f);

                if (std::max({fade0, fade1, fade2, fade3}) <= 0.004f) continue;

                constexpr int kAtmosphericVisibleMeshAlpha = 58;



                const ImU32 c0 = atmospheric_scale_color_alpha(atmospheric_idw_mesh_color_at(nodes, p0, sigma, kAtmosphericVisibleMeshAlpha), fade0);

                const ImU32 c1 = atmospheric_scale_color_alpha(atmospheric_idw_mesh_color_at(nodes, p1, sigma, kAtmosphericVisibleMeshAlpha), fade1);

                const ImU32 c2 = atmospheric_scale_color_alpha(atmospheric_idw_mesh_color_at(nodes, p2, sigma, kAtmosphericVisibleMeshAlpha), fade2);

                const ImU32 c3 = atmospheric_scale_color_alpha(atmospheric_idw_mesh_color_at(nodes, p3, sigma, kAtmosphericVisibleMeshAlpha), fade3);

                if ((ImGui::ColorConvertU32ToFloat4(c0).w + ImGui::ColorConvertU32ToFloat4(c1).w +

                     ImGui::ColorConvertU32ToFloat4(c2).w + ImGui::ColorConvertU32ToFloat4(c3).w) <= 0.004f) continue;
                dl->AddRectFilledMultiColor(p0, p2, c0, c1, c2, c3);
            }
        }
    }
}


void draw_atmospheric_cloud_field(ImDrawList* dl,

                                  const std::vector<AtmosphericRenderPoint>& points,

                                  const std::vector<MapStation>& station_domain,

                                  const MapViewport& view,

                                  const std::vector<MapFeature>& mask,
                                  const ImVec2& origin,
                                  const ImVec2& size,

                                  bool light_theme) {

    (void)origin;

    if (!dl || points.empty() || size.x <= 1.0f || size.y <= 1.0f) return;
    constexpr int kAtmosphericMeshAlpha30Percent = 61;
    constexpr int kAtmosphericPinAlpha82Percent = 209;
    constexpr int kAtmosphericCloudSoftMinimumAlpha = 0;

    draw_atmospheric_gradual_field_mesh(dl, points, station_domain, view, mask, origin, size);

    auto punctual_age_visibility = [](const AtmosphericCloudPoint& p) -> float {

        if (p.interval_aggregate) return 1.0f;



        return std::clamp(1.0f - static_cast<float>(p.latched_age_minutes) / 84.0f, 0.34f, 1.0f);
    };


    std::vector<AtmosphericCompositeDisc> halo_discs;

    std::vector<AtmosphericCompositeDisc> pin_discs;

    halo_discs.reserve(points.size());

    pin_discs.reserve(points.size());


    for (const AtmosphericRenderPoint& rp : points) {

        if (!rp.source) continue;

        if (!mask.empty()) {

            const Point2 geo = screen_to_lonlat(rp.screen, view);

            if (!point_in_geo_features(geo, mask)) continue;
        }
        const float t = std::clamp(rp.level, 0.0f, 1.0f);

        if (t < 0.01f) continue;

        const float age_visibility = punctual_age_visibility(*rp.source);


        const float halo_radius = atmospheric_halo_radius_pixels(view, *rp.source);

        if (halo_radius >= 3.0f) {
            const int halo_alpha = std::clamp(static_cast<int>(std::lround((18.0f + 40.0f * t) * age_visibility)),
                                              kAtmosphericCloudSoftMinimumAlpha,
                                              kAtmosphericMeshAlpha30Percent);
            const ImU32 halo_col = atmospheric_health_color(rp.source->pollutant, rp.source->mean, rp.source->unit, halo_alpha);



            halo_discs.push_back(AtmosphericCompositeDisc{&rp, rp.screen, halo_radius, halo_alpha,

                                                          ImGui::ColorConvertU32ToFloat4(halo_col),
                                                          std::max(0.08f, t * age_visibility),
                                                          false});
        }


        const float pin_radius = atmospheric_pin_radius_pixels(view, rp.source->pollutant, t);
        const int pin_alpha = kAtmosphericPinAlpha82Percent;
        const ImU32 pin_col = atmospheric_cloud_color(rp.source->pollutant, pin_alpha);



        pin_discs.push_back(AtmosphericCompositeDisc{&rp, rp.screen, pin_radius, pin_alpha,

                                                     ImGui::ColorConvertU32ToFloat4(pin_col),

                                                     std::max(0.10f, (0.35f + 0.65f * t) * age_visibility),

                                                     !rp.source->interval_aggregate && rp.source->latched_age_minutes >= 20});
    }

    draw_atmospheric_composite_discs(dl, halo_discs, false, light_theme);
    draw_atmospheric_composite_discs(dl, pin_discs, true, light_theme);
}



std::string atmospheric_layer_badge_text(const std::vector<AtmosphericCloudPoint>& points,
                                         bool interval_active,

                                         int64_t timeline_hour,

                                         int timeline_minute,

                                         bool snapshot_ready,

                                         bool snapshot_loading) {
    std::ostringstream os;

    if (!snapshot_ready) {
        os << (snapshot_loading ? "RAMA: cargando snapshot" : "RAMA: sin snapshot visible");

        os << " | " << format_timeline_long_spanish(timeline_hour, timeline_minute);

        return os.str();
    }
    os << "RAMA: " << points.size() << ' ';
    os << (interval_active ? "agregados de intervalo" : "valores vigentes");

    os << " | " << format_timeline_long_spanish(timeline_hour, timeline_minute);
    os << " | pin 82% + malla IDW continua con casco periferico redondeado";


    if (!interval_active && !points.empty()) {
        int max_age = 0;

        for (const auto& p : points) max_age = std::max(max_age, p.latched_age_minutes);
        os << " | edad max " << max_age << "/60 min";
    }

    return os.str();
}


void draw_atmospheric_layer_badge(ImDrawList* dl,
                                  const ImVec2& origin,
                                  bool light_theme,

                                  const std::string& text) {

    if (!dl || text.empty()) return;

    const ImVec2 pad(9.0f, 5.0f);

    const ImVec2 ts = ImGui::CalcTextSize(text.c_str());
    const ImVec2 a(origin.x + 14.0f, origin.y + 14.0f);
    const ImVec2 b(a.x + ts.x + pad.x * 2.0f, a.y + ts.y + pad.y * 2.0f);
    const ImU32 bg = light_theme ? IM_COL32(255, 255, 255, 205) : IM_COL32(7, 12, 18, 210);
    const ImU32 border = light_theme ? IM_COL32(28, 44, 54, 86) : IM_COL32(205, 230, 245, 72);
    const ImU32 fg = light_theme ? IM_COL32(26, 38, 48, 232) : IM_COL32(232, 242, 248, 235);
    dl->AddRectFilled(a, b, bg, 8.0f);
    dl->AddRect(a, b, border, 8.0f, 0, 1.0f);
    dl->AddText(ImVec2(a.x + pad.x, a.y + pad.y), fg, text.c_str());
}





std::string atmospheric_station_sigla3(const std::string& station_id, const std::string& station_name) {
    std::string src = station_id.empty() ? station_name : station_id;
    std::string out;
    out.reserve(3);
    for (char ch : src) {
        const unsigned char c = static_cast<unsigned char>(ch);
        if (std::isalnum(c)) out.push_back(static_cast<char>(std::toupper(c)));
        if (out.size() >= 3) break;
    }
    if (out.empty()) out = "RAM";
    while (out.size() < 3) out.push_back(' ');
    return out.substr(0, 3);
}

int atmospheric_quality_percent(const AtmosphericCloudPoint& point) {
    const std::string p = atmospheric_parameter_key(point.pollutant);
    /* Las variables meteorológicas no son “calidad del aire”. Para valores
       pequeños válidos —0 mm, 0 m/s, UV fraccional, humedad 0..1— se muestra
       la magnitud y su familia física, no “no cuantificable”. */
    if (ozmvm_atm_key_is_meteorological(p.data(), p.size()) != 0) return -2;
    const double health = atmospheric_health_ratio(point.pollutant, point.mean, point.unit);
    if (!std::isfinite(health) || health < 0.0) return -1;
    return static_cast<int>(std::lround(std::clamp(health / 1.35, 0.0, 1.0) * 100.0));
}

std::string atmospheric_radius_km_value_label(const AtmosphericCloudPoint& point) {
    const AtmosphericVisualSpec spec = atmospheric_visual_spec(point.pollutant);
    const double radius_m = point.representative_radius_m > 0.0 ? point.representative_radius_m : spec.radius_m;
    std::ostringstream os;
    os << std::fixed << std::setprecision(radius_m >= 9950.0 ? 0 : 1) << std::max(0.0, radius_m / 1000.0) << " Km";
    return os.str();
}

std::vector<std::pair<AtmosphericCloudPoint, float>> atmospheric_popup_pairs(const AtmosphericPopupData& data) {
    std::vector<std::pair<AtmosphericCloudPoint, float>> pairs;
    if (!data.station_points.empty()) {
        const size_t n = data.station_points.size();
        pairs.reserve(n);
        for (size_t i = 0; i < n; ++i) {
            const float level = i < data.station_levels.size() ? data.station_levels[i] : data.level;
            pairs.push_back({data.station_points[i], std::clamp(level, 0.0f, 1.0f)});
        }
    } else if (data.valid) {
        pairs.push_back({data.point, std::clamp(data.level, 0.0f, 1.0f)});
    }
    std::stable_sort(pairs.begin(), pairs.end(), [](const auto& a, const auto& b) {
        const std::string la = atmospheric_parameter_label(a.first.pollutant);
        const std::string lb = atmospheric_parameter_label(b.first.pollutant);
        if (la != lb) return la < lb;
        return a.first.pollutant < b.first.pollutant;
    });
    return pairs;
}

void draw_atmospheric_marker_circle(const char* id, ImU32 color, float radius, const char* tooltip) {
    ImDrawList* dl = ImGui::GetWindowDrawList();
    const ImVec2 p = ImGui::GetCursorScreenPos();
    const ImVec2 center(p.x + radius, p.y + radius);
    dl->AddCircleFilled(center, radius, color, 32);
    dl->AddCircle(center, radius + std::max(1.0f, radius * kGoldenN7), IM_COL32(255, 255, 255, 118), 32, std::max(1.0f, radius * kGoldenN8));
    ImGui::InvisibleButton(id, ImVec2(radius * 2.0f, radius * 2.0f));
    if (tooltip && tooltip[0] && ImGui::IsItemHovered()) {
        ImGui::BeginTooltip();
        ImGui::TextUnformatted(tooltip);
        ImGui::EndTooltip();
    }
}


std::string place_format_grouped_int(int value) {
    if (value <= 0) return {};
    std::string digits = std::to_string(value);
    std::string out;
    out.reserve(digits.size() + digits.size() / 3);
    int group = 0;
    for (auto it = digits.rbegin(); it != digits.rend(); ++it) {
        if (group == 3) { out.push_back(','); group = 0; }
        out.push_back(*it);
        ++group;
    }
    std::reverse(out.begin(), out.end());
    return out;
}

std::string place_category_label(const MapPlace& place) {
    const std::string k = normalize_key(place.kind + " " + place.notes + " " + place.id);
    if (k.find("originario") != std::string::npos || k.find("indigena originario") != std::string::npos) return "pueblo originario";
    if (k.find("barrio originario") != std::string::npos) return "pueblo originario";
    if (k.find("pueblo") != std::string::npos || k.find("villa") != std::string::npos || k.find("poblado") != std::string::npos || k.find("localidad") != std::string::npos || k.find("village") != std::string::npos || k.find("town") != std::string::npos) return "pueblo";
    if (k.find("capital") != std::string::npos || k.find("ciudad") != std::string::npos || k.find("cabecera") != std::string::npos || k.find("pplc") != std::string::npos || k.find("ppla") != std::string::npos || place.population >= 15000) return "ciudad";
    return "pueblo";
}

std::string place_population_sentence(const MapPlace& place) {
    const std::string category = place_category_label(place);
    if (place.population > 0) {
        std::string line = category + " de " + place_format_grouped_int(place.population) + " habitantes";
        if (place.population_year > 0) line += " en " + std::to_string(place.population_year);
        else line += "; año censal no especificado";
        return line;
    }
    return category + " de población no cuantificada en el catálogo cargado";
}

std::string place_admin_sentence(const MapPlace& place) {
    std::vector<std::string> parts;
    if (!trim(place.admin2).empty()) parts.push_back(trim(place.admin2));
    if (!trim(place.admin1).empty()) parts.push_back(trim(place.admin1));
    if (!trim(place.country).empty() && normalize_key(place.country) != "mx" && normalize_key(place.country) != "mexico") parts.push_back(trim(place.country));
    if (parts.empty()) return {};
    std::string out = "Ubicación administrativa: ";
    for (size_t i = 0; i < parts.size(); ++i) {
        if (i) out += ", ";
        out += parts[i];
    }
    return out;
}

std::string place_coordinate_sentence(const MapPlace& place) {
    char buf[160];
    std::snprintf(buf, sizeof(buf), "Coordenadas: %.5f°, %.5f°", place.lat, place.lon);
    return std::string(buf);
}

std::string place_elevation_sentence(const MapPlace& place) {
    if (place.elevation_m <= 0) return "Altitud: no disponible en el catálogo cargado";
    return "Altitud: " + place_format_grouped_int(place.elevation_m) + " m s. n. m.";
}

std::string place_card_kind_label(const MapPlace& place) {
    
    const std::string k = normalize_key(place.kind + " " + place.notes + " " + place.id);
    if (k.find("ciudad") != std::string::npos || k.find("capital") != std::string::npos ||
        k.find("pplc") != std::string::npos || k.find("ppla") != std::string::npos ||
        place.population >= 15000) {
        return "Ciudad";
    }
    if (k.find("cabecera") != std::string::npos) return "Cabecera";
    return "Pueblo";
}

std::string place_card_population_line(const MapPlace& place) {
    const std::string kind = place_card_kind_label(place);
    if (place.population <= 0) {
        
        return kind;
    }
    return kind + " de " + place_format_grouped_int(place.population) + " habs.";
}

std::string place_card_coordinate_line(const MapPlace& place) {
    char buf[96];
    std::snprintf(buf, sizeof(buf), "%.3f°, %.3f°", place.lat, place.lon);
    return std::string(buf);
}

std::string place_card_elevation_line(const MapPlace& place) {
    if (place.elevation_m <= 0) return {};
    return "altitud " + place_format_grouped_int(place.elevation_m) + " m";
}

std::string place_glyph_label(const MapPlace& place) {
    std::string norm = normalize_key(place.name);
    std::istringstream iss(norm);
    std::string tok;
    std::string out;
    while (iss >> tok) {
        if (tok == "san" || tok == "santa" || tok == "santo" || tok == "la" || tok == "las" || tok == "los" || tok == "el" || tok == "villa" || tok == "pueblo" || tok == "de" || tok == "del") continue;
        if (!tok.empty()) out.push_back(static_cast<char>(std::toupper(static_cast<unsigned char>(tok[0]))));
        if (out.size() >= 2) break;
    }
    if (out.empty() && !norm.empty()) out.push_back(static_cast<char>(std::toupper(static_cast<unsigned char>(norm[0]))));
    return out.empty() ? std::string("P") : out;
}

std::vector<fs::path> place_glyph_roots() {
    std::vector<fs::path> roots;
    auto add_root = [&](const fs::path& p) {
        if (p.empty()) return;
        const std::string key = normalize_key(path_utf8(p.lexically_normal()));
        for (const auto& old : roots) if (normalize_key(path_utf8(old.lexically_normal())) == key) return;
        roots.push_back(p);
    };
    const fs::path datos = datos_externos_root();
    const fs::path work = workspace_root();
    add_root(datos / "icon");
    add_root(datos / "icons");
    add_root(datos / "Icon");
    add_root(datos / "Iconos");
    add_root(datos / L"Íconos");
    add_root(datos / L"íconos");
    add_root(work / "Datos" / "icon");
    add_root(work / "Datos" / "icons");
    add_root(work / "Datos" / "Iconos");
    add_root(work / "Fuente" / "Config" / "geo" / "icon");
    return roots;
}

std::string place_icon_equivalence_key(std::string value) {
    
    value = normalize_key(path_utf8(fs::path(widen_utf8(trim(std::move(value)))).stem()));
    std::string out;
    out.reserve(value.size());
    for (char ch : value) {
        if (std::isalnum(static_cast<unsigned char>(ch))) out.push_back(ch);
    }
    return out;
}

int place_icon_extension_score(const fs::path& p) {
    const std::string ext = normalize_key(path_utf8(p.extension()));
    // Los glifos toponímicos se buscan como fuente vectorial primero: si el
    // usuario coloca Acatl.svg junto a Acatl.png, el SVG gobierna la identidad
    // del glifo y el PNG queda sólo como respaldo raster de ejecución. No se
    // introducen heurísticas nuevas: la resolución depende de catálogo curado,
    // nombre exacto de archivo o equivalencia toponímica explícita.
    if (ext == "svg") return 90;
    if (ext == "png") return 70;
    if (ext == "jpg" || ext == "jpeg") return 20;
    return 0;
}

bool place_icon_extension_supported(const fs::path& p) {
    return place_icon_extension_score(p) > 0;
}


void place_append_icon_lookup_stem(std::vector<std::string>& stems, std::string value);

struct PlaceToponymGlyphRule {
    std::string icon_stem;
    std::vector<std::string> keys;
};

std::vector<PlaceToponymGlyphRule> load_place_toponym_glyph_rules() {
    std::vector<PlaceToponymGlyphRule> rules;
    auto append_builtin = [&](const char* icon, std::initializer_list<const char*> aliases) {
        PlaceToponymGlyphRule r;
        r.icon_stem = icon ? icon : "";
        for (const char* alias : aliases) {
            const std::string k = place_icon_equivalence_key(alias ? alias : "");
            if (!k.empty() && std::find(r.keys.begin(), r.keys.end(), k) == r.keys.end()) r.keys.push_back(k);
        }
        const std::string icon_key = place_icon_equivalence_key(r.icon_stem);
        if (!icon_key.empty() && std::find(r.keys.begin(), r.keys.end(), icon_key) == r.keys.end()) r.keys.push_back(icon_key);
        if (!r.icon_stem.empty() && !r.keys.empty()) rules.push_back(std::move(r));
    };

    // Catálogo mínimo embebido para que la app siga resolviendo glifos aun si el
    // TSV curado no fue copiado. Cada equivalencia es deliberadamente explícita:
    // se evita inferir por fragmentos como "atl", "tepec" o "coatl" porque eso
    // vuelve a contaminar pueblos no relacionados. Sólo se reutiliza un glifo
    // cuando el topónimo completo, su grafía antigua o una variante histórica
    // concreta están declarados aquí o en glifos_toponimicos.tsv. Esta lista no
    // es una heurística fonética: es un índice curado de pueblos reales.
    append_builtin("Acatl", {"Acatlan", "Acatlán", "Acatlan de Osorio", "Acatlán de Osorio", "Acatlan de Juarez", "Acatlán de Juárez", "Acatepec", "San Juan Acatitlan", "San Juan Acatitlán", "Acatitlan", "Acatitlán"});
    append_builtin("Atenco", {"Atenco", "San Salvador Atenco", "San Mateo Atenco", "San Lucas Atenco", "San Sebastian Atenco", "San Sebastián Atenco"});
    append_builtin("Atotonilco", {"Atotonilco", "Atotonilco de Tula", "Atotonilco el Grande", "Atotonilco el Alto", "Atotonilco de Tula Hidalgo", "Atotonilco el Grande Hidalgo", "Atotonilco el Alto Jalisco"});
    append_builtin("Coacalco", {"Coacalco", "San Francisco Coacalco", "Coacalco de Berriozabal", "Coacalco de Berriozábal", "Coacalco Berriozabal", "Coacalco Berriozábal"});
    append_builtin("Coatepec", {"Coatepec", "Coatepec Harinas", "Coatepec de Harinas", "San Lorenzo Coatepec"});
    append_builtin("comitl", {"Comitl", "Comitlan", "Comitlán", "Comitan", "Comitán", "Comitan de Dominguez", "Comitán de Domínguez", "Santo Domingo de Comitán", "Santa María de Comitán"});
    append_builtin("Contla", {"Contla", "Contlan", "Contlán", "Contla de Juan Cuamatzi", "San Bernardino Contla"});
    append_builtin("cuauhtli", {"Cuauhtla", "Cuautla", "Quauhtla", "Quahutla", "Cuautla Morelos"});
    append_builtin("Ecatepec", {"Ecatepec", "Ehecatepec", "Ecatepec de Morelos", "San Cristobal Ecatepec", "San Cristóbal Ecatepec"});
    append_builtin("huitzilopuchco", {"Huitzilopochco", "Huitzilopuchco", "Churubusco", "San Mateo Churubusco"});
    append_builtin("malinalli", {"Malinalli", "Malinalco", "Santa Maria Malinalco", "Santa María Malinalco", "San Juan Malinaltongo", "Malinaltongo"});
    append_builtin("Malinalltepec", {"Malinalltepec", "Malinaltepec"});
    append_builtin("Mizquicuahuitl", {"Mizquicuahuitl", "Mixquic", "San Andres Mixquic", "San Andrés Mixquic"});
    append_builtin("nezahualcoyotl", {"Nezahualcoyotl", "Nezahualcóyotl", "Ciudad Nezahualcoyotl", "Ciudad Nezahualcóyotl"});
    append_builtin("Tlacatecuhtli_Nezahualcoyotl", {"Tlacatecuhtli Nezahualcoyotl"});
    append_builtin("Tochtepec", {"Tochtepec", "San Lorenzo Tochtepec", "San Juan Bautista Tuxtepec", "Tuxtepec", "San Juan Tuxtepec", "Tuxtepec Oaxaca"});
    append_builtin("Totoltepec", {"Totoltepec", "San Andres Totoltepec", "San Andrés Totoltepec", "Santo Tomas Totoltepec", "Santo Tomás Totoltepec", "Santiago Totoltepec", "San Miguel Totoltepec", "San Pedro Totoltepec", "Santa Cruz Totoltepec", "San Francisco Totoltepec"});
    append_builtin("xochitepec", {"Xochitepec", "Xuchipec", "San Juan Xochitepec", "Santa Cruz Xochitepec", "Xochitepec Morelos"});
    append_builtin("Xoco", {"Xoco", "San Sebastian Xoco", "San Sebastián Xoco"});
    append_builtin("Yopico", {"Yopico", "Tetlanman Yopico", "Santa Barbara Tetlanman Yopico", "Santa Bárbara Tetlanman Yopico"});
    append_builtin("Toluca", {"Toluca", "Toluca de Lerdo", "Tollocan"});

    const std::array<fs::path, 3> paths = {
        workspace_root() / "Fuente" / "Config" / "geo" / "glifos_toponimicos.tsv",
        datos_externos_root() / "glifos_toponimicos.tsv",
        workspace_root() / "Datos" / "glifos_toponimicos.tsv"
    };
    for (const fs::path& cfg : paths) {
        std::ifstream in(cfg);
        if (!in) continue;
        std::string line;
        bool header = true;
        while (std::getline(in, line)) {
            line = place_strip_bom(line);
            if (trim(line).empty() || trim(line)[0] == '#') continue;
            const auto cols = split_tsv_line(line);
            if (header) {
                header = false;
                if (!cols.empty() && normalize_key(cols[0]).find("icon") != std::string::npos) continue;
            }
            if (cols.size() < 2) continue;
            PlaceToponymGlyphRule r;
            r.icon_stem = trim(cols[0]);
            if (r.icon_stem.empty()) continue;
            auto add_keys = [&](const std::string& cell) {
                std::string token;
                auto flush = [&]() {
                    const std::string k = place_icon_equivalence_key(token);
                    if (!k.empty() && std::find(r.keys.begin(), r.keys.end(), k) == r.keys.end()) r.keys.push_back(k);
                    token.clear();
                };
                for (char ch : cell) {
                    if (ch == '|' || ch == ';' || ch == ',') flush();
                    else token.push_back(ch);
                }
                flush();
            };
            add_keys(r.icon_stem);
            // Sólo las columnas de grafía antigua y alias participan en la
            // equivalencia. Las notas son documentación humana y jamás deben
            // convertirse en llaves de búsqueda.
            const size_t alias_cols = std::min<size_t>(cols.size(), 3u);
            for (size_t i = 1; i < alias_cols; ++i) add_keys(cols[i]);
            if (!r.keys.empty()) rules.push_back(std::move(r));
        }
    }
    return rules;
}

const std::vector<PlaceToponymGlyphRule>& place_toponym_glyph_rules() {
    static const std::vector<PlaceToponymGlyphRule> rules = load_place_toponym_glyph_rules();
    return rules;
}

std::vector<std::string> place_toponymic_equivalence_keys_for_lookup(const std::string& raw_value) {
    std::vector<std::string> keys;
    auto add_key = [&](const std::string& value) {
        const std::string k = place_icon_equivalence_key(value);
        if (!k.empty() && std::find(keys.begin(), keys.end(), k) == keys.end()) keys.push_back(k);
    };
    add_key(raw_value);

    const std::string norm = normalize_key(raw_value);
    std::istringstream iss(norm);
    std::string word;
    std::string stripped;
    while (iss >> word) {
        if (word == "san" || word == "santa" || word == "santo" || word == "santos" ||
            word == "la" || word == "las" || word == "los" || word == "el" ||
            word == "de" || word == "del" || word == "y" || word == "villa" ||
            word == "pueblo" || word == "ciudad" || word == "municipio") {
            continue;
        }
        stripped += word;
    }
    add_key(stripped);
    return keys;
}

bool place_toponym_key_matches_curated_morpheme(const std::string& key, const std::string& root) {
    if (key.empty() || root.empty()) return false;
    if (key == root) return true;
    if (root.size() < 4) return false;

    // Este emparejamiento es intencionalmente morfológico-curado, no difuso:
    // acepta compuestos nahuas largos que conservan una raíz declarada, pero
    // evita que raíces cortísimas como atl contaminen cualquier topónimo con
    // letras coincidentes. Las equivalencias exactas del TSV gobiernan primero.
    if (key.size() > root.size() + 1 && key.rfind(root, 0) == 0) return true;
    if (key.size() > root.size() + 2 && key.size() >= root.size()) {
        const size_t start = key.size() - root.size();
        if (key.compare(start, root.size(), root) == 0) return true;
    }
    if (root.size() >= 5 && key.size() > root.size() + 2 && key.find(root) != std::string::npos) return true;
    return false;
}

void place_append_one_word_toponymic_glyph_aliases(std::vector<std::string>& stems, const std::string& raw_value) {
    const std::vector<std::string> keys = place_toponymic_equivalence_keys_for_lookup(raw_value);
    if (keys.empty()) return;

    struct RootRule {
        const char* icon_stem;
        const char* roots[8];
    };

    static const RootRule rules[] = {
        {"Acatl", {"acatl", "acat", "acatitlan", "acatlan", "acatepec"}},
        {"apantli", {"apantli", "apantla", "apan"}},
        {"Atenco", {"atenco"}},
        {"Atl", {"atlautla", "atlauhtla", "atlatlahucan", "atlacomulco"}},
        {"Atotonilco", {"atotonilco"}},
        {"calli", {"calli", "calpan", "calpulalpan"}},
        {"cipactli", {"cipactli"}},
        {"Coacalco", {"coacalco"}},
        {"Coatepec", {"coatepec"}},
        {"coatl", {"coatl", "coatlan", "coatzacoalcos", "coatzintla", "coatepec"}},
        {"comitl", {"comitl", "comitan", "comitlan"}},
        {"Contla", {"contla", "contlan"}},
        {"cuauhtli", {"cuauhtli", "cuauhtla", "cuautla"}},
        {"Ecatepec", {"ecatepec", "ehecatepec"}},
        {"ehecatl", {"ehecatl", "eheca"}},
        {"huitzilopuchco", {"huitzilopochco", "huitzilopuchco", "churubusco"}},
        {"itzcuintli", {"itzcuintli"}},
        {"malinalli", {"malinalli", "malinal", "malinalco", "malinaltongo"}},
        {"Malinalltepec", {"malinalltepec", "malinaltepec"}},
        {"mazatl", {"mazatl", "mazat"}},
        {"miquiztli", {"miquiztli"}},
        {"Mizquicuahuitl", {"mizquicuahuitl", "mizqui", "mixqui", "mixquic"}},
        {"nezahualcoyotl", {"nezahualcoyotl"}},
        {"ocelotl", {"ocelotl", "ocelo"}},
        {"Ollin", {"ollin"}},
        {"ozomahtli", {"ozomahtli"}},
        {"Pantli", {"pantli"}},
        {"Popoca", {"popoca", "popocatepetl"}},
        {"Quiahuitl", {"quiahuitl"}},
        {"Tecpatl", {"tecpatl"}},
        {"tepetl", {"tepetl", "tepec", "tepe"}},
        {"Tlalli", {"tlalli", "tlal", "tlalpan", "tlalnepantla"}},
        {"Tochtepec", {"tochtepec", "tuxtepec"}},
        {"Tochtli", {"tochtli", "toch"}},
        {"Toluca", {"toluca", "tollocan"}},
        {"Totolli", {"totolli", "totol"}},
        {"Totoltepec", {"totoltepec"}},
        {"Xilotl", {"xilotl", "xilo"}},
        {"xochitepec", {"xochitepec", "xuchipec"}},
        {"xochitl", {"xochitl", "xochi", "xochimilco"}}
    };

    for (const RootRule& rule : rules) {
        for (const char* raw_root : rule.roots) {
            if (!raw_root) break;
            const std::string root = place_icon_equivalence_key(raw_root);
            if (root.empty()) continue;
            for (const std::string& key : keys) {
                if (place_toponym_key_matches_curated_morpheme(key, root)) {
                    place_append_icon_lookup_stem(stems, rule.icon_stem);
                    return;
                }
            }
        }
    }

    static const RootRule exact_tail_rules[] = {
        {"Xoco", {"xoco", "xocotitlan"}},
        {"Xictli", {"xictli", "xic"}},
        {"Yopico", {"yopico"}}
    };
    for (const RootRule& rule : exact_tail_rules) {
        for (const char* raw_root : rule.roots) {
            if (!raw_root) break;
            const std::string root = place_icon_equivalence_key(raw_root);
            if (root.empty()) continue;
            for (const std::string& key : keys) {
                if (place_toponym_key_matches_curated_morpheme(key, root)) {
                    place_append_icon_lookup_stem(stems, rule.icon_stem);
                    return;
                }
            }
        }
    }
}

void place_append_curated_toponymic_glyph_aliases(std::vector<std::string>& stems, const std::string& raw_value) {
    const std::vector<std::string> keys = place_toponymic_equivalence_keys_for_lookup(raw_value);
    if (keys.empty()) return;

    bool matched_exact_catalog = false;
    for (const PlaceToponymGlyphRule& rule : place_toponym_glyph_rules()) {
        for (const std::string& key : keys) {
            if (std::find(rule.keys.begin(), rule.keys.end(), key) != rule.keys.end()) {
                place_append_icon_lookup_stem(stems, rule.icon_stem);
                matched_exact_catalog = true;
                break;
            }
        }
    }

    // Si el catálogo exacto no resolvió un pueblo, se permite una segunda capa
    // estrictamente curada de raíces de una palabra tomadas del propio inventario
    // Datos/icon. No participan gráficos de la UI ni el icono de la aplicación.
    if (!matched_exact_catalog) place_append_one_word_toponymic_glyph_aliases(stems, raw_value);
}

void place_append_icon_lookup_stem(std::vector<std::string>& stems, std::string value) {
    value = trim(std::move(value));
    if (value.empty()) return;
    const std::string key = place_icon_equivalence_key(value);
    if (key.empty()) return;
    for (const std::string& old : stems) {
        if (place_icon_equivalence_key(old) == key) return;
    }
    stems.push_back(std::move(value));
}

void place_append_explicit_place_icon_aliases(std::vector<std::string>& stems, const std::string& raw_value) {
    const std::string trimmed = trim(raw_value);
    if (trimmed.empty()) return;

    place_append_icon_lookup_stem(stems, trimmed);
    const std::string normalized = normalize_key(trimmed);
    place_append_icon_lookup_stem(stems, normalized);
    place_append_icon_lookup_stem(stems, safe_filename(trimmed));
    place_append_icon_lookup_stem(stems, safe_filename(normalized));

    // Primero se consulta el catálogo curado de topónimos: el vínculo entre un
    // pueblo y su glifo no debe ser una búsqueda difusa por sílabas, sino una
    // equivalencia explícita entre el topónimo real, su grafía antigua y el
    // archivo de glifo disponible. Esto permite reutilizaciones como
    // Cuautla/Cuauhtla -> cuauhtli o múltiples Totoltepec -> Totoltepec sin
    // contaminar otros pueblos terminados en -tepec.
    place_append_curated_toponymic_glyph_aliases(stems, trimmed);
}

std::optional<fs::path> find_place_icon_in_runtime_index(const std::vector<std::string>& wanted_keys) {
    
    if (wanted_keys.empty()) return std::nullopt;
    struct IndexedIconPath {
        fs::path path;
        int score = 0;
    };
    static std::mutex mu;
    static std::map<std::string, IndexedIconPath> index;
    static std::uint64_t last_rebuild_frame = 0;
    const std::uint64_t frame = g_map_frame_counter;

    auto rebuild = [&]() {
        std::map<std::string, IndexedIconPath> fresh;
        std::error_code ec;
        for (const fs::path& root : place_glyph_roots()) {
            if (!fs::exists(root, ec) || !fs::is_directory(root, ec)) { ec.clear(); continue; }
            fs::directory_iterator it(root, fs::directory_options::skip_permission_denied, ec);
            fs::directory_iterator end;
            for (; !ec && it != end; it.increment(ec)) {
                const fs::path candidate_path = it->path();
                if (!fs::is_regular_file(candidate_path, ec)) { ec.clear(); continue; }
                if (!place_icon_extension_supported(candidate_path)) continue;
                const std::string key = place_icon_equivalence_key(path_utf8(candidate_path.stem()));
                if (key.empty()) continue;
                int score = 10 + place_icon_extension_score(candidate_path);
                const std::string full = normalize_key(path_utf8(candidate_path.lexically_normal()));
                score += std::max(0, 200 - static_cast<int>(full.size())) / 10;
                auto old = fresh.find(key);
                if (old == fresh.end() || score > old->second.score) fresh[key] = IndexedIconPath{candidate_path, score};
            }
            ec.clear();
        }
        index.swap(fresh);
        last_rebuild_frame = frame;
    };

    std::lock_guard<std::mutex> lock(mu);
    if (last_rebuild_frame == 0 || frame > last_rebuild_frame + 900) rebuild();
    for (const std::string& key : wanted_keys) {
        if (key.empty()) continue;
        auto it = index.find(key);
        if (it != index.end() && !it->second.path.empty()) return it->second.path;
    }

    
    return std::nullopt;
}

std::optional<fs::path> find_place_glyph_icon(const MapPlace& place) {
    struct CacheEntry {
        std::optional<fs::path> path;
        std::uint64_t last_probe = 0;
    };
    static std::mutex mu;
    static std::map<std::string, CacheEntry> cache;
    const std::string key = place_icon_equivalence_key(place.id + "|" + place.name + "|" + place.glyph);
    const std::uint64_t frame = g_map_frame_counter;
    {
        std::lock_guard<std::mutex> lock(mu);
        auto it = cache.find(key);
        if (it != cache.end()) {
            if (it->second.path) return it->second.path;
            if (frame <= it->second.last_probe + 90) return std::nullopt;
        }
    }

    std::vector<std::string> stems;
    place_append_explicit_place_icon_aliases(stems, place.glyph);
    place_append_explicit_place_icon_aliases(stems, place.name);
    place_append_explicit_place_icon_aliases(stems, place.id);
    place_append_icon_lookup_stem(stems, safe_filename(place.name));
    place_append_icon_lookup_stem(stems, safe_filename(normalize_key(place.name)));
    place_append_icon_lookup_stem(stems, safe_filename(normalize_key(place.id)));

    std::vector<std::string> wanted_keys;
    wanted_keys.reserve(stems.size());
    for (const std::string& stem : stems) {
        const std::string k = place_icon_equivalence_key(stem);
        if (!k.empty() && std::find(wanted_keys.begin(), wanted_keys.end(), k) == wanted_keys.end()) wanted_keys.push_back(k);
    }

    const std::array<std::string, 4> exts = {".svg", ".png", ".jpg", ".jpeg"};
    std::optional<fs::path> found;
    std::error_code ec;
    for (const auto& root : place_glyph_roots()) {
        if (!fs::exists(root, ec) || !fs::is_directory(root, ec)) { ec.clear(); continue; }

        for (const std::string& stem : stems) {
            fs::path stem_path(widen_utf8(stem));
            if (stem_path.is_absolute() && fs::exists(stem_path, ec) && fs::is_regular_file(stem_path, ec) && place_icon_extension_supported(stem_path)) { found = stem_path; break; }
            ec.clear();
            if (stem_path.has_extension()) {
                fs::path p = root / stem_path;
                if (fs::exists(p, ec) && fs::is_regular_file(p, ec) && place_icon_extension_supported(p)) { found = p; break; }
                ec.clear();
            }
            for (const std::string& ext : exts) {
                fs::path p = root / fs::path(widen_utf8(stem + ext));
                if (fs::exists(p, ec) && fs::is_regular_file(p, ec)) { found = p; break; }
                ec.clear();
            }
            if (found) break;
        }
        if (found) break;

        if (auto indexed = find_place_icon_in_runtime_index(wanted_keys)) { found = indexed; break; }
        ec.clear();
    }
    {
        std::lock_guard<std::mutex> lock(mu);
        cache[key] = CacheEntry{found, frame};
        if (cache.size() > 4096) cache.clear();
    }
    return found;
}


int place_glyph_binary_threshold_rgba(const unsigned char* pixels, int w, int h) {
    if (!pixels || w <= 0 || h <= 0) return 196;
    std::array<unsigned long long, 256> hist{};
    unsigned long long total = 0;
    unsigned long long sum = 0;
    const int n = w * h;
    for (int i = 0; i < n; ++i) {
        const unsigned char* p = pixels + i * 4;
        const unsigned char a = p[3];
        if (a < 16) continue;
        const int lum = static_cast<int>(0.299f * p[0] + 0.587f * p[1] + 0.114f * p[2] + 0.5f);
        hist[static_cast<size_t>(std::clamp(lum, 0, 255))]++;
        total++;
        sum += static_cast<unsigned long long>(std::clamp(lum, 0, 255));
    }
    if (total == 0) return 196;

    unsigned long long w_b = 0;
    unsigned long long sum_b = 0;
    double best_score = -1.0;
    int best_t = 196;
    for (int t = 0; t < 256; ++t) {
        w_b += hist[static_cast<size_t>(t)];
        if (w_b == 0) continue;
        const unsigned long long w_f = total - w_b;
        if (w_f == 0) break;
        sum_b += static_cast<unsigned long long>(t) * hist[static_cast<size_t>(t)];
        const double mean_b = static_cast<double>(sum_b) / static_cast<double>(w_b);
        const double mean_f = static_cast<double>(sum - sum_b) / static_cast<double>(w_f);
        const double delta = mean_b - mean_f;
        const double score = static_cast<double>(w_b) * static_cast<double>(w_f) * delta * delta;
        if (score > best_score) {
            best_score = score;
            best_t = t;
        }
    }

    
    return std::clamp(best_t, 112, 224);
}


fs::path place_glyph_raster_fallback_for_svg(const fs::path& svg_path) {
    if (normalize_key(path_utf8(svg_path.extension())) != "svg") return svg_path;
    // La prioridad de identidad es SVG, pero el backend OpenGL actual no incluye
    // un rasterizador SVG general. Para no dejar sin glifo al usuario, se usa el
    // raster homónimo sólo como respaldo de render. La política sigue siendo:
    // SVG > PNG > JPG en selección; si se incorpora rasterizador vectorial, esta
    // función debe reducirse a `return svg_path` sin tocar el catálogo.
    std::error_code ec;
    for (const char* ext : {".png", ".jpg", ".jpeg"}) {
        fs::path p = svg_path;
        p.replace_extension(ext);
        if (fs::exists(p, ec) && fs::is_regular_file(p, ec)) return p;
        ec.clear();
    }
    return svg_path;
}

PreviewTexture load_persistent_place_glyph_texture(const fs::path& path, bool light_background) {
    struct PlaceGlyphTextureEntry {
        PreviewTexture tex;
        std::uint64_t last_used = 0;
    };
    static std::mutex mu;
    static std::map<std::string, PlaceGlyphTextureEntry> cache;

    const fs::path render_path = place_glyph_raster_fallback_for_svg(path);
    if (!fs::exists(render_path)) return {};
    if (normalize_key(path_utf8(render_path.extension())) == "svg") return {};
    std::error_code stat_ec;
    const auto file_size_for_key = fs::file_size(render_path, stat_ec);
    if (stat_ec) stat_ec.clear();
    const auto file_time_for_key = fs::last_write_time(render_path, stat_ec);
    const long long file_time_count = stat_ec ? 0ll : static_cast<long long>(file_time_for_key.time_since_epoch().count());
    if (stat_ec) stat_ec.clear();
    const std::string key = normalize_key(path_utf8(path.lexically_normal())) + "|render=" + normalize_key(path_utf8(render_path.lexically_normal())) +
        "|sz=" + std::to_string(static_cast<unsigned long long>(file_size_for_key)) +
        "|mt=" + std::to_string(file_time_count) +
        (light_background ? "|light" : "|dark");
    if (key.empty()) return {};
    {
        std::lock_guard<std::mutex> lock(mu);
        auto it = cache.find(key);
        if (it != cache.end()) {
            it->second.last_used = g_map_frame_counter;
            return it->second.tex;
        }
    }
    if (g_icon_texture_loads_remaining <= 0) return {};
    --g_icon_texture_loads_remaining;

    std::ifstream in(render_path, std::ios::binary);
    if (!in) return {};
    std::vector<unsigned char> bytes((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
    if (bytes.empty() || bytes.size() > static_cast<size_t>(std::numeric_limits<int>::max())) return {};

    int w = 0, h = 0, channels = 0;
    unsigned char* pixels = stbi_load_from_memory(bytes.data(), static_cast<int>(bytes.size()), &w, &h, &channels, 4);
    if (!pixels || w <= 0 || h <= 0) {
        if (pixels) stbi_image_free(pixels);
        return {};
    }

    const long long pixel_count_ll = static_cast<long long>(w) * static_cast<long long>(h);
    if (w > 4096 || h > 4096 || pixel_count_ll <= 0 || pixel_count_ll > 16777216ll) {
        stbi_image_free(pixels);
        return {};
    }
    const int n = static_cast<int>(pixel_count_ll);
    const int threshold = place_glyph_binary_threshold_rgba(pixels, w, h);
    const unsigned char ink = light_background ? static_cast<unsigned char>(92) : static_cast<unsigned char>(218);

    for (int i = 0; i < n; ++i) {
        const unsigned char r = pixels[i * 4 + 0];
        const unsigned char g = pixels[i * 4 + 1];
        const unsigned char b = pixels[i * 4 + 2];
        const unsigned char a = pixels[i * 4 + 3];
        const int lum = static_cast<int>(0.299f * r + 0.587f * g + 0.114f * b + 0.5f);
        const bool keep = a >= 16 && lum >= threshold;
        pixels[i * 4 + 0] = keep ? ink : static_cast<unsigned char>(0);
        pixels[i * 4 + 1] = keep ? ink : static_cast<unsigned char>(0);
        pixels[i * 4 + 2] = keep ? ink : static_cast<unsigned char>(0);
        pixels[i * 4 + 3] = keep ? static_cast<unsigned char>(255) : static_cast<unsigned char>(0);
    }

    unsigned int id = 0;
    glGenTextures(1, &id);
    glBindTexture(GL_TEXTURE_2D, id);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
    glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, w, h, 0, GL_RGBA, GL_UNSIGNED_BYTE, pixels);
    stbi_image_free(pixels);

    PreviewTexture tex{id, w, h};
    {
        std::lock_guard<std::mutex> lock(mu);
        cache[key] = PlaceGlyphTextureEntry{tex, g_map_frame_counter};
        if (cache.size() > 768) {
            for (auto it = cache.begin(); it != cache.end();) {
                if (g_map_frame_counter > it->second.last_used + 900) it = cache.erase(it);
                else ++it;
            }
            if (cache.size() > 1024) cache.clear();
        }
    }
    return tex;
}

bool draw_place_icon_texture_flat_box(ImDrawList* dl, PreviewTexture tex, ImVec2 a, ImVec2 b, ImU32 tint = IM_COL32(255, 255, 255, 255)) {
    
    if (!dl || tex.id == 0 || tex.width <= 0 || tex.height <= 0) return false;
    if (!(b.x > a.x && b.y > a.y)) return false;
    ImVec2 aa(std::floor(a.x), std::floor(a.y));
    ImVec2 bb(std::ceil(b.x), std::ceil(b.y));
    if (!(bb.x > aa.x && bb.y > aa.y)) return false;
    dl->AddImage((ImTextureID)(intptr_t)tex.id, aa, bb, ImVec2(0, 0), ImVec2(1, 1), tint);
    return true;
}

std::string place_card_interaction_key(const MapPlace& place) {
    if (!trim(place.id).empty()) return trim(place.id);
    const long long lon_i = static_cast<long long>(std::llround(place.lon * 1000000.0));
    const long long lat_i = static_cast<long long>(std::llround(place.lat * 1000000.0));
    return normalize_key(place.name) + "|" + std::to_string(lon_i) + "|" + std::to_string(lat_i);
}

void draw_place_radial_marker(ImDrawList* dl, const ImVec2& center, float size, const MapPlace& place, bool hot, bool light_theme) {
    (void)light_theme;
    const int rank = std::clamp(place.rank, 1, 4);
    float r = std::max(1.05f, size * 0.090f);
    r += static_cast<float>(4 - rank) * 0.16f;
    if (place.population >= 1000000) r += 0.30f;
    else if (place.population >= 250000) r += 0.18f;
    else if (place.population >= 50000) r += 0.10f;
    if (place.zocalo_anchor) r += 0.24f;
    if (hot) r += 0.82f;
    r = std::clamp(r, hot ? 2.35f : 1.35f, hot ? 4.35f : 3.10f);

    
    const ImU32 underlay = IM_COL32(10, 13, 18, hot ? 190 : 128);
    const ImU32 fill = IM_COL32(255, 255, 255, hot ? 255 : 238);
    dl->AddCircleFilled(center, r + 0.68f, underlay, 12);
    dl->AddCircleFilled(center, r, fill, 12);
}

bool draw_place_icon_texture_direct(ImDrawList* dl, PreviewTexture tex, const ImVec2& center, float side, bool hot, bool light_theme) {
    if (!dl || tex.id == 0 || tex.width <= 0 || tex.height <= 0 || side <= 0.0f) return false;

    const float phi = kGoldenN0 + kGoldenN1;
    const float halo_step = side * kGoldenN4;
    const float halo_side = side + halo_step * (hot ? phi : kGoldenN0);
    const float aspect = tex.height > 0 ? static_cast<float>(tex.width) / static_cast<float>(tex.height) : 1.0f;
    float draw_w = side;
    float draw_h = side;
    if (aspect > 1.0f) draw_h = side / std::min(aspect, phi * phi);
    else if (aspect > 0.0f) draw_w = side * std::max(aspect, kGoldenN2);

    float halo_w = halo_side;
    float halo_h = halo_side;
    if (aspect > 1.0f) halo_h = halo_side / std::min(aspect, phi * phi);
    else if (aspect > 0.0f) halo_w = halo_side * std::max(aspect, kGoldenN2);

    const ImU32 halo_0 = light_theme ? IM_COL32(255, 255, 255, hot ? 232 : 188) : IM_COL32(0, 0, 0, hot ? 228 : 186);
    const ImU32 halo_1 = light_theme ? IM_COL32(255, 255, 255, hot ? 150 : 104) : IM_COL32(0, 0, 0, hot ? 154 : 110);
    const ImU32 ink = IM_COL32(255, 255, 255, hot ? 255 : 238);

    const auto add_image_centered = [&](float w, float h, ImVec2 offset, ImU32 tint) {
        const ImVec2 a(center.x + offset.x - w * 0.5f, center.y + offset.y - h * 0.5f);
        const ImVec2 b(center.x + offset.x + w * 0.5f, center.y + offset.y + h * 0.5f);
        dl->AddImage((ImTextureID)(intptr_t)tex.id, a, b, ImVec2(0, 0), ImVec2(1, 1), tint);
    };

    
    add_image_centered(halo_w, halo_h, ImVec2(0.0f, 0.0f), halo_0);
    const float d = std::max(1.0f, side * kGoldenN7);
    add_image_centered(halo_w, halo_h, ImVec2( d, 0.0f), halo_1);
    add_image_centered(halo_w, halo_h, ImVec2(-d, 0.0f), halo_1);
    add_image_centered(halo_w, halo_h, ImVec2(0.0f,  d), halo_1);
    add_image_centered(halo_w, halo_h, ImVec2(0.0f, -d), halo_1);
    add_image_centered(draw_w, draw_h, ImVec2(0.0f, 0.0f), ink);
    return true;
}

bool draw_place_icon_marker(ImDrawList* dl, const MapPlace& place, const fs::path& icon_path, const ImVec2& center, float size, bool hot, bool light_theme) {
    PreviewTexture tex = load_persistent_place_glyph_texture(icon_path, light_theme);
    if (tex.id == 0 || tex.width <= 0 || tex.height <= 0) return false;

    const float phi = kGoldenN0 + kGoldenN1;
    const float glyph_box = std::clamp(size * phi * (hot ? phi : kGoldenN0), 24.0f, hot ? 72.0f : 52.0f);
    (void)place;
    return draw_place_icon_texture_direct(dl, tex, center, glyph_box, hot, light_theme);
}

bool draw_place_glyph_marker(ImDrawList* dl, const MapPlace& place, const ImVec2& center, float size, bool hot, bool light_theme) {
    if (auto icon_path = find_place_glyph_icon(place)) {
        if (draw_place_icon_marker(dl, place, *icon_path, center, size, hot, light_theme)) return true;
    }
    draw_place_radial_marker(dl, center, size, place, hot, light_theme);
    return false;
}

void draw_place_marker_lod(ImDrawList* dl, const MapPlace& place, const ImVec2& center, float size, bool hot, bool light_theme, bool glyph_lod_enabled) {
    if (glyph_lod_enabled) {
        (void)draw_place_glyph_marker(dl, place, center, size, hot, light_theme);
        return;
    }
    draw_place_radial_marker(dl, center, size, place, hot, light_theme);
}

bool draw_place_glyph_widget_direct(const MapPlace& place, float size, bool light_theme) {
    auto icon_path = find_place_glyph_icon(place);
    if (!icon_path) return false;
    PreviewTexture tex = load_persistent_place_glyph_texture(*icon_path, light_theme);
    if (tex.id == 0 || tex.width <= 0 || tex.height <= 0) return false;

    ImDrawList* dl = ImGui::GetWindowDrawList();
    const ImVec2 p = ImGui::GetCursorScreenPos();
    const float inset = std::max(0.0f, std::floor(size * kGoldenN12));
    const bool drawn = draw_place_icon_texture_flat_box(dl, tex, ImVec2(p.x + inset, p.y + inset), ImVec2(p.x + size - inset, p.y + size - inset));
    ImGui::InvisibleButton("##place-head-glyph-direct", ImVec2(size, size));
    return drawn;
}

void draw_place_card_contents(const MapPlace& place, bool light_theme) {
    const float phi = kGoldenN0 + kGoldenN1;
    const float text_h = ImGui::GetTextLineHeight();
    const float line_gap = std::max(1.0f, text_h * kGoldenN13);
    const float inner_gap = std::max(2.0f, text_h * kGoldenN9);
    const ImU32 muted = light_theme ? IM_COL32(62, 74, 86, 230) : IM_COL32(214, 226, 238, 232);

    std::vector<std::string> lines;
    lines.reserve(4);
    lines.push_back(trim(place.name));
    lines.push_back(place_card_population_line(place));
    lines.push_back(place_card_coordinate_line(place));
    const std::string elev = place_card_elevation_line(place);
    if (!elev.empty()) lines.push_back(elev);

    
    const auto card_icon_path = find_place_glyph_icon(place);
    const PreviewTexture card_icon_tex = card_icon_path ? load_persistent_place_glyph_texture(*card_icon_path, light_theme) : PreviewTexture{};
    const bool has_glyph = card_icon_tex.id != 0 && card_icon_tex.width > 0 && card_icon_tex.height > 0;

    const float text_block_h = std::max(text_h, static_cast<float>(lines.size()) * text_h + static_cast<float>(lines.size() > 1 ? lines.size() - 1 : 0) * line_gap);
    const float icon_side = std::clamp(text_block_h, text_h * phi * phi, text_h * phi * phi * phi * phi);
    // Un escalón áureo adicional evita que los topónimos densos se corten en tarjetas estrechas sin inflar el glifo.
    const float text_col_w = std::clamp(icon_side * phi * phi, text_h * phi * phi * phi * phi, text_h * phi * phi * phi * phi * phi * phi);

    ImGui::BeginGroup();
    {
        ImDrawList* card_dl = ImGui::GetWindowDrawList();
        const ImVec2 gp = ImGui::GetCursorScreenPos();
        const ImVec2 gc(gp.x + icon_side * 0.5f, gp.y + icon_side * 0.5f);
        if (has_glyph) {
            const float inset = std::max(0.0f, std::floor(icon_side * kGoldenN12));
            draw_place_icon_texture_flat_box(card_dl, card_icon_tex, ImVec2(gp.x + inset, gp.y + inset), ImVec2(gp.x + icon_side - inset, gp.y + icon_side - inset));
        } else {
            draw_place_radial_marker(card_dl, gc, icon_side * 0.86f, place, false, light_theme);
        }
        ImGui::InvisibleButton("##place-card-icon-compact", ImVec2(icon_side, icon_side));
    }
    ImGui::EndGroup();
    ImGui::SameLine(0.0f, inner_gap);

    ImGui::BeginGroup();
    for (size_t i = 0; i < lines.size(); ++i) {
        if (lines[i].empty()) continue;
        if (i > 0) ImGui::Dummy(ImVec2(1.0f, line_gap));
        if (i > 0) ImGui::PushStyleColor(ImGuiCol_Text, muted);
        ImGui::PushTextWrapPos(ImGui::GetCursorPosX() + text_col_w);
        ImGui::TextWrapped("%s", lines[i].c_str());
        ImGui::PopTextWrapPos();
        if (i > 0) ImGui::PopStyleColor();
    }
    ImGui::EndGroup();
}
void draw_atmospheric_station_card_contents(const AtmosphericPopupData& data, bool light_theme) {
    if (!data.valid) return;
    const auto pairs = atmospheric_popup_pairs(data);
    if (pairs.empty()) return;
    const AtmosphericCloudPoint& head = pairs.front().first;
    const float text_h = ImGui::GetTextLineHeight();
    const float pad_x = std::max(4.0f, golden_w(kGoldenN13));
    const float marker_r = std::max(5.0f, text_h * kGoldenN5);
    const ImU32 muted = light_theme ? IM_COL32(62, 74, 86, 230) : IM_COL32(214, 226, 238, 232);

    const float card_text_w = 318.0f;
    ImGui::PushTextWrapPos(ImGui::GetCursorPosX() + card_text_w);
    const size_t icon_count = std::min<size_t>(pairs.size(), static_cast<size_t>(3));
    for (size_t i = 0; i < icon_count; ++i) {
        if (i > 0) ImGui::SameLine(0.0f, std::max(2.0f, marker_r * kGoldenN5));
        const AtmosphericCloudPoint& point = pairs[i].first;
        const std::string tip = atmospheric_parameter_label(point.pollutant);
        char id[64];
        std::snprintf(id, sizeof(id), "##atm-head-%zu", i);
        draw_atmospheric_marker_circle(id, atmospheric_health_color(point.pollutant, point.mean, point.unit, 235), marker_r, nullptr);
    }
    if (icon_count > 0) ImGui::SameLine(0.0f, pad_x);
    const std::string title = atmospheric_station_sigla3(head.station_id, head.station) + " " + head.station;
    ImGui::TextWrapped("%s", title.c_str());
    ImGui::PopTextWrapPos();

    ImGui::Spacing();
    ImGui::Separator();
    ImGui::Spacing();

    for (size_t i = 0; i < pairs.size(); ++i) {
        const AtmosphericCloudPoint& point = pairs[i].first;
        const int pct = atmospheric_quality_percent(point);
        const char* band = atmospheric_measurement_band_label(point.pollutant, point.mean, point.unit);
        const std::string quality = pct == -2 ? std::string(band) :
            (pct >= 0 ? (std::to_string(pct) + "% " + band) : std::string("sin escala física"));
        char id[64];
        std::snprintf(id, sizeof(id), "##atm-line-%zu", i);
        draw_atmospheric_marker_circle(id, atmospheric_health_color(point.pollutant, point.mean, point.unit, 235), marker_r * (1.0f - kGoldenN7), nullptr);
        ImGui::SameLine(0.0f, pad_x);
        const std::string line = atmospheric_parameter_label(point.pollutant) + ": " +
            atmospheric_quantity_for_parameter(point.pollutant, point.mean, point.unit) + " (" + quality + ") " +
            atmospheric_radius_km_value_label(point);
        ImGui::PushStyleColor(ImGuiCol_Text, muted);
        ImGui::TextWrapped("%s", line.c_str());
        ImGui::PopStyleColor();
    }
}

void draw_atmospheric_pinned_window(AtmosphericPopupData& data, const ImVec2& canvas_origin, const ImVec2& canvas_size, bool light_theme) {
    if (!data.valid) return;
    const auto pairs = atmospheric_popup_pairs(data);
    const float w = std::clamp(canvas_size.x * kGoldenN3, 360.0f, 540.0f);
    const float estimated_h = std::clamp(92.0f + static_cast<float>(std::max<size_t>(1, pairs.size())) * 30.0f, 148.0f, 360.0f);
    ImVec2 pos(data.anchor.x + std::max(10.0f, golden_w(kGoldenN13)), data.anchor.y + std::max(10.0f, golden_h(kGoldenN13)));
    pos.x = std::clamp(pos.x, canvas_origin.x + 10.0f, std::max(canvas_origin.x + 10.0f, canvas_origin.x + canvas_size.x - w - 10.0f));
    pos.y = std::clamp(pos.y, canvas_origin.y + 10.0f, std::max(canvas_origin.y + 10.0f, canvas_origin.y + canvas_size.y - estimated_h - 10.0f));

    ImGui::SetNextWindowPos(pos, ImGuiCond_Appearing);
    ImGui::SetNextWindowSize(ImVec2(w, 0.0f), ImGuiCond_Appearing);
    bool open = true;
    ImGui::PushStyleVar(ImGuiStyleVar_WindowRounding, std::max(8.0f, golden_h(kGoldenN12)));
    ImGui::PushStyleVar(ImGuiStyleVar_FrameRounding, std::max(6.0f, golden_h(kGoldenN13)));
    ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(std::max(12.0f, golden_w(kGoldenN13)), std::max(10.0f, golden_h(kGoldenN13))));
    if (ImGui::Begin("Estación atmosférica###atmospheric-rama-detail", &open,
                     ImGuiWindowFlags_NoSavedSettings | ImGuiWindowFlags_NoCollapse | ImGuiWindowFlags_AlwaysAutoResize)) {
        draw_atmospheric_station_card_contents(data, light_theme);
    }
    ImGui::End();
    ImGui::PopStyleVar(3);
    if (!open) data.valid = false;
}


