const HistoricalLacustrineEpoch* historical_epoch_for_year(const HistoricalLacustrineBody& body, int year) {

    for (const auto& ep : body.epochs) {

        if (year >= ep.year_start && year <= ep.year_end && ep.polygon.size() >= 3) return &ep;
    }

    return nullptr;
}



std::string historical_lacustrine_stage_label(int year) {

    if (year <= 1550) return "sistema lacustre mayor";

    if (year <= 1700) return "primeras obras de control";

    if (year <= 1850) return "contraccion por drenaje colonial-tardio";

    if (year <= 1910) return "remanentes decimononicos";

    if (year <= 1975) return "vasos residuales del siglo XX";

    if (year < 2000) return "transicion hidraulica reciente";

    return "sin superficies lacustres historicas recreadas";
}



ImVec2 centroid_screen_of_polyline(const std::vector<ImVec2>& pts) {

    if (pts.empty()) return ImVec2(0.0f, 0.0f);
    double x = 0.0;
    double y = 0.0;

    for (const auto& p : pts) { x += p.x; y += p.y; }

    return ImVec2(static_cast<float>(x / static_cast<double>(pts.size())), static_cast<float>(y / static_cast<double>(pts.size())));
}



bool historical_poly_visible(const std::vector<ImVec2>& pts, const ImVec2& origin, const ImVec2& size) {

    if (pts.size() < 3) return false;
    float min_x = pts[0].x, max_x = pts[0].x, min_y = pts[0].y, max_y = pts[0].y;

    for (const auto& p : pts) {
        min_x = std::min(min_x, p.x); max_x = std::max(max_x, p.x);
        min_y = std::min(min_y, p.y); max_y = std::max(max_y, p.y);
    }

    return max_x >= origin.x - 12.0f && min_x <= origin.x + size.x + 12.0f &&
           max_y >= origin.y - 12.0f && min_y <= origin.y + size.y + 12.0f;
}



void draw_historical_dashed_closed_polyline(ImDrawList* dl, const std::vector<ImVec2>& pts, ImU32 col, float thickness) {

    if (!dl || pts.size() < 2) return;

    constexpr float dash = 8.0f;
    constexpr float gap = 5.0f;

    for (size_t i = 0; i < pts.size(); ++i) {
        const ImVec2 a = pts[i];
        const ImVec2 b = pts[(i + 1) % pts.size()];
        const float dx = b.x - a.x;
        const float dy = b.y - a.y;
        const float len = std::sqrt(dx * dx + dy * dy);

        if (len <= 0.5f) continue;
        const float ux = dx / len;
        const float uy = dy / len;

        for (float t = 0.0f; t < len; t += dash + gap) {

            const float t1 = std::min(len, t + dash);
            dl->AddLine(ImVec2(a.x + ux * t, a.y + uy * t), ImVec2(a.x + ux * t1, a.y + uy * t1), col, thickness);
        }
    }
}



void draw_historical_lacustrine_label(ImDrawList* dl, const ImVec2& anchor, const std::string& text, bool light_theme) {

    if (!dl || text.empty()) return;

    const ImVec2 ts = ImGui::CalcTextSize(text.c_str());
    const ImVec2 pad(6.0f, 3.0f);
    const ImVec2 a(anchor.x + 8.0f, anchor.y - ts.y * 0.5f - pad.y);
    const ImVec2 b(a.x + ts.x + pad.x * 2.0f, a.y + ts.y + pad.y * 2.0f);
    const ImU32 bg = light_theme ? IM_COL32(232, 247, 252, 214) : IM_COL32(3, 22, 32, 214);
    const ImU32 br = light_theme ? IM_COL32(44, 112, 136, 138) : IM_COL32(128, 218, 244, 126);
    const ImU32 fg = light_theme ? IM_COL32(14, 60, 78, 238) : IM_COL32(212, 244, 252, 238);
    dl->AddRectFilled(a, b, bg, 5.0f);
    dl->AddRect(a, b, br, 5.0f, 0, 1.0f);
    dl->AddText(ImVec2(a.x + pad.x, a.y + pad.y), fg, text.c_str());
}



void draw_historical_map_badge(ImDrawList* dl, const ImVec2& origin, bool light_theme, int year, bool thomas_patch_visible) {

    if (!dl) return;
    (void)thomas_patch_visible;

    std::string txt = "Mapa historico · " + std::to_string(year) + " · fuentes oficiales CDMX/REPSA";

    if (historical_external_kml_features().empty()) txt += " · esperando GeoJSON/KMZ oficial";
    const ImVec2 pad(9.0f, 5.0f);

    const ImVec2 ts = ImGui::CalcTextSize(txt.c_str());
    const ImVec2 a(origin.x + 14.0f, origin.y + 14.0f);
    const ImVec2 b(a.x + ts.x + pad.x * 2.0f, a.y + ts.y + pad.y * 2.0f);
    const ImU32 bg = light_theme ? IM_COL32(239, 250, 253, 205) : IM_COL32(2, 18, 28, 210);
    const ImU32 br = light_theme ? IM_COL32(42, 108, 132, 118) : IM_COL32(136, 218, 244, 108);
    const ImU32 fg = light_theme ? IM_COL32(14, 58, 76, 236) : IM_COL32(218, 245, 252, 238);
    dl->AddRectFilled(a, b, bg, 8.0f);
    dl->AddRect(a, b, br, 8.0f, 0, 1.0f);
    dl->AddText(ImVec2(a.x + pad.x, a.y + pad.y), fg, txt.c_str());
}



