void historical_schedule_authoritative_asset_downloads_once() {



    static std::atomic<bool> launched{false};

    bool expected = false;

    if (!launched.compare_exchange_strong(expected, true)) return;

    std::thread([]() {

        const fs::path cache = historical_authoritative_cache_dir();
        ensure_dir(cache);

        for (const auto& spec : historical_authoritative_asset_specs()) {

            bool already_available = false;

            for (const auto& root : historical_asset_roots()) {
                std::error_code ec;

                if (fs::exists(root / spec.filename, ec) && !ec) { already_available = true; break; }
            }


            if (already_available) continue;

            const fs::path dst = cache / spec.filename;
            std::error_code ec;

            if (fs::exists(dst, ec) && !ec && file_size_or_zero(dst) >= spec.min_bytes) continue;

            nlohmann::json audit = nlohmann::json::object();
            audit["asset_id"] = spec.id;

            audit["source_url"] = spec.url;

            audit["source_policy"] = "official_historical_geometry_cache";

            const std::string transfer_kind = (std::string(spec.kind) == "kmz") ? "kmz" : "geojson";

            (void)download_validated_url_to_file(spec.url, dst, transfer_kind, spec.min_bytes, 3, &audit);
            try {
                ensure_dir(cache / "_auditoria");

                std::ofstream out(cache / "_auditoria" / (std::string(spec.id) + ".json"), std::ios::binary | std::ios::trunc);
                out << audit.dump(2);

            } catch (...) {
            }
        }
    }).detach();
}



fs::path first_historical_asset(const fs::path& relative) {

    for (const auto& root : historical_asset_roots()) {

        const fs::path p = root / relative;
        std::error_code ec;

        if (fs::exists(p, ec) && !ec) return p;
    }

    return {};
}



PreviewTexture& persistent_historical_texture(const fs::path& path) {

    struct Entry { fs::path path; PreviewTexture tex; };
    static Entry entry;

    if (path.empty()) {

        if (entry.tex.id != 0) { glDeleteTextures(1, &entry.tex.id); entry.tex.id = 0; }

        entry.path.clear(); entry.tex = {};

        return entry.tex;
    }

    if (entry.path != path || entry.tex.id == 0) {

        if (entry.tex.id != 0) glDeleteTextures(1, &entry.tex.id);

        entry.path = path;

        entry.tex = load_texture_from_file(path);
    }

    return entry.tex;
}



