size_t ozone_station_sum_count(const OzoneStationSumsByTime& sums) {
    size_t count = 0;

    for (const auto& [_, stations] : sums) count += stations.size();

    return count;
}



bool accumulate_o3_measurement_batch_payload(std::istream& in, std::uint32_t schema, int wanted_year, bool hourly, OzoneStationSumsByTime& sums) {

    std::string source_id, source_file, source_path, domain;

    int year = 0, month = 0;
    std::uint32_t station_count = 0, pollutant_count = 0, unit_count = 0;

    if (!ixiptlah_read_string(in, source_id) ||

        !ixiptlah_read_string(in, source_file) ||

        !ixiptlah_read_string(in, source_path) ||

        !ixiptlah_read_string(in, domain) ||

        !ixiptlah_read_value(in, year) ||

        !ixiptlah_read_value(in, month) ||

        !ixiptlah_read_value(in, station_count) ||
        station_count > 200000u ||

        year < 1900 || year > 2300 ||

        month < 1 || month > 12) {



        return true;
    }

    if (wanted_year > 0 && year != wanted_year) {
        return true;
    }

    std::vector<TemporalAtmospherePackedStation> stations;

    stations.resize(station_count);

    for (auto& s : stations) {

        if (!ixiptlah_read_string(in, s.id) ||

            !ixiptlah_read_string(in, s.name) ||

            !ixiptlah_read_value(in, s.lon) ||

            !ixiptlah_read_value(in, s.lat) ||


            !ixiptlah_read_value(in, s.alt)) return true;
    }

    if (!ixiptlah_read_value(in, pollutant_count) || pollutant_count > 10000u) return true;

    std::vector<bool> is_o3(pollutant_count, false);

    for (std::uint32_t i = 0; i < pollutant_count; ++i) {
        std::string pollutant;

        if (!ixiptlah_read_string(in, pollutant)) return true;

        is_o3[static_cast<size_t>(i)] = atmospheric_parameter_key(pollutant) == "o3";
    }

    if (!ixiptlah_read_value(in, unit_count) || unit_count > 10000u) return true;

    for (std::uint32_t i = 0; i < unit_count; ++i) {
        std::string unit;

        if (!ixiptlah_read_string(in, unit)) return true;
    }
    std::uint64_t sample_count = 0;

    if (!ixiptlah_read_value(in, sample_count) || sample_count > 100000000ull) return true;

    for (std::uint64_t i = 0; i < sample_count; ++i) {

        TemporalAtmospherePackedSample sample;

        if (!read_ixiptlah_atmosphere_direct_sample(in, schema, sample)) return true;

        if (sample.pollutant_index >= is_o3.size() || !is_o3[static_cast<size_t>(sample.pollutant_index)]) continue;

        if (sample.station_index >= stations.size()) continue;

        if (!std::isfinite(sample.value) || sample.value < 0.0 || sample.value > 500.0) continue;

        const unsigned dim = timeline_navigation_days_in_month(year, static_cast<unsigned>(std::clamp(month, 1, 12)));
        if (sample.day < 1 || sample.day > dim || sample.hour > 23 || sample.minute > 59) continue;

        const auto& station = stations[static_cast<size_t>(sample.station_index)];

        if (station.id.empty()) continue;

        const int64_t key = hourly

            ? timeline_hour_from_civil(year, static_cast<unsigned>(month), static_cast<unsigned>(sample.day), static_cast<unsigned>(sample.hour))

            : days_from_civil(year, static_cast<unsigned>(month), static_cast<unsigned>(sample.day));
        auto& slot = sums[key][station.id];
        slot.sum += sample.value;
        ++slot.count;
    }

    (void)source_id; (void)source_file; (void)source_path; (void)domain;

    return true;
}



bool accumulate_o3_daily_graph_payload(std::istream& in, std::uint32_t schema, int wanted_year, OzoneStationSumsByTime& sums) {

    if (schema != 1) return true;

    std::string source_id, source_file, source_path, domain, pollutant;
    int year = 0, month = 0;
    std::uint32_t station_count = 0, unit_count = 0;

    if (!ixiptlah_read_string(in, source_id) ||
        !ixiptlah_read_string(in, source_file) ||
        !ixiptlah_read_string(in, source_path) ||
        !ixiptlah_read_string(in, domain) ||
        !ixiptlah_read_string(in, pollutant) ||
        !ixiptlah_read_value(in, year) ||
        !ixiptlah_read_value(in, month) ||
        !ixiptlah_read_value(in, station_count) || station_count > 200000u ||
        year < 1900 || year > 2300 || month < 1 || month > 12) return true;

    if (wanted_year > 0 && year != wanted_year) return true;
    if (atmospheric_parameter_key(pollutant) != "o3") return true;

    std::vector<TemporalAtmospherePackedStation> stations(station_count);
    for (auto& st : stations) {
        if (!ixiptlah_read_string(in, st.id) ||
            !ixiptlah_read_string(in, st.name) ||
            !ixiptlah_read_value(in, st.lon) ||
            !ixiptlah_read_value(in, st.lat) ||
            !ixiptlah_read_value(in, st.alt)) return true;
    }

    if (!ixiptlah_read_value(in, unit_count) || unit_count > 10000u) return true;
    for (std::uint32_t i = 0; i < unit_count; ++i) {
        std::string unit;
        if (!ixiptlah_read_string(in, unit)) return true;
    }

    std::uint64_t row_count = 0;
    if (!ixiptlah_read_value(in, row_count) || row_count > 100000000ull) return true;

    const unsigned dim = timeline_navigation_days_in_month(year, static_cast<unsigned>(std::clamp(month, 1, 12)));
    for (std::uint64_t i = 0; i < row_count; ++i) {
        std::uint8_t day = 0;
        std::uint32_t station_index = 0;
        std::uint32_t unit_index = 0;
        float mean32 = 0.0f, min32 = 0.0f, max32 = 0.0f;
        std::uint32_t count32 = 0;
        if (!ixiptlah_read_value(in, day) ||
            !ixiptlah_read_value(in, station_index) ||
            !ixiptlah_read_value(in, unit_index) ||
            !ixiptlah_read_value(in, mean32) ||
            !ixiptlah_read_value(in, min32) ||
            !ixiptlah_read_value(in, max32) ||
            !ixiptlah_read_value(in, count32)) return true;

        if (day < 1 || day > dim || station_index >= stations.size() || count32 == 0u) continue;
        if (!std::isfinite(mean32) || mean32 < 0.0f || mean32 > 500.0f) continue;
        const auto& station = stations[static_cast<std::size_t>(station_index)];
        if (station.id.empty()) continue;

        const int64_t key = days_from_civil(year, static_cast<unsigned>(month), static_cast<unsigned>(day));
        auto& slot = sums[key][station.id];
        slot.sum += static_cast<double>(mean32) * static_cast<double>(count32);
        const long long safe_add = static_cast<long long>(std::min<std::uint32_t>(count32, static_cast<std::uint32_t>(std::numeric_limits<int>::max())));
        const long long widened = static_cast<long long>(slot.count) + safe_add;
        slot.count = widened > static_cast<long long>(std::numeric_limits<int>::max()) ? std::numeric_limits<int>::max() : static_cast<int>(widened);
        (void)unit_index; (void)min32; (void)max32;
    }

    (void)source_id; (void)source_file; (void)source_path; (void)domain;
    return true;
}



bool accumulate_o3_hourly_graph_payload(std::istream& in, std::uint32_t schema, int wanted_year, OzoneStationSumsByTime& sums) {

    if (schema != 1) return true;

    std::string source_id, source_file, source_path, domain, pollutant;
    int year = 0, month = 0;
    std::uint32_t station_count = 0, unit_count = 0;

    if (!ixiptlah_read_string(in, source_id) ||
        !ixiptlah_read_string(in, source_file) ||
        !ixiptlah_read_string(in, source_path) ||
        !ixiptlah_read_string(in, domain) ||
        !ixiptlah_read_string(in, pollutant) ||
        !ixiptlah_read_value(in, year) ||
        !ixiptlah_read_value(in, month) ||
        !ixiptlah_read_value(in, station_count) || station_count > 200000u ||
        year < 1900 || year > 2300 || month < 1 || month > 12) return true;

    if (wanted_year > 0 && year != wanted_year) return true;
    if (atmospheric_parameter_key(pollutant) != "o3") return true;

    std::vector<TemporalAtmospherePackedStation> stations(station_count);
    for (auto& st : stations) {
        if (!ixiptlah_read_string(in, st.id) ||
            !ixiptlah_read_string(in, st.name) ||
            !ixiptlah_read_value(in, st.lon) ||
            !ixiptlah_read_value(in, st.lat) ||
            !ixiptlah_read_value(in, st.alt)) return true;
    }

    if (!ixiptlah_read_value(in, unit_count) || unit_count > 10000u) return true;
    for (std::uint32_t i = 0; i < unit_count; ++i) {
        std::string unit;
        if (!ixiptlah_read_string(in, unit)) return true;
    }

    std::uint64_t row_count = 0;
    if (!ixiptlah_read_value(in, row_count) || row_count > 200000000ull) return true;
    const unsigned dim = timeline_navigation_days_in_month(year, static_cast<unsigned>(std::clamp(month, 1, 12)));

    for (std::uint64_t i = 0; i < row_count; ++i) {
        std::uint8_t day = 0;
        std::uint16_t minute_of_day = 0;
        std::uint32_t station_index = 0, unit_index = 0;
        float value32 = 0.0f;
        if (!ixiptlah_read_value(in, day) ||
            !ixiptlah_read_value(in, minute_of_day) ||
            !ixiptlah_read_value(in, station_index) ||
            !ixiptlah_read_value(in, unit_index) ||
            !ixiptlah_read_value(in, value32)) return true;
        if (day < 1 || day > dim || minute_of_day >= 1440u || station_index >= stations.size()) continue;
        if (!std::isfinite(value32) || value32 < 0.0f || value32 > 500.0f) continue;
        const auto& station = stations[static_cast<std::size_t>(station_index)];
        if (station.id.empty()) continue;
        const int hour_of_day = static_cast<int>(minute_of_day / 60u);
        const int64_t key = timeline_hour_from_civil(year, static_cast<unsigned>(month), static_cast<unsigned>(day), static_cast<unsigned>(hour_of_day));
        auto& slot = sums[key][station.id];
        slot.sum += static_cast<double>(value32);
        ++slot.count;
        (void)unit_index;
    }

    (void)source_id; (void)source_file; (void)source_path; (void)domain;
    return true;
}

bool accumulate_o3_from_ixiptlah_year(int year, bool hourly, OzoneStationSumsByTime& sums) {
    const size_t before = ozone_station_sum_count(sums);

    for (const auto& block : rama_ixiptlah_month_files_for_year(year)) {

        const std::uint64_t o3_layer_hash = ixiptlah_layer_hash("o3");
        const std::uint64_t year_begin_key = static_cast<std::uint64_t>(std::clamp(year, 0, 9999)) * 100000000ull;
        const std::uint64_t year_end_key = static_cast<std::uint64_t>(std::clamp(year + 1, 0, 9999)) * 100000000ull;
        bool preformed_seen = false;

        if (hourly) {
            const std::vector<std::uint64_t> o3_layers{o3_layer_hash};
            ixiptlah_read_selected_records_tagged_temporal_exact(block,

                IxiptlahRecordType::AtmosphereGraphHourlyStationBatch, 1, o3_layers, true, year_begin_key, year_end_key,

                [&](IxiptlahRecordType, std::uint32_t schema, std::istream& in) {

                    preformed_seen = true;
                    return accumulate_o3_hourly_graph_payload(in, schema, year, sums);
                });

            if (preformed_seen) continue;
        } else {
            const std::vector<std::uint64_t> o3_layers{o3_layer_hash};
            ixiptlah_read_selected_records_tagged_temporal_exact(block,

                IxiptlahRecordType::AtmosphereGraphDailyStationBatch, 1, o3_layers, true, year_begin_key, year_end_key,

                [&](IxiptlahRecordType, std::uint32_t schema, std::istream& in) {

                    preformed_seen = true;
                    return accumulate_o3_daily_graph_payload(in, schema, year, sums);
                });

            if (preformed_seen) continue;
        }

        const std::vector<std::uint64_t> o3_layers{o3_layer_hash};
        ixiptlah_read_selected_records_tagged_temporal_exact(block,

            IxiptlahRecordType::MonthlyAtmosphereMeasurementBatch, 1, o3_layers, true, year_begin_key, year_end_key,

            [&](IxiptlahRecordType, std::uint32_t schema, std::istream& in) {

                return accumulate_o3_measurement_batch_payload(in, schema, year, hourly, sums);
            });
    }

    return ozone_station_sum_count(sums) > before;
}



std::string file_signature_fragment(const fs::path& p) {
    std::error_code ec;

    const auto size = fs::file_size(p, ec);
    const uintmax_t safe_size = ec ? 0 : size;

    ec.clear();

    const auto mtime = fs::last_write_time(p, ec);

    const auto tick = ec ? 0LL : static_cast<long long>(mtime.time_since_epoch().count());

    return path_utf8(p) + "|" + std::to_string(safe_size) + "|" + std::to_string(tick);
}




struct OzoneYearSourceSignatureStore {

    std::mutex mu;

    std::map<int, std::string> signatures;
};



OzoneYearSourceSignatureStore& ozone_year_source_signature_store() {

    static OzoneYearSourceSignatureStore store;

    return store;
}



std::string rama_o3_year_source_signature(int year) {

    auto& store = ozone_year_source_signature_store();
    {

        std::lock_guard<std::mutex> lock(store.mu);

        const auto it = store.signatures.find(year);

        if (it != store.signatures.end()) return it->second;
    }

    const auto files = rama_files_for_year(year);

    const auto ixiptlah_files = rama_ixiptlah_month_files_for_year(year);

    std::ostringstream os;

    os << "rama_o3_year_source_v3|" << year << "|ixiptlah|" << ixiptlah_files.size() << "|csv|" << files.size();

    for (const auto& file : ixiptlah_files) os << "\nIX|" << file_signature_fragment(file);

    for (const auto& file : files) os << "\n" << file_signature_fragment(file);
    const std::string signature = simple_hash_hex(os.str());
    {

        std::lock_guard<std::mutex> lock(store.mu);

        store.signatures[year] = signature;
    }

    return signature;
}



bool ozone_daily_station_meta_matches(int year, const std::string& expected_signature) {

    std::ifstream in(ozone_daily_station_cache_meta_path(year), std::ios::binary);

    if (!in) return false;
    std::string line;

    while (std::getline(in, line)) {
        const auto pos = line.find('=');

        if (pos == std::string::npos) continue;
        const std::string key = trim(line.substr(0, pos));
        const std::string value = trim(line.substr(pos + 1));

        if (key == "source_signature") return value == expected_signature;
    }

    return false;
}



void write_ozone_daily_station_meta(int year, const std::string& source_signature) {

    const fs::path p = ozone_daily_station_cache_meta_path(year);

    ensure_dir(p.parent_path());

    const fs::path tmp = fs::path(p.wstring() + L".tmp");

    std::ofstream out(tmp, std::ios::binary | std::ios::trunc);

    if (!out) return;

    out << "cache_schema=ixiptlah_binary_o3_daily_station_v1\n";

    out << "source=RAMA Ixiptlah/CSV horario\n";
    out << "source_signature=" << source_signature << "\n";

    out << "year=" << year << "\n";

    out << "generated_utc=" << now_utc_iso() << "\n";
    out.close();

    if (out) atomic_promote_file(tmp, p);
}



bool load_o3_daily_station_year_from_cache(int year, const std::string& expected_signature, OzoneDailyStationYear& out) {

    if (!ozone_daily_station_meta_matches(year, expected_signature)) return false;

    const fs::path p = ozone_daily_station_cache_path(year);

    std::ifstream in(p, std::ios::binary);

    if (!in) return false;
    char magic[8] = {};

    in.read(magic, sizeof(magic));

    if (!in || std::memcmp(magic, kIxiptlahBinaryDailyStationMagic, sizeof(kIxiptlahBinaryDailyStationMagic)) != 0) return false;
    std::uint32_t version = 0;

    std::uint64_t row_count = 0;


    if (!ozone_read_binary_value(in, version) || !ozone_read_binary_value(in, row_count)) return false;

    if (version != 1 || row_count > 200000000ull) return false;

    out.year = year;

    out.source_signature = expected_signature;

    for (std::uint64_t i = 0; i < row_count; ++i) {
        int64_t day = 0;
        std::string station;
        double mean = std::numeric_limits<double>::quiet_NaN();
        std::int32_t count = 0;

        if (!ozone_read_binary_value(in, day) ||

            !ozone_read_binary_string(in, station) ||

            !ozone_read_binary_value(in, mean) ||

            !ozone_read_binary_value(in, count)) return false;

        if (!station.empty() && std::isfinite(mean)) out.mean_by_day_station[day][station] = {mean, std::max(1, static_cast<int>(count))};
    }

    return !out.mean_by_day_station.empty();
}



std::string ozone_daily_station_memory_key(int year, const std::string& source_signature) {

    return std::to_string(year) + "|" + source_signature;
}



struct OzoneDailyStationRuntimeStore {

    std::mutex mu;

    std::map<std::string, std::shared_ptr<const OzoneDailyStationYear>> cache;

    std::set<std::string> building_keys;
};



OzoneDailyStationRuntimeStore& ozone_daily_station_runtime_store() {

    static OzoneDailyStationRuntimeStore store;

    return store;
}



std::shared_ptr<const OzoneDailyStationYear> cached_o3_daily_station_year_memory(int year, const std::string& source_signature) {

    auto& store = ozone_daily_station_runtime_store();

    std::lock_guard<std::mutex> lock(store.mu);

    const auto it = store.cache.find(ozone_daily_station_memory_key(year, source_signature));

    return it == store.cache.end() ? nullptr : it->second;
}



std::shared_ptr<const OzoneDailyStationYear> load_o3_daily_station_year(int year) {

    const std::string source_signature = rama_o3_year_source_signature(year);

    const std::string memory_key = ozone_daily_station_memory_key(year, source_signature);

    if (auto ready = cached_o3_daily_station_year_memory(year, source_signature)) return ready;


    auto built = std::make_shared<OzoneDailyStationYear>();

    if (!load_o3_daily_station_year_from_cache(year, source_signature, *built)) {

        OzoneStationSumsByTime sums;

        if (!accumulate_o3_from_ixiptlah_year(year, false, sums)) {

            for (const auto& file : rama_files_for_year(year)) {

                std::ifstream in(file, std::ios::binary);

                if (!in) continue;
                std::string line;
                bool header_seen = false;
                char delim = ',';

                int date_i = -1, station_i = -1, param_i = -1, value_i = -1;

                while (std::getline(in, line)) {

                    if (trim(line).empty()) continue;

                    if (!header_seen) {

                        const std::string n = normalize_key(line);

                        const bool has_date = contains_norm(n, "date") || contains_norm(n, "fecha");
                        const bool has_station = contains_norm(n, "id station") || contains_norm(n, "cve station") || contains_norm(n, "cve estac") || contains_norm(n, "estacion");

                        const bool has_parameter = contains_norm(n, "id parameter") || contains_norm(n, "cve parameter") || contains_norm(n, "parametro") || contains_norm(n, "cve param");

                        if (has_date && has_station && has_parameter) {
                            delim = infer_rama_delimiter(line);
                            const auto h = split_rama_line(line, delim);

                            for (int i = 0; i < static_cast<int>(h.size()); ++i) {


                                const std::string k = normalize_key(h[static_cast<size_t>(i)]);

                                if (k == "date" || k == "fecha") date_i = i;

                                else if (k == "id station" || k == "cve station" || k == "cve estac" || k == "estacion") station_i = i;

                                else if (k == "id parameter" || k == "cve parameter" || k == "parametro" || k == "cve param") param_i = i;

                                else if (k == "valor" || k == "value") value_i = i;
                            }

                            header_seen = date_i >= 0 && station_i >= 0 && param_i >= 0 && value_i >= 0;
                        }
                        continue;
                    }

                    const auto cols = split_rama_line(line, delim);

                    const int need = std::max(std::max(date_i, station_i), std::max(param_i, value_i));

                    if (static_cast<int>(cols.size()) <= need) continue;

                    if (canonical_rama_parameter_id(cols[static_cast<size_t>(param_i)]) != "o3") continue;
                    const std::string raw_value = trim(cols[static_cast<size_t>(value_i)]);

                    if (raw_value.empty() || raw_value == "NA" || raw_value == "NaN") continue;
                    char* end = nullptr;
                    const double value = std::strtod(raw_value.c_str(), &end);

                    if (end == raw_value.c_str() || !std::isfinite(value) || value < 0.0 || value > 500.0) continue;

                    const auto hour = parse_rama_datetime_hour(cols[static_cast<size_t>(date_i)]);

                    if (!hour) continue;

                    const int64_t day = timeline_epoch_days() + floor_div_i64(*hour, 24);
                    const std::string station = trim(cols[static_cast<size_t>(station_i)]);

                    if (station.empty()) continue;
                    auto& slot = sums[day][station];
                    slot.sum += value;
                    ++slot.count;
                }
            }
        }

        built->year = year;
        built->source_signature = source_signature;

        for (const auto& [day, stations] : sums) {

            for (const auto& [station, slot] : stations) {

                if (slot.count <= 0) continue;
                built->mean_by_day_station[day][station] = {slot.sum / static_cast<double>(slot.count), slot.count};
            }
        }

        if (!built->mean_by_day_station.empty()) {

            const fs::path p = ozone_daily_station_cache_path(year);

            ensure_dir(p.parent_path());

            const fs::path tmp = fs::path(p.wstring() + L".tmp");

            std::ofstream out(tmp, std::ios::binary | std::ios::trunc);

            if (out) {

                const std::uint32_t version = 1;

                std::uint64_t row_count = 0;

                for (const auto& [_, stations] : built->mean_by_day_station) row_count += stations.size();

                out.write(kIxiptlahBinaryDailyStationMagic, sizeof(kIxiptlahBinaryDailyStationMagic));

                ozone_write_binary_value(out, version);

                ozone_write_binary_value(out, row_count);

                for (const auto& [day, stations] : built->mean_by_day_station) {

                    for (const auto& [station, mc] : stations) {
                        const std::int32_t count = static_cast<std::int32_t>(mc.second);

                        ozone_write_binary_value(out, day);

                        ozone_write_binary_string(out, station);

                        ozone_write_binary_value(out, mc.first);

                        ozone_write_binary_value(out, count);
                    }
                }
                out.close();

                if (out) {

                    atomic_promote_file(tmp, p);

                    write_ozone_daily_station_meta(year, source_signature);
                }
            }
        }
    }
    {

        auto& store = ozone_daily_station_runtime_store();

        std::lock_guard<std::mutex> lock(store.mu);

        store.cache[memory_key] = built;

        store.building_keys.erase(memory_key);
    }

    return built;
}



std::shared_ptr<const OzoneDailyStationYear> load_o3_daily_station_year_nonblocking(int year) {

    const std::string source_signature = rama_o3_year_source_signature(year);

    if (auto ready = cached_o3_daily_station_year_memory(year, source_signature)) return ready;

    const std::string build_key = ozone_daily_station_memory_key(year, source_signature);
    bool should_start = false;
    {

        auto& store = ozone_daily_station_runtime_store();

        std::lock_guard<std::mutex> lock(store.mu);

        should_start = store.building_keys.insert(build_key).second;
    }

    if (should_start) {

        std::thread([year]() {

            (void)load_o3_daily_station_year(year);
        }).detach();
    }

    return nullptr;
}



struct OzoneHourlyStationYear {

    int year = 0;
    std::string source_signature;

    std::map<int64_t, std::map<std::string, double>> mean_by_hour_station;
};



bool ozone_hourly_station_meta_matches(int year, const std::string& expected_signature) {

    std::ifstream in(ozone_hourly_station_cache_meta_path(year), std::ios::binary);

    if (!in) return false;
    std::string line;

    while (std::getline(in, line)) {
        const auto pos = line.find('=');

        if (pos == std::string::npos) continue;
        const std::string key = trim(line.substr(0, pos));
        const std::string value = trim(line.substr(pos + 1));

        if (key == "source_signature") return value == expected_signature;
    }

    return false;
}



void write_ozone_hourly_station_meta(int year, const std::string& source_signature) {

    const fs::path p = ozone_hourly_station_cache_meta_path(year);

    ensure_dir(p.parent_path());

    const fs::path tmp = fs::path(p.wstring() + L".tmp");

    std::ofstream out(tmp, std::ios::binary | std::ios::trunc);

    if (!out) return;

    out << "cache_schema=ixiptlah_binary_o3_hourly_station_v1\n";

    out << "source=RAMA Ixiptlah/CSV horario\n";
    out << "source_signature=" << source_signature << "\n";

    out << "year=" << year << "\n";
    out << "generated_utc=" << now_utc_iso() << "\n";
    out.close();

    if (out) atomic_promote_file(tmp, p);
}



bool load_o3_hourly_station_year_from_cache(int year, const std::string& expected_signature, OzoneHourlyStationYear& out) {

    if (!ozone_hourly_station_meta_matches(year, expected_signature)) return false;

    const fs::path p = ozone_hourly_station_cache_path(year);

    std::ifstream in(p, std::ios::binary);

    if (!in) return false;

    char magic[8] = {};

    in.read(magic, sizeof(magic));

    if (!in || std::memcmp(magic, kIxiptlahBinaryHourlyStationMagic, sizeof(kIxiptlahBinaryHourlyStationMagic)) != 0) return false;
    std::uint32_t version = 0;

    std::uint64_t row_count = 0;

    if (!ozone_read_binary_value(in, version) || !ozone_read_binary_value(in, row_count)) return false;


    if (version != 1 || row_count > 500000000ull) return false;

    out.year = year;
    out.source_signature = expected_signature;

    for (std::uint64_t i = 0; i < row_count; ++i) {

        int64_t hour = 0;
        std::string station;
        double mean = std::numeric_limits<double>::quiet_NaN();

        if (!ozone_read_binary_value(in, hour) ||

            !ozone_read_binary_string(in, station) ||

            !ozone_read_binary_value(in, mean)) return false;

        if (!station.empty() && std::isfinite(mean)) out.mean_by_hour_station[hour][station] = mean;
    }

    return !out.mean_by_hour_station.empty();
}



std::string ozone_hourly_station_memory_key(int year, const std::string& source_signature) {

    return "hourly|" + std::to_string(year) + "|" + source_signature;
}



