Point2 feature_centroid_lonlat(const MapFeature& f) {
    double sx = 0.0, sy = 0.0;
    int64_t n = 0;

    for (const auto& ring : f.rings) {

        for (const auto& p : ring) {
            sx += p.x;
            sy += p.y;
            ++n;
        }
    }

    if (n <= 0) return {kValleyCenterLon, kValleyCenterLat};

    return {sx / static_cast<double>(n), sy / static_cast<double>(n)};
}



bool point_in_feature_lonlat(const Point2& p, const MapFeature& f) {

    for (const auto& ring : f.rings) {

        if (point_in_geo_ring(p, ring)) return true;
    }

    return false;
}



std::string station_geometry_signature(const std::map<std::string, MapStation>& stations) {
    std::ostringstream os;

    os << "station_geometry_v1|" << stations.size();

    for (const auto& [id, station] : stations) {

        os << '\n' << id << '|' << std::fixed << std::setprecision(6) << station.lon << '|' << station.lat << '|' << station.meteorological;
    }

    return simple_hash_hex(os.str());
}



std::string feature_geometry_signature(const MapFeature& feature) {
    std::ostringstream os;

    os << "feature_geometry_v1|" << feature.id << '|' << feature.rings.size();

    for (const auto& ring : feature.rings) {
        os << "|r" << ring.size();

        for (const auto& p : ring) os << '|' << std::fixed << std::setprecision(6) << p.x << ',' << p.y;
    }

    return simple_hash_hex(os.str());
}



std::vector<Point2> feature_area_samples_lonlat(const MapFeature& feature) {

    std::vector<Point2> samples;
    double minx = std::numeric_limits<double>::infinity();
    double maxx = -std::numeric_limits<double>::infinity();
    double miny = std::numeric_limits<double>::infinity();
    double maxy = -std::numeric_limits<double>::infinity();

    for (const auto& ring : feature.rings) {

        for (const auto& p : ring) {
            minx = std::min(minx, p.x); maxx = std::max(maxx, p.x);
            miny = std::min(miny, p.y); maxy = std::max(maxy, p.y);
        }
    }

    const Point2 centroid = feature_centroid_lonlat(feature);

    samples.push_back(centroid);

    if (!std::isfinite(minx) || !std::isfinite(maxx) || !std::isfinite(miny) || !std::isfinite(maxy) || maxx <= minx || maxy <= miny) return samples;

    constexpr int grid = 8;

    for (int iy = 0; iy < grid; ++iy) {
        const double fy = (static_cast<double>(iy) + 0.5) / static_cast<double>(grid);

        for (int ix = 0; ix < grid; ++ix) {
            const double fx = (static_cast<double>(ix) + 0.5) / static_cast<double>(grid);

            const Point2 p{minx + (maxx - minx) * fx, miny + (maxy - miny) * fy};

            if (point_in_feature_lonlat(p, feature)) samples.push_back(p);
        }
    }

    if (samples.size() == 1 && point_in_feature_lonlat(centroid, feature)) return samples;

    if (samples.size() == 1) {

        for (const auto& ring : feature.rings) {

            for (const auto& p : ring) {

                if (point_in_feature_lonlat(p, feature)) samples.push_back(p);

                if (samples.size() >= 6) break;
            }

            if (samples.size() >= 6) break;
        }
    }

    return samples;
}


std::vector<std::pair<std::string, double>> triangular_station_weights_for_point(const Point2& p,


                                                                                  const std::map<std::string, MapStation>& stations) {

    std::vector<std::tuple<double, std::string, double, double>> ranked;

    ranked.reserve(stations.size());

    for (const auto& [id, station] : stations) {

        if (!std::isfinite(station.lon) || !std::isfinite(station.lat)) continue;

        const double d = std::max(1.0, distance_meters(p.x, p.y, station.lon, station.lat));

        ranked.push_back({d, id, station.lon, station.lat});
    }
    std::sort(ranked.begin(), ranked.end(), [](const auto& a, const auto& b) { return std::get<0>(a) < std::get<0>(b); });

    if (ranked.empty()) return {};

    if (ranked.size() == 1 || std::get<0>(ranked.front()) < 40.0) return {{std::get<1>(ranked.front()), 1.0}};
    const int limit = std::min<int>(static_cast<int>(ranked.size()), 9);

    for (int i = 0; i < limit; ++i) {

        for (int j = i + 1; j < limit; ++j) {

            for (int k = j + 1; k < limit; ++k) {
                const double x1 = std::get<2>(ranked[static_cast<size_t>(i)]), y1 = std::get<3>(ranked[static_cast<size_t>(i)]);
                const double x2 = std::get<2>(ranked[static_cast<size_t>(j)]), y2 = std::get<3>(ranked[static_cast<size_t>(j)]);
                const double x3 = std::get<2>(ranked[static_cast<size_t>(k)]), y3 = std::get<3>(ranked[static_cast<size_t>(k)]);
                const double det = (y2 - y3) * (x1 - x3) + (x3 - x2) * (y1 - y3);

                if (std::fabs(det) < 1.0e-12) continue;
                const double l1 = ((y2 - y3) * (p.x - x3) + (x3 - x2) * (p.y - y3)) / det;
                const double l2 = ((y3 - y1) * (p.x - x3) + (x1 - x3) * (p.y - y3)) / det;
                const double l3 = 1.0 - l1 - l2;

                if (l1 >= -0.025 && l2 >= -0.025 && l3 >= -0.025) {
                    const double c1 = std::max(0.0, l1), c2 = std::max(0.0, l2), c3 = std::max(0.0, l3);
                    const double total = std::max(1.0e-12, c1 + c2 + c3);

                    return {{std::get<1>(ranked[static_cast<size_t>(i)]), c1 / total},
                            {std::get<1>(ranked[static_cast<size_t>(j)]), c2 / total},
                            {std::get<1>(ranked[static_cast<size_t>(k)]), c3 / total}};
                }
            }
        }
    }
    const int take = std::min<int>(3, static_cast<int>(ranked.size()));
    double total = 0.0;

    std::vector<std::pair<std::string, double>> weights;

    weights.reserve(static_cast<size_t>(take));

    for (int i = 0; i < take; ++i) {
        const double d = std::max(1.0, std::get<0>(ranked[static_cast<size_t>(i)]));
        const double w = 1.0 / (d * d);
        total += w;

        weights.push_back({std::get<1>(ranked[static_cast<size_t>(i)]), w});
    }

    if (total <= 0.0) return {};

    for (auto& w : weights) w.second /= total;

    return weights;
}


std::vector<std::pair<std::string, double>> ozone_station_weights_for_feature(const MapFeature& feature,


                                                                              const std::map<std::string, MapStation>& stations) {

    if (feature.id.empty() || stations.empty()) return {};

    const std::string cache_key = feature.id + "|" + feature_geometry_signature(feature) + "|" + station_geometry_signature(stations);


    static std::mutex weights_mu;

    static std::map<std::string, std::vector<std::pair<std::string, double>>> weights_cache;
    {

        std::lock_guard<std::mutex> lock(weights_mu);
        const auto it = weights_cache.find(cache_key);

        if (it != weights_cache.end()) return it->second;
    }

    std::map<std::string, double> accum;

    const auto samples = feature_area_samples_lonlat(feature);

    for (const auto& sample : samples) {
        const auto local_weights = triangular_station_weights_for_point(sample, stations);

        for (const auto& [station, w] : local_weights) accum[station] += w;
    }

    std::vector<std::pair<std::string, double>> weights;
    double total = 0.0;

    for (const auto& [station, w] : accum) total += std::max(0.0, w);

    if (total > 0.0) {

        weights.reserve(accum.size());

        for (const auto& [station, w] : accum) {

            if (w > 0.0) weights.push_back({station, w / total});
        }
    }
    {

        std::lock_guard<std::mutex> lock(weights_mu);
        weights_cache[cache_key] = weights;
    }

    return weights;
}



std::string ozone_area_spatial_signature(const MapFeature& feature, const std::map<std::string, MapStation>& stations) {

    return simple_hash_hex(std::string(kOzoneAreaMethodId) + "|" + feature_geometry_signature(feature) + "|" + station_geometry_signature(stations));
}



struct OzoneAreaSpatialSet {

    std::vector<Point2> samples;

    std::vector<std::pair<std::string, double>> station_weights;

    std::shared_ptr<const std::map<std::string, MapStation>> stations;
    std::string spatial_signature;
};



struct OzoneAreaDailyCell {
    double mean = std::numeric_limits<double>::quiet_NaN();

    int64_t hours = 0;
    int station_days = 0;

    bool pending_async = false;
};



struct OzoneAreaDailyCacheStore {

    std::mutex mu;

    std::set<std::string> loaded_decades;

    std::map<std::string, OzoneAreaDailyCell> rows;

    std::set<std::string> validated_keys;

    std::set<std::string> negative_keys;
};


std::atomic<std::uint64_t> g_ozone_area_cache_revision{0};



OzoneAreaDailyCacheStore& ozone_area_daily_cache_store() {

    static OzoneAreaDailyCacheStore store;

    return store;
}



std::string ozone_area_daily_cache_key(int64_t day, const std::string& jurisdiction_id, const std::string& cache_signature) {

    return std::string(kOzoneAreaFactorId) + "|" + kOzoneAreaMethodId + "|" + std::to_string(day) + "|" + jurisdiction_id + "|" + cache_signature;
}



void load_ozone_area_daily_cache_locked(OzoneAreaDailyCacheStore& store, int64_t day) {
    int y = 0;
    unsigned m = 1, d = 1;

    civil_from_days(day, y, m, d);

    const std::string decade = decade_label_for_year(y);

    if (!store.loaded_decades.insert(decade).second) return;

    std::ifstream in(ozone_area_daily_cache_path_for_day(day), std::ios::binary);

    if (!in) return;
    char magic[8] = {};

    in.read(magic, sizeof(magic));

    if (!in || std::memcmp(magic, kIxiptlahBinaryAreaDailyMagic, sizeof(kIxiptlahBinaryAreaDailyMagic)) != 0) return;

    std::uint32_t version = 0;

    if (!ozone_read_binary_value(in, version) || version != 1) return;

    while (in.peek() != EOF) {

        int64_t row_day = 0;
        std::string geo;
        double mean = std::numeric_limits<double>::quiet_NaN();

        int64_t hours = 0;
        std::int32_t station_days = 0;
        std::string sig;

        if (!ozone_read_binary_value(in, row_day) ||

            !ozone_read_binary_string(in, geo) ||

            !ozone_read_binary_value(in, mean) ||

            !ozone_read_binary_value(in, hours) ||

            !ozone_read_binary_value(in, station_days) ||

            !ozone_read_binary_string(in, sig)) break;

        if (geo.empty() || !std::isfinite(mean)) continue;

        store.rows[ozone_area_daily_cache_key(row_day, geo, sig)] = {mean, hours, static_cast<int>(station_days)};
    }
}


std::optional<OzoneAreaDailyCell> cached_ozone_area_daily_cell(int64_t day,
                                                               const std::string& jurisdiction_id,

                                                               const std::string& cache_signature) {
    auto& store = ozone_area_daily_cache_store();

    std::lock_guard<std::mutex> lock(store.mu);
    load_ozone_area_daily_cache_locked(store, day);

    const auto it = store.rows.find(ozone_area_daily_cache_key(day, jurisdiction_id, cache_signature));

    if (it == store.rows.end()) return std::nullopt;

    return it->second;
}



bool ozone_area_daily_key_is_negative(const std::string& key, int64_t day) {
    auto& store = ozone_area_daily_cache_store();

    std::lock_guard<std::mutex> lock(store.mu);
    load_ozone_area_daily_cache_locked(store, day);

    return store.negative_keys.count(key) > 0;
}



void mark_ozone_area_daily_negative(const std::string& key) {
    auto& store = ozone_area_daily_cache_store();
    bool inserted = false;
    {

        std::lock_guard<std::mutex> lock(store.mu);

        inserted = store.negative_keys.insert(key).second;
    }

    if (inserted) g_ozone_area_cache_revision.fetch_add(1, std::memory_order_relaxed);
}

void append_ozone_area_daily_cell(int64_t day,

                                  const std::string& jurisdiction_id,
                                  const std::string& cache_signature,


                                  const OzoneAreaDailyCell& cell) {

    if (!std::isfinite(cell.mean) || jurisdiction_id.empty()) return;
    auto& store = ozone_area_daily_cache_store();
    {

        std::lock_guard<std::mutex> lock(store.mu);
        load_ozone_area_daily_cache_locked(store, day);

        store.rows[ozone_area_daily_cache_key(day, jurisdiction_id, cache_signature)] = cell;
    }

    const fs::path p = ozone_area_daily_cache_path_for_day(day);

    ensure_dir(p.parent_path());
    std::error_code ec;

    const bool need_header = !fs::exists(p, ec) || ec || file_size_or_zero(p) == 0;

    std::ofstream out(p, std::ios::binary | std::ios::app);

    if (!out) return;

    if (need_header) {

        const std::uint32_t version = 1;

        out.write(kIxiptlahBinaryAreaDailyMagic, sizeof(kIxiptlahBinaryAreaDailyMagic));


        ozone_write_binary_value(out, version);
    }
    const std::int32_t station_days = static_cast<std::int32_t>(cell.station_days);

    ozone_write_binary_value(out, day);

    ozone_write_binary_string(out, jurisdiction_id);

    ozone_write_binary_value(out, cell.mean);

    ozone_write_binary_value(out, cell.hours);

    ozone_write_binary_value(out, station_days);

    ozone_write_binary_string(out, cache_signature);
    g_ozone_area_cache_revision.fetch_add(1, std::memory_order_relaxed);
}


OzoneAreaDailyCell compute_ozone_area_daily_cell_from_station_cache(const std::vector<Point2>& area_samples,

                                                                    const std::vector<std::pair<std::string, double>>& station_weights,

                                                                    const std::map<std::string, MapStation>& stations,
                                                                    int64_t day,

                                                                    bool allow_blocking = false) {

    OzoneAreaDailyCell cell;

    if ((area_samples.empty() && station_weights.empty()) || stations.empty()) return cell;
    int y = 0;
    unsigned m = 1, d = 1;

    civil_from_days(day, y, m, d);

    auto hourly = allow_blocking ? load_o3_hourly_station_year(y) : load_o3_hourly_station_year_nonblocking(y);

    if (!hourly) {

        cell.pending_async = true;

        return cell;
    }
    double day_sum = 0.0;

    int station_hour_inputs = 0;

    const int64_t first_hour = (day - timeline_epoch_days()) * 24;

    for (int offset = 0; offset < 24; ++offset) {

        const int64_t hour = first_hour + offset;

        const auto hit = hourly->mean_by_hour_station.find(hour);

        if (hit == hourly->mean_by_hour_station.end()) continue;

        if (!station_weights.empty()) {
            double weighted_sum = 0.0;
            double weight_sum = 0.0;
            int station_inputs = 0;

            for (const auto& [station_id, weight] : station_weights) {

                if (weight <= 0.0) continue;
                const auto vit = hit->second.find(station_id);

                if (vit == hit->second.end() || !std::isfinite(vit->second)) continue;
                weighted_sum += vit->second * weight;
                weight_sum += weight;
                ++station_inputs;
            }

            if (weight_sum <= 0.0 || station_inputs <= 0) continue;
            day_sum += weighted_sum / weight_sum;

            ++cell.hours;

            station_hour_inputs += station_inputs;

            continue;
        }

        std::map<std::string, MapStation> available_stations;

        for (const auto& [station_id, value] : hit->second) {

            if (!std::isfinite(value)) continue;
            const auto sit = stations.find(station_id);

            if (sit == stations.end()) continue;
            available_stations[station_id] = sit->second;
        }

        if (available_stations.empty()) continue;

        double hour_area_sum = 0.0;
        int sample_count = 0;

        int sample_station_inputs = 0;

        for (const auto& sample : area_samples) {
            const auto weights = triangular_station_weights_for_point(sample, available_stations);

            if (weights.empty()) continue;
            double sample_sum = 0.0;

            double sample_w = 0.0;

            for (const auto& [station_id, w] : weights) {
                const auto vit = hit->second.find(station_id);

                if (vit == hit->second.end() || !std::isfinite(vit->second) || w <= 0.0) continue;
                sample_sum += vit->second * w;
                sample_w += w;
            }

            if (sample_w <= 0.0) continue;

            hour_area_sum += sample_sum / sample_w;
            ++sample_count;
            sample_station_inputs += static_cast<int>(weights.size());
        }

        if (sample_count <= 0) continue;

        day_sum += hour_area_sum / static_cast<double>(sample_count);

        ++cell.hours;

        station_hour_inputs += sample_station_inputs;
    }

    if (cell.hours <= 0) return cell;

    cell.mean = day_sum / static_cast<double>(cell.hours);

    cell.station_days = station_hour_inputs;

    return cell;
}



struct OzoneAreaDailyJob {
    std::string key;
    int64_t day = 0;
    std::string jurisdiction_id;
    std::string cache_signature;

    std::vector<Point2> area_samples;

    std::vector<std::pair<std::string, double>> station_weights;

    std::shared_ptr<const std::map<std::string, MapStation>> stations;

    bool validate = false;

    OzoneAreaDailyCell cached;
};



struct OzoneAreaDailyJobQueue {

    std::mutex mu;

    std::condition_variable cv;
    int workers_started = 0;

    std::deque<OzoneAreaDailyJob> jobs;

    std::set<std::string> queued_keys;
};



OzoneAreaDailyJobQueue& ozone_area_daily_job_queue() {

    static OzoneAreaDailyJobQueue queue;

    return queue;
}



size_t ozone_area_daily_queue_pending_count() {
    auto& queue = ozone_area_daily_job_queue();

    std::lock_guard<std::mutex> lock(queue.mu);

    return queue.jobs.size();
}



void ozone_area_daily_worker_loop() {
    auto& queue = ozone_area_daily_job_queue();

    for (;;) {

        OzoneAreaDailyJob job;
        {

            std::unique_lock<std::mutex> lock(queue.mu);
            queue.cv.wait(lock, [&]() { return !queue.jobs.empty(); });
            job = std::move(queue.jobs.front());
            queue.jobs.pop_front();
        }

        const OzoneAreaDailyCell fresh = job.stations ? compute_ozone_area_daily_cell_from_station_cache(job.area_samples, job.station_weights, *job.stations, job.day, true) : OzoneAreaDailyCell{};


        if (std::isfinite(fresh.mean) && fresh.station_days > 0) {

            const bool changed = !job.validate || !std::isfinite(job.cached.mean) ||

                std::fabs(fresh.mean - job.cached.mean) > 0.0005 || fresh.hours != job.cached.hours || fresh.station_days != job.cached.station_days;

            if (changed) append_ozone_area_daily_cell(job.day, job.jurisdiction_id, job.cache_signature, fresh);

        } else if (!fresh.pending_async) {
            mark_ozone_area_daily_negative(job.key);
        }
        {

            std::lock_guard<std::mutex> lock(queue.mu);

            queue.queued_keys.erase(job.key);
        }
    }
}

void queue_ozone_area_daily_job(int64_t day,
                                const std::string& jurisdiction_id,
                                const std::string& cache_signature,

                                const std::vector<Point2>& area_samples,

                                const std::vector<std::pair<std::string, double>>& station_weights,

                                std::shared_ptr<const std::map<std::string, MapStation>> stations,

                                bool validate,


                                const OzoneAreaDailyCell* cached) {

    if (jurisdiction_id.empty() || cache_signature.empty() || (area_samples.empty() && station_weights.empty()) || !stations || stations->empty()) return;
    const std::string key = ozone_area_daily_cache_key(day, jurisdiction_id, cache_signature);

    if (ozone_area_daily_key_is_negative(key, day)) return;
    auto& queue = ozone_area_daily_job_queue();

    constexpr size_t kMaxPendingOzoneAreaJobs = 768;
    {

        std::lock_guard<std::mutex> lock(queue.mu);

        const int target_workers = std::max(2, std::min(3, static_cast<int>(std::max(1u, std::thread::hardware_concurrency()) / 2u)));

        while (queue.workers_started < target_workers) {
            ++queue.workers_started;

            std::thread(ozone_area_daily_worker_loop).detach();
        }

        if (queue.jobs.size() >= kMaxPendingOzoneAreaJobs) return;

        if (!queue.queued_keys.insert(key).second) return;
    }


    OzoneAreaDailyJob job;
    job.key = key;
    job.day = day;
    job.jurisdiction_id = jurisdiction_id;
    job.cache_signature = cache_signature;
    job.area_samples = area_samples;

    job.station_weights = station_weights;
    job.stations = stations;

    job.validate = validate;

    if (cached) job.cached = *cached;

    bool notify = false;
    {

        std::lock_guard<std::mutex> lock(queue.mu);

        if (queue.jobs.size() >= kMaxPendingOzoneAreaJobs) {

            queue.queued_keys.erase(key);

            return;
        }

        if (validate) {

            queue.jobs.push_back(std::move(job));
        } else {
            auto pos = queue.jobs.begin();

            while (pos != queue.jobs.end() && !pos->validate && pos->day >= job.day) ++pos;

            queue.jobs.insert(pos, std::move(job));
        }
        notify = true;
    }

    if (notify) queue.cv.notify_one();
}



std::string ozone_area_cache_signature_for_day(const std::string& spatial_signature, int64_t day) {
    int y = 0;
    unsigned m = 1, d = 1;

    civil_from_days(day, y, m, d);


    return simple_hash_hex(std::string(kOzoneAreaMethodId) + "|" + spatial_signature + "|" + std::to_string(y) + "|" + rama_o3_year_source_signature(y));
}


OzoneAreaDailyCell ozone_area_daily_cell(const std::string& jurisdiction_id,

                                         const std::vector<Point2>& area_samples,

                                         const std::vector<std::pair<std::string, double>>& station_weights,

                                         std::shared_ptr<const std::map<std::string, MapStation>> stations,
                                         const std::string& spatial_signature,

                                         int64_t day) {

    if (jurisdiction_id.empty() || (area_samples.empty() && station_weights.empty()) || !stations || stations->empty()) return {};
    const std::string cache_signature = ozone_area_cache_signature_for_day(spatial_signature, day);
    const std::string key = ozone_area_daily_cache_key(day, jurisdiction_id, cache_signature);

    if (ozone_area_daily_key_is_negative(key, day)) return {};

    if (auto cached = cached_ozone_area_daily_cell(day, jurisdiction_id, cache_signature)) {
        auto& store = ozone_area_daily_cache_store();
        const std::string validation_key = cache_signature + "|" + std::to_string(day) + "|" + jurisdiction_id;

        bool should_validate = false;
        {

            std::lock_guard<std::mutex> lock(store.mu);

            if (store.validated_keys.insert(validation_key).second) {
                const std::uint64_t h = ozmvm_fnv1a64_u64(validation_key.data(), validation_key.size());

                should_validate = (h % 257u) == 0u || store.validated_keys.size() == 1u;
            }
        }

        if (should_validate) queue_ozone_area_daily_job(day, jurisdiction_id, cache_signature, area_samples, station_weights, stations, true, &(*cached));

        return *cached;
    }

    OzoneAreaDailyCell pending;

    pending.pending_async = true;
    queue_ozone_area_daily_job(day, jurisdiction_id, cache_signature, area_samples, station_weights, stations, false, nullptr);

    return pending;
}




struct OzoneExposureMean {
    double mean = std::numeric_limits<double>::quiet_NaN();
    int days = 0;

    int64_t hours = 0;

    bool pending_async = false;
};



const char* ozone_exposure_aggregation_label(int mode) {
    switch (std::clamp(mode, 0, 5)) {

        case 1: return "mediana diaria semanal";
        case 2: return "media recortada robusta";

        case 3: return "maximo diario semanal";
        case 4: return "percentil 90 diario";
        case 5: return "moda diaria redondeada";

        default: return "media diaria semanal";
    }
}



double aggregate_weekly_exposure_values(std::vector<double> values, int mode) {

    if (values.empty()) return std::numeric_limits<double>::quiet_NaN();

    return ozmvm_aggregate_double_values(values.data(), values.size(), std::clamp(mode, 0, 5));
}


OzoneExposureMean ozone_area_mean_for_week(const std::string& jurisdiction_id,

                                           const std::vector<Point2>& area_samples,

                                           const std::vector<std::pair<std::string, double>>& station_weights,

                                           std::shared_ptr<const std::map<std::string, MapStation>> stations,
                                           const std::string& spatial_signature,

                                           int64_t epi_week_start_day,
                                           int lag_days,

                                           int aggregation_mode) {

    OzoneExposureMean out;

    if (jurisdiction_id.empty() || (area_samples.empty() && station_weights.empty()) || !stations || stations->empty() || spatial_signature.empty() || epi_week_start_day == std::numeric_limits<int64_t>::min()) return out;

    std::vector<double> daily_values;

    daily_values.reserve(7);

    for (int offset = 0; offset < 7; ++offset) {

        const int64_t day = epi_week_start_day - static_cast<int64_t>(lag_days) + offset;


        const OzoneAreaDailyCell cell = ozone_area_daily_cell(jurisdiction_id, area_samples, station_weights, stations, spatial_signature, day);

        if (cell.pending_async) out.pending_async = true;

        if (!std::isfinite(cell.mean) || cell.station_days <= 0) continue;

        daily_values.push_back(cell.mean);
        ++out.days;

        out.hours += cell.hours;
    }

    out.mean = aggregate_weekly_exposure_values(std::move(daily_values), aggregation_mode);

    return out;
}


void finalize_ozone_statistics(OzoneCorrelationResult& result) {

    const int n = static_cast<int>(result.rows.size());

    if (n < 2) return;

    std::vector<std::pair<double, double>> pairs;

    pairs.reserve(result.rows.size());

    std::set<std::string> diseases;

    std::set<std::string> jurisdictions;
    double sx = 0.0, sy = 0.0;

    for (const auto& r : result.rows) {

        pairs.push_back({r.ozone_mean, static_cast<double>(r.disease_cases)});
        sx += r.ozone_mean;
        sy += static_cast<double>(r.disease_cases);

        diseases.insert(r.disease_id);

        jurisdictions.insert(r.jurisdiction_id);
        result.ozone_day_count += r.ozone_days;

        result.ozone_hour_count += r.ozone_hours;
    }
    result.disease_count = static_cast<int>(diseases.size());

    result.jurisdiction_count = static_cast<int>(jurisdictions.size());
    result.mean_ozone = sx / static_cast<double>(n);
    result.mean_cases = sy / static_cast<double>(n);
    result.pearson = pearson_from_pairs(pairs);

    if (std::isfinite(result.pearson)) result.r2 = result.pearson * result.pearson;
    const char* pair_base = reinterpret_cast<const char*>(pairs.data());
    const size_t pair_x_offset = reinterpret_cast<const char*>(&pairs.front().first) - pair_base;
    const size_t pair_y_offset = reinterpret_cast<const char*>(&pairs.front().second) - pair_base;

    if (ozmvm_xy_ols_strided(pairs.data(), pairs.size(), sizeof(pairs.front()), pair_x_offset, pair_y_offset,
                             nullptr, &result.slope, &result.intercept)) {
        OzmvmLinearFitD fit_metrics{};

        if (ozmvm_xy_fit_metrics_strided(pairs.data(), pairs.size(), sizeof(pairs.front()), pair_x_offset, pair_y_offset,
                                         result.slope, result.intercept, &fit_metrics)) {
            result.rmse = fit_metrics.rmse;
            result.mae = fit_metrics.mae;
        }
    }

    if (n >= 3 && std::isfinite(result.pearson) && result.r2 < 0.999999) {
        result.t_stat = result.pearson * std::sqrt(static_cast<double>(n - 2) / std::max(1.0e-12, 1.0 - result.r2));
        result.p_normal_approx = std::erfc(std::fabs(result.t_stat) / std::sqrt(2.0));
    }

    std::vector<double> xs;

    std::vector<double> ys;

    xs.reserve(pairs.size());

    ys.reserve(pairs.size());

    for (const auto& p : pairs) {

        xs.push_back(p.first);

        ys.push_back(p.second);
    }
    const auto rx = dense_ranks(xs);
    const auto ry = dense_ranks(ys);

    std::vector<std::pair<double, double>> rank_pairs;

    rank_pairs.reserve(rx.size());

    for (size_t i = 0; i < rx.size(); ++i) rank_pairs.push_back({rx[i], ry[i]});


    result.spearman = pearson_from_pairs(rank_pairs);
    result.kendall = kendall_tau_from_pairs(pairs);
    result.theil_sen_slope = theil_sen_slope_from_pairs(pairs);

    if (std::isfinite(result.theil_sen_slope)) {

        std::vector<double> intercepts;

        intercepts.reserve(pairs.size());

        for (const auto& p : pairs) intercepts.push_back(p.second - result.theil_sen_slope * p.first);
        result.theil_sen_intercept = median_value(std::move(intercepts));
    }
}



std::string ozone_selection_cache_key(const std::set<std::string>& selected) {
    std::string key;

    for (const auto& id : selected) {
        key += id;

        key.push_back('|');
    }

    return key;
}



std::string ozone_tsv_clean(std::string value) {

    for (char& c : value) {

        if (c == '\t' || c == '\n' || c == '\r') c = ' ';
    }

    return value;
}

std::uint64_t tlalpowa_fnv_mix_string(std::uint64_t h, const std::string& s) {
    return ozmvm_fnv1a64_update(h, s.data(), s.size());
}

std::uint64_t tlalpowa_fnv_mix_byte(std::uint64_t h, char c) {
    return ozmvm_fnv1a64_update(h, &c, 1u);
}



std::string ozone_feature_collection_signature(const std::vector<MapFeature>& features) {
    std::ostringstream os;
    os << "features_v2|" << features.size();

    for (const auto& f : features) os << '\n' << f.id << '|' << feature_geometry_signature(f);

    return simple_hash_hex(os.str());
}



std::string ozone_observations_semantic_signature(const std::shared_ptr<const std::vector<ObservationRow>>& ptr, std::uint64_t revision) {

    static std::mutex mu;

    static std::map<std::string, std::string> cache;

    if (!ptr) return "empty";

    const std::string key = std::to_string(reinterpret_cast<std::uintptr_t>(ptr.get())) + "|" + std::to_string(revision) + "|" + std::to_string(ptr->size());
    {

        std::lock_guard<std::mutex> lock(mu);
        const auto it = cache.find(key);

        if (it != cache.end()) return it->second;
    }
    std::ostringstream os;
    os << "obs_o3_epi_v3|" << ptr->size();
    uint64_t checksum = 1469598103934665603ull;

    for (const auto& o : *ptr) {
        std::uint64_t field_hash = 1469598103934665603ull;
        field_hash = tlalpowa_fnv_mix_string(field_hash, o.week);
        field_hash = tlalpowa_fnv_mix_byte(field_hash, '|');
        field_hash = tlalpowa_fnv_mix_string(field_hash, o.jurisdiction_id);
        field_hash = tlalpowa_fnv_mix_byte(field_hash, '|');
        field_hash = tlalpowa_fnv_mix_string(field_hash, o.disease_id);
        field_hash = tlalpowa_fnv_mix_byte(field_hash, '|');
        field_hash = tlalpowa_fnv_mix_string(field_hash, o.metric);

        checksum ^= field_hash;
        checksum *= 1099511628211ull;

        checksum ^= static_cast<uint64_t>(o.week_index + 2048);
        checksum *= 1099511628211ull;
        checksum ^= static_cast<uint64_t>(std::max<int64_t>(0, o.value));
        checksum *= 1099511628211ull;
    }

    os << '|' << std::hex << checksum;
    const std::string sig = simple_hash_hex(os.str());
    {

        std::lock_guard<std::mutex> lock(mu);

        if (cache.size() > 16) cache.clear();
        cache[key] = sig;
    }

    return sig;
}



std::string ozone_grouped_rows_signature(const std::vector<OzoneCorrelationRow>& rows) {
    std::ostringstream os;

    os << "grouped_o3_epi_v2|" << rows.size();
    uint64_t checksum = 1469598103934665603ull;

    for (const auto& r : rows) {
        std::uint64_t field_hash = 1469598103934665603ull;
        field_hash = tlalpowa_fnv_mix_string(field_hash, r.week);
        field_hash = tlalpowa_fnv_mix_byte(field_hash, '|');
        field_hash = tlalpowa_fnv_mix_string(field_hash, r.jurisdiction_id);
        field_hash = tlalpowa_fnv_mix_byte(field_hash, '|');
        field_hash = tlalpowa_fnv_mix_string(field_hash, r.disease_id);

        checksum ^= field_hash;
        checksum *= 1099511628211ull;
        checksum ^= static_cast<uint64_t>(std::max<int64_t>(0, r.disease_cases));


        checksum *= 1099511628211ull;
    }
    os << '|' << std::hex << checksum;

    return simple_hash_hex(os.str());
}



std::string ozone_source_signature_for_grouped_rows(const std::vector<OzoneCorrelationRow>& rows, int lag_days) {

    std::set<int> years;

    for (const auto& r : rows) {

        for (int offset : {0, 6}) {
            int y = 0; unsigned m = 1, d = 1;

            civil_from_days(r.week_start_day - static_cast<int64_t>(lag_days) + offset, y, m, d);

            if (y >= 1900 && y <= 2100) years.insert(y);
        }
    }
    std::ostringstream os;

    os << "rama_o3_sources_for_pairs_v1|" << years.size();

    for (int y : years) os << '\n' << y << '|' << rama_o3_year_source_signature(y);

    return simple_hash_hex(os.str());
}



fs::path ozone_correlation_rows_cache_binary_path(const std::string& persistent_hash) {

    return ozone_correlation_rows_cache_root() / (persistent_hash + kIxiptlahBinaryCacheExtension);
}



bool load_ozone_correlation_result_binary_disk(const std::string& persistent_hash, OzoneCorrelationResult& out) {

    const fs::path p = ozone_correlation_rows_cache_binary_path(persistent_hash);

    std::ifstream in(p, std::ios::binary);

    if (!in) return false;
    char magic[8] = {};

    in.read(magic, sizeof(magic));

    if (!in || std::memcmp(magic, kIxiptlahBinaryCorrelationMagic, sizeof(kIxiptlahBinaryCorrelationMagic)) != 0) return false;
    std::uint32_t version = 0;

    std::uint64_t row_count = 0;

    if (!ozone_read_binary_value(in, version) || !ozone_read_binary_value(in, row_count)) return false;

    if (version != 4 || row_count > 100000000ull) return false;

    out.rows.clear();

    out.rows.reserve(static_cast<size_t>(std::min<std::uint64_t>(row_count, 2000000ull)));

    for (std::uint64_t i = 0; i < row_count; ++i) {

        OzoneCorrelationRow r;

        std::int32_t year = 0, lag_days = 0, ozone_days = 0;

        if (!ozone_read_binary_value(in, year) ||

            !ozone_read_binary_value(in, r.week_start_day) ||

            !ozone_read_binary_value(in, lag_days) ||

            !ozone_read_binary_string(in, r.week) ||

            !ozone_read_binary_string(in, r.jurisdiction_id) ||

            !ozone_read_binary_string(in, r.jurisdiction) ||

            !ozone_read_binary_string(in, r.disease_id) ||

            !ozone_read_binary_string(in, r.disease) ||

            !ozone_read_binary_string(in, r.disease_group) ||

            !ozone_read_binary_value(in, r.ozone_mean) ||

            !ozone_read_binary_value(in, r.disease_cases) ||

            !ozone_read_binary_value(in, ozone_days) ||

            !ozone_read_binary_value(in, r.ozone_hours)) {

            return false;
        }

        r.year = year;
        r.lag_days = lag_days;
        r.ozone_days = ozone_days;

        if (!r.week.empty() && !r.jurisdiction_id.empty() && !r.disease_id.empty() && std::isfinite(r.ozone_mean)) {

            out.rows.push_back(std::move(r));
        }
    }

    if (out.rows.empty()) return false;

    out.best_lag_days = out.rows.front().lag_days;
    finalize_ozone_statistics(out);

    out.status = "Cohorte O3-incidencia recuperada del cache binario interno; lectura completa sin TSV/JSON para uso interactivo.";


    return true;
}



bool load_ozone_correlation_result_disk(const std::string& persistent_hash, OzoneCorrelationResult& out) {

    return load_ozone_correlation_result_binary_disk(persistent_hash, out);
}



void write_ozone_correlation_result_disk(const std::string& persistent_hash, const std::string& persistent_key, const OzoneCorrelationResult& result) {

    if (result.pending_async || result.rows.empty()) return;

    const fs::path p = ozone_correlation_rows_cache_binary_path(persistent_hash);

    ensure_dir(p.parent_path());

    const fs::path tmp = fs::path(p.wstring() + L".tmp");

    std::ofstream out(tmp, std::ios::binary | std::ios::trunc);

    if (!out) return;
    const std::uint32_t version = 4;

    const std::uint64_t row_count = static_cast<std::uint64_t>(result.rows.size());

    out.write(kIxiptlahBinaryCorrelationMagic, sizeof(kIxiptlahBinaryCorrelationMagic));

    if (!ozone_write_binary_value(out, version) || !ozone_write_binary_value(out, row_count)) return;

    for (const auto& r : result.rows) {

        const std::int32_t year = static_cast<std::int32_t>(r.year);
        const std::int32_t lag_days = static_cast<std::int32_t>(r.lag_days);
        const std::int32_t ozone_days = static_cast<std::int32_t>(r.ozone_days);

        if (!ozone_write_binary_value(out, year) ||

            !ozone_write_binary_value(out, r.week_start_day) ||

            !ozone_write_binary_value(out, lag_days) ||

            !ozone_write_binary_string(out, r.week) ||

            !ozone_write_binary_string(out, r.jurisdiction_id) ||

            !ozone_write_binary_string(out, r.jurisdiction) ||

            !ozone_write_binary_string(out, r.disease_id) ||

            !ozone_write_binary_string(out, r.disease) ||

            !ozone_write_binary_string(out, r.disease_group) ||

            !ozone_write_binary_value(out, r.ozone_mean) ||

            !ozone_write_binary_value(out, r.disease_cases) ||

            !ozone_write_binary_value(out, ozone_days) ||

            !ozone_write_binary_value(out, r.ozone_hours)) {

            return;
        }
    }
    out.close();

    if (out) atomic_promote_file(tmp, p);

    (void)persistent_key;
}



std::string ozone_row_identity_key(const OzoneCorrelationRow& r) {

    return r.week + "|" + std::to_string(r.week_start_day) + "|" + std::to_string(r.lag_days) + "|" + r.jurisdiction_id + "|" + r.disease_id;
}



void merge_ozone_rows_keep_current(std::vector<OzoneCorrelationRow>& rows, const std::vector<OzoneCorrelationRow>& previous_rows) {

    if (previous_rows.empty()) return;

    std::set<std::string> seen;

    for (const auto& r : rows) seen.insert(ozone_row_identity_key(r));

    rows.reserve(rows.size() + previous_rows.size());

    for (const auto& r : previous_rows) {

        if (seen.insert(ozone_row_identity_key(r)).second) rows.push_back(r);
    }
}



size_t ozone_rows_estimated_bytes(const std::vector<OzoneCorrelationRow>& rows) {

    size_t bytes = rows.capacity() * sizeof(OzoneCorrelationRow);

    if (rows.empty()) return bytes;

    const size_t stride = rows.size() > 4096 ? std::max<size_t>(1, rows.size() / 4096) : 1;

    size_t row_bytes = 0;
    size_t sampled = 0;

    for (size_t i = 0; i < rows.size(); i += stride) {

        row_bytes += ozone_row_estimated_bytes(rows[i]);
        ++sampled;
    }

    if (sampled > 0) bytes += (row_bytes / sampled) * rows.size();

    return bytes;
}




void prune_ozone_result_cache_locked(std::map<std::string, std::shared_ptr<const OzoneCorrelationResult>>& cache) {
    constexpr size_t kMaxBytes = 384ull * 1024ull * 1024ull;
    constexpr size_t kMaxEntries = 4;

    auto total_bytes = [&]() {
        size_t total = 0;

        for (const auto& [_, ptr] : cache) if (ptr) total += ozone_result_estimated_bytes(*ptr);

        return total;
    };

    while (cache.size() > kMaxEntries || total_bytes() > kMaxBytes) {

        if (cache.empty()) break;
        auto victim = cache.begin();
        size_t victim_bytes = 0;

        for (auto it = cache.begin(); it != cache.end(); ++it) {
            const size_t b = it->second ? ozone_result_estimated_bytes(*it->second) : 0;

            if (b >= victim_bytes) {
                victim = it;
                victim_bytes = b;
            }
        }

        cache.erase(victim);
    }
}


void remember_ozone_result_cache_locked(std::map<std::string, std::shared_ptr<const OzoneCorrelationResult>>& cache,
                                        const std::string& key,


                                        const OzoneCorrelationResult& result) {

    if (result.pending_async || result.rows.empty()) return;
    constexpr size_t kMaxSingleBytes = 192ull * 1024ull * 1024ull;

    if (ozone_result_estimated_bytes(result) > kMaxSingleBytes && !cache.empty()) return;

    cache[key] = std::make_shared<const OzoneCorrelationResult>(result);
    prune_ozone_result_cache_locked(cache);
}



void prune_ozone_grouped_cache_locked(std::map<std::string, std::shared_ptr<const std::vector<OzoneCorrelationRow>>>& cache) {
    constexpr size_t kMaxBytes = 192ull * 1024ull * 1024ull;
    constexpr size_t kMaxEntries = 3;

    auto total_bytes = [&]() {
        size_t total = 0;

        for (const auto& [_, ptr] : cache) if (ptr) total += ozone_rows_estimated_bytes(*ptr);

        return total;
    };

    while (cache.size() > kMaxEntries || total_bytes() > kMaxBytes) {

        if (cache.empty()) break;

        auto victim = cache.begin();
        size_t victim_bytes = 0;

        for (auto it = cache.begin(); it != cache.end(); ++it) {

            const size_t b = it->second ? ozone_rows_estimated_bytes(*it->second) : 0;

            if (b >= victim_bytes) {
                victim = it;
                victim_bytes = b;
            }
        }

        cache.erase(victim);
    }
}



void prune_ozone_partial_rows_cache_locked(std::map<std::string, std::shared_ptr<const std::vector<OzoneCorrelationRow>>>& cache) {
    constexpr size_t kMaxBytes = 128ull * 1024ull * 1024ull;
    constexpr size_t kMaxEntries = 6;

    auto total_bytes = [&]() {
        size_t total = 0;

        for (const auto& [_, ptr] : cache) if (ptr) total += ozone_rows_estimated_bytes(*ptr);

        return total;
    };

    while (cache.size() > kMaxEntries || total_bytes() > kMaxBytes) {

        if (cache.empty()) break;
        auto victim = cache.begin();
        size_t victim_bytes = 0;

        for (auto it = cache.begin(); it != cache.end(); ++it) {

            const size_t b = it->second ? ozone_rows_estimated_bytes(*it->second) : 0;


            if (b >= victim_bytes) {
                victim = it;
                victim_bytes = b;
            }
        }

        cache.erase(victim);
    }
}


std::shared_ptr<const std::unordered_map<std::string, OzoneAreaSpatialSet>>

ozone_spatial_sets_for_features(const std::vector<MapFeature>& features,

                                const std::map<std::string, MapStation>& stations,
                                const std::string& feature_sig,

                                const std::string& station_sig) {
    const std::string key = feature_sig + "|" + station_sig;

    static std::mutex mu;

    static std::map<std::string, std::shared_ptr<const std::unordered_map<std::string, OzoneAreaSpatialSet>>> cache;
    {

        std::lock_guard<std::mutex> lock(mu);
        const auto it = cache.find(key);

        if (it != cache.end() && it->second) return it->second;
    }

    auto station_snapshot = std::make_shared<const std::map<std::string, MapStation>>(stations);

    auto built = std::make_shared<std::unordered_map<std::string, OzoneAreaSpatialSet>>();

    built->reserve(features.size() * 2 + 1);

    for (const auto& f : features) {

        if (f.id.empty()) continue;
        OzoneAreaSpatialSet set;

        set.samples = feature_area_samples_lonlat(f);
        set.station_weights = ozone_station_weights_for_feature(f, *station_snapshot);
        set.stations = station_snapshot;
        set.spatial_signature = ozone_area_spatial_signature(f, *station_snapshot);
        (*built)[f.id] = std::move(set);
    }

    std::shared_ptr<const std::unordered_map<std::string, OzoneAreaSpatialSet>> frozen = built;
    {

        std::lock_guard<std::mutex> lock(mu);

        if (cache.size() > 4) cache.clear();
        cache[key] = frozen;
    }

    return frozen;
}



OzoneCorrelationResult build_ozone_epidemiology_correlation_for_lag(UiState& ui, const GraphSpec& spec, int lag_days) {

    std::shared_ptr<const std::vector<ObservationRow>> observations_ptr;

    std::vector<MapFeature> features;

    std::vector<MapStation> station_list;

    std::map<std::string, MapStation> stations;

    std::set<std::string> selected;

    std::map<std::string, std::string> disease_groups;

    std::map<std::string, std::string> disease_names;
    std::string focus_id;

    int week_start = 0;

    int week_end = 0;

    int week_count = 0;
    const std::uint64_t obs_rev = ui.observations_revision.load(std::memory_order_relaxed);

    const std::uint64_t map_rev = ui.map_revision.load(std::memory_order_relaxed);
    {

        std::lock_guard<std::mutex> lock(ui.mu);
        observations_ptr = ui.observations_ptr;
        features = ui.features;

        station_list = ui.stations;
        selected = ui.selected_diseases;
        disease_groups = ui.disease_groups;
        disease_names = ui.diseases;
        focus_id = ui.focus_jurisdiction_id;

        week_start = ui.week_start;

        week_end = ui.week_end;


        week_count = static_cast<int>(ui.weeks.size());
    }

    static const std::vector<ObservationRow> empty_observations;

    const std::vector<ObservationRow>& observations = observations_ptr ? *observations_ptr : empty_observations;
    const std::string obs_sig = ozone_observations_semantic_signature(observations_ptr, obs_rev);

    const std::set<std::string> visible_selected = selected;

    if (spec.use_graph_disease_filter) {
        selected = spec.disease_filter;

        if (spec.use_selected_data) {

            for (auto it = selected.begin(); it != selected.end();) {

                if (visible_selected.count(*it) == 0) it = selected.erase(it);
                else ++it;
            }
        }
    }
    const bool filter_selected = spec.use_graph_disease_filter || spec.use_selected_data;

    int lo = 0;

    int hi = std::max(0, week_count - 1);

    if (spec.use_selected_data && week_count > 0) {
        const int exact = std::clamp(std::min(week_start, week_end), 0, hi);
        lo = exact;
        hi = exact;
    }


    for (const auto& s : station_list) {

        if (!s.id.empty() && std::isfinite(s.lon) && std::isfinite(s.lat)) stations[s.id] = s;
    }

    for (const auto& [id, s] : load_rama_station_catalog_runtime()) {

        if (!id.empty() && std::isfinite(s.lon) && std::isfinite(s.lat)) stations[id] = s;
    }

    if (features.empty()) {

        features = load_geojson(ui_config_root() / "geo" / "zmvm.geojson");
    }


    const std::string station_sig = station_geometry_signature(stations);
    const std::string feature_sig = ozone_feature_collection_signature(features);
    const std::string base_selection_key = std::to_string(lo) + "|" + std::to_string(hi) + "|" + std::to_string(lag_days) + "|" + focus_id + "|" +
        (filter_selected ? ozone_selection_cache_key(selected) : "ALL") + "|" +
        std::to_string(spec.use_selected_data ? 1 : 0) + "|" + std::to_string(spec.use_graph_disease_filter ? 1 : 0) + "|" +
        std::to_string(std::clamp(spec.exposure_aggregation, 0, 5));

    const std::string cache_key = std::to_string(obs_rev) + "|" + std::to_string(map_rev) + "|" + obs_sig + "|" + feature_sig + "|" + station_sig + "|" + base_selection_key;

    static std::mutex result_cache_mu;

    static std::map<std::string, std::shared_ptr<const OzoneCorrelationResult>> result_cache;
    {

        std::lock_guard<std::mutex> lock(result_cache_mu);
        const auto it = result_cache.find(cache_key);

        if (it != result_cache.end() && it->second) return *it->second;
        prune_ozone_result_cache_locked(result_cache);
    }

    const std::string grouped_key = std::to_string(obs_rev) + "|" + std::to_string(lo) + "|" + std::to_string(hi) + "|" +
        focus_id + "|" + (filter_selected ? ozone_selection_cache_key(selected) : "ALL") + "|" +
        std::to_string(spec.use_selected_data ? 1 : 0) + "|" + std::to_string(spec.use_graph_disease_filter ? 1 : 0);

    static std::mutex grouped_cache_mu;

    static std::map<std::string, std::shared_ptr<const std::vector<OzoneCorrelationRow>>> grouped_cache;

    std::shared_ptr<const std::vector<OzoneCorrelationRow>> grouped_rows_ptr;
    {

        std::lock_guard<std::mutex> lock(grouped_cache_mu);
        const auto git = grouped_cache.find(grouped_key);

        if (git != grouped_cache.end()) grouped_rows_ptr = git->second;
    }

    if (!grouped_rows_ptr || grouped_rows_ptr->empty()) {

        std::unordered_map<std::string, OzoneCorrelationRow> grouped;

        grouped.reserve(std::min<size_t>(observations.size(), 1000000) + 1);

        std::unordered_map<std::string, int64_t> week_day_cache;

        week_day_cache.reserve(4096);


        for (const auto& o : observations) {

            if (filter_selected && !tlalpowa_disease_selected_for_runtime(selected, o.disease_id)) continue;

            if (!o.metric_weekly_incidence && !observation_matches_chart_y(o, 0)) continue;

            if (o.week_index < lo || o.week_index > hi) continue;

            if (!focus_id.empty() && o.jurisdiction_id != focus_id) continue;

            auto wdit = week_day_cache.find(o.week);

            if (wdit == week_day_cache.end()) {

                wdit = week_day_cache.emplace(o.week, epi_week_start_day_from_label(o.week)).first;
            }

            const int64_t week_day = wdit->second;

            if (week_day == std::numeric_limits<int64_t>::min()) continue;

            const std::string key = o.week + "|" + o.jurisdiction_id + "|" + o.disease_id;

            auto& row = grouped[key];

            if (row.week.empty()) {

                row.week = o.week;

                row.week_start_day = week_day;

                row.lag_days = lag_days;

                row.jurisdiction_id = o.jurisdiction_id;

                row.jurisdiction = o.jurisdiction.empty() ? o.jurisdiction_id : o.jurisdiction;

                row.disease_id = o.disease_id;
                const auto nit = disease_names.find(o.disease_id);

                row.disease = nit == disease_names.end() ? (o.disease.empty() ? o.disease_id : o.disease) : nit->second;
                const auto dit = disease_groups.find(o.disease_id);

                row.disease_group = dit == disease_groups.end() ? "sin_categoria" : dit->second;

                if (auto yw = parse_epi_year_week(o.week)) row.year = yw->first;
            }

            row.disease_cases += std::max<int64_t>(0, o.value);
        }

        std::vector<OzoneCorrelationRow> grouped_rows;

        grouped_rows.reserve(grouped.size());

        for (auto& [_, row] : grouped) grouped_rows.push_back(std::move(row));

        std::sort(grouped_rows.begin(), grouped_rows.end(), [](const auto& a, const auto& b) {

            return std::tie(a.week_start_day, a.week, a.jurisdiction_id, a.disease_id) >

                   std::tie(b.week_start_day, b.week, b.jurisdiction_id, b.disease_id);
        });

        grouped_rows_ptr = std::make_shared<const std::vector<OzoneCorrelationRow>>(std::move(grouped_rows));
        {

            std::lock_guard<std::mutex> lock(grouped_cache_mu);

            grouped_cache[grouped_key] = grouped_rows_ptr;
            prune_ozone_grouped_cache_locked(grouped_cache);
        }
    }

    static const std::vector<OzoneCorrelationRow> empty_grouped_rows;

    const std::vector<OzoneCorrelationRow>& grouped_rows = grouped_rows_ptr ? *grouped_rows_ptr : empty_grouped_rows;


    const std::string grouped_sig = ozone_grouped_rows_signature(grouped_rows);

    const std::string source_sig = ozone_source_signature_for_grouped_rows(grouped_rows, lag_days);
    const std::string persistent_key = std::string("o3_epi_pairs_v3|") + obs_sig + "|" + grouped_sig + "|" + feature_sig + "|" + station_sig + "|" + source_sig + "|" + base_selection_key;
    const std::string persistent_hash = simple_hash_hex(persistent_key);
    {

        OzoneCorrelationResult disk_result;

        if (load_ozone_correlation_result_disk(persistent_hash, disk_result)) {

            std::lock_guard<std::mutex> lock(result_cache_mu);

            result_cache[cache_key] = std::make_shared<const OzoneCorrelationResult>(disk_result);
            prune_ozone_result_cache_locked(result_cache);

            return disk_result;
        }
    }

    auto weights_by_geo = ozone_spatial_sets_for_features(features, stations, feature_sig, station_sig);


    OzoneCorrelationResult result;
    result.best_lag_days = lag_days;

    result.grouped_total = static_cast<int>(std::min<size_t>(grouped_rows.size(), static_cast<size_t>(std::numeric_limits<int>::max())));

    std::unordered_map<std::string, OzoneExposureMean> weekly_exposure_cache;

    weekly_exposure_cache.reserve(std::min<size_t>(grouped_rows.size(), 262144) + 1);

    const auto build_started = std::chrono::steady_clock::now();

    constexpr int kOzoneBuildPendingSoftLimit = 160;

    constexpr int kOzoneBuildRowsBeforeBudget = 240;
    int pending_exposures_seen = 0;

    int grouped_rows_scanned = 0;

    for (const auto& base_row : grouped_rows) {

        OzoneCorrelationRow row = base_row;

        ++grouped_rows_scanned;

        row.lag_days = lag_days;

        if (!weights_by_geo) continue;

        const auto wit = weights_by_geo->find(row.jurisdiction_id);

        if (wit == weights_by_geo->end() || (wit->second.samples.empty() && wit->second.station_weights.empty()) || !wit->second.stations || wit->second.stations->empty()) continue;

        const std::string exposure_key = row.jurisdiction_id + "|" + std::to_string(row.week_start_day) + "|" +
            std::to_string(lag_days) + "|" + std::to_string(std::clamp(spec.exposure_aggregation, 0, 5));

        auto eit = weekly_exposure_cache.find(exposure_key);

        if (eit == weekly_exposure_cache.end()) {

            eit = weekly_exposure_cache.emplace(exposure_key,

                ozone_area_mean_for_week(row.jurisdiction_id, wit->second.samples, wit->second.station_weights, wit->second.stations, wit->second.spatial_signature,

                                         row.week_start_day, lag_days, spec.exposure_aggregation)).first;
        }
        const OzoneExposureMean& exposure = eit->second;

        if (exposure.pending_async) {

            result.pending_async = true;
            ++pending_exposures_seen;
        }

        if ((pending_exposures_seen >= kOzoneBuildPendingSoftLimit || grouped_rows_scanned >= kOzoneBuildRowsBeforeBudget) && result.pending_async) {

            const auto elapsed_us = std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now() - build_started).count();

            if (elapsed_us > 12000) break;
        }

        if (!std::isfinite(exposure.mean) || exposure.days <= 0) continue;

        row.ozone_mean = exposure.mean;

        row.ozone_days = exposure.days;

        row.ozone_hours = exposure.hours;

        result.rows.push_back(std::move(row));
    }

    result.grouped_scanned = grouped_rows_scanned;
    result.pending_exposures = pending_exposures_seen;
    {

        static std::mutex partial_mu;

        static std::map<std::string, std::shared_ptr<const std::vector<OzoneCorrelationRow>>> partial_rows_cache;

        std::lock_guard<std::mutex> lock(partial_mu);

        const auto pit = partial_rows_cache.find(persistent_hash);

        if (result.pending_async && pit != partial_rows_cache.end() && pit->second) {

            merge_ozone_rows_keep_current(result.rows, *pit->second);
        }

        if (!result.rows.empty()) {

            partial_rows_cache[persistent_hash] = std::make_shared<const std::vector<OzoneCorrelationRow>>(result.rows);

            prune_ozone_partial_rows_cache_locked(partial_rows_cache);
        }
    }

    std::sort(result.rows.begin(), result.rows.end(), [](const auto& a, const auto& b) {

        return std::tie(a.week, a.jurisdiction_id, a.disease_id) < std::tie(b.week, b.jurisdiction_id, b.disease_id);
    });
    finalize_ozone_statistics(result);
    const size_t queue_pending = ozone_area_daily_queue_pending_count();
    result.queue_pending = static_cast<int>(std::min<size_t>(queue_pending, static_cast<size_t>(std::numeric_limits<int>::max())));

    if (result.rows.empty()) {

        if (result.pending_async) {
            result.status = "O3 " + std::to_string(std::max(0, result.grouped_scanned)) + "/" +
                std::to_string(std::max(0, result.grouped_total)) +
                " pares; cola " + std::to_string(queue_pending) + ".";
        } else {
            result.status = "Sin pares comparables.";
        }
    } else {
        result.status = "Pares " + std::to_string(result.rows.size()) +
            "; O3 " + ozone_exposure_aggregation_label(spec.exposure_aggregation) +
            "; cola " + std::to_string(queue_pending) + ".";
    }

    write_ozone_correlation_result_disk(persistent_hash, persistent_key, result);
    {

        std::lock_guard<std::mutex> lock(result_cache_mu);
        remember_ozone_result_cache_locked(result_cache, cache_key, result);
    }

    return result;
}



OzoneCorrelationResult build_ozone_epidemiology_correlation(UiState& ui, const GraphSpec& spec, int lag_days) {

    return build_ozone_epidemiology_correlation_for_lag(ui, spec, std::max(0, lag_days));
}


double ozone_lag_score(const OzoneCorrelationResult& r);


int find_best_ozone_lag_days(UiState& ui, const GraphSpec& spec, int max_lag_days = 1460) {
    int best_lag = std::max(0, spec.lag_days);
    double best_score = -1.0;

    const auto score_lag = [&](int lag) {

        const OzoneCorrelationResult r = build_ozone_epidemiology_correlation_for_lag(ui, spec, lag);

        return ozone_lag_score(r);
    };

    for (int lag = 0; lag <= max_lag_days; lag += 7) {
        const double score = score_lag(lag);

        if (score > best_score) {
            best_score = score;
            best_lag = lag;
        }
    }
    const int refine_lo = std::max(0, best_lag - 9);
    const int refine_hi = std::min(max_lag_days, best_lag + 9);

    for (int lag = refine_lo; lag <= refine_hi; ++lag) {
        const double score = score_lag(lag);

        if (score > best_score) {
            best_score = score;

            best_lag = lag;
        }
    }

    return best_lag;
}



double ozone_lag_score(const OzoneCorrelationResult& r) {

    if (r.rows.size() < 4) return -1.0;

    const double n_weight_global = std::min(1.0, static_cast<double>(r.rows.size()) / 32.0);
    const double linear_global = std::isfinite(r.pearson) ? std::fabs(r.pearson) : 0.0;
    const double monotone_global = std::isfinite(r.spearman) ? std::fabs(r.spearman) : 0.0;
    const double global_score = std::max(linear_global, monotone_global) * n_weight_global;

    if (r.rows.size() > 50000 || r.disease_count > 180) return global_score;

    std::map<std::string, std::vector<std::pair<double, double>>> by_disease;

    for (const auto& row : r.rows) by_disease[row.disease_id].push_back({row.ozone_mean, static_cast<double>(row.disease_cases)});
    double weighted = 0.0;
    double weight_sum = 0.0;

    for (const auto& [_, pairs] : by_disease) {

        if (pairs.size() < 4) continue;
        double local_best = -1.0;

        for (int method = 0; method < kOzoneFitMethodCount; ++method) {
            local_best = std::max(local_best, ozone_fit_score(ozone_fit_for_pairs_cached(pairs, method)));
        }

        if (local_best >= 0.0) {
            const double w = std::min(1.0, static_cast<double>(pairs.size()) / 32.0);
            weighted += local_best * w;
            weight_sum += w;
        }
    }

    if (weight_sum > 0.0) return weighted / weight_sum;

    return global_score;
}



void reset_ozone_best_lag_search(GraphSpec& spec) {
    spec.best_lag_search_active = false;
    spec.best_lag_phase = 0;

    spec.best_lag_next = 0;

    spec.best_lag_best = std::max(0, spec.lag_days);
    spec.best_lag_refine_hi = 0;
    spec.best_lag_current = 0;
    spec.best_lag_tested = 0;
    spec.best_lag_total = 0;
    spec.best_lag_last_pairs = 0;
    spec.best_lag_score = -1.0;

    spec.best_lag_next_step_time = 0.0;

    spec.best_lag_candidates.clear();

    std::fill(spec.best_lag_seen.begin(), spec.best_lag_seen.end(), static_cast<unsigned char>(0));

    spec.best_lag_scores.clear();
    spec.best_lag_region_rank = 0;
    spec.best_lag_region_radius = 0;
}



bool step_ozone_best_lag_search(UiState& ui, GraphSpec& spec) {
    constexpr int kMaxLagDays = 1825;

    const double now = ImGui::GetTime();

    if (spec.best_lag_search_active && now < spec.best_lag_next_step_time) return false;

    if (!spec.best_lag_search_active) {
        spec.best_lag_search_active = true;
        spec.best_lag_phase = 0;
        spec.best_lag_next = 0;
        spec.best_lag_best = std::max(0, spec.lag_days);
        spec.best_lag_refine_hi = 0;
        spec.best_lag_current = 0;
        spec.best_lag_tested = 0;
        spec.best_lag_total = kMaxLagDays + 1;

        spec.best_lag_last_pairs = 0;
        spec.best_lag_score = -1.0;

        spec.best_lag_next_step_time = now;

        spec.best_lag_candidates.resize(static_cast<size_t>(kMaxLagDays + 1));
        const size_t seed_n = tlac_lag_seed_fill(kMaxLagDays, spec.best_lag_candidates.data(), spec.best_lag_candidates.size());
        spec.best_lag_candidates.resize(seed_n);

        std::fill(spec.best_lag_seen.begin(), spec.best_lag_seen.end(), static_cast<unsigned char>(0));

        spec.best_lag_scores.clear();
        spec.best_lag_region_rank = 0;
        spec.best_lag_region_radius = 1;
    }

    int lag = -1;

    if (spec.best_lag_phase == 0) {

        while (spec.best_lag_next < static_cast<int>(spec.best_lag_candidates.size()) &&

               tlac_lag_seen(spec.best_lag_seen.data(), spec.best_lag_seen.size(), spec.best_lag_candidates[static_cast<size_t>(spec.best_lag_next)]) != 0) {
            ++spec.best_lag_next;
        }

        if (spec.best_lag_next < static_cast<int>(spec.best_lag_candidates.size())) {

            lag = spec.best_lag_candidates[static_cast<size_t>(spec.best_lag_next)];
        } else {
            spec.best_lag_phase = 1;
            spec.best_lag_region_radius = 1;
            lag = tlac_lag_next_region(spec.best_lag_scores.data(), spec.best_lag_scores.size(), spec.best_lag_seen.data(), spec.best_lag_seen.size(), &spec.best_lag_region_radius, &spec.best_lag_region_rank, kMaxLagDays);
        }
    }

    if (spec.best_lag_phase == 1) {

        if (lag < 0) lag = tlac_lag_next_region(spec.best_lag_scores.data(), spec.best_lag_scores.size(), spec.best_lag_seen.data(), spec.best_lag_seen.size(), &spec.best_lag_region_radius, &spec.best_lag_region_rank, kMaxLagDays);

        if (lag < 0) {
            spec.best_lag_phase = 2;
            spec.best_lag_next = 0;
        }
    }

    if (spec.best_lag_phase == 2) {

        while (spec.best_lag_next <= kMaxLagDays && tlac_lag_seen(spec.best_lag_seen.data(), spec.best_lag_seen.size(), spec.best_lag_next) != 0) ++spec.best_lag_next;

        if (spec.best_lag_next <= kMaxLagDays) lag = spec.best_lag_next;
        else {
            spec.lag_days = std::clamp(spec.best_lag_best, 0, kMaxLagDays);
            spec.lag_unit = 0;
            spec.lag_value = spec.lag_days;
            spec.auto_best_lag = false;

            spec.best_lag_search_active = false;

            return true;
        }
    }

    lag = std::clamp(lag, 0, kMaxLagDays);
    spec.best_lag_current = lag;

    const OzoneCorrelationResult r = build_ozone_epidemiology_correlation_for_lag(ui, spec, lag);

    spec.best_lag_last_pairs = static_cast<int>(r.rows.size());

    if (r.pending_async) {

        spec.best_lag_next_step_time = now + 0.035;

        return false;
    }

    const double score = ozone_lag_score(r);

    if (tlac_lag_mark(spec.best_lag_seen.data(), spec.best_lag_seen.size(), lag)) {
        ++spec.best_lag_tested;

        spec.best_lag_scores.push_back(TlacLagScore{lag, score});
    }

    if (score > spec.best_lag_score) {
        spec.best_lag_score = score;
        spec.best_lag_best = lag;
    }

    if (spec.best_lag_phase == 0) ++spec.best_lag_next;

    else if (spec.best_lag_phase == 2) ++spec.best_lag_next;

    spec.best_lag_next_step_time = now + 0.018;

    return false;
}



void draw_chart_points(ImDrawList* dl, const ImVec2& a, const ImVec2& b, const std::vector<ChartPoint>& pts, int chart_type,

                       const ImVec4& accent, bool light_theme, bool show_fit_line, int fit_model) {
    chart_type = tlac_tipo_limpia(chart_type);
    const TlacPlot tla = tlac_plot_rect(a.x, a.y, b.x, b.y);
    if (!tla.ok) return;
    const ImVec2 plot_min(tla.x0, tla.y0);
    const ImVec2 plot_max(tla.x1, tla.y1);
    const float bottom_pad = tla.bottom;

    const ImU32 axis = light_theme ? IM_COL32(78, 92, 104, 166) : IM_COL32(172, 188, 202, 154);
    const ImU32 grid = light_theme ? IM_COL32(150, 164, 176, 58) : IM_COL32(108, 124, 140, 62);
    const ImU32 fill = u32(accent, light_theme ? 0.74f : 0.84f);
    const ImU32 fill_soft = u32(accent, light_theme ? 0.20f : 0.31f);
    const ImU32 line = u32(accent, 0.96f);
    const ImU32 text_soft = light_theme ? IM_COL32(82, 96, 108, 205) : IM_COL32(182, 198, 212, 205);
    const float w = tla.w;
    const float h = tla.h;

    const auto draw_axes = [&]() {
        dl->AddLine(ImVec2(plot_min.x, plot_max.y), plot_max, axis, 1.0f);
        dl->AddLine(ImVec2(plot_min.x, plot_max.y), plot_min, axis, 1.0f);
        for (int i = 1; i <= 4; ++i) {
            const float y = plot_max.y - h * (static_cast<float>(i) / 4.0f);
            dl->AddLine(ImVec2(plot_min.x, y), ImVec2(plot_max.x, y), grid, 1.0f);
        }
        if (chart_type == 6) {
            for (int i = 1; i <= 4; ++i) {
                const float x = plot_min.x + w * (static_cast<float>(i) / 4.0f);
                dl->AddLine(ImVec2(x, plot_min.y), ImVec2(x, plot_max.y), grid, 1.0f);
            }
        }
    };
    draw_axes();

    if (pts.empty()) {
        const char* msg = "Sin datos.";
        const ImVec2 ts = ImGui::CalcTextSize(msg);
        dl->AddText(ImVec2((plot_min.x + plot_max.x - ts.x) * 0.5f, plot_max.y + std::max(6.0f, bottom_pad * kGoldenN2)), text_soft, msg);
        return;
    }

    int64_t max_v = 1;
    int64_t min_v = std::numeric_limits<int64_t>::max();
    for (const auto& p : pts) {
        max_v = std::max(max_v, p.value);
        min_v = std::min(min_v, p.value);
    }
    const auto y_for_value = [&](int64_t v) { return tlac_plot_y_i64(&tla, v, max_v); };
    const auto x_for_index = [&](int i, int n) { return tlac_plot_x_index(&tla, i, n); };

    if (chart_type == 5) {
        const int bins = tlac_hist_bin_count(pts.size());
        std::vector<int> hist(static_cast<size_t>(bins), 0);
        const int64_t range = std::max<int64_t>(1, max_v - min_v);
        int hist_max = 1;
        for (const auto& p : pts) {
            const int bin = tlac_hist_bin_i64(p.value, min_v, range, bins);
            hist[static_cast<size_t>(bin)]++;
            hist_max = std::max(hist_max, hist[static_cast<size_t>(bin)]);
        }
        const float slot = w / static_cast<float>(bins);
        for (int i = 0; i < bins; ++i) {
            const float bh = h * (static_cast<float>(hist[static_cast<size_t>(i)]) / static_cast<float>(hist_max));
            dl->AddRectFilled(ImVec2(plot_min.x + slot * i + slot * 0.035f, plot_max.y - bh),
                              ImVec2(plot_min.x + slot * (i + 1) - slot * 0.035f, plot_max.y),
                              i % 2 ? fill : u32(accent, light_theme ? 0.50f : 0.70f), 1.6f);
        }
    } else {
        std::vector<ImVec2> line_pts;
        line_pts.reserve(pts.size());
        const int n = static_cast<int>(pts.size());
        for (int i = 0; i < n; ++i) {
            const float cx = x_for_index(i, n);
            const float y = y_for_value(pts[static_cast<size_t>(i)].value);
            const float slot = w / static_cast<float>(std::max(1, n));
            if (chart_type == 1) {
                const float bw = std::clamp(slot * 0.62f, 2.0f, 36.0f);
                dl->AddRectFilled(ImVec2(cx - bw * 0.5f, y), ImVec2(cx + bw * 0.5f, plot_max.y), fill, 3.0f);
            }
            line_pts.push_back(ImVec2(cx, y));
            if (chart_type == 6) {
                const float jitter = (std::sin(static_cast<float>(i) * 12.9898f) * 0.5f + 0.5f - 0.5f) * std::min(18.0f, slot * 0.28f);
                dl->AddCircleFilled(ImVec2(cx + jitter, y), chart_type == 6 ? 3.0f : 3.6f, i % 2 ? line : fill_soft, 16);
            }
            if ((i % std::max(1, n / 8)) == 0) {
                std::string lab = compact_label(pts[static_cast<size_t>(i)].label, 10);
                dl->AddText(ImVec2(cx - 20.0f, plot_max.y + 8.0f), light_theme ? IM_COL32(84, 98, 110, 186) : IM_COL32(168, 184, 198, 186), lab.c_str());
            }
        }
        if ((chart_type == 2 || chart_type == 4) && line_pts.size() >= 2) {
            if (chart_type == 4) {
                std::vector<ImVec2> area;
                area.reserve(line_pts.size() + 2);
                area.push_back(ImVec2(line_pts.front().x, plot_max.y));
                area.insert(area.end(), line_pts.begin(), line_pts.end());
                area.push_back(ImVec2(line_pts.back().x, plot_max.y));
                dl->AddConvexPolyFilled(area.data(), static_cast<int>(area.size()), fill_soft);
            }
            dl->AddPolyline(line_pts.data(), static_cast<int>(line_pts.size()), line, 0, 2.2f);
            if (chart_type == 2) {
                for (const ImVec2& p : line_pts) dl->AddCircleFilled(p, 2.8f, line, 14);
            }
        }
        if (show_fit_line && chart_type == 6 && line_pts.size() >= 2) {
            double sx = 0.0, sy = 0.0, sxx = 0.0, sxy = 0.0;
            const double fit_n = static_cast<double>(line_pts.size());
            for (size_t i = 0; i < line_pts.size(); ++i) {
                const double x = static_cast<double>(i);
                const double yv = static_cast<double>(pts[i].value);
                sx += x; sy += yv; sxx += x * x; sxy += x * yv;
            }
            const double denom = fit_n * sxx - sx * sx;
            if (std::abs(denom) > 1e-9) {
                const double slope = (fit_n * sxy - sx * sy) / denom;
                const double intercept = (sy - slope * sx) / fit_n;
                const auto fit_y = [&](double x) { return y_for_value(static_cast<int64_t>(std::llround(std::clamp(intercept + slope * x, 0.0, static_cast<double>(max_v))))); };
                const ImU32 fit_col = fit_model == 1
                    ? (light_theme ? IM_COL32(24, 128, 114, 220) : IM_COL32(92, 224, 205, 220))
                    : (light_theme ? IM_COL32(42, 78, 132, 220) : IM_COL32(120, 170, 240, 220));
                dl->PushClipRect(plot_min, plot_max, true);
                dl->AddLine(ImVec2(x_for_index(0, static_cast<int>(line_pts.size())), fit_y(0.0)),
                            ImVec2(x_for_index(static_cast<int>(line_pts.size()) - 1, static_cast<int>(line_pts.size())), fit_y(static_cast<double>(line_pts.size() - 1))),
                            fit_col, 2.1f);
                dl->PopClipRect();
            }
        }
    }
    dl->AddText(ImVec2(plot_min.x + 4.0f, plot_min.y - 24.0f), text_soft, compact_number(max_v).c_str());
}

void draw_ozone_correlation_plot(ImDrawList* dl,
                                 const ImVec2& a,
                                 const ImVec2& b,

                                 const OzoneCorrelationResult& corr,
                                 const GraphSpec& spec,
                                 const ImVec4& accent,

                                 bool light_theme) {
    const float area_w = std::max(1.0f, b.x - a.x);
    const float area_h = std::max(1.0f, b.y - a.y);
    const float left_pad = std::clamp(area_w * 0.105f, 52.0f, 70.0f);
    const float right_pad = std::clamp(area_w * 0.026f, 10.0f, 16.0f);
    const float top_pad = std::clamp(area_h * 0.070f, 20.0f, 30.0f);
    const float bottom_pad = std::clamp(area_h * 0.122f, 44.0f, 56.0f);
    const ImVec2 plot_min(a.x + left_pad, a.y + top_pad);
    const ImVec2 plot_max(b.x - right_pad, b.y - bottom_pad);

    if (plot_max.x <= plot_min.x + 8.0f || plot_max.y <= plot_min.y + 8.0f) return;
    const ImU32 axis = light_theme ? IM_COL32(68, 82, 96, 188) : IM_COL32(176, 194, 208, 172);

    const ImU32 major_grid = light_theme ? IM_COL32(135, 151, 166, 90) : IM_COL32(112, 130, 146, 82);
    dl->AddLine(ImVec2(plot_min.x, plot_max.y), plot_max, axis, 1.15f);
    dl->AddLine(ImVec2(plot_min.x, plot_max.y), plot_min, axis, 1.15f);

    if (corr.rows.empty()) {
        const std::string msg = corr.status.empty()

            ? "Preparando pares"
            : corr.status;

        const ImVec2 ts = ImGui::CalcTextSize(msg.c_str());
        dl->AddText(ImVec2((plot_min.x + plot_max.x - ts.x) * 0.5f, (plot_min.y + plot_max.y - ts.y) * 0.5f),
                    light_theme ? IM_COL32(72, 84, 96, 220) : IM_COL32(190, 204, 216, 220), msg.c_str());

        if (corr.pending_async && plot_max.y + 42.0f <= b.y) {
            const float pct = corr.grouped_total > 0
                ? std::clamp(static_cast<float>(corr.grouped_scanned) / static_cast<float>(corr.grouped_total), 0.0f, 1.0f)
                : 0.0f;
            const float plot_w = std::max(1.0f, plot_max.x - plot_min.x);
            const float bar_w = std::clamp(plot_w * 0.62f, 120.0f, 460.0f);
            const float bar_x = plot_min.x + (plot_w - bar_w) * 0.5f;

            const float bar_y = plot_max.y + 31.0f;
            char progress_label[192];
            std::snprintf(progress_label, sizeof(progress_label), "%.0f%% · %d/%d · cola %d",
                          pct * 100.0f, std::max(0, corr.grouped_scanned), std::max(0, corr.grouped_total), std::max(0, corr.queue_pending));

            const ImVec2 label_size = ImGui::CalcTextSize(progress_label);
            dl->AddText(ImVec2(bar_x + (bar_w - label_size.x) * 0.5f, plot_max.y + 14.0f),
                        light_theme ? IM_COL32(84, 96, 108, 218) : IM_COL32(170, 184, 198, 218), progress_label);
            const ImVec2 bar_a(bar_x, bar_y);
            const ImVec2 bar_b(bar_x + bar_w, bar_y + 5.0f);
            dl->AddRectFilled(bar_a, bar_b, light_theme ? IM_COL32(215, 225, 234, 235) : IM_COL32(38, 50, 62, 235), 3.0f);
            dl->AddRectFilled(bar_a, ImVec2(bar_a.x + (bar_b.x - bar_a.x) * pct, bar_b.y), u32(accent, 0.92f), 3.0f);
        }

        return;
    }

    double min_o3 = corr.rows.front().ozone_mean;

    double max_o3 = corr.rows.front().ozone_mean;

    int64_t min_cases = corr.rows.front().disease_cases;


    int64_t max_cases = corr.rows.front().disease_cases;

    std::map<std::string, std::vector<std::pair<double, double>>> pairs_by_disease;

    std::map<std::string, std::string> group_by_disease;

    for (const auto& r : corr.rows) {
        min_o3 = std::min(min_o3, r.ozone_mean);
        max_o3 = std::max(max_o3, r.ozone_mean);
        min_cases = std::min(min_cases, r.disease_cases);
        max_cases = std::max(max_cases, r.disease_cases);

        if (spec.show_fit_line) {

            pairs_by_disease[r.disease_id].push_back({r.ozone_mean, static_cast<double>(r.disease_cases)});
            group_by_disease[r.disease_id] = r.disease_group;
        }
    }
    const double o3_span_raw = std::max(1.0e-9, max_o3 - min_o3);
    const double case_span_raw = std::max<double>(1.0, static_cast<double>(max_cases - min_cases));
    min_o3 -= o3_span_raw * 0.035;
    max_o3 += o3_span_raw * 0.035;

    std::vector<double> x_ticks = nice_axis_ticks(min_o3, max_o3, 7);

    if (x_ticks.size() >= 2) {
        min_o3 = x_ticks.front();
        max_o3 = x_ticks.back();
    }
    const double o3_span = std::max(1.0e-9, max_o3 - min_o3);
    const double y_pad = std::max(1.0, case_span_raw * 0.055);
    double min_case_d = min_cases < 0 ? static_cast<double>(min_cases) - y_pad : 0.0;
    double max_case_d = static_cast<double>(max_cases) + y_pad;

    std::vector<double> y_ticks = nice_axis_ticks(min_case_d, max_case_d, 7);

    if (y_ticks.size() >= 2) {
        min_case_d = y_ticks.front();
        max_case_d = y_ticks.back();

        if (min_cases >= 0) min_case_d = std::min(0.0, min_case_d);
    }
    const double case_span = std::max(1.0, max_case_d - min_case_d);
    const float w = std::max(1.0f, plot_max.x - plot_min.x);

    const float h = std::max(1.0f, plot_max.y - plot_min.y);
    const ImU32 point = u32(accent, 0.96f);
    const ImU32 tick_col = light_theme ? IM_COL32(62, 74, 86, 230) : IM_COL32(190, 206, 220, 225);

    const auto sx_for = [&](double o3) {

        return plot_min.x + static_cast<float>((o3 - min_o3) / o3_span) * w;
    };

    const auto sy_for = [&](double cases) {
        const double clipped_cases = std::clamp(cases, min_case_d - case_span * 3.0, max_case_d + case_span * 3.0);

        return plot_max.y - static_cast<float>((clipped_cases - min_case_d) / case_span) * h;
    };

    for (double xv : x_ticks) {

        if (xv < min_o3 - o3_span * 0.01 || xv > max_o3 + o3_span * 0.01) continue;
        const float x = sx_for(xv);
        dl->AddLine(ImVec2(x, plot_min.y), ImVec2(x, plot_max.y), major_grid, 1.05f);
        const std::string label = nice_tick_label(xv);

        const ImVec2 xt = ImGui::CalcTextSize(label.c_str());
        dl->AddText(ImVec2(x - xt.x * 0.5f, plot_max.y + 6.0f), tick_col, label.c_str());
    }

    for (double yv : y_ticks) {

        if (yv < min_case_d - case_span * 0.01 || yv > max_case_d + case_span * 0.01) continue;
        const float y = sy_for(yv);
        dl->AddLine(ImVec2(plot_min.x, y), ImVec2(plot_max.x, y), major_grid, 1.05f);
        const std::string label = nice_tick_label(yv);

        const ImVec2 yt = ImGui::CalcTextSize(label.c_str());
        dl->AddText(ImVec2(plot_min.x - yt.x - 7.0f, y - yt.y * 0.5f), tick_col, label.c_str());
    }
    dl->PushClipRect(plot_min, plot_max, true);

    if (spec.show_fit_line) {

        for (const auto& [id, pairs] : pairs_by_disease) {


            if (pairs.size() < 2) continue;
            const int method = ozone_selected_fit_method(spec, id, pairs);
            const auto fit = ozone_fit_for_pairs_cached(pairs, method);

            if (!fit.valid) continue;
            const double y0 = fit.intercept + fit.slope * min_o3;

            const double y1 = fit.intercept + fit.slope * max_o3;
            const auto git = group_by_disease.find(id);
            const ImU32 fit_col = disease_color_u32(id, git == group_by_disease.end() ? "" : git->second, 0.74f);
            draw_dashed_line(dl, ImVec2(sx_for(min_o3), sy_for(y0)), ImVec2(sx_for(max_o3), sy_for(y1)), fit_col, 1.65f, 6.0f, 4.0f);
        }
    }

    const ImVec2 mouse = ImGui::GetIO().MousePos;
    const bool mouse_in_plot = mouse.x >= plot_min.x && mouse.x <= plot_max.x && mouse.y >= plot_min.y && mouse.y <= plot_max.y;
    int hovered_index = -1;
    float hovered_d2 = 64.0f;
    int hovered_bin = -1;

    const bool density_mode = corr.rows.size() > 24000;
    int density_bins_x = 0;
    int density_bins_y = 0;

    std::vector<std::uint32_t> density_counts;

    if (density_mode) {
        density_bins_x = std::clamp(static_cast<int>(w / 3.0f), 96, 520);

        density_bins_y = std::clamp(static_cast<int>(h / 3.0f), 72, 340);
        const int bin_count = density_bins_x * density_bins_y;
        density_counts.assign(static_cast<size_t>(bin_count), 0);

        std::vector<ImU32> density_color(static_cast<size_t>(bin_count), point);

        for (const auto& r : corr.rows) {
            const float x = std::clamp(sx_for(r.ozone_mean), plot_min.x, plot_max.x);
            const float y = std::clamp(sy_for(static_cast<double>(r.disease_cases)), plot_min.y, plot_max.y);
            const int bx = std::clamp(static_cast<int>(((x - plot_min.x) / w) * static_cast<float>(density_bins_x)), 0, density_bins_x - 1);
            const int by = std::clamp(static_cast<int>(((y - plot_min.y) / h) * static_cast<float>(density_bins_y)), 0, density_bins_y - 1);
            const size_t idx = static_cast<size_t>(by * density_bins_x + bx);

            if (density_counts[idx] == 0) density_color[idx] = disease_color_u32(r.disease_id, r.disease_group, 0.74f);
            ++density_counts[idx];
        }
        std::uint32_t max_count = 1;

        for (const auto c : density_counts) max_count = std::max(max_count, c);
        const float cell_w = w / static_cast<float>(density_bins_x);
        const float cell_h = h / static_cast<float>(density_bins_y);

        for (int by = 0; by < density_bins_y; ++by) {

            for (int bx = 0; bx < density_bins_x; ++bx) {
                const size_t idx = static_cast<size_t>(by * density_bins_x + bx);
                const std::uint32_t c = density_counts[idx];

                if (c == 0) continue;
                const float strength = static_cast<float>(std::log1p(static_cast<double>(c)) / std::log1p(static_cast<double>(max_count)));

                ImVec4 col = ImGui::ColorConvertU32ToFloat4(density_color[idx] ? density_color[idx] : point);
                col.w = std::clamp(0.16f + strength * 0.68f, 0.18f, 0.88f);
                const float x0 = plot_min.x + static_cast<float>(bx) * cell_w;
                const float y0 = plot_min.y + static_cast<float>(by) * cell_h;
                dl->AddRectFilled(ImVec2(x0, y0), ImVec2(x0 + std::max(1.35f, cell_w), y0 + std::max(1.35f, cell_h)),

                                  ImGui::ColorConvertFloat4ToU32(col));
            }
        }

        if (mouse_in_plot) {
            const int bx = std::clamp(static_cast<int>(((mouse.x - plot_min.x) / w) * static_cast<float>(density_bins_x)), 0, density_bins_x - 1);
            const int by = std::clamp(static_cast<int>(((mouse.y - plot_min.y) / h) * static_cast<float>(density_bins_y)), 0, density_bins_y - 1);

            const int idx = by * density_bins_x + bx;

            if (idx >= 0 && static_cast<size_t>(idx) < density_counts.size() && density_counts[static_cast<size_t>(idx)] > 0) hovered_bin = idx;
        }
    } else {

        for (size_t ii = 0; ii < corr.rows.size(); ++ii) {

            const int i = static_cast<int>(ii);

            const auto& r = corr.rows[ii];
            const float x = std::clamp(sx_for(r.ozone_mean), plot_min.x, plot_max.x);
            const float y = std::clamp(sy_for(static_cast<double>(r.disease_cases)), plot_min.y, plot_max.y);
            const ImU32 disease_col = disease_color_u32(r.disease_id, r.disease_group, 0.86f);

            if (mouse_in_plot) {
                const float dx = mouse.x - x;
                const float dy = mouse.y - y;
                const float d2 = dx * dx + dy * dy;

                if (d2 < hovered_d2) {
                    hovered_d2 = d2;
                    hovered_index = i;
                }
            }
            dl->AddCircleFilled(ImVec2(x, y), hovered_index == i ? 3.9f : 2.12f, disease_col ? disease_col : point, 8);
        }
    }
    dl->PopClipRect();

    if (density_mode && hovered_bin >= 0 && mouse_in_plot && ImGui::IsWindowHovered(ImGuiHoveredFlags_AllowWhenBlockedByActiveItem)) {
        const int bx = hovered_bin % std::max(1, density_bins_x);
        const int by = hovered_bin / std::max(1, density_bins_x);
        const double x0 = min_o3 + (static_cast<double>(bx) / static_cast<double>(std::max(1, density_bins_x))) * o3_span;
        const double x1 = min_o3 + (static_cast<double>(bx + 1) / static_cast<double>(std::max(1, density_bins_x))) * o3_span;
        const double y1 = max_case_d - (static_cast<double>(by) / static_cast<double>(std::max(1, density_bins_y))) * case_span;
        const double y0 = max_case_d - (static_cast<double>(by + 1) / static_cast<double>(std::max(1, density_bins_y))) * case_span;

        ImGui::BeginTooltip();

        ImGui::Text("%u pares", density_counts[static_cast<size_t>(hovered_bin)]);
        ImGui::Text("O3 %.4f-%.4f ppb", x0, x1);
        ImGui::Text("Incidencia %.2f-%.2f", y0, y1);

        ImGui::EndTooltip();

    } else if (hovered_index >= 0 && mouse_in_plot && ImGui::IsWindowHovered(ImGuiHoveredFlags_AllowWhenBlockedByActiveItem)) {

        const auto& r = corr.rows[static_cast<size_t>(hovered_index)];

        ImGui::BeginTooltip();

        ImGui::TextUnformatted(r.disease.empty() ? r.disease_id.c_str() : r.disease.c_str());
        ImGui::TextUnformatted((r.jurisdiction.empty() ? r.jurisdiction_id : r.jurisdiction).c_str());
        ImGui::Text("%s · O3 %.4f · casos %lld · %d d", r.week.c_str(), r.ozone_mean,
                    static_cast<long long>(r.disease_cases), r.lag_days);

        ImGui::EndTooltip();
    }
    char footer[192];

    if (std::isfinite(corr.pearson)) {
        std::snprintf(footer, sizeof(footer), "n=%d · r=%.4f · rho=%.4f · desfase=%d d",
                      static_cast<int>(corr.rows.size()), corr.pearson, corr.spearman, corr.best_lag_days);
    } else {
        std::snprintf(footer, sizeof(footer), "n=%d · desfase=%d d", static_cast<int>(corr.rows.size()), corr.best_lag_days);
    }
    dl->AddText(ImVec2(plot_min.x, plot_max.y + 12.0f), light_theme ? IM_COL32(62, 74, 86, 235) : IM_COL32(186, 202, 216, 235), footer);
    dl->AddText(ImVec2(plot_min.x, plot_min.y - 19.0f), light_theme ? IM_COL32(62, 74, 86, 235) : IM_COL32(186, 202, 216, 235), "O3 territorial · incidencia semanal");
}


