std::string graph_csv_escape(std::string v) {
    char stack[512];
    size_t n = ozmvm_csv_escape_copy(v.data(), v.size(), stack, sizeof(stack));
    if (n < sizeof(stack)) return std::string(stack, n);
    std::string out(n + 1, '\0');
    n = ozmvm_csv_escape_copy(v.data(), v.size(), out.data(), out.size());
    out.resize(n);
    return out;
}

std::string graph_safe_file_fragment(std::string s) {
    char stack[128];
    size_t n = ozmvm_key_fragment_copy(s.data(), s.size(), stack, sizeof(stack), 54, "grafica");
    if (n < sizeof(stack)) return std::string(stack, n);
    std::string out(n + 1, '\0');
    n = ozmvm_key_fragment_copy(s.data(), s.size(), out.data(), out.size(), 54, "grafica");
    out.resize(n);
    return out;
}

std::string tlac_tiempo_txt() {
    char buf[32] = {};
    tlac_tiempo_compacto_copy(0, buf, sizeof(buf));
    return buf;
}

void tlac_titulo_pon(GraphSpec& spec, const std::string& title) {
    tlac_titulo_copy(title.c_str(), spec.title, sizeof(spec.title));
}

TlacSpec tlac_de_spec(const GraphSpec& spec) {
    TlacSpec c{};
    c.chart_type = spec.chart_type;
    c.axis_x_domain = spec.axis_x_domain;
    c.axis_x = spec.axis_x;
    c.axis_y_domain = spec.axis_y_domain;
    c.axis_y = spec.axis_y;
    c.axis_z_domain = spec.axis_z_domain;
    c.axis_z = spec.axis_z;
    c.dependency = spec.dependency;
    c.measurement = spec.measurement;
    c.exposure_aggregation = spec.exposure_aggregation;
    c.use_selected_data = spec.use_selected_data ? 1 : 0;
    c.compare_best_lag = spec.compare_best_lag ? 1 : 0;
    c.auto_best_lag = spec.auto_best_lag ? 1 : 0;
    c.force_ozone_epi = spec.force_ozone_epi ? 1 : 0;
    c.use_graph_disease_filter = spec.use_graph_disease_filter ? 1 : 0;
    c.show_fit_line = spec.show_fit_line ? 1 : 0;
    c.fit_model = spec.fit_model;
    c.lag_weeks = spec.lag_weeks;
    c.lag_days = spec.lag_days;
    c.lag_value = spec.lag_value;
    c.lag_unit = spec.lag_unit;
    return c;
}

void spec_de_tlac(GraphSpec& spec, const TlacSpec& c) {
    spec.chart_type = c.chart_type;
    spec.axis_x_domain = c.axis_x_domain;
    spec.axis_x = c.axis_x;
    spec.axis_y_domain = c.axis_y_domain;
    spec.axis_y = c.axis_y;
    spec.axis_z_domain = c.axis_z_domain;
    spec.axis_z = c.axis_z;
    spec.dependency = c.dependency;
    spec.measurement = c.measurement;
    spec.exposure_aggregation = c.exposure_aggregation;
    spec.use_selected_data = c.use_selected_data != 0;
    spec.compare_best_lag = c.compare_best_lag != 0;
    spec.auto_best_lag = c.auto_best_lag != 0;
    spec.force_ozone_epi = c.force_ozone_epi != 0;
    spec.use_graph_disease_filter = c.use_graph_disease_filter != 0;
    spec.show_fit_line = c.show_fit_line != 0;
    spec.fit_model = c.fit_model;
    spec.lag_weeks = c.lag_weeks;
    spec.lag_days = c.lag_days;
    spec.lag_value = c.lag_value;
    spec.lag_unit = c.lag_unit;
}

std::string tlac_titulo_base(const GraphSpec& spec) {
    TlacSpec c = tlac_de_spec(spec);
    tlac_spec_limpia(&c);
    char stack[128] = {};
    const size_t n = tlac_titulo_base_copy(&c, stack, sizeof(stack));
    if (n < sizeof(stack)) return std::string(stack, n);
    std::string out(n + 1, '\0');
    tlac_titulo_base_copy(&c, out.data(), out.size());
    out.resize(n);
    return out;
}

void tlac_limpia_spec(GraphSpec& spec) {
    TlacSpec c = tlac_de_spec(spec);
    tlac_spec_limpia(&c);
    spec_de_tlac(spec, c);
}

GraphSpec tlac_spec_de_item(const TlacGal& item, UiState& ui) {
    TlacSpec c{};
    tlac_spec_de_gal(&item, &c);
    GraphSpec spec;
    spec_de_tlac(spec, c);
    if (item.ozone_template) {
        std::lock_guard<std::mutex> lock(ui.mu);
        spec.disease_filter = ui.selected_diseases;
        if (spec.disease_filter.empty() && !ui.diseases.empty()) spec.disease_filter.insert(ui.diseases.begin()->first);
    }
    tlac_limpia_spec(spec);
    tlac_titulo_pon(spec, item.title && item.title[0] ? item.title : tlac_titulo_base(spec));
    return spec;
}

void tlac_precarga_spec(UiState& ui, const GraphSpec& spec) {
    ui.pending_chart_type = tlac_tipo_limpia(spec.chart_type);
    ui.pending_lag_weeks = std::clamp(spec.lag_days, 0, 1825);
    ui.pending_axis_y_domain = std::clamp(spec.axis_y_domain, 0, 4);
    ui.pending_axis_x_domain = std::clamp(spec.axis_x_domain, 0, 4);
    ui.pending_axis_z_domain = std::clamp(spec.axis_z_domain, 0, 4);
    ui.pending_axis_y = std::clamp(spec.axis_y, 0, 4);
    ui.pending_axis_x = std::clamp(spec.axis_x, 0, 4);
    ui.pending_axis_z = std::clamp(spec.axis_z, 0, 4);
    ui.pending_dependency = spec.dependency;
    ui.pending_measurement = spec.measurement;
    ui.pending_exposure_aggregation = std::clamp(spec.exposure_aggregation, 0, 5);
    ui.pending_use_selected_data = spec.use_selected_data;
    ui.pending_compare_best_lag = spec.compare_best_lag;
    ui.pending_show_fit_line = spec.show_fit_line;
    ui.pending_fit_model = std::clamp(spec.fit_model, 0, 1);
    ui.pending_diseases = spec.disease_filter;
    ui.pending_disease_search[0] = '\0';
}

fs::path graph_export_directory() {
    return executable_dir() / "Datos" / "Exportaciones" / "Graficas";
}

void graph_set_status(UiState& ui, const std::string& msg) {
    std::lock_guard<std::mutex> lock(ui.mu);
    ui.status = msg;
}

bool export_graph_csv(UiState& ui, const GraphSpec& spec, int tab_index, int graph_index) {
    try {
        const fs::path dir = graph_export_directory();
        fs::create_directories(dir);
        const std::string base = graph_safe_file_fragment(spec.title[0] ? spec.title : tlac_titulo_base(spec));
        const fs::path path = dir / (tlac_tiempo_txt() + "_pestana_" + std::to_string(tab_index) + "_grafica_" + std::to_string(graph_index + 1) + "_" + base + ".csv");
        std::ofstream out(path, std::ios::binary);
        if (!out) {
            graph_set_status(ui, "No pude crear CSV de grafica en " + path_utf8(path));
            return false;
        }
        const bool ozone_epi_disp = spec.force_ozone_epi || spec.chart_type == 6 ||
            (spec.axis_x_domain == 1 && spec.axis_y_domain == 0) ||
            (spec.axis_x_domain == 0 && spec.axis_y_domain == 1);
        if (ozone_epi_disp) {
            const OzoneCorrelationResult corr = build_ozone_epidemiology_correlation(ui, spec, std::max(0, spec.lag_days));
            out << "year,week_start_day,lag_days,week,jurisdiction_id,jurisdiction,disease_id,disease,disease_group,ozone_mean,disease_cases,ozone_days,ozone_hours\n";
            for (const auto& r : corr.rows) {
                out << r.year << ',' << r.week_start_day << ',' << r.lag_days << ','
                    << graph_csv_escape(r.week) << ','
                    << graph_csv_escape(r.jurisdiction_id) << ','
                    << graph_csv_escape(r.jurisdiction) << ','
                    << graph_csv_escape(r.disease_id) << ','
                    << graph_csv_escape(r.disease) << ','
                    << graph_csv_escape(r.disease_group) << ','
                    << std::setprecision(12) << r.ozone_mean << ','
                    << r.disease_cases << ',' << r.ozone_days << ',' << r.ozone_hours << "\n";
            }
        } else {
            const std::vector<ChartPoint> pts = build_epidemiological_chart_points_for_spec(ui, spec);
            out << "key,label,value,chart_type,axis_y_domain,axis_y,axis_x_domain,axis_x\n";
            for (const auto& pt : pts) {
                out << graph_csv_escape(pt.key) << ','
                    << graph_csv_escape(pt.label) << ','
                    << pt.value << ','
                    << spec.chart_type << ','
                    << spec.axis_y_domain << ',' << spec.axis_y << ','
                    << spec.axis_x_domain << ',' << spec.axis_x << "\n";
            }
        }
        out.flush();
        graph_set_status(ui, "CSV de grafica guardado: " + path_utf8(path));
        return true;
    } catch (const std::exception& e) {
        graph_set_status(ui, std::string("No pude exportar CSV de grafica: ") + e.what());
        return false;
    } catch (...) {
        graph_set_status(ui, "No pude exportar CSV de grafica: error desconocido");
        return false;
    }
}

std::vector<unsigned char> encode_png_rgba_uncompressed(int w, int h, const std::vector<unsigned char>& rgba_top_down) {
    if (w <= 0 || h <= 0) return {};
    const size_t sw = static_cast<size_t>(w);
    const size_t sh = static_cast<size_t>(h);
    if (sw > std::numeric_limits<size_t>::max() / sh) return {};
    const size_t pixel_count = sw * sh;
    if (pixel_count > std::numeric_limits<size_t>::max() / 4u) return {};
    const size_t rgba_bytes = pixel_count * 4u;
    const size_t need = rgba_top_down.size() >= rgba_bytes ? ozmvm_png_rgba_uncompressed_size(w, h) : 0u;
    if (need == 0) return {};
    std::vector<unsigned char> png(need);
    const size_t written = ozmvm_png_rgba_uncompressed_encode(w, h, rgba_top_down.data(), png.data(), png.size());
    if (written == 0) return {};
    png.resize(written);
    return png;
}

#ifdef _WIN32
bool graph_set_clipboard_png_and_dib(const std::vector<unsigned char>& png, int w, int h, const std::vector<unsigned char>& rgba_top_down) {
    if (png.empty() || w <= 0 || h <= 0) return false;
    HWND hwnd = g_tlalpowa_main_window ? glfwGetWin32Window(g_tlalpowa_main_window) : nullptr;
    if (!OpenClipboard(hwnd)) return false;
    EmptyClipboard();
    const UINT png_format = RegisterClipboardFormatW(L"PNG");
    if (png_format != 0) {
        HGLOBAL hpng = GlobalAlloc(GMEM_MOVEABLE, png.size());
        if (hpng) {
            void* dst = GlobalLock(hpng);
            if (dst) {
                std::memcpy(dst, png.data(), png.size());
                GlobalUnlock(hpng);
                if (!SetClipboardData(png_format, hpng)) GlobalFree(hpng);
            } else {
                GlobalFree(hpng);
            }
        }
    }
    const size_t dib_pixels = static_cast<size_t>(w) * static_cast<size_t>(h) * 4u;
    const size_t dib_bytes = sizeof(BITMAPINFOHEADER) + dib_pixels;
    HGLOBAL hdib = GlobalAlloc(GMEM_MOVEABLE, dib_bytes);
    if (hdib) {
        unsigned char* mem = static_cast<unsigned char*>(GlobalLock(hdib));
        if (mem) {
            std::memset(mem, 0, dib_bytes);
            BITMAPINFOHEADER* bih = reinterpret_cast<BITMAPINFOHEADER*>(mem);
            bih->biSize = sizeof(BITMAPINFOHEADER);
            bih->biWidth = w;
            bih->biHeight = -h; 
            bih->biPlanes = 1;
            bih->biBitCount = 32;
            bih->biCompression = BI_RGB;
            unsigned char* pix = mem + sizeof(BITMAPINFOHEADER);
            for (size_t i = 0; i < static_cast<size_t>(w) * static_cast<size_t>(h); ++i) {
                pix[i * 4u + 0u] = rgba_top_down[i * 4u + 2u];
                pix[i * 4u + 1u] = rgba_top_down[i * 4u + 1u];
                pix[i * 4u + 2u] = rgba_top_down[i * 4u + 0u];
                pix[i * 4u + 3u] = rgba_top_down[i * 4u + 3u];
            }
            GlobalUnlock(hdib);
            if (!SetClipboardData(CF_DIB, hdib)) GlobalFree(hdib);
        } else {
            GlobalFree(hdib);
        }
    }
    CloseClipboard();
    return true;
}
#endif

void process_pending_graph_capture(UiState& ui, int framebuffer_w, int framebuffer_h) {
    if (!ui.graph_capture_pending || ui.graph_capture_mode != 1) return;
    ui.graph_capture_pending = false;
    const ImGuiIO& io = ImGui::GetIO();
    const float sx = std::max(0.1f, io.DisplayFramebufferScale.x);
    const float sy = std::max(0.1f, io.DisplayFramebufferScale.y);
    TlacRectI r;
    if (!tlac_px_rect(ui.graph_capture_min.x, ui.graph_capture_min.y,
                      ui.graph_capture_max.x, ui.graph_capture_max.y,
                      sx, sy, framebuffer_w, framebuffer_h, &r)) {
        graph_set_status(ui, "No pude copiar PNG: rectangulo de grafica invalido.");
        return;
    }
    const int x0 = r.x0;
    const int gl_y = r.gl_y;
    const int w = r.w;
    const int h = r.h;
    std::vector<unsigned char> bottom_up(static_cast<size_t>(w) * static_cast<size_t>(h) * 4u);
    glPixelStorei(GL_PACK_ALIGNMENT, 1);
    glReadPixels(x0, gl_y, w, h, GL_RGBA, GL_UNSIGNED_BYTE, bottom_up.data());
    std::vector<unsigned char> top_down(bottom_up.size());
    const size_t row = static_cast<size_t>(w) * 4u;
    for (int y = 0; y < h; ++y) {
        const size_t src = static_cast<size_t>(h - 1 - y) * row;
        const size_t dst = static_cast<size_t>(y) * row;
        std::memcpy(top_down.data() + dst, bottom_up.data() + src, row);
    }
    std::vector<unsigned char> png = encode_png_rgba_uncompressed(w, h, top_down);
    bool ok = false;
#ifdef _WIN32
    ok = graph_set_clipboard_png_and_dib(png, w, h, top_down);
#else
    (void)png;
#endif
    graph_set_status(ui, ok ? "PNG de grafica copiado al portapapeles." : "No pude copiar PNG al portapapeles en esta plataforma.");
}


fs::path graph_gallery_icon_path(const char* filename) {
    if (!filename || !*filename) return {};
    const fs::path name = fs::path(widen_utf8(filename));
    const fs::path datos = datos_externos_root();
    const fs::path work = workspace_root();
    const fs::path exe = executable_dir();
    const std::array<fs::path, 7> roots = {
        datos / "icon",
        datos / "icons",
        work / "Datos" / "icon",
        work / "Datos" / "icons",
        exe / "Datos" / "icon",
        exe / "Datos" / "icons",
        work / "Fuente" / "Config" / "icons"
    };
    std::error_code ec;
    for (const fs::path& root : roots) {
        const fs::path p = root / name;
        if (fs::exists(p, ec) && fs::is_regular_file(p, ec)) return p;
        ec.clear();
    }
    return {};
}

PreviewTexture load_persistent_graph_gallery_icon_texture(const fs::path& path) {
    struct Entry { PreviewTexture tex; std::uintmax_t size = 0; long long mtime = 0; };
    static std::mutex mu;
    static std::map<std::string, Entry> cache;
    if (path.empty()) return {};
    std::error_code ec;
    if (!fs::exists(path, ec) || !fs::is_regular_file(path, ec)) return {};
    ec.clear();
    const std::uintmax_t sz = fs::file_size(path, ec);
    if (ec || sz == 0) return {};
    ec.clear();
    const auto mt = fs::last_write_time(path, ec);
    const long long mt_key = ec ? 0ll : static_cast<long long>(mt.time_since_epoch().count());
    const std::string key = normalize_key(path_utf8(path.lexically_normal()));
    {
        std::lock_guard<std::mutex> lock(mu);
        auto it = cache.find(key);
        if (it != cache.end() && it->second.size == sz && it->second.mtime == mt_key && it->second.tex.id != 0) return it->second.tex;
        if (it != cache.end()) {
            if (it->second.tex.id != 0) glDeleteTextures(1, &it->second.tex.id);
            cache.erase(it);
        }
    }
    PreviewTexture tex = load_texture_from_file(path);
    if (tex.id == 0 || tex.width <= 0 || tex.height <= 0) return {};
    {
        std::lock_guard<std::mutex> lock(mu);
        if (cache.size() > 24) {
            for (auto it = cache.begin(); it != cache.end();) {
                if (it->second.tex.id != 0) glDeleteTextures(1, &it->second.tex.id);
                it = cache.erase(it);
                if (cache.size() <= 12) break;
            }
        }
        cache[key] = Entry{tex, sz, mt_key};
    }
    return tex;
}

bool draw_graph_gallery_icon_png(ImDrawList* dl, const TlacGal& item, const ImVec2& a, const ImVec2& b, const ImVec4& accent) {
    const fs::path path = graph_gallery_icon_path(item.icon_filename);
    const PreviewTexture tex = load_persistent_graph_gallery_icon_texture(path);
    if (tex.id == 0) return false;
    const float w = std::max(1.0f, b.x - a.x);
    const float h = std::max(1.0f, b.y - a.y);
    const float image_aspect = tex.height > 0 ? static_cast<float>(tex.width) / static_cast<float>(tex.height) : 1.0f;
    float iw = w;
    float ih = h;
    if (image_aspect > 1.0f) ih = std::min(h, w / image_aspect);
    else iw = std::min(w, h * image_aspect);
    const ImVec2 p0(a.x + (w - iw) * 0.5f, a.y + (h - ih) * 0.5f);
    const ImVec2 p1(p0.x + iw, p0.y + ih);
    dl->AddImage((ImTextureID)(intptr_t)tex.id, p0, p1, ImVec2(0, 0), ImVec2(1, 1), u32(accent, 0.94f));
    return true;
}

bool draw_graph_gallery_tile(UiState& ui, const TlacGal& item, const ImVec2& pos, const ImVec2& size, int tile_index) {
    ImDrawList* dl = ImGui::GetWindowDrawList();
    const TlacBoxF t = tlac_box_xywh(pos.x, pos.y, size.x, size.y);
    const ImVec2 b(t.x1, t.y1);
    const bool light = ui.light_theme;
    ImGui::SetCursorScreenPos(pos);
    ImGui::PushID(tile_index);
    ImGui::InvisibleButton("graph-gallery-tile", size);
    const bool hovered = ImGui::IsItemHovered();
    const bool clicked = ImGui::IsItemClicked(ImGuiMouseButton_Left);
    ImGui::PopID();
    if (hovered) {
        dl->AddRectFilled(pos, b, light ? IM_COL32(236, 243, 249, 132) : IM_COL32(24, 32, 40, 132),
                          std::max(8.0f, t.h * kGoldenN5));
        dl->AddRectFilled(ImVec2(t.x0, t.y1 - std::max(3.0f, t.h * kGoldenN11)), b,
                          u32(ui.accent, light ? 0.58f : 0.68f), std::max(4.0f, t.h * kGoldenN6));
    }
    const TlacBoxF ic = tlac_tile_icon_box(&t);
    (void)draw_graph_gallery_icon_png(dl, item, ImVec2(ic.x0, ic.y0), ImVec2(ic.x1, ic.y1), ui.accent);
    float tx = 0.0f, ty0 = 0.0f, ty1 = 0.0f;
    tlac_tile_text_xy(&t, ImGui::GetTextLineHeight(), &tx, &ty0, &ty1);
    const ImU32 text_col = light ? IM_COL32(33, 45, 58, 238) : IM_COL32(232, 240, 247, 238);
    const ImU32 sub_col = light ? IM_COL32(92, 104, 118, 188) : IM_COL32(166, 182, 196, 188);
    dl->AddText(ImVec2(tx, ty0), text_col, item.title);
    dl->AddText(ImVec2(tx, ty1), sub_col, item.subtitle);
    return clicked;
}

void draw_graph_type_gallery(UiState& ui, int tab_index, float width, float height) {
    const ImVec2 origin = ImGui::GetCursorScreenPos();
    const TlacBoxF gal = tlac_box_xywh(origin.x, origin.y, width, height);
    const ImVec2 end(gal.x1, gal.y1);
    ImDrawList* dl = ImGui::GetWindowDrawList();
    const TlacToc layout = tlac_gal_fila_unica(width, height, ImGui::GetTextLineHeight());
    const float pad = layout.pad;
    const float gap = layout.gap;
    const float grid_x = origin.x + layout.grid_x;
    const float grid_y = origin.y + layout.grid_y;
    const int item_count = layout.item_count;
    const float tile_w = layout.tile_w;
    const float tile_h = layout.tile_h;
    dl->AddText(ImVec2(origin.x + pad, origin.y + pad * kGoldenN1), ui.light_theme ? IM_COL32(36, 48, 60, 232) : IM_COL32(226, 236, 245, 232), "Crear grafica");
    dl->AddText(ImVec2(origin.x + pad, origin.y + pad * kGoldenN1 + ImGui::GetTextLineHeight() * 1.10f), ui.light_theme ? IM_COL32(90, 104, 118, 180) : IM_COL32(162, 178, 194, 180), "Elige un tipo.");
    int& count = ui.graph_counts[tab_index];
    for (int i = 0; i < item_count; ++i) {
        const TlacGal* item = tlac_gal_item(static_cast<size_t>(i));
        if (!item) continue;
        const ImVec2 p(grid_x + static_cast<float>(i) * (tile_w + gap), grid_y);
        const bool clicked = draw_graph_gallery_tile(ui, *item, p, ImVec2(tile_w, tile_h), i);
        if (clicked) {
            if (count < 8) {
                GraphSpec spec = tlac_spec_de_item(*item, ui);
                ui.graph_specs[tab_index][static_cast<size_t>(count)] = spec;
                ui.selected_graph_tab = tab_index;
                ui.selected_graph_index = count;
                ++count;
                graph_set_status(ui, std::string("Creada: ") + (item->title && item->title[0] ? item->title : tlac_tipo_txt(spec.chart_type)) + ".");
            } else {
                graph_set_status(ui, "Limite de 8 graficas alcanzado en esta pestana.");
            }
        }
    }
    ImGui::SetCursorScreenPos(ImVec2(origin.x, end.y));
    ImGui::Dummy(ImVec2(width, 1.0f));
}

